CREATE OR REPLACE FUNCTION public.act_on_reshop(p_actor text, p_org text, p_id uuid, p_action text, p_outcome text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item jsonb; record public.reshop_reviews; task uuid; anchor timestamptz; identity record;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('task','review') OR p_action='review' AND (p_outcome IS NULL OR p_outcome NOT IN ('kept_plan','reshopped','could_not_reach','asked_not_to_be_contacted','no_longer_client')) THEN RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023'; END IF;
 -- Enrollment lock serializes task/review retries. Scope/exclusions are checked
 -- again after the lock using the current canonical enrollment and CMS rows.
 PERFORM 1 FROM public.enrollment_intakes WHERE id=p_id FOR UPDATE;
 SELECT value INTO item FROM public.reshop_rows(p_actor,p_org,p_id) value;
 IF item IS NULL THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 IF item->>'target_year' IS NULL THEN RAISE EXCEPTION 'Effective date required' USING ERRCODE='22023'; END IF;
 SELECT * INTO identity FROM public.resolve_deployment_subject(p_actor,p_org);
 IF identity.authority='admin' AND NOT EXISTS(SELECT 1 FROM public.admin_action_permit WHERE transaction_id=txid_current()) THEN RAISE EXCEPTION 'Audited administrator required' USING ERRCODE='42501'; END IF;
 SELECT retention_started_at INTO anchor FROM public.enrollment_intakes WHERE id=p_id;
 INSERT INTO public.reshop_reviews(tenant_id,enrollment_id,contact_id,agent_id,target_year,retention_started_at) VALUES(identity.tenant_id,p_id,(item->>'contact_id')::uuid,(item->>'agent_id')::uuid,(item->>'target_year')::integer,anchor) ON CONFLICT(enrollment_id,target_year) DO NOTHING;
 SELECT * INTO record FROM public.reshop_reviews WHERE enrollment_id=p_id AND target_year=(item->>'target_year')::integer FOR UPDATE;
 IF p_action='task' THEN
  IF item#>>'{reasons,0}' IS NULL THEN RAISE EXCEPTION 'CMS reason required' USING ERRCODE='22023'; END IF;
  task:=record.task_id;
  IF task IS NULL THEN
   INSERT INTO public.follow_ups(tenant_id,contact_id,agent_id,due_at,reason) VALUES(identity.tenant_id,record.contact_id,item->>'agent_slug',clock_timestamp(),public.reshop_reason_label(item#>>'{reasons,0}')) RETURNING id INTO task;
   UPDATE public.reshop_reviews SET task_id=task WHERE id=record.id;
  END IF;
 ELSE
  IF record.outcome IS NOT NULL AND record.outcome<>p_outcome THEN RAISE EXCEPTION 'Already reviewed' USING ERRCODE='40001'; END IF;
  UPDATE public.reshop_reviews SET outcome=p_outcome,reviewed_by=p_actor,reviewed_at=clock_timestamp() WHERE id=record.id AND outcome IS NULL;
 END IF;
 SELECT * INTO record FROM public.reshop_reviews WHERE id=record.id;
 RETURN jsonb_build_object('task_id',record.task_id,'outcome',record.outcome,'actor',record.reviewed_by,'time',record.reviewed_at,'use_do_not_call_control',record.outcome='asked_not_to_be_contacted');
END $function$

CREATE OR REPLACE FUNCTION public.add_contact_tag(p_tenant_id uuid, p_contact_id uuid, p_requesting_agent_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE tag public.contact_tags; label text := btrim(p_name);
BEGIN
 IF current_setting('role',true)<>'service_role' AND NOT public.deployment_can_access_contact(p_contact_id) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501'; END IF;
  PERFORM public.opportunities_assert_agent(p_tenant_id,p_requesting_agent_id);
  IF label IS NULL OR length(label) NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'Enter a tag with 1–60 characters'; END IF;
  -- A contact lock serializes duplicate checks, including concurrent additions.
  PERFORM id FROM public.contacts WHERE id = p_contact_id AND tenant_id = p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Select a contact in this workspace'; END IF;
  SELECT * INTO tag FROM public.contact_tags WHERE tenant_id = p_tenant_id AND contact_id = p_contact_id
    AND lower(public.decrypt_pii_value(name_encrypted)) = lower(label) LIMIT 1;
  IF tag.id IS NULL THEN
    INSERT INTO public.contact_tags(tenant_id,contact_id,name_encrypted,created_by)
      VALUES(p_tenant_id,p_contact_id,public.encrypt_pii_value(label),p_requesting_agent_id) RETURNING * INTO tag;
    INSERT INTO public.pii_access_log(contact_id,agent_id,clerk_user_id,action)
      VALUES(p_contact_id,p_requesting_agent_id,auth.jwt()->>'sub','edit');
  END IF;
  RETURN jsonb_build_object('id',tag.id,'contact_id',tag.contact_id,'name',public.decrypt_pii_value(tag.name_encrypted));
END;
$function$

CREATE OR REPLACE FUNCTION public.append_transcription_gap(p_attempt_id uuid, p_participant_id uuid, p_gap_id uuid, p_start_ms integer, p_end_ms integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records;rid uuid;
BEGIN
 IF p_start_ms<0 OR p_end_ms<=p_start_ms THEN RAISE EXCEPTION 'Invalid capture gap'; END IF;
 IF p_participant_id IS NOT NULL THEN SELECT call_id INTO STRICT rid FROM call_participants WHERE id=p_participant_id;
 ELSE SELECT call_record_id INTO STRICT rid FROM telephony_call_attempts WHERE id=p_attempt_id; END IF;
 SELECT * INTO STRICT c FROM call_records WHERE id=rid FOR UPDATE;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(c.metadata->'transcription_gaps','[]')) g WHERE g->>'id'=p_gap_id::text) THEN RETURN; END IF;
 UPDATE call_records SET metadata=jsonb_set(coalesce(metadata,'{}'),'{transcription_gaps}',coalesce(metadata->'transcription_gaps','[]')||jsonb_build_array(jsonb_build_object('id',p_gap_id,'start_ms',p_start_ms,'end_ms',p_end_ms,'source','capture_buffer_overflow'))) WHERE id=c.id;
END $function$

CREATE OR REPLACE FUNCTION public.apply_call_wrap_up()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE w call_wrap_ups;
BEGIN
 SELECT * INTO w FROM call_wrap_ups WHERE call_sid=NEW.twilio_call_sid AND tenant_id=NEW.tenant_id AND agent_id=NEW.agent_id;
 IF w.status='saved' AND w.outcome='short_call_hangup' AND NEW.metadata->>'wrap_up_saved_at' IS NULL THEN
  NEW.call_outcome:=w.outcome;
  NEW.metadata:=coalesce(NEW.metadata,'{}')||jsonb_build_object('wrap_up_saved_at',w.saved_at,'auto_disposition',w.outcome);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.approve_client_recap(p_actor text, p_org text, p_id uuid, p_channel text, p_approved boolean, p_checksum text, p_revision timestamp with time zone, p_resend boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source jsonb; e public.enrollment_intakes; c public.call_records; content text; rid uuid:=gen_random_uuid(); mid uuid; phone text; template jsonb; prior boolean; allowance jsonb;
BEGIN
 IF p_approved IS DISTINCT FROM true OR p_channel IS NULL OR p_channel NOT IN ('sms','pdf') THEN RAISE EXCEPTION 'Approval required' USING ERRCODE='22023'; END IF;
 SELECT * INTO e FROM public.enrollment_intakes WHERE id=p_id FOR UPDATE;
 PERFORM 1 FROM public.tenants WHERE id=e.tenant_id FOR SHARE;
 source:=public.client_recap_source(p_actor,p_org,p_id,false);
 IF jsonb_array_length(source->'missing')>0 THEN RAISE EXCEPTION 'Incomplete enrollment' USING ERRCODE='22023'; END IF;
 IF p_channel='sms' AND source->>'sms_reason' IS NOT NULL THEN RAISE EXCEPTION 'Channel unavailable' USING ERRCODE='42501'; END IF;
 template:=source->'templates'->p_channel;
 content:=public.client_recap_render(source->'fields',template,p_channel);
 IF p_checksum IS DISTINCT FROM encode(extensions.digest(content,'sha256'),'hex') OR p_revision IS DISTINCT FROM e.updated_at THEN RAISE EXCEPTION 'Preview changed' USING ERRCODE='40001'; END IF;
 SELECT EXISTS(SELECT 1 FROM public.client_recaps WHERE enrollment_id=e.id AND channel=p_channel) INTO prior;
 IF prior AND (NOT coalesce(p_resend,false) OR source->>'admin'<>'true') OR p_resend AND source->>'admin'<>'true' THEN RAISE EXCEPTION 'Already approved' USING ERRCODE='23505'; END IF;
 IF source->>'admin'='true' AND NOT EXISTS(SELECT 1 FROM public.admin_action_permit WHERE transaction_id=txid_current()) THEN RAISE EXCEPTION 'Audited administrator required' USING ERRCODE='42501'; END IF;
 -- Independent service-RPC resend fence in addition to profile HTTP admission.
 IF prior THEN
  SELECT public.consume_admission(jsonb_build_array(jsonb_build_object('key',e.tenant_id::text||':client-recap-resend:'||p_actor,'seconds',60,'limit',3))) INTO allowance;
  IF allowance->>'allowed'<>'true' THEN RAISE EXCEPTION 'Resend limited' USING ERRCODE='54000'; END IF;
 END IF;
 SELECT * INTO c FROM public.call_records WHERE id=e.call_id AND tenant_id=e.tenant_id;
 IF p_channel='sms' THEN
  SELECT consumer.phone INTO phone FROM public.contacts consumer WHERE consumer.id=e.contact_id AND consumer.tenant_id=e.tenant_id;
  INSERT INTO public.messages(tenant_id,contact_id,direction,channel,to_number,body,status,agent_id) VALUES(e.tenant_id,e.contact_id,'outbound','sms',phone,content,'queued',(SELECT agent_slug FROM public.tenant_agents a JOIN public.enrolled_agents ea ON ea.clerk_user_id=a.clerk_user_id AND ea.tenant_id=a.tenant_id WHERE ea.id=c.agent_id AND a.tenant_id=e.tenant_id)) RETURNING id INTO mid;
 END IF;
 INSERT INTO public.client_recaps(id,enrollment_id,contact_id,agent_id,tenant_id,channel,template_version,approved_by,enrollment_updated_at,message_id,status,content_sha256,retention_started_at)
 VALUES(rid,e.id,e.contact_id,c.agent_id,e.tenant_id,p_channel,(template->>'version')::integer,p_actor,e.updated_at,mid,CASE WHEN p_channel='pdf' THEN 'downloaded' ELSE 'queued' END,p_checksum,e.retention_started_at);
 RETURN jsonb_build_object('id',rid,'message_id',mid,'phone',phone,'body',content);
END $function$

CREATE OR REPLACE FUNCTION public.attach_supervisor_whisper(p_id uuid, p_actor text, p_org text, p_session text, p_call uuid, p_sid text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.supervisor_listen_sessions; c public.call_conferences; leg public.call_participants; pid uuid:=gen_random_uuid();
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('SUPERVISOR_WHISPER_ENABLED') OR NOT public.deployment_feature_enabled('SUPERVISOR_FLOOR_ENABLED') OR NOT public.deployment_feature_enabled('CONFERENCE_CALLING_ENABLED') THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.supervisor_listen_sessions WHERE id=p_id AND actor_id=p_actor AND session_id=p_session AND mode='whisper' AND ended_at IS NULL AND lease_until>clock_timestamp() AND expires_at>clock_timestamp() FOR UPDATE;
 SELECT * INTO c FROM public.call_conferences WHERE call_id=p_call AND attempt_id=s.attempt_id AND tenant_id=s.tenant_id AND ended_at IS NULL AND phase IN ('active','warm_completed');
 IF s.id IS NULL OR c.call_id IS NULL OR s.call_id IS NOT NULL AND s.call_id<>c.call_id OR s.participant_id IS NOT NULL OR p_sid !~ '^CA[0-9a-fA-F]{32}$' THEN RAISE EXCEPTION 'Call unavailable' USING ERRCODE='42501'; END IF;
 -- The lease is already held by this join. Reauthorize the same protected actor,
 -- agent and latest lock event without rejecting our own operation token.
 IF NOT EXISTS(SELECT 1 FROM public.resolve_deployment_subject(p_actor,p_org) i WHERE i.tenant_id=s.tenant_id AND (i.authority='admin' OR i.authority='manager' AND s.agent_id=ANY(i.team_agent_ids)))
 OR EXISTS(SELECT 1 FROM public.telephony_events WHERE tenant_id=s.tenant_id AND event='session_lock' AND payload->>'clerk_user_id'=p_actor AND occurred_at>=s.started_at)
 OR NOT EXISTS(SELECT 1 FROM public.supervisor_floor_rows(s.tenant_id,NULL) f WHERE f.attempt_id=s.attempt_id AND f.agent_id=s.agent_id AND f.status IN ('on_call','on_hold')) THEN RAISE EXCEPTION 'Authority unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO leg FROM public.call_participants WHERE call_id=c.call_id AND role='agent' AND agent_id=c.owner_agent_id AND status='connected';
 IF leg.id IS NULL THEN RAISE EXCEPTION 'Agent unavailable' USING ERRCODE='42501'; END IF;
 -- Persist the recording-to-text safety marker before any coach audio exists.
 UPDATE public.call_records SET metadata=coalesce(metadata,'{}')||jsonb_build_object('supervisor_whisper',true) WHERE id=c.call_id;
 INSERT INTO public.call_participants(id,call_id,role,speaker,twilio_call_sid,added_by_agent_id) VALUES(pid,c.call_id,'supervisor','supervisor',p_sid,c.owner_agent_id);
 UPDATE public.supervisor_listen_sessions SET participant_id=pid,call_id=c.call_id,agent_leg_sid=leg.twilio_call_sid WHERE id=p_id RETURNING * INTO s;
 RETURN to_jsonb(s);
END $function$

CREATE OR REPLACE FUNCTION public.audit_ping_source_control()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r ping_source_controls;
BEGIN
 r:=CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 INSERT INTO ping_source_control_audit(control_id,tenant_id,source_id,campaign_id,paused,operation,changed_by)
 VALUES(r.id,r.tenant_id,r.source_id,r.campaign_id,r.paused,TG_OP,r.changed_by);
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.authorize_paragon_report(p_hash text, p_ip text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_source uuid; v_limited boolean; v_ip text := left(coalesce(nullif(p_ip,''),'unknown'), 128);
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('paragon-report:' || v_ip, 0));
  SELECT count(*) >= 30 INTO v_limited FROM paragon_report_access
    WHERE ip=v_ip AND attempted_at > clock_timestamp() - interval '5 minutes';
  IF NOT v_limited AND p_hash ~ '^[a-f0-9]{64}$' THEN
    SELECT t.source_id INTO v_source FROM paragon_report_tokens t
      JOIN lead_sources s ON s.id=t.source_id
      WHERE t.token_hash=p_hash AND s.name=public.bootstrap_vendor_source_name() AND s.type='publisher' AND s.active;
  END IF;
  INSERT INTO paragon_report_access(ip,authorized,rate_limited)
    VALUES(v_ip,v_source IS NOT NULL,v_limited);
  RETURN v_source;
END;
$function$

CREATE OR REPLACE FUNCTION public.authorize_paragon_report_limited(p_hash text, p_ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE ip_key text:=left(coalesce(nullif(p_ip,''),'unknown'),128);limited boolean;source uuid;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('paragon-report:'||ip_key,0));
 SELECT count(*)>=30 INTO limited FROM paragon_report_access WHERE ip=ip_key AND attempted_at>clock_timestamp()-interval '5 minutes';
 source:=authorize_paragon_report(p_hash,ip_key);
 RETURN jsonb_build_object('source_id',source,'limited',limited,'retry_after',CASE WHEN limited THEN 300 ELSE 0 END);
END $function$

CREATE OR REPLACE FUNCTION public.begin_post_call_coaching(p_call uuid, p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.call_records; d public.transcript_score_dispatch; t public.call_transcripts; cap integer; allowance jsonb; day date:=(clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
 IF NOT public.deployment_feature_enabled('POST_CALL_COACHING_ENABLED') THEN RETURN NULL; END IF;
 SELECT * INTO c FROM public.call_records WHERE id=p_call FOR UPDATE;
 SELECT * INTO d FROM public.transcript_score_dispatch WHERE call_id=p_call FOR UPDATE;
 IF c.id IS NULL OR p_token IS NULL OR d.coaching_lease_until IS NULL OR d.coaching_token IS DISTINCT FROM p_token OR d.coaching_state NOT IN ('queued','processing') OR d.coaching_lease_until<clock_timestamp() THEN RETURN NULL; END IF;
 IF d.coaching_state='processing' AND d.coaching_available_at>clock_timestamp() THEN RETURN NULL; END IF;
 IF NOT public.coaching_call_eligible(c) THEN
  UPDATE public.transcript_score_dispatch SET coaching_state='skipped',coaching_lease_until=NULL WHERE call_id=p_call;
  RETURN NULL;
 END IF;
 SELECT * INTO t FROM public.call_transcripts WHERE tenant_id=c.tenant_id AND (id=c.transcript_id OR call_record_id=c.id) ORDER BY (id=c.transcript_id) DESC NULLS LAST,created_at DESC,id DESC LIMIT 1;
 IF d.coaching_reserved_day IS DISTINCT FROM day THEN
  SELECT (coaching_settings->>'daily_cap')::integer INTO cap FROM public.tenants WHERE id=c.tenant_id;
  SELECT public.consume_admission(jsonb_build_array(jsonb_build_object('key',c.tenant_id::text||':post-call-coaching:agency-day','seconds',86400,'limit',cap))) INTO allowance;
  IF allowance->>'allowed' IS DISTINCT FROM 'true' THEN
   INSERT INTO public.post_call_coaching(call_id,transcript_id,agent_id,tenant_id,status,reason,generation,retention_started_at)
   VALUES(c.id,t.id,c.agent_id,c.tenant_id,'skipped','daily_cap',d.coaching_generation,c.retention_started_at)
   ON CONFLICT(call_id) DO UPDATE SET status='skipped',reason='daily_cap',objections='[]',did_well=NULL,model=NULL,prompt_version=NULL,generated_at=clock_timestamp(),reviewed_at=NULL,reviewed_by=NULL,generation=d.coaching_generation;
   UPDATE public.transcript_score_dispatch SET coaching_state='skipped',coaching_lease_until=NULL WHERE call_id=c.id;
   RETURN jsonb_build_object('status','skipped');
  END IF;
 END IF;
 UPDATE public.transcript_score_dispatch SET coaching_state='processing',coaching_reserved_day=day,
 coaching_revision=md5(public.scoring_transcript_snapshot(c)::text||coalesce(t.transcript_text,'')),coaching_available_at=coaching_lease_until WHERE call_id=c.id;
 RETURN jsonb_build_object('status','claimed','generation',d.coaching_generation,'call',jsonb_build_object('id',c.id,'tenant_id',c.tenant_id,'agent_id',c.agent_id,'call_duration_seconds',c.call_duration_seconds,'product_type',c.product_type,'transcript_raw',coalesce(nullif(c.transcript_raw,''),t.transcript_text),'transcript_diarized',c.transcript_diarized));
END $function$

CREATE OR REPLACE FUNCTION public.begin_practice_work(p_actor text, p_org text, p_id uuid, p_kind text, p_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.practice_sessions; token uuid:=gen_random_uuid(); at_ms integer;
BEGIN
 s:=public.practice_target(p_actor,p_org,p_id,true);
 SELECT * INTO s FROM public.practice_sessions WHERE id=p_id FOR UPDATE;
 IF s.status IN ('completed','incomplete') THEN RETURN NULL; END IF;
 IF s.work_token IS NOT NULL AND s.lease_until>clock_timestamp() THEN RAISE EXCEPTION 'Practice busy' USING ERRCODE='55000'; END IF;
 IF p_kind IS NULL OR p_kind NOT IN ('turn','result') THEN RAISE EXCEPTION 'Invalid work' USING ERRCODE='22023'; END IF;
 IF s.expires_at<=clock_timestamp() THEN s.status:='ending';s.end_reason:='time_limit';
 ELSIF s.last_activity_at<clock_timestamp()-interval '5 minutes' THEN UPDATE public.practice_sessions SET status='incomplete',end_reason='abandoned',ended_at=clock_timestamp(),work_token=NULL,lease_until=NULL WHERE id=p_id; RETURN NULL;
 ELSIF s.status='ending' OR p_kind='result' THEN s.status:='ending';s.end_reason:=coalesce(s.end_reason,'agent'); END IF;
 IF s.status='ending' THEN p_kind:='result'; ELSE
  IF p_text IS NULL OR length(btrim(p_text))=0 OR length(p_text)>1000 THEN RAISE EXCEPTION 'Invalid turn' USING ERRCODE='22023'; END IF;
  at_ms:=greatest(coalesce((s.transcript->-1->>'end_ms')::integer,0)+1,(extract(epoch FROM clock_timestamp()-s.started_at)*1000)::integer);
  s.transcript:=s.transcript||jsonb_build_array(jsonb_build_object('speaker','agent','text',p_text,'start_ms',at_ms,'end_ms',at_ms+1));
 END IF;
 UPDATE public.practice_sessions SET status=s.status,end_reason=s.end_reason,transcript=s.transcript,work_token=token,work_kind=p_kind,lease_until=clock_timestamp()+interval '3 minutes',last_activity_at=clock_timestamp() WHERE id=p_id RETURNING * INTO s;
 RETURN to_jsonb(s);
END $function$

CREATE OR REPLACE FUNCTION public.begin_scoring_job_pre133(p_call_id uuid, p_template_id uuid, p_transcript jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c public.call_records; j public.scoring_jobs; revision text; completed_job uuid;
BEGIN
  SELECT * INTO STRICT c FROM call_records WHERE id=p_call_id FOR UPDATE;
  IF NOT public.is_compliance_sale(c.call_outcome) OR c.compliance_requested_at IS NULL THEN
    RETURN jsonb_build_object('status','skipped','reason','non_sale_or_not_requested');
  END IF;
  IF c.compliance_run_at IS NOT NULL AND c.compliance_transcript_hash=public.compliance_content_hash(c) THEN
    SELECT id INTO completed_job FROM scoring_jobs WHERE scorecard_id=c.compliance_scorecard_id AND status='complete' LIMIT 1;
    IF completed_job IS NOT NULL THEN RETURN jsonb_build_object('status','complete','result',scoring_job_result(completed_job)); END IF;
  END IF;
  IF NOT public.sale_compliance_transcript_ready(c) OR NOT EXISTS(SELECT 1 FROM transcript_score_dispatch d
    WHERE d.call_id=c.id AND d.snapshot_revision=public.compliance_content_hash(c)
      AND d.transcript_ready_at<=clock_timestamp() AND d.delivered_revision<d.revision) THEN
    RETURN jsonb_build_object('status','pending','reason','transcript_pending');
  END IF;
  IF scoring_transcript_snapshot(c) IS DISTINCT FROM p_transcript THEN RAISE EXCEPTION 'Transcript changed; reload before scoring'; END IF;
  PERFORM 1 FROM scoring_templates WHERE id=p_template_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Scoring template not found'; END IF;
  revision:=md5(p_transcript::text);
  INSERT INTO scoring_jobs(tenant_id,call_id,template_id,transcript_revision,status,lease_until,attempt_count,estimated_input_tokens)
    VALUES(c.tenant_id,c.id,p_template_id,revision,'pending',now()+interval '15 minutes',1,0)
    ON CONFLICT(call_id,template_id,transcript_revision) DO NOTHING RETURNING * INTO j;
  IF j.id IS NULL THEN
    SELECT * INTO STRICT j FROM scoring_jobs WHERE call_id=c.id AND template_id=p_template_id AND transcript_revision=revision FOR UPDATE;
    IF j.status='complete' THEN RETURN jsonb_build_object('status','complete','result',scoring_job_result(j.id)); END IF;
    IF j.status='failed' AND j.error IN ('scoring_attempts_exhausted','call_token_budget_exceeded') THEN
      RETURN jsonb_build_object('status','failed','error',j.error);
    END IF;
    IF j.status='pending' AND j.lease_until>now() THEN RETURN jsonb_build_object('status','pending','reason','scoring_in_progress'); END IF;
    IF j.attempt_count >= 3 THEN
      UPDATE scoring_jobs SET status='failed',error='scoring_attempts_exhausted',updated_at=now() WHERE id=j.id RETURNING * INTO j;
      UPDATE call_records SET metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('scoring_status','failed',
        'scoring_error_code','scoring_attempts_exhausted','scoring_failed_at',now()),updated_at=now() WHERE id=c.id;
      RETURN jsonb_build_object('status','failed','error','scoring_attempts_exhausted');
    END IF;
    UPDATE scoring_jobs SET status='pending',attempt_count=attempt_count+1,attempt_token=gen_random_uuid(),
      lease_until=now()+interval '15 minutes',error=NULL,updated_at=now() WHERE id=j.id RETURNING * INTO j;
  END IF;
  UPDATE call_records SET metadata=(coalesce(metadata,'{}'::jsonb)-'scoring_error'-'scoring_failed_at'-'scoring_completed_at') ||
    jsonb_build_object('scoring_status','pending','scoring_job_id',j.id,'scoring_revision',revision),updated_at=now() WHERE id=c.id;
  RETURN jsonb_build_object('status','claimed','jobId',j.id,'attemptToken',j.attempt_token,'revision',revision,'attemptCount',j.attempt_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.capture_lifecycle_purge_marker(p_table text, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r jsonb; consumer uuid; call uuid; tenant uuid;
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('RETENTION_PURGE_ENABLED') THEN RETURN; END IF;
 IF p_table<>ALL(ARRAY['reshop_reviews','client_recaps','call_records','inbound_calls','telephony_call_attempts','sessions','messages','message_media','call_transcripts','enrollment_intakes','policies','compliance_scorecards','compliance_scores','recording_ingestion','ghl_enrollment_deliveries','ix_uploads','conversely_submissions','transcript_chunks','intent_detections','scorecard_items','section_scores','compliance_flags','manual_transcript_gap_fills']) THEN RETURN; END IF;
 EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id=$1',p_table) INTO r USING p_id;
 IF r IS NULL THEN RETURN; END IF;
 tenant:=nullif(r->>'tenant_id','')::uuid;
 consumer:=nullif(r->>'contact_id','')::uuid;
 call:=nullif(coalesce(r->>'call_record_id',r->>'call_id'),'')::uuid;
 IF p_table='call_records' THEN call:=p_id; END IF;
 IF call IS NOT NULL AND consumer IS NULL THEN SELECT contact_id,tenant_id INTO consumer,tenant FROM public.call_records WHERE id=call; END IF;
 IF p_table='message_media' THEN SELECT contact_id,tenant_id INTO consumer,tenant FROM public.messages WHERE id=(r->>'message_id')::uuid; END IF;
 IF consumer IS NULL AND nullif(r->>'session_id','') IS NOT NULL THEN SELECT contact_id,tenant_id,coalesce(call,call_record_id) INTO consumer,tenant,call FROM public.sessions WHERE id=(r->>'session_id')::uuid; END IF;
 IF consumer IS NULL AND nullif(r->>'scorecard_id','') IS NOT NULL THEN SELECT c.contact_id,c.tenant_id,c.id INTO consumer,tenant,call FROM public.compliance_scorecards s JOIN public.call_records c ON c.id=s.call_id WHERE s.id=(r->>'scorecard_id')::uuid; END IF;
 IF consumer IS NULL AND nullif(r->>'transcript_id','') IS NOT NULL THEN SELECT coalesce(c.contact_id,s.contact_id),t.tenant_id,coalesce(c.id,s.call_record_id) INTO consumer,tenant,call FROM public.call_transcripts t LEFT JOIN public.call_records c ON c.id=t.call_record_id LEFT JOIN public.sessions s ON s.id=t.session_id WHERE t.id=(r->>'transcript_id')::uuid; END IF;
 IF p_table='recording_ingestion' THEN
  SELECT coalesce(consumer,i.contact_id,c.contact_id),coalesce(call,i.call_record_id,c.id) INTO consumer,call
  FROM (SELECT 1) x LEFT JOIN public.inbound_calls i ON i.id=nullif(r->>'inbound_call_id','')::uuid
  LEFT JOIN public.telephony_call_attempts a ON a.id=nullif(r->>'attempt_id','')::uuid
  LEFT JOIN public.call_records c ON c.id=coalesce(nullif(r->>'call_record_id','')::uuid,a.call_record_id);
  UPDATE public.retention_recording_purges SET contact_id=consumer,call_id=call,sha256=r->>'sha256' WHERE recording_id=p_id;
 END IF;
 IF consumer IS NOT NULL AND tenant IS NOT NULL THEN
 INSERT INTO public.retention_purge_items(tenant_id,contact_id,source_table,resource_id,call_id) VALUES(tenant,consumer,p_table,p_id,call) ON CONFLICT DO NOTHING;
 END IF;
 RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.claim_automatic_transcript_recovery(p_call_id uuid, p_tenant_id uuid, p_recording_id uuid, p_ranges jsonb, p_mapping jsonb, p_cost numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records;r recording_ingestion;j manual_transcript_gap_fills; seconds numeric;total numeric;
BEGIN
 IF NOT public.deployment_feature_enabled('TRANSCRIPT_AUTO_RECOVERY_ENABLED') THEN RETURN jsonb_build_object('status','disabled'); END IF;
 SELECT * INTO STRICT c FROM call_records WHERE id=p_call_id AND tenant_id=p_tenant_id FOR UPDATE;
 IF c.call_end IS NULL OR NOT is_compliance_sale(c.call_outcome) OR c.compliance_scorecard_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM compliance_llm_passes WHERE call_id=c.id)
 OR EXISTS(SELECT 1 FROM usage_records WHERE metadata->>'call_record_id'=c.id::text AND record_type='llm_tokens')
 THEN RETURN jsonb_build_object('status','blocked','reason','existing_score_or_active_call'); END IF;
 SELECT * INTO j FROM manual_transcript_gap_fills WHERE call_id=c.id AND (mode='automatic' OR status IN ('queued','processing')) ORDER BY created_at DESC LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('status',CASE WHEN j.status IN ('queued','processing') AND j.created_at>clock_timestamp()-interval '15 minutes' THEN 'busy' ELSE 'blocked' END,'reason','automatic_recovery_already_attempted'); END IF;
 SELECT * INTO STRICT r FROM recording_ingestion WHERE id=p_recording_id AND call_record_id=c.id AND tenant_id=c.tenant_id;
 IF c.metadata->'supervisor_whisper'='true'::jsonb THEN
 IF NOT EXISTS(SELECT 1 FROM public.whisper_customer_recordings(c.id,c.tenant_id) x WHERE x.id=r.id) OR p_mapping IS DISTINCT FROM '["customer","agent"]'::jsonb THEN RAISE EXCEPTION 'Unverified recording'; END IF;
 ELSE
 IF r.provider_status<>'completed' OR r.recording_source<>'DialVerb' OR r.recording_channels<>2 OR r.parent_call_sid IS DISTINCT FROM c.twilio_call_sid
 OR abs(r.recording_duration_seconds-c.call_duration_seconds)>1 OR EXISTS(SELECT 1 FROM call_conferences WHERE call_id=c.id)
 OR (SELECT count(*) FROM telephony_call_attempts WHERE call_record_id=c.id)<>1
 OR NOT EXISTS(SELECT 1 FROM telephony_call_attempts a WHERE a.id=r.attempt_id AND a.ended_at IS NOT NULL AND abs(extract(epoch FROM(r.provider_created_at-a.answered_at)))<=1)
 OR p_mapping IS DISTINCT FROM (CASE WHEN r.direction='inbound' THEN '["customer","agent"]'::jsonb WHEN r.direction='outbound' THEN '["agent","customer"]'::jsonb ELSE NULL END)
 THEN RAISE EXCEPTION 'Unverified recording'; END IF;
 END IF;
 IF jsonb_array_length(p_ranges) NOT BETWEEN 1 AND 4 OR c.call_duration_seconds NOT BETWEEN 1 AND 21600 THEN RAISE EXCEPTION 'Invalid gap ranges'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_ranges) g WHERE (g->>'start_ms')::numeric<0 OR (g->>'end_ms')::numeric>(c.call_duration_seconds*1000) OR (g->>'end_ms')::numeric<=(g->>'start_ms')::numeric) THEN RAISE EXCEPTION 'Invalid range'; END IF;
 SELECT sum((g->>'end_ms')::numeric-(g->>'start_ms')::numeric)/1000 INTO seconds FROM jsonb_array_elements(p_ranges)g;
 total:=seconds/60*2*0.0043;
 IF p_cost IS NULL OR p_cost<total-0.000001 OR p_cost>0.50 OR total>0.50 THEN RETURN jsonb_build_object('status','blocked','reason','recovery_cost_cap'); END IF;
 -- Global daily reservation, including failed/ambiguous requests. No refunds/retries.
 PERFORM pg_advisory_xact_lock(147,1);
 IF (SELECT coalesce(sum(estimated_cost_usd),0) FROM manual_transcript_gap_fills WHERE mode='automatic' AND created_at>=date_trunc('day',clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC')+p_cost>10 THEN RETURN jsonb_build_object('status','blocked','reason','daily_recovery_cost_cap'); END IF;
 INSERT INTO manual_transcript_gap_fills(request_id,call_id,tenant_id,recording_id,requested_by,source_transcript,ranges,channel_speakers,timeline_offset_ms,estimated_cost_usd,mode)
 VALUES(gen_random_uuid(),c.id,c.tenant_id,r.id,'automatic',coalesce(c.transcript_diarized,'[]'),p_ranges,p_mapping,CASE WHEN c.metadata->'supervisor_whisper'='true'::jsonb THEN greatest(0,round(extract(epoch FROM(r.provider_created_at-c.call_start))*1000))::integer ELSE 0 END,p_cost,'automatic') RETURNING * INTO j;
 UPDATE transcript_score_dispatch SET dispatch_attempts=0,available_at=clock_timestamp()+interval '15 minutes' WHERE call_id=c.id;
 RETURN jsonb_build_object('status','claimed','job_id',j.id);
END $function$

CREATE OR REPLACE FUNCTION public.claim_call_agent(p_call_sid text, p_exclude text[] DEFAULT '{}'::text[], p_agent_id text DEFAULT NULL::text)
 RETURNS TABLE(agent_id text, agent_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE selected_id text;
BEGIN
  IF p_call_sid IS NULL OR length(p_call_sid) = 0 THEN RAISE EXCEPTION 'call SID required'; END IF;
  -- Serialize retries of the same call across service instances.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_call_sid, 0));
  RETURN QUERY SELECT a.agent_id, a.agent_name FROM agent_availability a WHERE a.active_call_sid = p_call_sid;
  IF FOUND THEN RETURN; END IF;
  SELECT a.agent_id INTO selected_id FROM agent_availability a
    WHERE ((p_agent_id IS NULL AND public.agent_inbound_routable(a.agent_id, a.status, a.available, a.active_call_sid))
        OR (p_agent_id IS NOT NULL AND a.agent_id = p_agent_id
          AND a.active_call_sid IS NULL AND public.agent_phone_routable(a.agent_id)))
      AND NOT (a.agent_id = ANY(COALESCE(p_exclude, '{}'::text[])))
    ORDER BY a.last_assigned_at ASC NULLS FIRST, a.toggled_at ASC NULLS FIRST, a.agent_id
    FOR UPDATE SKIP LOCKED LIMIT 1;
  IF selected_id IS NULL THEN RETURN; END IF;
  RETURN QUERY UPDATE agent_availability a
    SET active_call_sid = p_call_sid, resume_status = a.status,
        status = 'busy', available = false, last_assigned_at = clock_timestamp(), toggled_at = clock_timestamp()
    WHERE a.agent_id = selected_id RETURNING a.agent_id, a.agent_name;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_call_agent_with_preference(p_call_sid text, p_exclude text[], p_agent_id text, p_preferred_agent_id text, p_enforce_presence boolean)
 RETURNS TABLE(agent_id text, agent_name text, claim_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE selected_id TEXT;
BEGIN
  IF p_call_sid IS NULL OR length(p_call_sid) = 0 THEN RAISE EXCEPTION 'call SID required'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_call_sid, 0));
  RETURN QUERY SELECT a.agent_id, a.agent_name, 'existing'::text
    FROM agent_availability a WHERE a.active_call_sid = p_call_sid;
  IF FOUND THEN RETURN; END IF;

  -- Explicit outbound identity always retains the legacy claim semantics.
  IF p_agent_id IS NOT NULL OR nullif(p_preferred_agent_id, '') IS NULL THEN
    RETURN QUERY SELECT a.agent_id, a.agent_name,
      CASE WHEN p_agent_id IS NOT NULL THEN 'outbound' ELSE 'round_robin' END
      FROM claim_call_agent(p_call_sid, p_exclude, p_agent_id) a;
    RETURN;
  END IF;

  SELECT a.agent_id INTO selected_id FROM agent_availability a
    WHERE a.agent_id = p_preferred_agent_id
      AND public.agent_inbound_routable(a.agent_id, a.status, a.available, a.active_call_sid)
      AND NOT (a.agent_id = ANY(COALESCE(p_exclude, '{}'::text[])))
      AND EXISTS (SELECT 1 FROM tenant_agents t WHERE t.agent_slug = a.agent_id AND t.is_active = true)
    FOR UPDATE OF a SKIP LOCKED LIMIT 1;

  IF selected_id IS NOT NULL THEN
    RETURN QUERY UPDATE agent_availability a
      SET active_call_sid = p_call_sid, resume_status = a.status,
        status = 'busy', available = false,
        last_assigned_at = clock_timestamp(), toggled_at = clock_timestamp()
      WHERE a.agent_id = selected_id RETURNING a.agent_id, a.agent_name, 'preferred'::text;
    RETURN;
  END IF;

  -- A roster-inactive preferred agent could otherwise be chosen by the legacy
  -- rotation (which has no roster predicate). Exclude this rejected candidate.
  -- The legacy RPC reacquires our transaction's own advisory lock and uses
  -- SKIP LOCKED for other agents; no second service/DB round trip occurs.
  RETURN QUERY SELECT a.agent_id, a.agent_name, 'round_robin'::text
    FROM claim_call_agent(p_call_sid,
      array_append(COALESCE(p_exclude, '{}'::text[]), p_preferred_agent_id), NULL) a;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_compliance_pass(p_call_id uuid, p_tenant_id uuid, p_request_id uuid, p_mode text, p_requested_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records; p compliance_llm_passes; n integer;
BEGIN
 IF NOT public.deployment_feature_enabled('SCORING_ENABLED') THEN RETURN jsonb_build_object('status','disabled'); END IF;
 IF NOT EXISTS(SELECT 1 FROM compliance_runtime_control WHERE id AND enabled) THEN RETURN jsonb_build_object('status','disabled'); END IF;
 IF EXISTS(SELECT 1 FROM compliance_daily_budget WHERE day=(clock_timestamp() AT TIME ZONE 'UTC')::date AND halted) THEN RETURN jsonb_build_object('status','daily_scoring_token_cap'); END IF;
 SELECT * INTO STRICT c FROM call_records WHERE id=p_call_id AND tenant_id=p_tenant_id FOR UPDATE;
 IF compliance_call_excluded(c) THEN RETURN jsonb_build_object('status','not_applicable'); END IF;
 SELECT * INTO p FROM compliance_llm_passes WHERE request_id=p_request_id;
 IF FOUND THEN
  IF p.call_id<>c.id THEN RAISE EXCEPTION 'Request belongs to another call'; END IF;
  RETURN jsonb_build_object('status','already_reserved','id',p.id);
 END IF;
 IF p_mode='automatic' AND (EXISTS(SELECT 1 FROM compliance_llm_passes WHERE call_id=c.id)
  OR EXISTS(SELECT 1 FROM compliance_scorecards WHERE call_id=c.id)
  OR EXISTS(SELECT 1 FROM usage_records WHERE metadata->>'call_record_id'=c.id::text AND record_type='llm_tokens')) THEN
  RETURN jsonb_build_object('status','paid_pass_already_exists');
 END IF;
 IF p_mode NOT IN ('automatic','manual') THEN RAISE EXCEPTION 'Invalid mode'; END IF;
 IF EXISTS(SELECT 1 FROM compliance_llm_passes WHERE call_id=c.id AND status IN ('reserved','running')) THEN
  RETURN jsonb_build_object('status','busy');
 END IF;
 IF p_mode='manual' THEN
  IF nullif(p_requested_by,'') IS NULL THEN RAISE EXCEPTION 'Verified administrator required'; END IF;
  SELECT count(*) INTO n FROM compliance_llm_passes WHERE call_id=c.id AND mode='manual'
   AND created_at >= date_trunc('day',clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  IF n>=3 THEN RETURN jsonb_build_object('status','daily_manual_limit'); END IF;
 END IF;
 INSERT INTO compliance_llm_passes(call_id,tenant_id,request_id,mode,requested_by)
 VALUES(c.id,c.tenant_id,p_request_id,p_mode,p_requested_by) RETURNING * INTO p;
 RETURN jsonb_build_object('status','claimed','id',p.id);
END $function$

CREATE OR REPLACE FUNCTION public.claim_compliance_upload(p_provider text)
 RETURNS SETOF conversely_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE tab text; ordering_guard text:=''; BEGIN
 IF NOT public.deployment_feature_enabled(CASE p_provider WHEN 'ghl' THEN 'GHL_ENABLED' WHEN 'ix' THEN 'IX_UPLOAD_ENABLED' WHEN 'conversely' THEN 'CONVERSELY_UPLOAD_ENABLED' ELSE '' END) THEN RETURN; END IF;
 IF p_provider='ix' THEN
  RETURN QUERY SELECT q.id,q.tenant_id,q.call_id,q.twilio_recording_sid,q.enrollment_key,q.confirmation_code,q.status,q.attempts,q.last_error,q.next_attempt_at,q.lease_token,q.lease_until,q.ix_receipt_id,q.uploaded_at,q.created_at,q.updated_at,q.retention_started_at FROM claim_ix_upload() q;
  RETURN;
 END IF;
 tab := CASE p_provider WHEN 'conversely' THEN 'conversely_submissions' WHEN 'ix' THEN 'ix_uploads' WHEN 'ghl' THEN 'ghl_enrollment_deliveries' ELSE NULL END;
 IF tab IS NULL THEN RAISE EXCEPTION 'Invalid provider'; END IF;
 IF p_provider='ghl' THEN
  ordering_guard:=' AND NOT EXISTS(SELECT 1 FROM ghl_enrollment_deliveries earlier WHERE earlier.intake_id=candidate.intake_id AND earlier.revision<candidate.revision AND earlier.status<>''uploaded'' AND (earlier.attempts<5 OR (earlier.status=''uploading'' AND earlier.lease_until>now())))';
 END IF;
 ordering_guard:=ordering_guard || CASE WHEN p_provider='ghl' THEN
 ' AND EXISTS(SELECT 1 FROM enrollment_intakes i WHERE i.id=candidate.intake_id AND i.tenant_id=candidate.tenant_id AND NOT i.is_test_enrollment)'
 ELSE ' AND EXISTS(SELECT 1 FROM enrollment_intakes i WHERE i.id::text=candidate.enrollment_key AND i.call_id=candidate.call_id AND i.tenant_id=candidate.tenant_id AND NOT i.is_test_enrollment)' END;
 -- A lost final lease must still become terminal after five attempts.
 EXECUTE format('UPDATE %I SET status=''failed'',last_error=''lease_expired'',updated_at=now() WHERE status=''uploading'' AND lease_until<now() AND attempts>=5',tab);
 RETURN QUERY EXECUTE format('UPDATE %I q SET status=''uploading'',attempts=q.attempts+1,lease_token=gen_random_uuid(),lease_until=now()+interval ''30 minutes'',updated_at=now()
 WHERE id=(SELECT id FROM %I candidate WHERE attempts<5 AND ((status IN (''pending'',''failed'') AND next_attempt_at<=now()) OR (status=''uploading'' AND lease_until<now())) %s
 ORDER BY next_attempt_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1) RETURNING q.id,q.tenant_id,q.call_id,q.twilio_recording_sid,q.enrollment_key,q.confirmation_code,q.status,q.attempts,q.last_error,q.next_attempt_at,q.lease_token,q.lease_until,q.ix_receipt_id,q.uploaded_at,q.created_at,q.updated_at,q.retention_started_at',tab,tab,ordering_guard);
END; $function$

CREATE OR REPLACE FUNCTION public.claim_customer_call_agent(p_call_sid text, p_exclude text[], p_preferred_agent_id text, p_direct boolean)
 RETURNS TABLE(agent_id text, agent_name text, claim_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE selected_id text;
BEGIN
  IF nullif(p_call_sid,'') IS NULL OR nullif(p_preferred_agent_id,'') IS NULL THEN
    RAISE EXCEPTION 'Call SID and customer destination required';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_call_sid,0));
  RETURN QUERY SELECT a.agent_id,a.agent_name,'existing'::text
    FROM agent_availability a WHERE a.active_call_sid=p_call_sid;
  IF FOUND THEN RETURN; END IF;

  SELECT a.agent_id INTO selected_id FROM agent_availability a
    WHERE a.agent_id=p_preferred_agent_id
      AND public.agent_customer_routable(a.agent_id,a.status,a.available,a.active_call_sid)
      AND NOT (a.agent_id=ANY(coalesce(p_exclude,'{}'::text[])))
      AND EXISTS(SELECT 1 FROM tenant_agents t WHERE t.agent_slug=a.agent_id AND t.is_active=true)
    FOR UPDATE OF a SKIP LOCKED LIMIT 1;
  IF selected_id IS NOT NULL THEN
    RETURN QUERY UPDATE agent_availability a
      SET active_call_sid=p_call_sid,resume_status=a.status,status='busy',available=false,
        last_assigned_at=clock_timestamp(),toggled_at=clock_timestamp()
      WHERE a.agent_id=selected_id RETURNING a.agent_id,a.agent_name,'preferred'::text;
    RETURN;
  END IF;

  -- A dedicated destination that is Offline/Busy is never rung. Sticky calls
  -- retain immediate normal overflow; subsequent Dial retries also use rotation.
  IF p_direct THEN RETURN; END IF;
  RETURN QUERY SELECT a.agent_id,a.agent_name,'round_robin'::text
    FROM claim_call_agent(p_call_sid,
      array_append(coalesce(p_exclude,'{}'::text[]),p_preferred_agent_id),NULL) a;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_integration_delivery()
 RETURNS SETOF integration_deliveries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE job integration_deliveries; token uuid:=gen_random_uuid();
BEGIN
 IF NOT public.deployment_feature_enabled('PARAGON_ENABLED') THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('integration_claim',0));
  UPDATE integration_deliveries SET status='canceled' WHERE superseded AND status='processing' AND lease_until<=now();
  UPDATE integration_deliveries SET status='failed' WHERE expires_at<=now() AND (status='pending' OR (status='processing' AND lease_until<=now()));
  SELECT d.* INTO job FROM integration_deliveries d
    WHERE (d.kind<>'report' OR public.deployment_feature_enabled('OPERATIONAL_EMAIL_ENABLED')) AND NOT d.superseded AND d.expires_at>now() AND ((d.status='pending' AND d.available_at<=now()) OR (d.status='processing' AND d.lease_until<=now()))
      AND NOT EXISTS (SELECT 1 FROM integration_deliveries running WHERE running.id<>d.id
        AND running.status='processing' AND running.lease_until>now()
        AND coalesce(running.consumer_name,running.source_id::text)=coalesce(d.consumer_name,d.source_id::text))
    ORDER BY CASE WHEN d.kind='push' THEN 0 ELSE 1 END,d.available_at FOR UPDATE OF d SKIP LOCKED LIMIT 1;
  IF job.id IS NULL THEN RETURN; END IF;
  UPDATE integration_deliveries SET status='processing',lease_token=token,lease_until=now()+interval '60 seconds',attempts=attempts+1 WHERE id=job.id RETURNING * INTO job;
  INSERT INTO integration_delivery_attempts(delivery_id,attempt,lease_token) VALUES(job.id,job.attempts,token);
  RETURN NEXT job;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_paragon_call_at(p_call_sid text, p_phone text, p_call_id text, p_exclude text[], p_preferred_agent_id text, p_routing_enabled boolean, p_arrived_at timestamp with time zone)
 RETURNS TABLE(agent_id text, agent_name text, caller_state text, claim_path text, vendor_call_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE src lead_sources; ping paragon_ping_decisions; reserved paragon_agent_reservations;
  selected_id text; selected_tier text; preferred_tier text;
  ctl vendor_controls; cfg vendor_routing_config; local_now timestamp; day_cfg jsonb;
BEGIN
  IF NOT p_routing_enabled OR nullif(p_call_sid,'') IS NULL THEN RETURN; END IF;
  SELECT * INTO src FROM lead_sources WHERE name=public.bootstrap_vendor_source_name() AND type='publisher' AND active LIMIT 1;
  IF src.id IS NULL THEN RETURN; END IF;
  SELECT * INTO ctl FROM vendor_controls WHERE tenant_id=src.tenant_id;
  IF coalesce(ctl.vendor_pause,false) THEN RETURN; END IF;
  -- Hours/cap apply only to NEW pings; the arrival must honor the 30s commitment.
  IF p_arrived_at IS NULL OR p_arrived_at>clock_timestamp()+interval '5 seconds' THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_call_sid,0));
  RETURN QUERY SELECT a.agent_id,a.agent_name,i.caller_state,'existing'::text,i.aggregator_call_id
    FROM agent_availability a JOIN inbound_calls i ON i.twilio_call_sid=p_call_sid
    WHERE a.active_call_sid=p_call_sid AND i.caller_state IS NOT NULL LIMIT 1;
  IF FOUND THEN RETURN; END IF;
  SELECT * INTO ping FROM paragon_ping_decisions d WHERE d.source_id=src.id AND d.available
    AND (d.matched_call_sid IS NULL OR d.matched_call_sid=p_call_sid)
    AND d.received_at<=p_arrived_at AND d.accepted_until>=p_arrived_at
    AND ((nullif(p_call_id,'') IS NOT NULL AND d.vendor_call_id=p_call_id)
      OR (nullif(p_phone,'') IS NOT NULL AND d.caller_phone=p_phone
        AND (nullif(p_call_id,'') IS NULL OR d.vendor_call_id IS NULL)))
    ORDER BY (d.vendor_call_id=p_call_id) DESC NULLS LAST,d.received_at DESC FOR UPDATE SKIP LOCKED LIMIT 1;
  IF ping.id IS NULL OR ping.caller_state IS NULL THEN RETURN; END IF;
  SELECT * INTO cfg FROM vendor_routing_config WHERE source_id=src.id;
  IF cfg.source_id IS NULL OR NOT ping.caller_state=ANY(cfg.allowed_states) THEN RETURN; END IF;
  SELECT * INTO reserved FROM paragon_agent_reservations r WHERE r.source_id=src.id
    AND r.reservation_key=CASE WHEN ping.vendor_call_id IS NOT NULL THEN 'id:'||ping.vendor_call_id
      ELSE 'phone:'||ping.caller_phone END AND r.expires_at>=p_arrived_at
    AND r.consumed_call_sid IS NULL FOR UPDATE;
  -- A reserved agent is used only while still routable and eligible.
  IF reserved.id IS NOT NULL AND reserved.agent_id<>ALL(coalesce(p_exclude,'{}'))
    AND public.paragon_agent_tier(reserved.agent_id,ping.caller_state,src.id) IN ('full','partial')
    AND (public.paragon_agent_tier(reserved.agent_id,ping.caller_state,src.id)='full'
      OR NOT EXISTS(SELECT 1 FROM agent_availability f
        WHERE public.agent_inbound_routable(f.agent_id,f.status,f.available,f.active_call_sid)
          AND public.paragon_agent_tier(f.agent_id,ping.caller_state,src.id)='full'
          AND f.agent_id<>ALL(coalesce(p_exclude,'{}'))))
    AND EXISTS(SELECT 1 FROM agent_availability a WHERE a.agent_id=reserved.agent_id
      AND public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)) THEN
    selected_id:=reserved.agent_id; claim_path:='reserved';
  ELSE
    preferred_tier:=public.paragon_agent_tier(p_preferred_agent_id,ping.caller_state,src.id);
    SELECT a.agent_id,public.paragon_agent_tier(a.agent_id,ping.caller_state,src.id)
      INTO selected_id,selected_tier FROM agent_availability a
      WHERE public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)
        AND a.agent_id<>ALL(coalesce(p_exclude,'{}'))
        AND public.paragon_agent_tier(a.agent_id,ping.caller_state,src.id) IN ('full','partial')
        AND NOT EXISTS(SELECT 1 FROM paragon_agent_reservations r WHERE r.agent_id=a.agent_id
          AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL AND r.id IS DISTINCT FROM reserved.id)
      ORDER BY CASE public.paragon_agent_tier(a.agent_id,ping.caller_state,src.id)
        WHEN 'full' THEN 0 ELSE 1 END,
        CASE WHEN a.agent_id=p_preferred_agent_id THEN 0 ELSE 1 END,
        a.last_assigned_at ASC NULLS FIRST,a.agent_id
      FOR UPDATE OF a SKIP LOCKED LIMIT 1;
    claim_path:=CASE WHEN selected_id=p_preferred_agent_id AND preferred_tier=selected_tier
      THEN 'preferred' ELSE 'round_robin' END;
  END IF;
  IF selected_id IS NULL THEN
    RETURN QUERY SELECT NULL::text,NULL::text,ping.caller_state,'rejected'::text,ping.vendor_call_id;
    RETURN;
  END IF;
  RETURN QUERY UPDATE agent_availability a
    SET active_call_sid=p_call_sid,resume_status=a.status,status='busy',available=false,
      last_assigned_at=clock_timestamp(),toggled_at=clock_timestamp()
    WHERE a.agent_id=selected_id AND a.active_call_sid IS NULL
    RETURNING a.agent_id,a.agent_name,ping.caller_state,claim_path,ping.vendor_call_id;
  IF FOUND THEN
    UPDATE paragon_ping_decisions SET matched_call_sid=p_call_sid WHERE id=ping.id;
    UPDATE paragon_agent_reservations SET consumed_call_sid=p_call_sid WHERE id=reserved.id;
    PERFORM seed_paragon_billing();
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_paragon_report_email(p_date date, p_call_count integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_status text; v_lease timestamptz; v_id bigint;
BEGIN
 IF NOT public.deployment_feature_enabled('OPERATIONAL_EMAIL_ENABLED') THEN RETURN NULL; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('paragon-report-email:' || p_date::text,0));
  SELECT status,lease_until INTO v_status,v_lease FROM paragon_report_email_days WHERE report_date=p_date;
  IF v_status='sent' OR v_status='skipped' OR (v_status='sending' AND v_lease>clock_timestamp()) THEN RETURN NULL; END IF;
  INSERT INTO paragon_report_email_days(report_date,status,lease_until)
    VALUES(p_date,CASE WHEN p_call_count=0 THEN 'skipped' ELSE 'sending' END,clock_timestamp()+interval '10 minutes')
    ON CONFLICT(report_date) DO UPDATE SET status=EXCLUDED.status,lease_until=EXCLUDED.lease_until,updated_at=clock_timestamp();
  INSERT INTO paragon_report_email_log(report_date,status,call_count)
    VALUES(p_date,CASE WHEN p_call_count=0 THEN 'skipped' ELSE 'sending' END,p_call_count) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_paragon_residence_jobs(p_limit integer DEFAULT 5)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE j paragon_residence_jobs;c inbound_calls;segs jsonb;cp jsonb;sp jsonb; token uuid;
BEGIN
 IF NOT public.deployment_feature_enabled('PARAGON_ENABLED') THEN RETURN; END IF;
 -- Discovery is separate from call ingress: no new trigger can delay routing.
 INSERT INTO paragon_residence_jobs(inbound_call_id,tenant_id)
 SELECT i.id,i.tenant_id FROM inbound_calls i JOIN lead_sources s ON s.id=i.lead_source_id AND s.tenant_id=i.tenant_id
 WHERE s.name=public.bootstrap_vendor_source_name() AND s.type='publisher' AND i.source_kind='publisher'
 AND i.created_at>=(SELECT enabled_at FROM paragon_residence_settings WHERE singleton)
 ON CONFLICT DO NOTHING;
 FOR j IN SELECT * FROM paragon_residence_jobs WHERE available_at<=clock_timestamp()
 AND (lease_until IS NULL OR lease_until<clock_timestamp()) ORDER BY available_at LIMIT least(greatest(p_limit,1),20) FOR UPDATE SKIP LOCKED
 LOOP
  token:=gen_random_uuid();
  UPDATE paragon_residence_jobs SET lease_token=token,lease_until=clock_timestamp()+interval '45 seconds' WHERE inbound_call_id=j.inbound_call_id;
  SELECT * INTO c FROM inbound_calls WHERE id=j.inbound_call_id AND tenant_id=j.tenant_id;
  SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.captured_at,t.id),'[]') INTO segs FROM (
   SELECT x.id,x.speaker,x.text,x.captured_at FROM telephony_transcript_segments x
   JOIN telephony_call_attempts a ON a.id=x.attempt_id
   WHERE a.inbound_call_id=c.id AND a.tenant_id=c.tenant_id
   ORDER BY x.captured_at DESC,x.id DESC LIMIT 200
  ) t;
  -- Positive per-value provenance is mandatory. An fmo/manual label is insufficient:
  -- vendor lead intake can fill missing ZIPs on previously manual contacts.
  SELECT jsonb_build_object('zip',ct.zip,'state',NULL,'observed_at',o.recorded_at) INTO cp
   FROM contacts ct JOIN paragon_contact_zip_origin o ON o.contact_id=ct.id AND o.tenant_id=ct.tenant_id
   WHERE ct.id=c.contact_id AND ct.tenant_id=c.tenant_id AND o.zip=ct.zip AND o.contact_version=ct.updated_at AND o.metadata->>'source'='agent_entered';
  SELECT jsonb_build_object('zip',zip,'state',state,'county_fips',county_fips,'observed_at',observed_at) INTO sp
   FROM paragon_residence_sep_inputs WHERE inbound_call_id=c.id AND tenant_id=c.tenant_id;
  RETURN NEXT jsonb_build_object('inbound_call_id',c.id,'lease_token',token,'capture',j.capture,'metadata',j.metadata,'segments',segs,'contact',cp,'sep',sp);
 END LOOP;
END; $function$

CREATE OR REPLACE FUNCTION public.claim_post_call_webhook(p_call_record_id uuid, p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 IF NOT public.deployment_feature_enabled('GHL_ENABLED') THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM call_records WHERE id=p_call_record_id AND tenant_id=p_tenant_id AND NOT coalesce(webhook_sent,false)) THEN RETURN false; END IF;
 INSERT INTO post_call_webhook_claims(call_record_id) VALUES(p_call_record_id) ON CONFLICT DO NOTHING;
 RETURN FOUND;
END; $function$

CREATE OR REPLACE FUNCTION public.client_recap_render(fields jsonb, t jsonb, ch text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE body text:=t->>'body'; k text; v text; rendered text;
BEGIN
 IF ch NOT IN ('sms','pdf') OR fields-ARRAY['firstName','planName','carrier','planType','effectiveDate','confirmationNumber','agentName','agencyName','callbackNumber']<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid fields' USING ERRCODE='22023'; END IF;
 FOR k,v IN SELECT key,value FROM jsonb_each_text(fields) LOOP
  v:=coalesce(nullif(v,''),'Not recorded');
  IF length(v)>200 OR v ~ '[{}\x00-\x1F\x7F]' THEN RAISE EXCEPTION 'Invalid field' USING ERRCODE='22023'; END IF;
  body:=replace(body,'{{'||k||'}}',v);
 END LOOP;
 rendered:=body||CASE WHEN ch='sms' THEN ' ' ELSE E'\n\n' END||(t->>'next')||CASE WHEN ch='sms' THEN ' ' ELSE E'\n\n' END||(t->>'disclaimer');
 IF ch='sms' AND nullif(fields->>'confirmationNumber','') IS NOT NULL AND strpos(rendered,fields->>'confirmationNumber')>0 THEN RAISE EXCEPTION 'Confirmation unavailable in text' USING ERRCODE='22023'; END IF;
 IF ch='sms' AND length(rendered)>480 OR length(rendered)>2600 THEN RAISE EXCEPTION 'Recap exceeds channel limit' USING ERRCODE='22023'; END IF;
 RETURN rendered;
END $function$

CREATE OR REPLACE FUNCTION public.client_recap_source(p_actor text, p_org text, p_id uuid, p_status_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE identity record; e public.enrollment_intakes; c public.call_records; consumer public.contacts; fields jsonb; settings jsonb; profile jsonb; history jsonb; missing text[]:='{}'; reason text; can_send boolean;
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('CLIENT_RECAP_ENABLED') THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO identity FROM public.resolve_deployment_subject(p_actor,p_org);
 IF identity.tenant_id IS NULL THEN RAISE EXCEPTION 'Membership required' USING ERRCODE='42501'; END IF;
 SELECT * INTO e FROM public.enrollment_intakes WHERE id=p_id AND tenant_id=identity.tenant_id;
 SELECT * INTO c FROM public.call_records WHERE id=e.call_id AND tenant_id=identity.tenant_id;
 SELECT * INTO consumer FROM public.contacts WHERE id=e.contact_id AND tenant_id=identity.tenant_id;
 IF e.id IS NULL OR c.id IS NULL OR consumer.id IS NULL OR NOT (identity.authority='admin' OR c.agent_id=identity.agent_id AND consumer.assigned_agent_id=identity.agent_slug OR identity.authority='manager' AND c.agent_id=ANY(identity.team_agent_ids) AND EXISTS(SELECT 1 FROM public.tenant_agents a JOIN public.enrolled_agents ea ON ea.clerk_user_id=a.clerk_user_id AND ea.tenant_id=a.tenant_id WHERE a.tenant_id=identity.tenant_id AND a.agent_slug=consumer.assigned_agent_id AND ea.id=ANY(identity.team_agent_ids))) THEN RAISE EXCEPTION 'Enrollment unavailable' USING ERRCODE='42501'; END IF;
 can_send:=identity.authority='admin' OR identity.authority='agent' AND c.agent_id=identity.agent_id;
 IF p_status_only IS DISTINCT FROM true AND NOT can_send THEN RAISE EXCEPTION 'Status only' USING ERRCODE='42501'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'channel',r.channel,'template_version',r.template_version,'approved_by',r.approved_by,'approved_at',r.approved_at,'status',r.status,'sha256',r.content_sha256,'out_of_date',e.updated_at>r.enrollment_updated_at) ORDER BY r.approved_at,r.id),'[]') INTO history FROM public.client_recaps r WHERE r.enrollment_id=e.id AND r.tenant_id=e.tenant_id;
 IF p_status_only IS TRUE THEN RETURN jsonb_build_object('history',history,'can_send',can_send,'admin',identity.authority='admin'); END IF;
 IF e.completed_at IS NULL OR e.submitted_at IS NULL OR e.is_test_enrollment THEN missing:=array_append(missing,'submitted enrollment'); END IF;
 IF nullif(btrim(e.data->>'planName'),'') IS NULL THEN missing:=array_append(missing,'plan name'); END IF;
 IF nullif(btrim(e.data->>'newCarrier'),'') IS NULL THEN missing:=array_append(missing,'carrier'); END IF;
 IF nullif(btrim(e.data->>'effectiveDate'),'') IS NULL THEN missing:=array_append(missing,'effective date'); END IF;
 SELECT public_profile INTO profile FROM public.deployment_settings WHERE singleton AND tenant_id=e.tenant_id;
 SELECT client_recap_templates INTO settings FROM public.tenants WHERE id=e.tenant_id;
 fields:=jsonb_build_object('firstName',e.data->>'firstName','planName',e.data->>'planName','carrier',e.data->>'newCarrier','planType',e.data->>'planType','effectiveDate',e.data->>'effectiveDate','confirmationNumber',coalesce(nullif(e.data->>'sunfireCode',''),e.data->>'enrollmentId'),'agentName',(SELECT name FROM public.enrolled_agents WHERE id=c.agent_id AND tenant_id=e.tenant_id),'agencyName',profile->>'agencyName','callbackNumber',profile->>'agencyLine');
 -- Existing DNC flag and permission records are authoritative; inbound STOP is
 -- conservatively permanent here (no inferred reconsent from a later message).
 reason:=CASE WHEN consumer.do_not_call THEN 'Consumer opted out.'
 WHEN EXISTS(SELECT 1 FROM public.messages m WHERE m.tenant_id=e.tenant_id AND m.contact_id=e.contact_id AND m.direction='inbound' AND upper(btrim(m.body)) IN ('STOP','STOPALL','UNSUBSCRIBE','CANCEL','END','QUIT','REVOKE','OPTOUT')) THEN 'Consumer opted out.'
 WHEN NOT EXISTS(SELECT 1 FROM public.call_records pc WHERE pc.tenant_id=e.tenant_id AND pc.contact_id=e.contact_id AND pc.ptc_on_file IS TRUE AND pc.ptc_date IS NOT NULL AND pc.ptc_date<=current_date AND pc.ptc_expiry IS NOT NULL AND pc.ptc_expiry>=current_date) THEN 'Current permission to contact is missing.'
 WHEN NOT EXISTS(SELECT 1 FROM public.messages m JOIN public.call_records pc ON pc.tenant_id=m.tenant_id AND pc.contact_id=m.contact_id WHERE m.tenant_id=e.tenant_id AND m.contact_id=e.contact_id AND m.channel='sms' AND m.direction='inbound' AND upper(btrim(m.body)) IN ('START','UNSTOP') AND pc.ptc_on_file IS TRUE AND pc.ptc_date IS NOT NULL AND pc.ptc_date<=current_date AND pc.ptc_expiry>=current_date AND m.created_at>=pc.ptc_date::timestamptz AND m.created_at<=clock_timestamp()) THEN 'Recorded text opt-in is missing.'
 WHEN public.normalize_phone_e164(consumer.phone) IS NULL THEN 'Consumer phone is missing or invalid.' ELSE NULL END;
 RETURN jsonb_build_object('fields',fields,'templates',settings,'missing',missing,'sms_reason',reason,'history',history,'can_send',can_send,'admin',identity.authority='admin','revision',e.updated_at);
END $function$

CREATE OR REPLACE FUNCTION public.combine_call_records(p_tenant_id uuid, p_actor text, p_admin boolean, p_action text, p_first uuid, p_second uuid, p_confirm_different boolean DEFAULT false, p_expected_primary uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE first_call call_records; second_call call_records; primary_id uuid; child_id uuid;
  affected uuid[]; subject_slug text; actor_agent uuid; activity_contact uuid;
BEGIN
  IF p_action NOT IN ('preview','combine','uncombine') OR p_first=p_second THEN
    RAISE EXCEPTION 'Invalid call selection' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant_id::text,118));
  SELECT * INTO first_call FROM call_records WHERE id=p_first AND tenant_id=p_tenant_id FOR UPDATE;
  SELECT * INTO second_call FROM call_records WHERE id=p_second AND tenant_id=p_tenant_id FOR UPDATE;
  IF first_call.id IS NULL OR second_call.id IS NULL THEN
    RAISE EXCEPTION 'Call unavailable' USING ERRCODE='42501';
  END IF;
  SELECT id INTO actor_agent FROM enrolled_agents WHERE tenant_id=p_tenant_id
    AND clerk_user_id=p_actor AND is_active=true;
  SELECT agent_slug INTO subject_slug FROM recording_agent_subjects
    WHERE tenant_id=p_tenant_id AND clerk_user_id=p_actor;
  SELECT array_agg(id ORDER BY id) INTO affected FROM call_records WHERE tenant_id=p_tenant_id
    AND (id IN (p_first,p_second) OR parent_call_id IN (p_first,p_second));
  IF NOT p_admin AND (actor_agent IS NULL OR EXISTS (
    SELECT 1 FROM call_records c WHERE c.id=ANY(affected) AND (
      EXISTS (SELECT 1 FROM telephony_call_attempts a WHERE a.call_record_id=c.id
        AND a.tenant_id=p_tenant_id AND a.agent_id IS DISTINCT FROM subject_slug)
      OR NOT (EXISTS (SELECT 1 FROM sessions s WHERE s.id=c.session_id
        AND s.call_record_id=c.id AND s.tenant_id=p_tenant_id AND s.agent_id=actor_agent)
        OR (c.session_id IS NULL AND EXISTS (SELECT 1 FROM telephony_call_attempts a
          WHERE a.call_record_id=c.id AND a.tenant_id=p_tenant_id AND a.agent_id=subject_slug))))
  )) THEN RAISE EXCEPTION 'Call unavailable for this agent' USING ERRCODE='42501'; END IF;

  IF p_action='uncombine' THEN
    IF first_call.parent_call_id IS NOT NULL OR second_call.parent_call_id IS DISTINCT FROM p_first THEN
      RAISE EXCEPTION 'Calls changed; reload before uncombining' USING ERRCODE='22023';
    END IF;
    primary_id:=p_first; child_id:=p_second; affected:=ARRAY[p_first,p_second];
    UPDATE call_records SET parent_call_id=NULL WHERE id=child_id;
  ELSE
    IF first_call.parent_call_id IS NOT NULL OR second_call.parent_call_id IS NOT NULL THEN
      RAISE EXCEPTION 'Calls changed; reload before combining' USING ERRCODE='22023';
    END IF;
    -- Missing either recording falls back to measured talk, then earlier call.
    SELECT f.id INTO primary_id FROM v_call_combine_facts f WHERE f.id IN (p_first,p_second)
      ORDER BY CASE WHEN (SELECT count(recording_seconds) FROM v_call_combine_facts
        WHERE id IN (p_first,p_second))=2 THEN f.recording_seconds ELSE NULL END DESC NULLS LAST,
        f.talk_seconds DESC NULLS LAST,f.occurred_at ASC NULLS LAST,f.id LIMIT 1;
    child_id:=CASE WHEN primary_id=p_first THEN p_second ELSE p_first END;
    IF p_action='preview' THEN
      RETURN jsonb_build_object('primary_id',primary_id,'child_id',child_id,
        'different_contacts',first_call.contact_id IS DISTINCT FROM second_call.contact_id,
        'calls',(SELECT jsonb_agg(coalesce(to_jsonb(e),'{}'::jsonb)||jsonb_build_object(
          'call_record_id',c.id,'log_id',coalesce(e.log_id,'cr-'||c.id),
          'occurred_at',coalesce(e.occurred_at,c.call_start,c.created_at),
          'agent',coalesce(e.agent,c.writing_agent,c.agent_name::text),
          'disposition',e.disposition,'call_outcome',c.call_outcome,
          'recording_seconds',f.recording_seconds,'original_talk_seconds',f.talk_seconds))
          FROM call_records c JOIN v_call_combine_facts f ON f.id=c.id
          LEFT JOIN LATERAL (SELECT * FROM v_call_log_entries entry
            WHERE entry.call_record_id=c.id AND entry.tenant_id=c.tenant_id
            ORDER BY entry.occurred_at,entry.log_id LIMIT 1) e ON true
          WHERE c.tenant_id=p_tenant_id AND c.id IN (p_first,p_second)));
    END IF;
    IF p_expected_primary IS DISTINCT FROM primary_id THEN
      RAISE EXCEPTION 'Call durations changed; review the calls again' USING ERRCODE='22023';
    END IF;
    IF first_call.contact_id IS DISTINCT FROM second_call.contact_id AND NOT p_confirm_different THEN
      RAISE EXCEPTION 'Confirm different contacts before combining' USING ERRCODE='22023';
    END IF;
    -- Re-parent children first so the final update never creates a chain.
    UPDATE call_records SET parent_call_id=primary_id WHERE tenant_id=p_tenant_id AND parent_call_id=child_id;
    UPDATE call_records SET parent_call_id=primary_id WHERE id=child_id;
  END IF;
  FOR activity_contact IN SELECT DISTINCT contact_id FROM call_records
    WHERE id=ANY(affected) LOOP
    INSERT INTO contact_activities(tenant_id,contact_id,type,ref_id,summary,actor_clerk_user_id,call_action_details)
      VALUES(p_tenant_id,activity_contact,'call',primary_id,
        CASE WHEN p_action='combine' THEN 'Combined calls' ELSE 'Uncombined call' END,
        p_actor,jsonb_build_object('action',p_action,'primary_call_id',primary_id,'child_call_id',child_id,
          'affected_call_ids',affected));
  END LOOP;
  RETURN jsonb_build_object('primary_id',primary_id,'child_id',child_id);
END $function$

CREATE OR REPLACE FUNCTION public.complete_conference_agent_transfer(p_call_id uuid, p_participant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE room call_conferences; p call_participants; owner enrolled_agents;
BEGIN
 IF EXISTS(SELECT 1 FROM public.call_participants WHERE id=p_participant_id AND role='supervisor') THEN RAISE EXCEPTION 'Coach is isolated' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT room FROM call_conferences WHERE call_id=p_call_id FOR UPDATE;
 SELECT * INTO STRICT p FROM call_participants WHERE id=p_participant_id AND call_id=p_call_id AND status='connected';
 IF p.agent_id IS NULL THEN RETURN; END IF;
 SELECT e.* INTO STRICT owner FROM enrolled_agents e JOIN availability_agent_subjects r
 ON r.tenant_id=e.tenant_id AND r.clerk_user_id=e.clerk_user_id
 WHERE r.tenant_id=room.tenant_id AND r.agent_slug=p.agent_id AND r.is_active AND e.is_active;
 IF NOT EXISTS(SELECT 1 FROM agent_availability WHERE agent_id=p.agent_id AND active_call_sid=room.parent_call_sid)
 THEN RAISE EXCEPTION 'Receiving agent reservation lost'; END IF;
 UPDATE call_records SET agent_id=owner.id,agent_name=owner.name WHERE id=p_call_id;
 UPDATE sessions SET agent_id=owner.id WHERE call_record_id=p_call_id AND tenant_id=room.tenant_id;
 UPDATE call_transcripts SET owner_agent_id=owner.id WHERE call_record_id=p_call_id AND tenant_id=room.tenant_id;
 UPDATE telephony_call_attempts SET agent_id=p.agent_id WHERE id=room.attempt_id;
 UPDATE call_participants SET role='agent' WHERE id=p.id;
 UPDATE call_conferences SET owner_agent_id=p.agent_id WHERE call_id=p_call_id;
END $function$

CREATE OR REPLACE FUNCTION public.configure_deployment_vendor(p_vendor jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE deployment deployment_settings; source uuid; item jsonb; required text[]; critical text[]; states text[];
BEGIN
 SELECT * INTO STRICT deployment FROM deployment_settings WHERE singleton;
 INSERT INTO deployment_vendor_settings(singleton,source_name) VALUES(true,p_vendor->>'sourceName') ON CONFLICT(singleton) DO UPDATE SET source_name=excluded.source_name;
 SELECT array_agg(value) INTO states FROM jsonb_array_elements_text(p_vendor->'states');
 SELECT array_agg(value) INTO required FROM jsonb_array_elements_text(p_vendor->'requiredCarriers');
 SELECT array_agg(value) INTO critical FROM jsonb_array_elements_text(p_vendor->'criticalCarriers');
 INSERT INTO lead_sources(tenant_id,name,type,ping_key_hash,postback_url,postback_secret,report_emails,active)
 VALUES(deployment.tenant_id,p_vendor->>'sourceName','publisher',p_vendor->>'pingKeyHash',p_vendor->>'postbackUrl',p_vendor->>'postbackSecret',ARRAY(SELECT jsonb_array_elements_text(coalesce(p_vendor->'reportRecipients','[]'))),true)
 ON CONFLICT(tenant_id,name) DO UPDATE SET ping_key_hash=excluded.ping_key_hash,postback_url=excluded.postback_url,postback_secret=excluded.postback_secret,report_emails=excluded.report_emails,active=true RETURNING id INTO source;
 INSERT INTO availability_consumers(name,key_hash,active,push_url,push_secret,push_enabled)
 VALUES(p_vendor->>'sourceName',p_vendor->>'availabilityKeyHash',true,p_vendor->>'pushUrl',p_vendor->>'pushSecret',true)
 ON CONFLICT(name) DO UPDATE SET key_hash=excluded.key_hash,active=true,push_url=excluded.push_url,push_secret=excluded.push_secret,push_enabled=true;
 INSERT INTO vendor_routing_config(source_id,allowed_states,required_carriers,critical_carriers,plan_year,reservation_ttl_seconds)
 VALUES(source,states,required,critical,(p_vendor->>'planYear')::integer,(p_vendor->>'reservationTtlSeconds')::integer)
 ON CONFLICT(source_id) DO UPDATE SET allowed_states=excluded.allowed_states,required_carriers=excluded.required_carriers,critical_carriers=excluded.critical_carriers,plan_year=excluded.plan_year,reservation_ttl_seconds=excluded.reservation_ttl_seconds;
 INSERT INTO vendor_controls(tenant_id,vendor_pause,staffed_hours,paragon_daily_cap,paragon_cap_mode,paragon_rate,updated_by)
 VALUES(deployment.tenant_id,true,jsonb_build_object('timezone',deployment.public_profile->>'timezone','days',deployment.public_profile->'staffedHours'),(p_vendor->>'dailyCap')::integer,p_vendor->>'capMode',(p_vendor->>'rate')::numeric,'deployment-operator')
 ON CONFLICT(tenant_id) DO UPDATE SET staffed_hours=excluded.staffed_hours,paragon_daily_cap=excluded.paragon_daily_cap,paragon_cap_mode=excluded.paragon_cap_mode,paragon_rate=excluded.paragon_rate,updated_by=excluded.updated_by;
 INSERT INTO paragon_report_tokens(source_id,token_hash,updated_by) VALUES(source,p_vendor->>'reportTokenHash','deployment-operator')
 ON CONFLICT(source_id) DO UPDATE SET token_hash=excluded.token_hash,updated_by=excluded.updated_by;
 DELETE FROM vendor_agent_state_eligibility WHERE source_id=source;
 FOR item IN SELECT * FROM jsonb_array_elements(p_vendor->'eligibility') LOOP
  IF NOT EXISTS(SELECT 1 FROM tenant_agents WHERE tenant_id=deployment.tenant_id AND id=(item->>'agentId')::uuid AND is_active AND licensed_states ? (item->>'state')) THEN RAISE EXCEPTION 'Vendor matrix requires an active licensed roster binding'; END IF;
