END $function$

CREATE OR REPLACE FUNCTION public.configure_operational_profile(p_summary jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tenant uuid; previous jsonb;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Operator required' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_summary)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each(p_summary) WHERE key NOT IN ('alert_audit_failures','alert_delivery_retry_seconds','alert_evaluation_seconds','alert_exhausted_jobs','alert_lease_conflicts','alert_paid_budget_percent','alert_provider_error_percent','alert_provider_minimum_requests','alert_purge_failures','alert_queue_age_seconds','alert_queue_depth','alert_rate_rejections','alert_routing_anomalies','alert_secret_review_days','alert_subject_denials','alert_window_seconds','approved_retention_overrides','feature_consumer_lifecycle_enabled','feature_post_call_coaching_enabled','feature_client_recap_enabled','feature_supervisor_whisper_enabled','feature_supervisor_floor_enabled','feature_supervisor_listen_enabled','feature_reshop_list_enabled','feature_ping_platform_enabled','feature_ping_shadow_enabled','feature_ping_retention_alerts_enabled','feature_ping_scorecard_enabled','feature_ping_screener_enabled','feature_ping_exchange_enabled','feature_conference_calling_enabled','feature_conversely_upload_enabled','feature_daily_verse_enabled','feature_ghl_enabled','feature_ix_report_enabled','feature_ix_upload_enabled','feature_operational_email_enabled','feature_paragon_enabled','feature_paragon_state_routing_enabled','feature_retention_purge_enabled','feature_scoring_enabled','feature_stripe_billing_enabled','feature_transcript_auto_recovery_enabled','feature_transcript_gap_fill_enabled','retention_contact_review_years','retention_enrollment_recording_years','retention_enrollment_transcript_years','retention_enrollment_years','retention_evidence_audit_years','retention_marketing_recording_years','retention_marketing_transcript_years','retention_operational_days','retention_reduced_marketing_rule','retention_scope_of_appointment_years','retention_service_call_years','retention_text_consent_years') OR jsonb_typeof(value) NOT IN ('number','boolean')) THEN RAISE EXCEPTION 'Invalid operational profile'; END IF;
 SELECT tenant_id INTO tenant FROM public.deployment_settings WHERE singleton;
 SELECT summary INTO previous FROM public.operational_configuration WHERE tenant_id=tenant FOR UPDATE;
 IF previous IS NOT DISTINCT FROM p_summary THEN RETURN; END IF;
 INSERT INTO public.operational_configuration VALUES(tenant,p_summary) ON CONFLICT(tenant_id) DO UPDATE SET summary=excluded.summary;
 BEGIN
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,before_summary,after_summary)
 VALUES(gen_random_uuid(),'service:deployment_operator',tenant,'operator_operational_profile','operational_configuration',tenant::text,'succeeded',coalesce(previous,'{}'),p_summary);
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Administrator audit unavailable' USING ERRCODE='P1611'; END;
END $function$

CREATE OR REPLACE FUNCTION public.connect_supervisor_listen(p_actor text, p_org text, p_session text, p_hash text, p_attempt uuid, p_seconds integer, p_call_limit integer, p_agency_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE g public.supervisor_listen_grants; target jsonb; s record; now_at timestamptz:=clock_timestamp();
BEGIN
 target:=public.supervisor_listen_authorize(p_actor,p_org,p_attempt);
 PERFORM pg_advisory_xact_lock(hashtextextended('supervisor-listen:'||(target->>'tenant'),0));
 IF p_seconds NOT BETWEEN 1 AND 7200 OR p_call_limit NOT BETWEEN 1 AND 10 OR p_agency_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid limits'; END IF;
 SELECT * INTO g FROM public.supervisor_listen_grants WHERE token_hash=p_hash FOR UPDATE;
 IF g.mode<>'listen' OR g.id IS NULL OR g.actor_id<>p_actor OR g.session_id<>p_session OR g.attempt_id<>p_attempt OR g.tenant_id::text<>target->>'tenant' OR g.agent_id::text<>target->>'agent' OR g.expires_at<=now_at OR g.used_at IS NOT NULL THEN RAISE EXCEPTION 'Invalid grant' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.telephony_events WHERE tenant_id=g.tenant_id AND event='session_lock' AND payload->>'clerk_user_id'=p_actor AND occurred_at>=g.created_at) THEN RAISE EXCEPTION 'Session locked' USING ERRCODE='42501'; END IF;
 FOR s IN SELECT id FROM public.supervisor_listen_sessions WHERE tenant_id=g.tenant_id AND ended_at IS NULL AND (lease_until<=now_at OR expires_at<=now_at) LOOP PERFORM public.finish_supervisor_listen(s.id); END LOOP;
 IF EXISTS(SELECT 1 FROM public.supervisor_listen_sessions WHERE actor_id=p_actor AND ended_at IS NULL)
 OR (SELECT count(*) FROM public.supervisor_listen_sessions WHERE attempt_id=p_attempt AND ended_at IS NULL)>=p_call_limit
 OR (SELECT count(*) FROM public.supervisor_listen_sessions WHERE tenant_id=g.tenant_id AND ended_at IS NULL)>=p_agency_limit THEN RAISE EXCEPTION 'Listen limit' USING ERRCODE='54000'; END IF;
 UPDATE public.supervisor_listen_grants SET used_at=now_at WHERE id=g.id;
 INSERT INTO public.supervisor_listen_sessions(id,tenant_id,actor_id,session_id,agent_id,attempt_id,call_id,started_at,expires_at,lease_until)
 VALUES(g.id,g.tenant_id,g.actor_id,g.session_id,g.agent_id,g.attempt_id,g.call_id,now_at,now_at+make_interval(secs=>p_seconds),now_at+interval '8 seconds');
 -- Both inserts commit with the session or no audio is authorized.
 BEGIN
 INSERT INTO public.evidence_access_log(actor_id,tenant_id,resource_type,resource_id,action,result,grant_id,occurred_at) VALUES(p_actor,g.tenant_id,'supervisor_listen',coalesce(g.call_id,g.attempt_id)::text,'play','allowed',g.id,now_at);
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Evidence audit unavailable' USING ERRCODE='P1571'; END;
 BEGIN
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,occurred_at,after_summary) VALUES(gen_random_uuid(),p_actor,g.tenant_id,'supervisor_listen_start','supervisor_listen_sessions',g.id::text,'succeeded',now_at,jsonb_build_object('agent_id',g.agent_id,'call_id',coalesce(g.call_id,g.attempt_id)));
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Administrator audit unavailable' USING ERRCODE='P1611'; END;
 RETURN jsonb_build_object('id',g.id,'tenant',g.tenant_id,'agent',g.agent_id,'attempt',g.attempt_id,'expires',now_at+make_interval(secs=>p_seconds));
END $function$

CREATE OR REPLACE FUNCTION public.connect_supervisor_whisper(p_actor text, p_org text, p_session text, p_hash text, p_attempt uuid, p_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE g public.supervisor_listen_grants; target jsonb; s record; at timestamptz:=clock_timestamp();
BEGIN
 target:=public.supervisor_whisper_authorize(p_actor,p_org,p_attempt);
 PERFORM pg_advisory_xact_lock(hashtextextended('supervisor-listen:'||(target->>'tenant'),0));
 IF p_seconds NOT BETWEEN 1 AND 7200 THEN RAISE EXCEPTION 'Invalid limit'; END IF;
 SELECT * INTO g FROM public.supervisor_listen_grants WHERE token_hash=p_hash FOR UPDATE;
 IF g.id IS NULL OR g.mode<>'whisper' OR g.actor_id<>p_actor OR g.session_id<>p_session OR g.attempt_id<>p_attempt OR g.tenant_id::text<>target->>'tenant' OR g.agent_id::text<>target->>'agent' OR g.call_id IS DISTINCT FROM (target->>'call')::uuid OR g.expires_at<=at OR g.used_at IS NOT NULL THEN RAISE EXCEPTION 'Invalid grant' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.telephony_events WHERE tenant_id=g.tenant_id AND event='session_lock' AND payload->>'clerk_user_id'=p_actor AND occurred_at>=g.created_at) THEN RAISE EXCEPTION 'Session locked' USING ERRCODE='42501'; END IF;
 -- Only relay sessions can end here. A coach cap is not freed until its provider
 -- leg is removed by recovery, including expired/crashed sessions.
 FOR s IN SELECT id FROM public.supervisor_listen_sessions WHERE actor_id=p_actor AND attempt_id=p_attempt AND mode='listen' AND ended_at IS NULL LOOP PERFORM public.finish_supervisor_listen(s.id); END LOOP;
 IF EXISTS(SELECT 1 FROM public.supervisor_listen_sessions WHERE ended_at IS NULL AND (actor_id=p_actor OR mode='whisper' AND attempt_id=p_attempt)) THEN RAISE EXCEPTION 'Whisper limit' USING ERRCODE='54000'; END IF;
 UPDATE public.supervisor_listen_grants SET used_at=at WHERE id=g.id;
 INSERT INTO public.supervisor_listen_sessions(id,tenant_id,actor_id,session_id,agent_id,attempt_id,call_id,started_at,expires_at,lease_until,mode)
 VALUES(g.id,g.tenant_id,g.actor_id,g.session_id,g.agent_id,g.attempt_id,g.call_id,at,at+make_interval(secs=>p_seconds),at+interval '8 seconds','whisper');
 BEGIN
 INSERT INTO public.evidence_access_log(actor_id,tenant_id,resource_type,resource_id,action,result,grant_id,occurred_at) VALUES(p_actor,g.tenant_id,'supervisor_whisper',coalesce(g.call_id,g.attempt_id)::text,'play','allowed',g.id,at);
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Evidence audit unavailable' USING ERRCODE='P1571'; END;
 BEGIN
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,occurred_at,after_summary) VALUES(gen_random_uuid(),p_actor,g.tenant_id,'supervisor_whisper_start','supervisor_listen_sessions',g.id::text,'authorized',at,jsonb_build_object('agent_id',g.agent_id,'call_id',coalesce(g.call_id,g.attempt_id)));
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Administrator audit unavailable' USING ERRCODE='P1611'; END;
 RETURN to_jsonb((SELECT x FROM public.supervisor_listen_sessions x WHERE id=g.id));
END $function$

CREATE OR REPLACE FUNCTION public.consume_admission(p_rules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r jsonb; k text; s integer; cap integer; w bigint; n integer; retry integer:=0;
 t bigint:=floor(extract(epoch FROM clock_timestamp()));
BEGIN
 IF jsonb_typeof(p_rules)<>'array' OR jsonb_array_length(p_rules) NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'Invalid admission rules'; END IF;
 -- Lock all keys in a stable order BEFORE reading. Shared daily budgets serialize
 -- requests from different function instances. No read/count then insert race.
 FOR k IN SELECT DISTINCT encode(sha256(convert_to(value->>'key','UTF8')),'hex') FROM jsonb_array_elements(p_rules) ORDER BY 1 LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('admission:'||k,0));
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(p_rules) LOOP
  IF r->>'key' IS NULL OR length(r->>'key') NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'Invalid admission key'; END IF;
  s:=(r->>'seconds')::integer;cap:=(r->>'limit')::integer;
  IF s IS NULL OR cap IS NULL OR s NOT IN (60,300,86400) OR cap NOT BETWEEN 1 AND 1000000 THEN RAISE EXCEPTION 'Invalid admission limit'; END IF;
  k:=encode(sha256(convert_to(r->>'key','UTF8')),'hex');w:=(t/s)*s;
  SELECT used INTO n FROM admission_counters WHERE key_hash=k AND window_start=w AND window_seconds=s;
  IF coalesce(n,0)>=cap THEN retry:=greatest(retry,(w+s-t)::integer); END IF;
 END LOOP;
 IF retry>0 THEN RETURN jsonb_build_object('allowed',false,'retry_after',retry); END IF;
 FOR r IN SELECT DISTINCT value FROM jsonb_array_elements(p_rules) LOOP
  s:=(r->>'seconds')::integer;k:=encode(sha256(convert_to(r->>'key','UTF8')),'hex');w:=(t/s)*s;
  INSERT INTO admission_counters VALUES(k,w,s,1,to_timestamp(w+s))
  ON CONFLICT(key_hash,window_start,window_seconds) DO UPDATE SET used=admission_counters.used+1;
 END LOOP;
 RETURN jsonb_build_object('allowed',true,'retry_after',0);
END $function$

CREATE OR REPLACE FUNCTION public.contacts_normalize_phone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
  IF nullif(btrim(NEW.phone), '') IS NOT NULL AND public.normalize_phone_e164(NEW.phone) IS NULL THEN
    RAISE EXCEPTION 'Enter a valid phone number, including its area code.' USING ERRCODE = '22023';
  END IF;
  NEW.phone := public.normalize_phone_e164(NEW.phone);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.contacts_sync_pii_encrypted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_key RECORD;
  v_fields JSONB := '{}'::jsonb;
BEGIN
  SELECT * INTO v_key FROM pii_vault.get_active_key();
  IF v_key.key_id IS NULL THEN
    RAISE EXCEPTION 'no active PII encryption key configured';
  END IF;

  IF NEW.first_name IS NOT NULL THEN
    v_fields := v_fields || jsonb_build_object('first_name', public.encrypt_pii_value(NEW.first_name));
  END IF;
  IF NEW.last_name IS NOT NULL THEN
    v_fields := v_fields || jsonb_build_object('last_name', public.encrypt_pii_value(NEW.last_name));
  END IF;
  IF NEW.dob IS NOT NULL THEN
    v_fields := v_fields || jsonb_build_object('dob', public.encrypt_pii_value(NEW.dob::text));
  END IF;
  IF NEW.phone IS NOT NULL THEN
    v_fields := v_fields || jsonb_build_object('phone', public.encrypt_pii_value(NEW.phone));
  END IF;
  IF NEW.email IS NOT NULL THEN
    v_fields := v_fields || jsonb_build_object('email', public.encrypt_pii_value(NEW.email));
  END IF;
  IF NEW.address IS NOT NULL THEN
    v_fields := v_fields || jsonb_build_object('address', public.encrypt_pii_value(NEW.address));
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.pii_encrypted IS NOT NULL THEN
    v_fields := (OLD.pii_encrypted - 'first_name' - 'last_name' - 'dob' - 'phone' - 'email' - 'address' - 'mbi_last4') || v_fields;
  END IF;

  NEW.pii_encrypted := v_fields;

  NEW.phone_hash := public.pii_blind_index(public.normalize_phone_e164(NEW.phone));
  NEW.name_search := public.pii_blind_index(concat_ws(' ', NEW.first_name, NEW.last_name));
  NEW.first_initial := CASE WHEN NEW.first_name IS NOT NULL AND length(NEW.first_name) > 0
    THEN upper(left(NEW.first_name, 1)) END;
  NEW.last_initial := CASE WHEN NEW.last_name IS NOT NULL AND length(NEW.last_name) > 0
    THEN upper(left(NEW.last_name, 1)) END;
  NEW.phone_last4 := CASE WHEN NEW.phone IS NOT NULL AND length(regexp_replace(NEW.phone, '[^0-9]', '', 'g')) >= 4
    THEN right(regexp_replace(NEW.phone, '[^0-9]', '', 'g'), 4) END;
  NEW.email_set := NEW.email IS NOT NULL AND btrim(NEW.email) != '';
  NEW.dob_set := NEW.dob IS NOT NULL;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.control_supervisor_whisper(p_id uuid, p_actor text, p_session text, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.supervisor_listen_sessions; at timestamptz:=clock_timestamp();
BEGIN
 IF current_setting('role',true)<>'service_role' OR p_action NOT IN ('talk','mute','confirm','end') THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.supervisor_listen_sessions WHERE id=p_id AND actor_id=p_actor AND session_id=p_session AND mode='whisper' FOR UPDATE;
 IF s.id IS NULL OR s.ended_at IS NOT NULL THEN RETURN; END IF;
 IF p_action IN ('talk','confirm') AND (s.lease_until<=at OR s.expires_at<=at OR s.participant_id IS NULL) THEN RAISE EXCEPTION 'Session expired' USING ERRCODE='42501'; END IF;
 IF p_action='confirm' THEN UPDATE public.supervisor_listen_sessions SET confirmed_at=at WHERE id=p_id; RETURN; END IF;
 IF p_action='talk' AND s.confirmed_at IS NULL THEN RAISE EXCEPTION 'Coaching unconfirmed' USING ERRCODE='42501'; END IF;
 IF p_action='talk' AND s.talk_started_at IS NOT NULL OR p_action='mute' AND s.talk_started_at IS NULL THEN RETURN; END IF;
 IF p_action='end' AND s.participant_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.call_participants WHERE id=s.participant_id AND status<>'left') THEN RAISE EXCEPTION 'Remove coach first'; END IF;
 UPDATE public.supervisor_listen_sessions SET
 talk_seconds=talk_seconds+CASE WHEN talk_started_at IS NULL THEN 0 ELSE greatest(0,extract(epoch FROM at-talk_started_at)) END,
 talk_started_at=CASE WHEN p_action='talk' THEN at END,
 ended_at=CASE WHEN p_action='end' THEN at END,
 duration_seconds=CASE WHEN p_action='end' THEN greatest(0,extract(epoch FROM at-started_at)::integer) END WHERE id=p_id RETURNING * INTO s;
 BEGIN
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,occurred_at,after_summary) VALUES(gen_random_uuid(),s.actor_id,s.tenant_id,'supervisor_whisper_'||p_action,'supervisor_listen_sessions',s.id::text,'authorized',at,jsonb_build_object('agent_id',s.agent_id,'call_id',coalesce(s.call_id,s.attempt_id),'duration_seconds',s.duration_seconds,'talk_seconds',s.talk_seconds));
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Administrator audit unavailable' USING ERRCODE='P1611'; END;
 IF p_action='end' THEN
 BEGIN
 INSERT INTO public.evidence_access_log(actor_id,tenant_id,resource_type,resource_id,action,result,grant_id,occurred_at) VALUES(s.actor_id,s.tenant_id,'supervisor_whisper_end',coalesce(s.call_id,s.attempt_id)::text,'play','allowed',s.id,at);
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Evidence audit unavailable' USING ERRCODE='P1571'; END;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.create_workspace_record(p_table text, p_fields jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE i record; allowed text[]; fields jsonb; result jsonb; cols text; key text; c public.contacts; s public.sessions;
BEGIN
 SELECT * INTO i FROM public.current_deployment_identity();
 IF i.tenant_id IS NULL THEN RAISE EXCEPTION 'Active deployment membership required' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_fields)<>'object' OR p_fields ?| ARRAY['id','tenant_id','clerk_user_id','clerk_org_id','organization_id','role','actor','agent_id','assigned_agent_id','writing_agent_id','created_by'] THEN
  RAISE EXCEPTION 'Identity fields are service managed' USING ERRCODE='42501';
 END IF;
 CASE p_table
 WHEN 'contacts' THEN allowed:=ARRAY['first_name','last_name','phone','email','dob','address','zip','county','state','medicare_parts','current_carrier','current_plan','status','do_not_call'];
 WHEN 'contact_notes' THEN allowed:=ARRAY['contact_id','body','pinned'];
 WHEN 'contact_activities' THEN allowed:=ARRAY['contact_id','type','summary','ref_id'];
 WHEN 'policies' THEN allowed:=ARRAY['contact_id','carrier','plan_name','plan_id','product_line','effective_date','status'];
 WHEN 'cross_sell_attempts' THEN allowed:=ARRAY['session_id','call_transcript_id','primary_product','primary_carrier','cross_sell_product','presented','client_response','decline_reason','metadata'];
 WHEN 'user_preferences' THEN allowed:=ARRAY['theme_preference'];
 ELSE RAISE EXCEPTION 'Unsupported workspace mutation' USING ERRCODE='42501';
 END CASE;
 FOR key IN SELECT jsonb_object_keys(p_fields) LOOP
  IF NOT key=ANY(allowed) THEN RAISE EXCEPTION 'Unsupported content field' USING ERRCODE='42501'; END IF;
 END LOOP;
 fields:=p_fields;
 IF p_table='user_preferences' THEN
  INSERT INTO public.user_preferences(clerk_user_id,theme_preference) VALUES(auth.jwt()->>'sub',p_fields->>'theme_preference')
  ON CONFLICT(clerk_user_id) DO UPDATE SET theme_preference=excluded.theme_preference RETURNING to_jsonb(user_preferences) INTO result;
  RETURN result;
 END IF;
 fields:=fields||jsonb_build_object('tenant_id',i.tenant_id);
 IF p_table='contacts' THEN fields:=fields||jsonb_build_object('assigned_agent_id',i.agent_slug,'source','manual');
 ELSIF p_table='cross_sell_attempts' THEN
  SELECT * INTO s FROM public.sessions WHERE id=(fields->>'session_id')::uuid AND tenant_id=i.tenant_id AND agent_id=i.agent_id;
  IF s.id IS NULL OR (nullif(fields->>'call_transcript_id','') IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.call_transcripts t WHERE t.id=(fields->>'call_transcript_id')::uuid AND t.session_id=s.id AND t.tenant_id=i.tenant_id)) THEN
   RAISE EXCEPTION 'Session access denied' USING ERRCODE='42501';
  END IF;
  fields:=fields||jsonb_build_object('agent_id',i.agent_id);
 ELSE
  SELECT * INTO c FROM public.contacts WHERE id=(fields->>'contact_id')::uuid AND tenant_id=i.tenant_id;
  IF c.id IS NULL OR NOT public.deployment_can_access_contact(c.id) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501'; END IF;
  IF p_table='contact_notes' THEN fields:=fields||jsonb_build_object('agent_id',i.agent_slug); END IF;
  IF p_table='policies' THEN fields:=fields||jsonb_build_object('writing_agent_id',i.agent_slug); END IF;
 END IF;
 SELECT string_agg(quote_ident(k),',') INTO cols FROM jsonb_object_keys(fields) k;
 EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1) RETURNING to_jsonb(%I)',p_table,cols,cols,p_table,p_table)
 INTO result USING fields;
 IF p_table='contacts' THEN result:=result-ARRAY['first_name','last_name','phone','email','dob','address','mbi_last4','pii_encrypted','phone_hash','name_search']; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.decrypt_pii(p_contact_id uuid, p_requesting_agent_id uuid, p_action text DEFAULT 'view'::text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_contact RECORD;
  v_agent RECORD;
  v_result JSONB := '{}'::jsonb;
  v_field TEXT;
  v_value JSONB;
BEGIN
  IF current_setting('role',true)<>'service_role' AND NOT public.deployment_can_access_contact(p_contact_id) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501'; END IF;
  IF p_action NOT IN ('view', 'edit', 'export', 'search') THEN
    RAISE EXCEPTION 'invalid pii_access_log action: %', p_action;
  END IF;

  SELECT id, tenant_id, assigned_agent_id, pii_encrypted INTO v_contact
  FROM public.contacts WHERE id = p_contact_id;
  IF v_contact.id IS NULL THEN
    RAISE EXCEPTION 'contact % not found', p_contact_id;
  END IF;

  SELECT * INTO v_agent FROM public.deployment_assert_roster(p_requesting_agent_id);
  IF v_agent.id IS NULL THEN
    RAISE EXCEPTION 'requesting agent % not found', p_requesting_agent_id;
  END IF;
  IF auth.role() = 'authenticated'
     AND v_agent.clerk_user_id IS DISTINCT FROM NULLIF(auth.jwt() ->> 'sub', '') THEN
    RAISE EXCEPTION 'access denied: requesting agent is not the signed-in Clerk user';
  END IF;
  IF v_agent.tenant_id != v_contact.tenant_id THEN
    RAISE EXCEPTION 'access denied: agent and contact belong to different tenants';
  END IF;

  IF v_contact.pii_encrypted IS NOT NULL THEN
    FOR v_field, v_value IN SELECT * FROM jsonb_each(v_contact.pii_encrypted) LOOP
      v_result := v_result || jsonb_build_object(v_field, public.decrypt_pii_value(v_value));
    END LOOP;
  END IF;

  INSERT INTO public.pii_access_log (contact_id, agent_id, clerk_user_id, action, ip_address, user_agent)
  VALUES (p_contact_id, p_requesting_agent_id, v_agent.clerk_user_id, p_action, p_ip_address, p_user_agent);
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.decrypt_pii_value(p_encrypted jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_key_material TEXT;
BEGIN
  IF p_encrypted IS NULL OR p_encrypted = 'null'::jsonb THEN
    RETURN NULL;
  END IF;

  v_key_material := pii_vault.get_key((p_encrypted->>'k')::UUID);
  IF v_key_material IS NULL THEN
    RAISE EXCEPTION 'PII encryption key % not found', p_encrypted->>'k';
  END IF;

  RETURN extensions.pgp_sym_decrypt(decode(p_encrypted->>'c', 'base64'), v_key_material);
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_opportunity(p_opportunity_id uuid, p_requesting_agent_id uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE o public.opportunities; a public.tenant_agents; ts timestamptz;
BEGIN
  SELECT * INTO o FROM public.opportunities WHERE id = p_opportunity_id;
  IF o.id IS NULL THEN RAISE EXCEPTION 'Opportunity not found'; END IF;
  IF current_setting('role',true)<>'service_role' AND public.deployment_row_visible('opportunities',to_jsonb(o)) IS NOT TRUE THEN RAISE EXCEPTION 'Opportunity access denied' USING ERRCODE='42501'; END IF; a := public.opportunities_assert_agent(o.tenant_id,p_requesting_agent_id);
  -- Match move/edit lock order, then check ownership on the locked row.
  PERFORM id FROM public.pipelines WHERE id = o.pipeline_id FOR UPDATE;
  SELECT * INTO o FROM public.opportunities WHERE id = p_opportunity_id FOR UPDATE;
  IF a.role IS DISTINCT FROM 'admin' AND o.assigned_agent_id IS DISTINCT FROM a.id THEN
    RAISE EXCEPTION 'Only the assigned agent or an administrator can delete this opportunity' USING ERRCODE = '42501';
  END IF;
  -- Retried deletes are harmless and retain the original actor/time.
  IF o.deleted_at IS NOT NULL THEN RETURN; END IF;
  IF p_expected_updated_at IS NULL OR o.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'This opportunity changed in another session. Refresh and try again.' USING ERRCODE = '40001';
  END IF;
  ts := clock_timestamp();
  UPDATE public.opportunities SET deleted_at = ts,deleted_by = a.id,updated_at = ts WHERE id = o.id;
  -- Deliberately no stage/history/event writes.
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_opportunity_stage(p_stage_id uuid, p_requesting_agent_id uuid, p_move_to_stage_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE s public.pipeline_stages; o record; retained_stage uuid;
BEGIN
  SELECT * INTO s FROM public.pipeline_stages WHERE id = p_stage_id;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Stage not found'; END IF;
  PERFORM public.opportunities_assert_agent(s.tenant_id,p_requesting_agent_id,true);
  PERFORM id FROM public.pipelines WHERE id = s.pipeline_id FOR UPDATE;
  IF (SELECT count(*) FROM public.pipeline_stages WHERE pipeline_id = s.pipeline_id) <= 1 THEN RAISE EXCEPTION 'Keep at least one stage'; END IF;
  IF p_move_to_stage_id IS NOT NULL AND (p_move_to_stage_id = s.id OR NOT EXISTS(
    SELECT 1 FROM public.pipeline_stages WHERE id = p_move_to_stage_id AND pipeline_id = s.pipeline_id AND tenant_id = s.tenant_id)) THEN
    RAISE EXCEPTION 'Choose another stage in this pipeline';
  END IF;
  IF EXISTS(SELECT 1 FROM public.opportunities WHERE stage_id = s.id AND deleted_at IS NULL) AND p_move_to_stage_id IS NULL THEN
    RAISE EXCEPTION 'Stage has opportunities. Move them to another stage before deleting.' USING ERRCODE = '23503';
  END IF;
  FOR o IN SELECT id,stage_id FROM public.opportunities WHERE stage_id = s.id AND deleted_at IS NULL ORDER BY id FOR UPDATE LOOP
    PERFORM public.opportunities_move_internal(o.id,p_move_to_stage_id,p_requesting_agent_id,o.stage_id);
  END LOOP;
  -- Retained deleted records must not block stage removal. Relink only their
  -- inert FK, without changing clocks/status or writing history/events. Their
  -- original stage names/colors remain in the retained history snapshots.
  SELECT id INTO retained_stage FROM public.pipeline_stages
    WHERE pipeline_id = s.pipeline_id AND id <> s.id
    ORDER BY (id = p_move_to_stage_id) DESC NULLS LAST,position,id LIMIT 1;
  UPDATE public.opportunities SET stage_id = retained_stage
    WHERE stage_id = s.id AND deleted_at IS NOT NULL;
  DELETE FROM public.pipeline_stages WHERE id = s.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.deployment_assert_roster(p_agent uuid)
 RETURNS tenant_agents
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a public.tenant_agents; i record;
BEGIN
 SELECT * INTO a FROM public.tenant_agents WHERE id=p_agent;
 SELECT * INTO i FROM public.resolve_deployment_subject(a.clerk_user_id,NULL);
 IF a.id IS NULL OR i.roster_id IS DISTINCT FROM a.id OR
  (current_setting('role',true)<>'service_role' AND NOT EXISTS(
   SELECT 1 FROM public.current_deployment_identity() me WHERE me.roster_id=a.id)) THEN
  RAISE EXCEPTION 'Active deployment membership required' USING ERRCODE='42501';
 END IF;
 a.role:=CASE WHEN i.authority='admin' OR public.deployment_is_admin(a.tenant_id) THEN 'admin' ELSE 'agent' END;
 RETURN a;
END $function$

CREATE OR REPLACE FUNCTION public.deployment_feature_enabled(flag text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE headers jsonb; claims jsonb;
BEGIN
 claims:=coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb;
 IF coalesce(claims->>'role','')<>'service_role' AND coalesce(current_setting('role',true),'')<>'service_role' THEN RETURN false; END IF;
 headers:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
 RETURN coalesce(((headers->>'x-enrollgen-features')::jsonb)->flag,'false'::jsonb)='true'::jsonb;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.deployment_log_owner(r jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE t uuid:=(r->>'tenant_id')::uuid; owner_id uuid; item jsonb; slug text; subject text;
BEGIN
 IF nullif(r->>'call_record_id','') IS NOT NULL THEN
  SELECT c.agent_id INTO owner_id FROM public.call_records c WHERE c.tenant_id=t AND c.id=(r->>'call_record_id')::uuid;
  IF owner_id IS NOT NULL THEN RETURN owner_id; END IF;
  SELECT s.agent_id INTO owner_id FROM public.sessions s JOIN public.call_records c ON c.session_id=s.id AND c.tenant_id=s.tenant_id
   WHERE c.id=(r->>'call_record_id')::uuid AND c.tenant_id=t AND s.call_record_id=c.id;
  IF owner_id IS NOT NULL THEN RETURN owner_id; END IF;
 END IF;
 IF nullif(r->>'attempt_id','') IS NOT NULL THEN
  SELECT to_jsonb(a) INTO item FROM public.telephony_call_attempts a WHERE a.tenant_id=t AND a.id=(r->>'attempt_id')::uuid;
  slug:=item->>'agent_id';
 ELSIF nullif(r->>'inbound_call_id','') IS NOT NULL THEN
  SELECT to_jsonb(c) INTO item FROM public.inbound_calls c WHERE c.tenant_id=t AND c.id=(r->>'inbound_call_id')::uuid;
  slug:=coalesce(nullif(item->>'answered_agent_id',''),nullif(item->>'routed_agent_id',''));
 END IF;
 IF slug IS NULL THEN RETURN NULL; END IF;
 SELECT s.clerk_user_id INTO subject FROM public.availability_agent_subjects s WHERE s.tenant_id=t AND s.agent_slug=slug AND s.is_active;
 SELECT i.agent_id INTO owner_id FROM public.resolve_deployment_subject(subject,NULL) i WHERE i.tenant_id=t AND i.agent_slug=slug;
 RETURN owner_id;
END $function$

CREATE OR REPLACE FUNCTION public.deployment_row_visible(p_table text, r jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE i record; t uuid; parent jsonb; owner_id uuid;
BEGIN
 SELECT * INTO i FROM public.current_deployment_identity();
 IF i.tenant_id IS NULL THEN RETURN false; END IF;
 t:=nullif(r->>'tenant_id','')::uuid;
 IF t IS NOT NULL AND t<>i.tenant_id THEN RETURN false; END IF;
 CASE
 WHEN p_table='post_call_coaching' THEN
   SELECT to_jsonb(c) INTO parent FROM public.call_records c WHERE c.id=(r->>'call_id')::uuid AND c.tenant_id=t AND c.agent_id=(r->>'agent_id')::uuid;
   RETURN public.deployment_row_visible('call_records',parent);
  WHEN p_table='client_recaps' THEN
   SELECT to_jsonb(c) INTO parent FROM public.enrollment_intakes e JOIN public.call_records c ON c.id=e.call_id AND c.tenant_id=e.tenant_id WHERE e.id=(r->>'enrollment_id')::uuid AND e.tenant_id=t AND c.agent_id=(r->>'agent_id')::uuid;
   RETURN public.deployment_row_visible('call_records',parent);
  WHEN p_table IN ('practice_sessions','practice_results') THEN RETURN EXISTS(SELECT 1 FROM public.current_deployment_identity() i WHERE i.tenant_id=t AND (i.agent_id=(r->>'agent_id')::uuid OR i.authority='admin' OR i.authority='manager' AND (r->>'agent_id')::uuid=ANY(i.team_agent_ids))); WHEN p_table='tenants' THEN RETURN r->>'id'=i.tenant_id::text;
 WHEN p_table IN ('tenant_agents','enrolled_agents') THEN RETURN t=i.tenant_id;
 WHEN p_table='agents' THEN
  RETURN EXISTS(SELECT 1 FROM public.call_transcripts ct WHERE ct.agent_id=(r->>'id')::uuid AND public.deployment_row_visible('call_transcripts',to_jsonb(ct)));
 WHEN p_table='contacts' THEN RETURN public.deployment_can_access_contact((r->>'id')::uuid);
 WHEN p_table IN ('contact_notes','contact_activities','contact_lead_intel','policies','messages','contact_tags','opportunities','follow_ups') THEN
  IF NOT public.deployment_can_access_contact(nullif(r->>'contact_id','')::uuid) THEN RETURN false; END IF;
  IF p_table='contact_notes' THEN RETURN r->>'agent_id'=i.agent_slug OR public.deployment_is_admin(i.tenant_id); END IF;
  IF p_table='follow_ups' THEN RETURN public.follow_up_access(t,r->>'agent_id'); END IF;
  IF p_table='opportunities' THEN RETURN r->>'assigned_agent_id'=i.roster_id::text OR public.deployment_is_admin(i.tenant_id); END IF;
  RETURN t=i.tenant_id;
 WHEN p_table IN ('opportunity_events','opportunity_stage_history') THEN
  SELECT to_jsonb(o) INTO parent FROM public.opportunities o WHERE o.id=(r->>'opportunity_id')::uuid;
  RETURN public.deployment_row_visible('opportunities',parent);
 WHEN p_table='call_disposition_opportunity_log' THEN
  SELECT to_jsonb(c) INTO parent FROM public.call_records c WHERE c.id=(r->>'call_id')::uuid;
  RETURN public.deployment_row_visible('call_records',parent);
 WHEN p_table IN ('pipelines','pipeline_stages') THEN RETURN t=i.tenant_id;
 WHEN p_table IN ('script_templates','knowledge_base') THEN RETURN t=i.tenant_id OR t IS NULL;
 WHEN p_table='message_media' THEN
  SELECT to_jsonb(m) INTO parent FROM public.messages m WHERE m.id=(r->>'message_id')::uuid;
  RETURN public.deployment_row_visible('messages',parent);
 WHEN p_table='knowledge_updates' THEN
  SELECT to_jsonb(k) INTO parent FROM public.knowledge_base k WHERE k.id=(r->>'knowledge_base_id')::uuid;
  RETURN public.deployment_row_visible('knowledge_base',parent);
 WHEN p_table IN ('sessions','call_records','call_logs','sales_log','call_threads','agent_compliance_profiles','corrective_actions','cross_sell_attempts') THEN
  owner_id:=nullif(r->>'agent_id','')::uuid;
  IF t IS NULL THEN SELECT e.tenant_id INTO t FROM public.enrolled_agents e WHERE e.id=owner_id; END IF;
  RETURN public.deployment_can_read_agent(t,owner_id);
 WHEN p_table='call_transcripts' THEN
  owner_id:=nullif(r->>'owner_agent_id','')::uuid;
  IF owner_id IS NOT NULL THEN RETURN public.deployment_can_read_agent(t,owner_id); END IF;
  SELECT to_jsonb(s) INTO parent FROM public.sessions s WHERE s.id=(r->>'session_id')::uuid AND s.tenant_id=t;
  RETURN public.deployment_row_visible('sessions',parent);
 WHEN p_table='transcript_chunks' THEN
  SELECT to_jsonb(c) INTO parent FROM public.call_transcripts c WHERE c.id=(r->>'transcript_id')::uuid;
  RETURN public.deployment_row_visible('call_transcripts',parent);
 WHEN p_table IN ('compliance_flags','section_scores') THEN
  SELECT to_jsonb(s) INTO parent FROM public.sessions s WHERE s.id=(r->>'session_id')::uuid;
  RETURN public.deployment_row_visible('sessions',parent);
 WHEN p_table IN ('compliance_scorecards','compliance_scores','intent_detections','phi_redactions','followup_queue','enrollment_intakes') THEN
  SELECT to_jsonb(c) INTO parent FROM public.call_records c WHERE c.id=(r->>'call_id')::uuid;
  RETURN public.deployment_row_visible('call_records',parent);
 WHEN p_table='scorecard_items' THEN
  SELECT to_jsonb(s) INTO parent FROM public.compliance_scorecards s WHERE s.id=(r->>'scorecard_id')::uuid;
  RETURN public.deployment_row_visible('compliance_scorecards',parent);
 WHEN p_table='inbound_calls' THEN
  SELECT to_jsonb(c) INTO parent FROM public.call_records c WHERE c.id=(r->>'call_record_id')::uuid AND c.tenant_id=t;
  RETURN public.deployment_row_visible('call_records',parent);
 WHEN p_table='telephony_events' THEN
  SELECT to_jsonb(c) INTO parent FROM public.call_records c WHERE c.twilio_call_sid=coalesce(r->>'twilio_call_sid',r->>'call_sid') AND c.tenant_id=t;
  RETURN public.deployment_row_visible('call_records',parent);
 WHEN p_table='carrier_rts' THEN RETURN t=i.tenant_id AND (r->>'agent_id'=i.roster_id::text OR public.deployment_is_admin(t));
 WHEN p_table='pii_access_log' THEN RETURN r->>'clerk_user_id'=auth.jwt()->>'sub' OR
  (public.deployment_is_admin(i.tenant_id) AND EXISTS(SELECT 1 FROM public.tenant_agents a WHERE a.id=(r->>'agent_id')::uuid AND a.tenant_id=i.tenant_id));
 WHEN p_table IN ('subscriptions','usage_records','rts_ingestion_log','call_insights','agent_coaching') THEN RETURN t=i.tenant_id AND public.deployment_is_admin(t);
 WHEN p_table IN ('calibration_runs','calibration_overrides','autoresearch_iterations') THEN RETURN false; -- legacy rows have no reliable tenant binding
 WHEN p_table='training_completions' THEN RETURN t=i.tenant_id AND (r->>'agent_id'=i.agent_id::text OR r->>'agent_id'=auth.jwt()->>'sub' OR public.deployment_is_admin(t));
 WHEN p_table='user_preferences' THEN RETURN r->>'clerk_user_id'=auth.jwt()->>'sub';
 WHEN p_table IN ('compliance_intents','scoring_templates','scoring_template_items') THEN RETURN true; -- authenticated deployment reference data
 ELSE RETURN false; -- unrecognized, missing-baseline and service ledgers stay closed
 END CASE;
 RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.deployment_row_writable(p_table text, r jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE owner_id uuid; tenant uuid:=(r->>'tenant_id')::uuid;
BEGIN
 IF public.deployment_row_visible(p_table,r) IS NOT TRUE THEN RETURN false; END IF;
 IF p_table IN ('call_records','followup_queue') THEN
  IF public.deployment_is_admin(tenant) THEN RETURN true; END IF;
  IF p_table='call_records' THEN owner_id:=nullif(r->>'agent_id','')::uuid;
  ELSE SELECT c.agent_id INTO owner_id FROM public.call_records c WHERE c.tenant_id=tenant AND c.id=(r->>'call_id')::uuid; END IF;
  RETURN public.evidence_owns_agent(owner_id,tenant);
 END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.deployment_timezone()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE zone text; tenant uuid;
BEGIN
 SELECT tenant_id,public_profile->>'timezone' INTO tenant,zone FROM public.deployment_settings WHERE singleton;
 IF current_setting('role',true)='authenticated' AND NOT public.is_current_tenant(tenant) THEN
  RAISE EXCEPTION 'Active deployment membership required' USING ERRCODE='42501';
 END IF;
 IF zone IS NULL OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone) THEN RAISE EXCEPTION 'Deployment timezone has not been provisioned'; END IF;
 RETURN zone;
END $function$

CREATE OR REPLACE FUNCTION public.encrypt_pii_value(p_plaintext text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_key RECORD;
BEGIN
  IF p_plaintext IS NULL OR btrim(p_plaintext) = '' THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_key FROM pii_vault.get_active_key();
  IF v_key.key_id IS NULL THEN
    RAISE EXCEPTION 'no active PII encryption key configured';
  END IF;

  RETURN jsonb_build_object(
    'c', encode(extensions.pgp_sym_encrypt(p_plaintext, v_key.key_material, 'cipher-algo=aes256'), 'base64'),
    'k', v_key.key_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_availability_push(p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE snapshot jsonb; next_fingerprint jsonb; state integration_push_state; consumer availability_consumers; stamp timestamptz:=p_now;
BEGIN
 IF NOT public.deployment_feature_enabled('PARAGON_ENABLED') THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM availability_consumers WHERE active AND push_enabled) THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('vendor_availability_push',0));
  snapshot:=availability_snapshot();
  next_fingerprint:=jsonb_build_array(snapshot->'any_available',snapshot->'available_count',snapshot->'available_states');
  SELECT * INTO state FROM integration_push_state WHERE singleton FOR UPDATE;
  IF state.fingerprint IS DISTINCT FROM next_fingerprint THEN
    UPDATE integration_push_state SET fingerprint=next_fingerprint,changed_at=stamp WHERE singleton;
    RETURN;
  END IF;
  IF stamp<state.changed_at+interval '5 seconds' THEN RETURN; END IF;
  FOR consumer IN SELECT * FROM availability_consumers WHERE active AND push_enabled
    AND (push_fingerprint IS DISTINCT FROM next_fingerprint OR push_enqueued_at IS NULL OR push_enqueued_at<=stamp-interval '5 minutes') LOOP
    -- Replace unsent stale status; an in-flight request is serialized per consumer.
    IF consumer.push_fingerprint IS DISTINCT FROM next_fingerprint THEN
      UPDATE integration_deliveries SET superseded=true,
        status=CASE WHEN status='pending' THEN 'canceled' ELSE status END
        WHERE kind='push' AND consumer_name=consumer.name AND status IN ('pending','processing');
    END IF;
    INSERT INTO integration_deliveries(kind,consumer_name,dedupe_key,payload,config_snapshot,expires_at)
      VALUES('push',consumer.name,'push:'||gen_random_uuid(),snapshot,jsonb_build_object('format',consumer.push_format),stamp+interval '10 minutes');
    UPDATE availability_consumers SET push_fingerprint=next_fingerprint,push_enqueued_at=stamp WHERE name=consumer.name;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_conference_recording(p_participant_id uuid, p_callback jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE p call_participants; c call_conferences; a telephony_call_attempts; rid uuid;
BEGIN
 IF EXISTS(SELECT 1 FROM public.call_participants WHERE id=p_participant_id AND role='supervisor') THEN RAISE EXCEPTION 'Coach is isolated' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT p FROM call_participants WHERE id=p_participant_id AND twilio_call_sid=p_callback->>'CallSid';
 SELECT * INTO STRICT c FROM call_conferences WHERE call_id=p.call_id;
 SELECT * INTO STRICT a FROM telephony_call_attempts WHERE id=c.attempt_id;
 rid:=enqueue_recording(p_callback,NULL);
 -- Preserve the real provider CallSid for secure media fetches. New outbound
 -- participant legs do not have an original Dial parent/child relationship.
 UPDATE recording_ingestion SET tenant_id=c.tenant_id,call_record_id=c.call_id,
  parent_call_sid=c.parent_call_sid,attempt_id=c.attempt_id,inbound_call_id=a.inbound_call_id,direction=a.direction
 WHERE id=rid;
 RETURN rid;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_daily_vendor_reports(p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE local_now timestamp:=p_now AT TIME ZONE public.deployment_timezone(); source lead_sources; day date; rows jsonb;
BEGIN
 IF NOT public.deployment_feature_enabled('OPERATIONAL_EMAIL_ENABLED') THEN RETURN; END IF;
  IF extract(hour FROM local_now)<7 THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('vendor_daily_reports',0));
  FOR source IN SELECT * FROM lead_sources WHERE active AND cardinality(report_emails)>0 FOR UPDATE LOOP
    day:=coalesce(source.report_cursor+1,local_now::date-1);
    WHILE day<local_now::date LOOP
      SELECT coalesce(jsonb_agg(vendor_call_payload(i.id) ORDER BY i.created_at),'[]'::jsonb) INTO rows
      FROM inbound_calls i WHERE NOT EXISTS(SELECT 1 FROM call_records tc WHERE tc.id=i.call_record_id AND tc.tenant_id=i.tenant_id AND tc.is_test_enrollment) AND i.tenant_id=source.tenant_id
        AND (i.lead_source_id=source.id OR i.aggregator_source_id=source.id)
        AND i.created_at>=day::timestamp AT TIME ZONE public.deployment_timezone()
        AND i.created_at<(day+1)::timestamp AT TIME ZONE public.deployment_timezone();
      IF jsonb_array_length(rows)>0 THEN
        INSERT INTO integration_deliveries(kind,source_id,dedupe_key,payload,expires_at)
          VALUES('report',source.id,'report:'||source.id||':'||day,
            jsonb_build_object('date',day,'calls',rows),clock_timestamp()+interval '24 hours')
          ON CONFLICT(dedupe_key) DO NOTHING;
      END IF;
      INSERT INTO integration_report_log(source_id,report_date,call_count,result)
        VALUES(source.id,day,jsonb_array_length(rows),CASE WHEN jsonb_array_length(rows)>0 THEN 'queued' ELSE 'skipped_empty' END)
        ON CONFLICT DO NOTHING;
      UPDATE lead_sources SET report_cursor=day WHERE id=source.id;
      day:=day+1;
    END LOOP;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_paragon_billing_event(p_parent_sid text, p_event_key text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 IF NOT public.deployment_feature_enabled('PARAGON_ENABLED') THEN RETURN; END IF;
 IF p_parent_sid !~ '^CA[0-9a-fA-F]{32}$' OR length(p_event_key)>200 THEN RAISE EXCEPTION 'Invalid billing event'; END IF;
 INSERT INTO paragon_billing_events VALUES(p_event_key,p_parent_sid,p_payload,clock_timestamp()) ON CONFLICT DO NOTHING;
 -- The callback can precede claim/link: seed/reconciliation resolves it later.
 UPDATE paragon_call_billing SET next_attempt_at=least(next_attempt_at,clock_timestamp()) WHERE parent_call_sid=p_parent_sid;
END; $function$

CREATE OR REPLACE FUNCTION public.enqueue_paragon_sep_residence(p_call uuid, p_tenant uuid, p_agent text, p_sid text, p_zip text, p_state text, p_county text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c inbound_calls;
BEGIN
 SELECT i.* INTO c FROM inbound_calls i JOIN lead_sources s ON s.id=i.lead_source_id AND s.tenant_id=i.tenant_id
 WHERE i.id=p_call AND i.tenant_id=p_tenant AND i.routed_agent_id=p_agent AND i.twilio_call_sid=p_sid
 AND s.name=public.bootstrap_vendor_source_name() AND s.type='publisher' AND i.source_kind='publisher'
 AND EXISTS(SELECT 1 FROM telephony_call_attempts a WHERE a.inbound_call_id=i.id AND a.answered_at IS NOT NULL AND a.ended_at IS NULL);
 IF NOT FOUND THEN RAISE EXCEPTION 'Active owned Paragon call required'; END IF;
 IF p_zip !~ '^[0-9]{5}$' OR p_state !~ '^[A-Z]{2}$' OR NOT EXISTS(
 SELECT 1 FROM zip_county_crosswalk WHERE zip=p_zip AND state_code=p_state AND (p_county IS NULL OR county_fips=p_county OR lower(county_name)=lower(p_county))) THEN RAISE EXCEPTION 'Invalid lookup area'; END IF;
 INSERT INTO paragon_residence_sep_inputs(inbound_call_id,tenant_id,zip,state,county_fips,metadata)
 VALUES(c.id,c.tenant_id,p_zip,p_state,(SELECT min(county_fips) FROM zip_county_crosswalk WHERE zip=p_zip AND state_code=p_state AND (county_fips=p_county OR lower(county_name)=lower(p_county))),jsonb_build_object('source','sep_lookup','agent_id',p_agent,'entry','agent_typed'))
 ON CONFLICT(inbound_call_id) DO UPDATE SET zip=excluded.zip,state=excluded.state,county_fips=excluded.county_fips,metadata=excluded.metadata,observed_at=clock_timestamp();
 INSERT INTO paragon_residence_jobs(inbound_call_id,tenant_id) VALUES(c.id,c.tenant_id)
 ON CONFLICT(inbound_call_id) DO UPDATE SET available_at=clock_timestamp();
 RETURN jsonb_build_object('queued',true);
END; $function$

CREATE OR REPLACE FUNCTION public.enqueue_ping_billing_event(p_parent_sid text, p_event_key text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF NOT public.deployment_feature_enabled('PING_PLATFORM_ENABLED') THEN RETURN; END IF;
 IF p_parent_sid !~ '^CA[0-9a-fA-F]{32}$' OR length(p_event_key)>200 THEN RAISE EXCEPTION 'Invalid billing event'; END IF;
 INSERT INTO ping_call_billing_events VALUES(p_event_key,p_parent_sid,p_payload,clock_timestamp()) ON CONFLICT DO NOTHING;
 UPDATE ping_call_billing SET next_attempt_at=least(next_attempt_at,clock_timestamp()) WHERE parent_call_sid=p_parent_sid;
END; $function$

CREATE OR REPLACE FUNCTION public.enqueue_post_call_request(p_session_id uuid, p_tenant_id uuid, p_agent_id uuid, p_user_id text, p_org_id text, p_clerk_session_id text, p_request_key text, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE job post_call_jobs; request post_call_requests;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM sessions s JOIN enrolled_agents e ON e.id=s.agent_id AND e.tenant_id=s.tenant_id
 WHERE s.id=p_session_id AND s.tenant_id=p_tenant_id AND s.agent_id=p_agent_id AND e.clerk_user_id=p_user_id AND e.is_active) THEN
 RAISE EXCEPTION 'Session ownership mismatch'; END IF;
 INSERT INTO post_call_jobs(session_id,tenant_id,agent_id,clerk_user_id,clerk_org_id,clerk_session_id)
 VALUES(p_session_id,p_tenant_id,p_agent_id,p_user_id,p_org_id,p_clerk_session_id) ON CONFLICT DO NOTHING;
 SELECT * INTO job FROM post_call_jobs WHERE session_id=p_session_id FOR UPDATE;
 IF job.tenant_id<>p_tenant_id OR job.agent_id<>p_agent_id OR job.clerk_user_id<>p_user_id THEN RAISE EXCEPTION 'Job ownership mismatch'; END IF;
 INSERT INTO post_call_requests(session_id,request_key,action,payload)
 VALUES(p_session_id,p_request_key,p_action,p_payload) ON CONFLICT DO NOTHING;
 SELECT * INTO request FROM post_call_requests WHERE session_id=p_session_id AND request_key=p_request_key;
 IF request.status='queued' AND job.worker_id IS NULL THEN
 UPDATE post_call_jobs SET status='queued',progress='queued',error_code=NULL,updated_at=clock_timestamp() WHERE session_id=p_session_id;
 END IF;
 RETURN jsonb_build_object('request_key',request.request_key,'status',request.status,'result',request.result,
 'dispatch_token',job.dispatch_token,'dispatch',request.status='queued' AND job.worker_id IS NULL);
END; $function$

CREATE OR REPLACE FUNCTION public.enrich_call_display_names()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE safe_name text;first text;last text;contact contacts;
BEGIN
 IF NEW.agent_name IS NULL OR lower(trim(NEW.agent_name)) IN ('agent','unknown','') THEN
  SELECT coalesce(nullif(nullif(trim(e.name),'Agent'),''),initcap(replace(r.agent_slug,'_',' '))) INTO safe_name
  FROM enrolled_agents e JOIN availability_agent_subjects r
   ON r.clerk_user_id=e.clerk_user_id AND r.tenant_id=e.tenant_id AND r.is_active
  WHERE e.id=NEW.agent_id AND e.tenant_id=NEW.tenant_id AND e.is_active;
  IF safe_name IS NOT NULL THEN NEW.agent_name:=safe_name; END IF;
 END IF;
 IF NEW.beneficiary_name IS NULL AND NEW.contact_id IS NOT NULL THEN
  SELECT * INTO contact FROM contacts WHERE id=NEW.contact_id AND tenant_id=NEW.tenant_id;
  IF FOUND THEN
   first:=contact.first_name;last:=contact.last_name;
   IF contact.pii_encrypted->>'first_name' IS NOT NULL THEN first:=decrypt_pii_value(contact.pii_encrypted->'first_name'); END IF;
   IF contact.pii_encrypted->>'last_name' IS NOT NULL THEN last:=decrypt_pii_value(contact.pii_encrypted->'last_name'); END IF;
   NEW.beneficiary_name:=nullif(trim(concat_ws(' ',first,last)),'');
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.ensure_inbound_transcript_record(p_attempt_id uuid, p_session_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a telephony_call_attempts; owner enrolled_agents; rid uuid;
BEGIN
 SELECT * INTO STRICT a FROM telephony_call_attempts WHERE id=p_attempt_id AND direction='inbound' FOR UPDATE;
 SELECT e.* INTO STRICT owner FROM enrolled_agents e JOIN tenant_agents t
 ON t.tenant_id=e.tenant_id AND t.clerk_user_id=e.clerk_user_id
 WHERE t.tenant_id=a.tenant_id AND t.agent_slug=a.agent_id AND e.is_active AND t.is_active;
 rid:=a.call_record_id;
 IF rid IS NULL THEN
  SELECT id INTO rid FROM call_records WHERE tenant_id=a.tenant_id AND twilio_call_sid=a.parent_call_sid
   AND agent_id=owner.id ORDER BY created_at LIMIT 1;
 END IF;
 IF rid IS NULL THEN
  INSERT INTO call_records(tenant_id,agent_id,agent_name,call_direction,call_type,product_type,
   call_start,twilio_call_sid,contact_id,metadata)
  VALUES(a.tenant_id,owner.id,owner.name,'inbound','enrollment','MA',a.created_at,a.parent_call_sid,a.contact_id,
   jsonb_build_object('telephony_call',true,'transcript_source','deepgram_server')) RETURNING id INTO rid;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM call_records WHERE id=rid AND tenant_id=a.tenant_id AND agent_id=owner.id) THEN
  RAISE EXCEPTION 'Transcript record owner mismatch';
 END IF;
 IF p_session_id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM sessions WHERE id=p_session_id AND tenant_id=a.tenant_id AND agent_id=owner.id
   AND (call_record_id IS NULL OR call_record_id=rid)) THEN RAISE EXCEPTION 'Transcript session mismatch'; END IF;
  UPDATE call_records SET session_id=p_session_id WHERE id=rid AND (session_id IS NULL OR session_id=p_session_id);
  IF NOT FOUND THEN RAISE EXCEPTION 'Transcript already belongs to another session'; END IF;
  UPDATE sessions SET call_record_id=rid WHERE id=p_session_id;
  UPDATE call_transcripts SET session_id=p_session_id WHERE call_record_id=rid AND tenant_id=a.tenant_id;
 END IF;
 UPDATE telephony_call_attempts SET call_record_id=rid WHERE id=a.id;
 UPDATE inbound_calls SET call_record_id=rid WHERE id=a.inbound_call_id AND tenant_id=a.tenant_id;
 RETURN rid;
END $function$

CREATE OR REPLACE FUNCTION public.ensure_opportunities_pipeline(p_tenant_id uuid, p_requesting_agent_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE result uuid;
BEGIN
 PERFORM public.opportunities_assert_agent(p_tenant_id,p_requesting_agent_id);
 SELECT id INTO result FROM public.pipelines WHERE tenant_id=p_tenant_id AND is_default;
 IF result IS NULL THEN RAISE EXCEPTION 'An operator must provision the default pipeline'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.exchange_cap_window(p_hours jsonb, p_unit text, p_at timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE zone text:=p_hours->>'timezone';
BEGIN
 IF p_unit NOT IN ('day','hour') THEN RAISE EXCEPTION 'Invalid cap window'; END IF;
 IF zone IS NULL OR zone !~ '^[A-Z][A-Za-z_]+(/[A-Za-z0-9_+-]+){1,2}$' THEN zone:='UTC'; END IF;
 RETURN date_trunc(p_unit,p_at AT TIME ZONE zone) AT TIME ZONE zone;
EXCEPTION WHEN OTHERS THEN RETURN date_trunc(p_unit,p_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
END $function$

CREATE OR REPLACE FUNCTION public.exchange_ping(p_key_hash text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE started timestamptz:=clock_timestamp(); src lead_sources; xs exchange_sources;
  payload jsonb:=coalesce(p_payload,'{}'::jsonb); phone text; call_id text; state_code text:='';
  sub_id text; consent text; phone_hash text; hash_trace jsonb:='[]'::jsonb;
  r record; d jsonb; cand jsonb:='[]'::jsonb; accepts jsonb:='[]'::jsonb;
  cap_scope text; used_day integer; used_hour integer; day_start timestamptz; hour_start timestamptz;
  committed_campaign uuid; ranking uuid[]; total integer; rotation jsonb;
  winner_campaign uuid; winner_decision jsonb; pick uuid; cap_decision uuid; auction_id uuid;
  transfer text; reason text; public_reason text; retention_accepts boolean:=false;
BEGIN
  IF NOT public.deployment_feature_enabled('PING_PLATFORM_ENABLED') THEN
    RETURN jsonb_build_object('status','disabled','feature','PING_PLATFORM_ENABLED'); END IF;
  IF NOT public.deployment_feature_enabled('PING_EXCHANGE_ENABLED') THEN
    RETURN jsonb_build_object('status','disabled','feature','PING_EXCHANGE_ENABLED'); END IF;
  -- Publisher authentication exactly as ping_decide.
  SELECT s.* INTO src FROM lead_sources s WHERE s.active AND s.type IN ('publisher','aggregator')
    AND (s.ping_key_hash=p_key_hash OR EXISTS(SELECT 1 FROM availability_consumers c
      WHERE c.name=s.name AND c.active AND c.key_hash=p_key_hash))
    ORDER BY (s.ping_key_hash=p_key_hash) DESC NULLS LAST LIMIT 1;
  IF src.id IS NULL THEN RETURN jsonb_build_object('authorized',false); END IF;
  -- Fail closed: without the pepper no loser row could be written safely.
  IF public.ping_phone_pepper() IS NULL THEN RAISE EXCEPTION 'Ping phone pepper is not provisioned'; END IF;

  IF jsonb_typeof(payload)='object' THEN
    phone:=left(nullif(trim(payload->>'phone'),''),32);
    state_code:=upper(trim(coalesce(payload->>'state','')));
    call_id:=left(nullif(trim(payload->>'call_id'),''),128);
    sub_id:=left(nullif(trim(payload->>'sub_id'),''),128);
    consent:=left(nullif(trim(payload->>'consent_cert_id'),''),128);
  END IF;
  phone_hash:=public.ping_phone_hash(phone);
  IF phone_hash IS NOT NULL THEN
    hash_trace:=jsonb_build_array(jsonb_build_object('rule','phone_hash','result','recorded','sha256',phone_hash));
  END IF;

  -- The row lock serializes this source's auctions and its rotation state.
  SELECT * INTO xs FROM exchange_sources WHERE source_id=src.id AND active FOR UPDATE;
  IF xs.source_id IS NOT NULL THEN
    -- A re-ping inside the 30 second commitment stays with the buyer that
    -- already holds an agent for it, so two buyers never hold the same call.
    SELECT x.campaign_id INTO committed_campaign FROM ping_decisions x
      WHERE x.source_id=src.id AND x.engine='exchange' AND x.available AND x.matched_call_sid IS NULL
        AND x.received_at+interval '30 seconds'>=started AND x.caller_state=state_code
        AND ((call_id IS NOT NULL AND x.vendor_call_id=call_id)
          OR (call_id IS NULL AND phone IS NOT NULL AND x.caller_phone=phone))
        AND NOT x.rule_trace @> '[{"rule":"commitment_replay"}]'::jsonb
      ORDER BY x.received_at DESC LIMIT 1;

    FOR r IN SELECT er.campaign_id,er.priority,er.weight,c.tenant_id AS buyer,c.transfer_number,
        c.exchange_daily_cap,c.exchange_hourly_cap,coalesce(c.staffed_hours_override,v.staffed_hours) AS hours,
        coalesce(er.price_override,CASE c.pricing_model WHEN 'free' THEN 0 ELSE c.rate END) AS price,
        (SELECT max(a.received_at) FROM exchange_auctions a
          WHERE a.source_id=src.id AND a.winner_campaign_id=er.campaign_id) AS last_won
      FROM exchange_routes er JOIN ping_campaigns c ON c.id=er.campaign_id
      LEFT JOIN vendor_controls v ON v.tenant_id=c.tenant_id
      WHERE er.source_id=src.id AND er.active AND c.active AND c.engine_mode='generic'
      ORDER BY er.priority,er.campaign_id
    LOOP
      -- A campaign without a transfer number can never win; it is not evaluated.
      IF r.transfer_number IS NULL THEN
        cand:=cand||jsonb_build_array(jsonb_build_object('campaign_id',r.campaign_id,'decision_id',NULL,
          'available',false,'reason','campaign_inactive','price',NULL));
        CONTINUE;
      END IF;
      -- Caps count accepted, non-replayed exchange decisions in the buyer's own day and hour.
      cap_scope:=NULL;
      IF (r.exchange_daily_cap IS NOT NULL OR r.exchange_hourly_cap IS NOT NULL)
      AND r.campaign_id IS DISTINCT FROM committed_campaign THEN
        day_start:=public.exchange_cap_window(r.hours,'day',started);
        hour_start:=public.exchange_cap_window(r.hours,'hour',started);
        SELECT count(*) FILTER (WHERE x.received_at>=day_start),count(*) FILTER (WHERE x.received_at>=hour_start)
          INTO used_day,used_hour FROM ping_decisions x
          WHERE x.campaign_id=r.campaign_id AND x.engine='exchange' AND x.available
            AND x.received_at>=least(day_start,hour_start)
            AND NOT x.rule_trace @> '[{"rule":"commitment_replay"}]'::jsonb;
        IF r.exchange_daily_cap IS NOT NULL AND used_day>=r.exchange_daily_cap THEN cap_scope:='daily';
        ELSIF r.exchange_hourly_cap IS NOT NULL AND used_hour>=r.exchange_hourly_cap THEN cap_scope:='hourly'; END IF;
      END IF;
      IF cap_scope IS NOT NULL THEN
        INSERT INTO ping_decisions(tenant_id,source_id,campaign_id,latency_ms,caller_phone,caller_state,caller_zip,
          vendor_call_id,publisher_sub_id,consent_cert_id,available,reason,rule_trace,engine)
        VALUES(r.buyer,src.id,r.campaign_id,0,NULL,nullif(left(state_code,8),''),NULL,call_id,sub_id,consent,false,
          'buyer_cap_reached',jsonb_build_array(jsonb_build_object('rule','buyer_cap_reached','result','reject','scope',cap_scope))||hash_trace,
          'exchange_eval')
        RETURNING id INTO cap_decision;
        cand:=cand||jsonb_build_array(jsonb_build_object('campaign_id',r.campaign_id,'decision_id',cap_decision,
          'available',false,'reason','buyer_cap_reached','price',r.price));
        CONTINUE;
      END IF;

      d:=public.ping_decide_campaign(r.campaign_id,src.id,payload,'exchange_eval');
      cand:=cand||jsonb_build_array(jsonb_build_object('campaign_id',r.campaign_id,'decision_id',d->'decision_id',
        'available',d->'available','reason',d->'reason','price',r.price));
      -- Pings the publisher or platform could not deliver are not metered.
      IF d->>'reason' NOT IN ('routing_disabled','invalid_payload','error_rejected') THEN
        PERFORM public.platform_record_usage(r.buyer,'ping',src.id,r.campaign_id,d->>'decision_id');
      END IF;
      IF (d->>'available')::boolean THEN
        accepts:=accepts||jsonb_build_array(jsonb_build_object('campaign_id',r.campaign_id,'priority',r.priority,
          'weight',r.weight,'price',r.price,'last_won',r.last_won,
          'retention',d->>'reason'='accepted_retention_owner'));
      END IF;
    END LOOP;

    -- Rank the accepts: the committed buyer, then retention owners, then the
    -- strategy; ties go to the least recently won, then id. weighted_rotation
    -- is smooth weighted round robin over rotation_state.
    rotation:=xs.rotation_state;
    SELECT coalesce(sum((e->>'weight')::integer),0),coalesce(bool_or((e->>'retention')::boolean),false)
      INTO total,retention_accepts FROM jsonb_array_elements(accepts) e;
    SELECT array_agg(x.cid ORDER BY (x.cid IS NOT DISTINCT FROM committed_campaign) DESC,x.retention DESC,
        CASE xs.strategy WHEN 'priority_waterfall' THEN x.priority END ASC,
        CASE xs.strategy WHEN 'highest_price' THEN x.price END DESC NULLS LAST,
        CASE xs.strategy WHEN 'weighted_rotation' THEN x.current END DESC,
        x.last_won ASC NULLS FIRST,x.cid::text)
      INTO ranking FROM (SELECT (e->>'campaign_id')::uuid AS cid,(e->>'priority')::integer AS priority,
        (e->>'price')::numeric AS price,(e->>'last_won')::timestamptz AS last_won,
        coalesce((e->>'retention')::boolean,false) AS retention,
        coalesce((rotation->>(e->>'campaign_id'))::numeric,0)+(e->>'weight')::integer AS current
        FROM jsonb_array_elements(accepts) e) x;

    -- The real decision reserves an agent. If it loses a race, the next best
    -- accept is tried once.
    FOR attempt IN 1..least(2,coalesce(array_length(ranking,1),0)) LOOP
      pick:=ranking[attempt];
      d:=public.ping_decide_campaign(pick,src.id,payload,'exchange');
      IF (d->>'available')::boolean THEN winner_campaign:=pick; winner_decision:=d; EXIT; END IF;
      UPDATE ping_decisions SET caller_phone=NULL,caller_zip=NULL,rule_trace=rule_trace||hash_trace
        WHERE id=(d->>'decision_id')::uuid;
    END LOOP;

    IF xs.strategy='weighted_rotation' AND winner_campaign IS NOT NULL
    AND winner_campaign IS DISTINCT FROM committed_campaign AND NOT retention_accepts THEN
      SELECT rotation||coalesce(jsonb_object_agg(e->>'campaign_id',
          coalesce((rotation->>(e->>'campaign_id'))::numeric,0)+(e->>'weight')::integer
          -CASE WHEN (e->>'campaign_id')::uuid=winner_campaign THEN total ELSE 0 END),'{}'::jsonb)
        INTO rotation FROM jsonb_array_elements(accepts) e;
      UPDATE exchange_sources SET rotation_state=rotation WHERE source_id=src.id;
    END IF;
  END IF;

  reason:=coalesce(winner_decision->>'reason','exchange_no_buyer');
  INSERT INTO exchange_auctions(source_id,received_at,latency_ms,strategy,candidate_count,
    winner_campaign_id,winner_decision_id,reason,candidates)
  VALUES(src.id,started,greatest(0,floor(extract(epoch FROM clock_timestamp()-started)*1000))::integer,xs.strategy,
    jsonb_array_length(cand),winner_campaign,(winner_decision->>'decision_id')::uuid,reason,cand)
  RETURNING id INTO auction_id;
  -- One pooled shopper row per exchange ping, under the publisher's tenant.
  IF phone ~ '^\+[1-9][0-9]{7,14}$' THEN
    BEGIN PERFORM public.shopper_history_record(phone,src.tenant_id,src.id);
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'shopper_history_record_failed';
    END;
  END IF;
  -- The publisher never learns that the caller is a buyer's existing client.
  public_reason:=CASE WHEN reason='accepted_retention_owner' THEN
    CASE public.ping_agent_tier(winner_decision->>'agent_id',state_code,winner_campaign)
      WHEN 'partial' THEN 'accepted_partial' ELSE 'accepted_full' END
    ELSE reason END;
  SELECT c.transfer_number INTO transfer FROM ping_campaigns c WHERE c.id=winner_campaign;
  RETURN jsonb_build_object('authorized',true,'auction_id',auction_id,'available',winner_campaign IS NOT NULL,
    'reason',public_reason,'ttl_seconds',(winner_decision->>'ttl_seconds')::integer,'transfer_number',transfer);
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_admin_action(p_actor text, p_org text, p_action text, p_request uuid, p_command jsonb, p_verified_admin boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tenant uuid; relation text:=p_command->>'name'; operation text:=p_command->>'operation';
 args text; query text; answer jsonb; before_value jsonb:='{}'; after_value jsonb:='{}'; cols text; updates text; predicate text; row_value jsonb; routine record; target text:='collection';
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 SELECT tenant_id INTO tenant FROM public.resolve_deployment_subject(p_actor,p_org) WHERE authority='admin' OR p_verified_admin;
 IF tenant IS NULL THEN RAISE EXCEPTION 'Protected admin required' USING ERRCODE='42501'; END IF;
 IF p_action NOT IN ('access_review','consumer_lifecycle','post_call_coaching','client_recap','reshop_list','tenant_settings','contact_assignment','pipeline_settings','script_settings','vendor_pause','compliance_review','compliance_uploads','post_call_admin','retention_holds','trigger_knowledge_update','rts_ingest','recordings','enrollment_intakes','transcript_import','set_availability','test_ghl_webhook','stripe_checkout','stripe_portal','paragon_residence') THEN RAISE EXCEPTION 'Unknown administrator action'; END IF;
 INSERT INTO public.admin_action_permit VALUES(txid_current(),p_request);
 IF p_command->>'kind'='rpc' THEN
  target:=coalesce(p_command->'args'->>'p_call',p_command->'args'->>'p_call_id',p_command->'args'->>'p_contact',p_command->'args'->>'p_hold',p_command->'args'->>'p_transcript',p_command->'args'->>'p_pipeline_id',p_command->'args'->>'p_stage_id',p_command->'args'->>'p_target',p_command->'args'->>'p_session_id',p_command->'args'->>'p_id','collection');
  IF target !~ '^[a-f0-9]{8}-[a-f0-9-]{27}$' THEN target:='collection'; END IF;
  IF relation='set_vendor_pause' THEN SELECT jsonb_build_object('vendor_pause',vendor_pause) INTO before_value FROM public.vendor_controls WHERE tenant_id=tenant; END IF;
  IF relation NOT IN ('regenerate_post_call_coaching','approve_client_recap','act_on_reshop','set_vendor_pause','save_opportunity_pipeline','delete_opportunity_stage','retry_failed_scoring','retry_post_call_transcript','retention_place_hold','retention_release_hold','retention_flag_complaint','retention_resolve_complaint','retention_certify_transcript','claim_compliance_pass','retry_ix_upload','request_conversely_run','save_compliance_version','save_enrollment_intake','commit_rts_ingestion','request_manual_transcript_gap','mint_recording_compliance_ticket') THEN RAISE EXCEPTION 'Unreviewed admin routine'; END IF;
  SELECT p.oid,p.proargnames,p.proargtypes,p.proretset INTO STRICT routine FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=relation;
  SELECT string_agg(format('%I => %s',e.key,CASE WHEN e.value='null'::jsonb THEN format('NULL::%s',t.oid::regtype) WHEN t.typname IN ('json','jsonb') THEN format('%L::%s',e.value::text,t.oid::regtype) ELSE format('%L::%s',e.value#>>'{}',t.oid::regtype) END),',') INTO args
  FROM jsonb_each(p_command->'args') e JOIN unnest(routine.proargnames,routine.proargtypes::oid[]) a(name,type) ON a.name=e.key JOIN pg_type t ON t.oid=a.type;
  IF (SELECT count(*) FROM jsonb_each(p_command->'args'))<>(SELECT count(*) FROM unnest(routine.proargnames) n WHERE p_command->'args' ? n) THEN RAISE EXCEPTION 'Invalid argument'; END IF;
  -- Original routine retains all ownership, feature, lease and budget fences.
  EXECUTE format('SELECT %s FROM public.%I(%s) x',CASE WHEN routine.proretset THEN 'coalesce(jsonb_agg(to_jsonb(x)),''[]'')' ELSE 'to_jsonb(x)' END,relation,args) INTO answer;
  IF NOT routine.proretset AND jsonb_typeof(answer)='object' AND answer ? relation THEN answer:=answer->relation; END IF;
  IF relation='set_vendor_pause' THEN SELECT jsonb_build_object('vendor_pause',vendor_pause) INTO after_value FROM public.vendor_controls WHERE tenant_id=tenant; END IF;
 ELSE
  IF relation NOT IN ('tenants','contacts','script_templates','manual_transcript_gap_fills','compliance_llm_passes','call_records','knowledge_entries','knowledge_update_drafts','knowledge_updates','knowledge_base','agent_availability','recording_compliance_tickets','transcript_ingestion_jobs','call_transcripts','transcript_chunks') OR operation NOT IN ('insert','update','delete','upsert') THEN RAISE EXCEPTION 'Unreviewed admin table mutation'; END IF;
  IF relation='tenants' THEN predicate:=format('t.id=%L::uuid',tenant); ELSIF relation='knowledge_updates' THEN predicate:=format('t.knowledge_base_id IN (SELECT id FROM public.knowledge_base WHERE tenant_id IS NULL OR tenant_id=%L::uuid)',tenant); ELSIF relation='agent_availability' THEN predicate:=format('t.agent_id IN (SELECT agent_slug FROM public.tenant_agents WHERE tenant_id=%L::uuid)',tenant); ELSE predicate:=format('t.tenant_id=%L::uuid',tenant); END IF;
  FOR row_value IN SELECT value FROM jsonb_array_elements(coalesce(p_command->'filters','[]')) LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=format('public.%I',relation)::regclass AND attname=row_value->>'column' AND attnum>0 AND NOT attisdropped) THEN RAISE EXCEPTION 'Invalid filter'; END IF;
   predicate:=predicate||format(' AND t.%I::text=%L',row_value->>'column',row_value->>'value');
   IF row_value->>'column'='id' AND row_value->>'value' ~ '^[a-f0-9]{8}-[a-f0-9-]{27}$' THEN target:=row_value->>'value'; END IF;
  END LOOP;
  IF operation IN ('update','delete') THEN EXECUTE format('SELECT public.admin_safe_summary(to_jsonb(t)) FROM public.%I t WHERE %s LIMIT 1',relation,predicate) INTO before_value; END IF;
  IF relation='contacts' THEN SELECT jsonb_build_object('assigned_agent_id',e.id) INTO before_value FROM public.contacts c LEFT JOIN public.tenant_agents r ON r.tenant_id=c.tenant_id AND r.agent_slug=c.assigned_agent_id LEFT JOIN public.enrolled_agents e ON e.tenant_id=r.tenant_id AND e.clerk_user_id=r.clerk_user_id WHERE c.id::text=target AND c.tenant_id=tenant; END IF;
  row_value:=p_command->'values';
  IF jsonb_typeof(row_value)='array' THEN RAISE EXCEPTION 'Bulk administrator changes require a reviewed routine'; END IF;
  IF operation IN ('insert','upsert','update') THEN
   IF relation<>'tenants' AND row_value ? 'tenant_id' AND row_value->>'tenant_id'<>tenant::text THEN RAISE EXCEPTION 'Foreign tenant'; END IF;
   IF operation IN ('insert','upsert') AND relation NOT IN ('tenants','agent_availability','knowledge_updates') THEN row_value:=row_value||jsonb_build_object('tenant_id',tenant); END IF;
   SELECT string_agg(format('%I',key),','),string_agg(format('%I=r.%I',key,key),',') INTO cols,updates FROM jsonb_object_keys(row_value) key;
   IF operation='update' THEN query:=format('UPDATE public.%I t SET %s FROM jsonb_populate_record(NULL::public.%I,$1) r WHERE %s RETURNING t.*',relation,updates,relation,predicate);
   ELSE query:=format('INSERT INTO public.%I(%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1) r RETURNING *',relation,cols,cols,relation); END IF;
  ELSE query:=format('DELETE FROM public.%I t WHERE %s RETURNING t.*',relation,predicate); END IF;
  EXECUTE 'WITH changed AS ('||query||') SELECT coalesce(jsonb_agg(to_jsonb(changed)),''[]'') FROM changed' INTO answer USING row_value;
  after_value:=public.admin_safe_summary(answer->0);
  IF relation='contacts' THEN SELECT jsonb_build_object('assigned_agent_id',e.id) INTO after_value FROM public.contacts c LEFT JOIN public.tenant_agents r ON r.tenant_id=c.tenant_id AND r.agent_slug=c.assigned_agent_id LEFT JOIN public.enrolled_agents e ON e.tenant_id=r.tenant_id AND e.clerk_user_id=r.clerk_user_id WHERE c.id::text=target AND c.tenant_id=tenant; END IF;
  IF p_command->>'projection' IS NULL THEN answer:='null'::jsonb;
  ELSIF p_command->>'projection'<>'*' THEN
   IF p_command->>'projection' !~ '^[a-z_][a-z0-9_,]*$' THEN RAISE EXCEPTION 'Invalid projection'; END IF;
   SELECT coalesce(jsonb_agg((SELECT coalesce(jsonb_object_agg(e.key,e.value),'{}') FROM jsonb_each(row_data) e WHERE e.key=ANY(string_to_array(p_command->>'projection',',')))),'[]') INTO answer FROM jsonb_array_elements(answer) row_data;
  END IF;
 END IF;
 BEGIN
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,before_summary,after_summary)
 VALUES(p_request,p_actor,tenant,p_action,relation,target,'succeeded',coalesce(before_value,'{}'),coalesce(after_value,'{}')) ON CONFLICT(request_id) DO NOTHING;
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Administrator audit unavailable' USING ERRCODE='P1611'; END;
 DELETE FROM public.admin_action_permit WHERE transaction_id=txid_current();
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.execute_operator_action(p_routine text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tenant uuid; request uuid:=gen_random_uuid(); before_value jsonb; after_value jsonb; answer jsonb;
BEGIN
 IF current_setting('role',true)<>'service_role' OR p_routine NOT IN ('provision_deployment_roster','configure_deployment_vendor') THEN RAISE EXCEPTION 'Reviewed server operator required' USING ERRCODE='42501'; END IF;
 SELECT tenant_id INTO tenant FROM public.deployment_settings WHERE singleton;
 IF p_routine='provision_deployment_roster' THEN
  tenant:=coalesce(tenant,(p_args->'p_profile'->>'tenantId')::uuid);
  SELECT jsonb_build_object('active_agent_ids',coalesce(jsonb_agg(id ORDER BY id) FILTER(WHERE is_active),'[]'),'active_count',count(*) FILTER(WHERE is_active),'inactive_count',count(*) FILTER(WHERE NOT is_active)) INTO before_value FROM public.tenant_agents WHERE tenant_id=tenant;
 ELSE
  SELECT jsonb_build_object('configured_sources',count(*)) INTO before_value FROM public.lead_sources WHERE tenant_id=tenant;
 END IF;
 INSERT INTO public.admin_action_permit VALUES(txid_current(),request);
 IF p_routine='provision_deployment_roster' THEN
  answer:=to_jsonb(public.provision_deployment_roster(p_args->'p_profile',p_args->'p_agents'));
  SELECT jsonb_build_object('active_agent_ids',coalesce(jsonb_agg(id ORDER BY id) FILTER(WHERE is_active),'[]'),'active_count',count(*) FILTER(WHERE is_active),'inactive_count',count(*) FILTER(WHERE NOT is_active)) INTO after_value FROM public.tenant_agents WHERE tenant_id=tenant;
 ELSE
  answer:=to_jsonb(public.configure_deployment_vendor(p_args->'p_vendor'));
  SELECT jsonb_build_object('configured_sources',count(*)) INTO after_value FROM public.lead_sources WHERE tenant_id=tenant;
 END IF;
 BEGIN
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,before_summary,after_summary)
 VALUES(request,'service:deployment_operator',tenant,p_routine,CASE WHEN p_routine='provision_deployment_roster' THEN 'tenant_agents' ELSE 'vendor_settings' END,tenant::text,'succeeded',before_value,after_value);
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Administrator audit unavailable' USING ERRCODE='P1611'; END;
 DELETE FROM public.admin_action_permit WHERE transaction_id=txid_current();RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.expire_agent_phone_sessions()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE agent record;
BEGIN
  IF NOT (SELECT enforced FROM telephony_presence_policy WHERE singleton) THEN RETURN; END IF;
  FOR agent IN SELECT agent_id FROM agent_availability ORDER BY agent_id FOR UPDATE LOOP
    DELETE FROM agent_phone_sessions WHERE agent_id=agent.agent_id AND expires_at<=clock_timestamp();
    IF NOT public.agent_phone_routable(agent.agent_id) THEN
      UPDATE agent_availability SET status='offline',available=false,toggled_at=clock_timestamp()
        WHERE agent_id=agent.agent_id AND (status IN ('available','callbacks_only') OR
          (status='busy' AND (active_call_sid IS NULL OR resume_status IS DISTINCT FROM 'offline')));
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.fail_scoring_job(p_job_id uuid, p_attempt_token uuid, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE j public.scoring_jobs;
BEGIN
  PERFORM cr.id FROM call_records cr JOIN scoring_jobs sj ON sj.call_id=cr.id WHERE sj.id=p_job_id FOR UPDATE OF cr;
  UPDATE scoring_jobs SET status='failed',error=left(p_error,1000),updated_at=now()
    WHERE id=p_job_id AND attempt_token=p_attempt_token AND status='pending' RETURNING * INTO j;
  IF j.id IS NULL THEN RETURN false; END IF;
  UPDATE call_records SET metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('scoring_status','failed',
    'scoring_error',left(p_error,1000),'scoring_failed_at',now()),updated_at=now()
    WHERE id=j.call_id AND metadata->>'scoring_job_id'=j.id::text;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.fence_coaching_dispatch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE score_on boolean:=public.deployment_feature_enabled('SCORING_ENABLED'); coach_on boolean:=public.deployment_feature_enabled('POST_CALL_COACHING_ENABLED');
 score_keys text[]:=ARRAY['call_id','tenant_id','revision','delivered_revision','available_at','last_error','snapshot_revision','transcript_ready_at','dispatch_attempts','retention_started_at'];
BEGIN
 IF NOT coach_on AND NEW.coaching_state IS NOT NULL AND (TG_OP='INSERT' OR
 (to_jsonb(NEW)-score_keys) IS DISTINCT FROM (to_jsonb(OLD)-score_keys)) THEN RETURN NULL; END IF;
 IF score_on THEN RETURN NEW; END IF;
 IF NOT coach_on THEN RETURN NULL; END IF;
 IF TG_OP='INSERT' THEN
  -- Coaching-only rows cannot make scoring work eligible while scoring is off.
  IF NEW.coaching_state<>'queued' OR NEW.available_at<>'infinity'::timestamptz OR NEW.delivered_revision<>NEW.revision OR NEW.snapshot_revision IS NOT NULL OR NEW.dispatch_attempts<>0 THEN RETURN NULL; END IF;
 ELSIF EXISTS(SELECT 1 FROM unnest(score_keys) k WHERE to_jsonb(NEW)->k IS DISTINCT FROM to_jsonb(OLD)->k) THEN RETURN NULL;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fence_deployment_queue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE flag text:=TG_ARGV[0]; row_data jsonb:=to_jsonb(NEW);
BEGIN
 IF flag='TRANSCRIPT_REQUEST_MODE' THEN
  SELECT CASE WHEN mode='automatic' THEN 'TRANSCRIPT_AUTO_RECOVERY_ENABLED' ELSE 'TRANSCRIPT_GAP_FILL_ENABLED' END INTO flag
   FROM manual_transcript_gap_fills WHERE id::text=row_data->>'job_id';
  IF flag IS NULL THEN RETURN NULL; END IF;
 END IF;
 IF flag='TRANSCRIPT_MODE' THEN
  flag:=CASE WHEN row_data->>'mode'='automatic' THEN 'TRANSCRIPT_AUTO_RECOVERY_ENABLED' ELSE 'TRANSCRIPT_GAP_FILL_ENABLED' END;
 END IF;
 IF NOT deployment_feature_enabled(flag) THEN RETURN NULL; END IF;
 IF TG_TABLE_NAME='integration_deliveries' AND row_data->>'kind'='report' AND NOT deployment_feature_enabled('OPERATIONAL_EMAIL_ENABLED') THEN RETURN NULL; END IF;
 IF TG_TABLE_NAME IN ('paragon_report_email_log','paragon_report_email_days') AND NOT deployment_feature_enabled('OPERATIONAL_EMAIL_ENABLED') THEN RETURN NULL; END IF;
 IF TG_TABLE_NAME='compliance_daily_summaries' AND (NOT deployment_feature_enabled('IX_UPLOAD_ENABLED') OR NOT deployment_feature_enabled('OPERATIONAL_EMAIL_ENABLED')) THEN RETURN NULL; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.finalize_telephony_transcript(p_call_sid text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a record; rid uuid;
BEGIN
 FOR a IN SELECT id,direction,call_record_id FROM telephony_call_attempts WHERE parent_call_sid=p_call_sid LOOP
  -- No speech: keep the missing-evidence reconciliation visible, don't fabricate a transcript.
  IF a.direction='inbound' THEN
   IF NOT EXISTS(SELECT 1 FROM telephony_transcript_segments WHERE attempt_id=a.id) THEN CONTINUE; END IF;
   rid:=ensure_inbound_transcript_record(a.id);
  ELSE
   rid:=a.call_record_id;
   IF NOT EXISTS(SELECT 1 FROM call_records WHERE id=rid AND transcript_id IS NOT NULL
    AND nullif(trim(transcript_raw),'') IS NOT NULL) THEN CONTINUE; END IF;
  END IF;
  UPDATE call_records c SET metadata=coalesce(c.metadata,'{}')||jsonb_build_object('transcript_finalized_at',now()),
   call_end=coalesce(c.call_end,(SELECT max(ended_at) FROM telephony_call_attempts WHERE call_record_id=rid)),
   call_duration_seconds=coalesce(c.call_duration_seconds,(SELECT nullif(max(talk_seconds),0) FROM telephony_call_attempts WHERE call_record_id=rid))
   WHERE c.id=rid;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.finish_automatic_transcript_recovery(p_call_id uuid, p_tenant_id uuid, p_job_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 PERFORM 1 FROM call_records WHERE id=p_call_id AND tenant_id=p_tenant_id FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM manual_transcript_gap_fills WHERE id=p_job_id AND call_id=p_call_id AND tenant_id=p_tenant_id AND mode='automatic' AND status='complete') THEN RAISE EXCEPTION 'Recovery unavailable'; END IF;
 UPDATE call_records SET metadata=(coalesce(metadata,'{}')-'scoring_error_code'-'scoring_error'-'scoring_failed_at'-'transcript_recovery_reason')||jsonb_build_object('scoring_status','queued'),compliance_status='queued' WHERE id=p_call_id;
 PERFORM refresh_sale_compliance_request(p_call_id);
 UPDATE transcript_score_dispatch SET delivered_revision=greatest(0,revision-1),dispatch_attempts=0,available_at=clock_timestamp(),transcript_ready_at=clock_timestamp(),last_error=NULL WHERE call_id=p_call_id;
END $function$

CREATE OR REPLACE FUNCTION public.finish_call_conference(p_call_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE room call_conferences; at timestamptz:=clock_timestamp();
BEGIN
 SELECT * INTO STRICT room FROM call_conferences WHERE call_id=p_call_id FOR UPDATE;
 IF room.ended_at IS NOT NULL THEN RETURN false; END IF;
 UPDATE call_conferences SET phase='ended',ended_at=at,customer_held=false WHERE call_id=p_call_id;
 UPDATE call_participants SET status='left',left_at=coalesce(left_at,at) WHERE call_id=p_call_id;
 UPDATE telephony_call_attempts SET status='completed',ended_at=at,
  talk_seconds=greatest(0,floor(extract(epoch FROM at-answered_at))::integer) WHERE id=room.attempt_id;
 UPDATE inbound_calls SET status='completed',ended_at=at WHERE twilio_call_sid=room.parent_call_sid AND tenant_id=room.tenant_id;
 UPDATE call_records SET call_end=at,call_duration_seconds=greatest(0,floor(extract(epoch FROM at-call_start))::integer),
  metadata=coalesce(metadata,'{}')||jsonb_build_object('transcript_finalized_at',at) WHERE id=p_call_id;
 -- Existing disposition requires terminal evidence for an outbound browser parent.
 INSERT INTO telephony_events(tenant_id,twilio_call_sid,event,payload)
 VALUES(room.tenant_id,room.parent_call_sid,'call_completed',jsonb_build_object('CallSid',room.parent_call_sid,'CallStatus','completed','source','conference'));
 PERFORM release_call_agent(room.parent_call_sid,NULL);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.finish_integration_delivery(p_id uuid, p_token uuid, p_status integer, p_result text, p_delay integer, p_error jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE job integration_deliveries;
BEGIN
  SELECT * INTO job FROM integration_deliveries WHERE id=p_id AND lease_token=p_token AND status='processing' FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  UPDATE integration_delivery_attempts SET finished_at=now(),status_code=p_status,result=p_result,error_detail=p_error WHERE delivery_id=p_id AND lease_token=p_token;
  UPDATE integration_deliveries SET
    status=CASE WHEN job.superseded THEN 'canceled' WHEN p_result='sent' THEN 'sent' WHEN p_result='disabled' THEN 'canceled'
      WHEN now()+make_interval(secs=>p_delay)>=expires_at THEN 'failed' ELSE 'pending' END,
    sent_at=CASE WHEN p_result='sent' THEN now() ELSE NULL END,
    available_at=now()+make_interval(secs=>p_delay),lease_until=NULL
    WHERE id=p_id;
  IF job.kind='report' THEN
    UPDATE integration_report_log SET result=CASE WHEN p_result='sent' THEN 'sent' ELSE 'delivery_'||p_result END
    WHERE source_id=job.source_id AND report_date=(job.payload->>'date')::date;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_paragon_report_email(p_log_id bigint, p_status text, p_message_id text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_date date;
BEGIN
  IF p_status NOT IN ('sent','failed') THEN RAISE EXCEPTION 'Invalid status'; END IF;
  UPDATE paragon_report_email_log SET status=p_status,finished_at=clock_timestamp(),
    provider_message_id=p_message_id,error_code=p_error_code WHERE id=p_log_id AND status='sending'
    RETURNING report_date INTO v_date;
  IF v_date IS NULL THEN RAISE EXCEPTION 'No active send log'; END IF;
  UPDATE paragon_report_email_days SET status=p_status,lease_until=NULL,updated_at=clock_timestamp()
    WHERE report_date=v_date;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_paragon_residence_job(p_call uuid, p_token uuid, p_candidate jsonb, p_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE j paragon_residence_jobs;c inbound_calls; chosen jsonb; ranks jsonb:='{"transcript":3,"sep_lookup":2,"contact_record":1}';result jsonb; ended timestamptz;
BEGIN
 SELECT * INTO STRICT j FROM paragon_residence_jobs WHERE inbound_call_id=p_call AND lease_token=p_token AND lease_until>clock_timestamp() FOR UPDATE;
 SELECT * INTO STRICT c FROM inbound_calls WHERE id=p_call AND tenant_id=j.tenant_id FOR UPDATE;
 chosen:=j.capture;
 IF p_candidate->>'source' IN ('transcript','sep_lookup','contact_record')
 AND coalesce((ranks->>(p_candidate->>'source'))::int,0)>=coalesce((ranks->>(j.capture->>'source'))::int,0)
 AND ((ranks->>(p_candidate->>'source'))::int>coalesce((ranks->>(j.capture->>'source'))::int,0)
 OR coalesce((p_candidate->>'observed_at')::timestamptz,'epoch')>=coalesce((j.capture->>'observed_at')::timestamptz,'epoch')) THEN
  IF (p_candidate->>'zip',p_candidate->>'state') IS DISTINCT FROM (j.capture->>'zip',j.capture->>'state') THEN
   result:=confirm_paragon_call_state(c.id,c.tenant_id,c.routed_agent_id,p_candidate->>'zip',p_candidate->>'state');
  END IF;
  IF p_candidate IS DISTINCT FROM (j.capture-'captured_at') THEN chosen:=p_candidate||jsonb_build_object('captured_at',clock_timestamp()); END IF;
 END IF;
 IF chosen<>'{}'::jsonb THEN
  UPDATE inbound_calls SET vendor_metadata=jsonb_set(coalesce(vendor_metadata,'{}'),'{paragon_residence}',chosen||jsonb_build_object('ambiguous',coalesce((p_metadata->>'ambiguous')::boolean,false) OR coalesce((j.metadata->>'ambiguous')::boolean,false)),true)
   WHERE id=c.id AND tenant_id=c.tenant_id AND vendor_metadata->'paragon_residence' IS DISTINCT FROM chosen||jsonb_build_object('ambiguous',coalesce((p_metadata->>'ambiguous')::boolean,false) OR coalesce((j.metadata->>'ambiguous')::boolean,false));
 END IF;
 SELECT max(ended_at) INTO ended FROM telephony_call_attempts WHERE inbound_call_id=c.id AND tenant_id=c.tenant_id;
 UPDATE paragon_residence_jobs SET capture=chosen,metadata=metadata||p_metadata||jsonb_build_object('ambiguous',coalesce((p_metadata->>'ambiguous')::boolean,false) OR coalesce((metadata->>'ambiguous')::boolean,false)),
 lease_token=NULL,lease_until=NULL,last_error=NULL,attempts=0,updated_at=clock_timestamp(),
 available_at=CASE WHEN c.status IN ('completed','declined','canceled','failed','no-answer','busy','voicemail','rejected') AND coalesce(ended,c.created_at)<clock_timestamp()-interval '5 minutes'
 THEN 'infinity'::timestamptz ELSE clock_timestamp()+interval '3 seconds' END
 WHERE inbound_call_id=c.id;
 RETURN coalesce(result,jsonb_build_object('captured',chosen<>'{}'::jsonb));
END; $function$

CREATE OR REPLACE FUNCTION public.finish_post_call_coaching(p_call uuid, p_token uuid, p_note jsonb, p_model text, p_prompt text, p_reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.call_records; d public.transcript_score_dispatch; t public.call_transcripts; terminal boolean;
BEGIN
 IF NOT public.deployment_feature_enabled('POST_CALL_COACHING_ENABLED') THEN RETURN false; END IF;
 SELECT * INTO c FROM public.call_records WHERE id=p_call FOR UPDATE;
 SELECT * INTO d FROM public.transcript_score_dispatch WHERE call_id=p_call FOR UPDATE;
 IF c.id IS NULL OR p_token IS NULL OR d.coaching_lease_until IS NULL OR d.coaching_token IS DISTINCT FROM p_token OR d.coaching_state NOT IN ('queued','processing') OR d.coaching_lease_until<clock_timestamp() THEN RETURN false; END IF;
 SELECT * INTO t FROM public.call_transcripts WHERE tenant_id=c.tenant_id AND (id=c.transcript_id OR call_record_id=c.id) ORDER BY (id=c.transcript_id) DESC NULLS LAST,created_at DESC,id DESC LIMIT 1;
 IF NOT public.coaching_call_eligible(c) THEN p_reason:='call_ineligible';p_note:=NULL; END IF;
 IF p_note IS NOT NULL AND d.coaching_revision IS DISTINCT FROM md5(public.scoring_transcript_snapshot(c)::text||coalesce(t.transcript_text,'')) THEN p_reason:='transcript_changed';p_note:=NULL; END IF;
 IF p_reason IS NOT NULL AND p_reason NOT IN ('redaction_failed','invalid_output','generation_failed','attempts_exhausted','call_ineligible','transcript_changed') THEN RAISE EXCEPTION 'Invalid coaching reason'; END IF;
 terminal:=p_reason IS NULL OR d.coaching_attempts>=3 OR p_reason IN ('redaction_failed','attempts_exhausted','call_ineligible','transcript_changed');
 IF terminal THEN
  INSERT INTO public.post_call_coaching(call_id,transcript_id,agent_id,tenant_id,status,objections,did_well,reason,model,prompt_version,generation,retention_started_at)
  VALUES(c.id,t.id,c.agent_id,c.tenant_id,CASE WHEN p_reason IS NULL THEN p_note->>'status' ELSE 'failed' END,
   CASE WHEN p_reason IS NULL THEN p_note->'objections' ELSE '[]' END,CASE WHEN p_reason IS NULL THEN p_note->>'did_well' END,p_reason,left(p_model,120),left(p_prompt,80),d.coaching_generation,c.retention_started_at)
  ON CONFLICT(call_id) DO UPDATE SET agent_id=c.agent_id,tenant_id=c.tenant_id,transcript_id=t.id,status=excluded.status,objections=excluded.objections,did_well=excluded.did_well,reason=excluded.reason,model=excluded.model,prompt_version=excluded.prompt_version,generation=excluded.generation,generated_at=clock_timestamp(),reviewed_at=NULL,reviewed_by=NULL;
 END IF;
 UPDATE public.transcript_score_dispatch SET coaching_state=CASE WHEN terminal THEN CASE WHEN p_reason IS NULL THEN 'done' ELSE 'failed' END ELSE 'queued' END,
 coaching_available_at=clock_timestamp()+make_interval(secs=>30*power(2,greatest(0,d.coaching_attempts-1))::integer),coaching_lease_until=NULL,coaching_token=NULL WHERE call_id=c.id;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.finish_practice_result(p_id uuid, p_token uuid, p_result jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.practice_sessions;
BEGIN
 PERFORM public.practice_server();SELECT * INTO s FROM public.practice_sessions WHERE id=p_id FOR UPDATE;
 IF p_token IS NULL OR s.work_token IS DISTINCT FROM p_token OR s.lease_until<=clock_timestamp() OR s.status NOT IN ('active','ending') THEN RETURN false; END IF;
 IF p_result='null'::jsonb THEN p_result:=NULL; END IF;
 IF p_result IS NOT NULL THEN
  IF s.work_kind<>'result' OR s.status<>'ending' THEN RETURN false; END IF;
  INSERT INTO public.practice_results(id,tenant_id,agent_id,score,rules_version,scorecard,coaching,retention_started_at) VALUES(s.id,s.tenant_id,s.agent_id,(p_result->>'score')::numeric,p_result->>'rules_version',p_result->'scorecard',p_result->'coaching',s.retention_started_at);
 END IF;
 UPDATE public.practice_sessions SET status=CASE WHEN p_result IS NULL THEN 'incomplete' ELSE 'completed' END,end_reason=CASE WHEN p_result IS NULL THEN 'generation_failed' ELSE end_reason END,ended_at=clock_timestamp(),work_token=NULL,work_kind=NULL,lease_until=NULL WHERE id=p_id; RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.finish_practice_turn(p_id uuid, p_token uuid, p_reply text, p_ended boolean, p_collected text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.practice_sessions; at_ms integer;
BEGIN
 PERFORM public.practice_server();SELECT * INTO s FROM public.practice_sessions WHERE id=p_id FOR UPDATE;
 IF p_token IS NULL OR s.work_token IS DISTINCT FROM p_token OR s.work_kind<>'turn' OR s.lease_until<=clock_timestamp() OR s.status<>'active' THEN RETURN NULL; END IF;
 IF p_reply IS NULL OR length(btrim(p_reply))=0 OR length(p_reply)>600 OR p_ended IS NULL OR p_collected IS NULL THEN RAISE EXCEPTION 'Invalid reply' USING ERRCODE='22023'; END IF;
 at_ms:=greatest((s.transcript->-1->>'end_ms')::integer+1,(extract(epoch FROM clock_timestamp()-s.started_at)*1000)::integer);
 s.transcript:=s.transcript||jsonb_build_array(jsonb_build_object('speaker','customer','text',p_reply,'start_ms',at_ms,'end_ms',at_ms+1));
 s.end_reason:=CASE WHEN s.expires_at<=clock_timestamp() THEN 'time_limit' WHEN p_ended THEN 'consumer' WHEN s.turn_count+1>=s.turn_limit THEN 'turn_limit' END;
 UPDATE public.practice_sessions SET transcript=s.transcript,turn_count=turn_count+1,collected=ARRAY(SELECT DISTINCT unnest(collected||p_collected)),status=CASE WHEN s.end_reason IS NULL THEN 'active' ELSE 'ending' END,end_reason=s.end_reason,work_token=NULL,work_kind=NULL,lease_until=NULL,last_activity_at=clock_timestamp() WHERE id=p_id RETURNING * INTO s;
 RETURN to_jsonb(s)-ARRAY['work_token','work_kind','lease_until'];
END $function$

CREATE OR REPLACE FUNCTION public.finish_supervisor_listen(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.supervisor_listen_sessions; ended timestamptz:=clock_timestamp();
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 UPDATE public.supervisor_listen_sessions SET ended_at=least(ended,lease_until,expires_at),duration_seconds=greatest(0,extract(epoch FROM least(ended,lease_until,expires_at)-started_at)::integer) WHERE mode='listen' AND id=p_id AND ended_at IS NULL RETURNING * INTO s;
 IF s.id IS NULL THEN RETURN false; END IF;
 BEGIN
