CREATE OR REPLACE FUNCTION public.get_available_seps(input_zip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  result jsonb;
  snapshot public.fema_feed_snapshot%ROWTYPE;
  matches jsonb := '[]'::jsonb;
  disaster_sep jsonb;
  fresh boolean;
BEGIN
  result := public.get_available_seps_before_fema_078(input_zip);
  IF result ? 'error' THEN RETURN result; END IF;
  SELECT * INTO snapshot FROM public.fema_feed_snapshot WHERE singleton;
  fresh := coalesce(snapshot.status = 'live'
    AND snapshot.fetched_at BETWEEN now() - interval '24 hours' AND now(), false);
  IF fresh THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'disaster_number', d->'disasterNumber', 'title', d->>'title',
      'type', d->>'type', 'declared', d->>'declaredDate',
      'sep_ends', CASE WHEN (d->>'isOngoing')::boolean THEN 'Open (incident ongoing)' ELSE d->>'sepEndDate' END,
      'county_fips', d->>'countyFips', 'designated_area', d->'counties'
    )), '[]'::jsonb) INTO matches
    FROM jsonb_array_elements(snapshot.disasters) d
    WHERE (d->>'verified')::boolean AND d->>'source' = 'OpenFEMA'
      AND NOT coalesce((d->>'paOnly')::boolean, true)
      AND (coalesce((d->>'iaProgram')::boolean, false) OR coalesce((d->>'ihProgram')::boolean, false))
      AND (coalesce((d->>'isOngoing')::boolean, false) OR (d->>'sepEndDate')::date >= CURRENT_DATE)
      AND EXISTS (SELECT 1 FROM public.zip_county_crosswalk z
        WHERE z.zip = input_zip AND z.county_fips = d->>'countyFips' AND z.state_code = d->>'state');
  END IF;
  disaster_sep := jsonb_build_object(
    'sep_type', 'Disaster / Emergency SEP',
    'cfr_reference', '42 CFR Sec. 422.62(b)(18)(ii); CMS HPMS memo',
    'available', fresh AND jsonb_array_length(matches) > 0,
    'period', 'Duration of disaster declaration + 2 calendar months',
    'data_status', CASE WHEN fresh THEN 'live' ELSE 'unavailable' END,
    'fetched_at', snapshot.fetched_at, 'checked_at', snapshot.checked_at,
    'evidence', CASE WHEN NOT fresh THEN 'FEMA data unavailable'
      WHEN jsonb_array_length(matches) > 0 THEN 'County designated in OpenFEMA; verify missed election period and beneficiary impact. Data from ' || snapshot.fetched_at::text
      ELSE 'No active FEMA declaration in this county. Data from ' || snapshot.fetched_at::text END,
    'disasters', matches
  );
  RETURN jsonb_set(result, '{seps}', (
    SELECT coalesce(jsonb_agg(CASE WHEN s->>'sep_type' = 'Disaster / Emergency SEP' THEN disaster_sep ELSE s END ORDER BY ord), '[]'::jsonb)
    FROM jsonb_array_elements(result->'seps') WITH ORDINALITY AS items(s, ord)
  ));
END $function$

CREATE OR REPLACE FUNCTION public.get_post_call_coaching_dispatch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb:='[]'; d public.transcript_score_dispatch; token uuid;
BEGIN
 IF NOT public.deployment_feature_enabled('POST_CALL_COACHING_ENABLED') THEN RETURN '[]'; END IF;
 PERFORM public.enqueue_post_call_coaching();
 FOR d IN SELECT * FROM public.transcript_score_dispatch
 WHERE coaching_state IN ('queued','processing') AND coaching_available_at<=clock_timestamp()
 AND (coaching_lease_until IS NULL OR coaching_lease_until<clock_timestamp())
 ORDER BY coaching_available_at,call_id LIMIT 20 FOR UPDATE SKIP LOCKED LOOP
  token:=gen_random_uuid();
  UPDATE public.transcript_score_dispatch SET coaching_token=token,coaching_lease_until=clock_timestamp()+interval '3 minutes' WHERE call_id=d.call_id;
  IF d.coaching_attempts>=3 THEN
   PERFORM public.finish_post_call_coaching(d.call_id,token,NULL,NULL,NULL,'attempts_exhausted');
  ELSE
   UPDATE public.transcript_score_dispatch SET coaching_attempts=coaching_attempts+1 WHERE call_id=d.call_id;
   result:=result||jsonb_build_array(jsonb_build_object('call_id',d.call_id,'tenant_id',d.tenant_id,'coaching_token',token));
  END IF;
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.get_sale_compliance_dispatch()
 RETURNS SETOF transcript_score_dispatch
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE j record;
BEGIN
 IF NOT public.deployment_feature_enabled('SCORING_ENABLED') THEN RETURN; END IF;
 FOR j IN SELECT call_id,tenant_id,id FROM manual_transcript_gap_fills WHERE mode='automatic' AND status IN ('queued','processing') AND created_at<clock_timestamp()-interval '15 minutes' LOOP
  UPDATE manual_transcript_gap_fills SET status='failed',error='recovery_worker_expired' WHERE id=j.id;
  PERFORM mark_transcript_recovery_blocked(j.call_id,j.tenant_id,'recovery_worker_expired');
 END LOOP;
 RETURN QUERY SELECT * FROM get_sale_compliance_dispatch_before_147();
 INSERT INTO transcript_recovery_alerts(call_id,tenant_id,reason)
 SELECT c.id,c.tenant_id,'scoring_attempts_exhausted' FROM call_records c
 WHERE c.metadata->>'scoring_error_code'='scoring_attempts_exhausted' AND c.compliance_status='failed'
 ON CONFLICT DO NOTHING;
END $function$

CREATE OR REPLACE FUNCTION public.get_sale_compliance_dispatch_pre133()
 RETURNS SETOF transcript_score_dispatch
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records; d transcript_score_dispatch; active_until timestamptz;
BEGIN
 FOR c IN
  SELECT cr.* FROM call_records cr JOIN transcript_score_dispatch ds ON ds.call_id=cr.id AND ds.tenant_id=cr.tenant_id
  WHERE public.is_compliance_sale(cr.call_outcome) AND cr.compliance_requested_at IS NOT NULL
   AND public.sale_compliance_transcript_ready(cr) AND ds.available_at<=clock_timestamp()
   AND ds.delivered_revision<ds.revision
  ORDER BY ds.available_at LIMIT 20 FOR UPDATE OF cr SKIP LOCKED
 LOOP
  SELECT * INTO d FROM transcript_score_dispatch WHERE call_id=c.id FOR UPDATE;
  SELECT max(lease_until) INTO active_until FROM scoring_jobs
   WHERE call_id=c.id AND transcript_revision=md5(scoring_transcript_snapshot(c)::text)
    AND status='pending' AND lease_until>clock_timestamp();
  IF active_until IS NOT NULL THEN
   UPDATE transcript_score_dispatch SET available_at=active_until WHERE call_id=c.id;
   CONTINUE;
  END IF;
  IF d.dispatch_attempts>=3 THEN
   UPDATE transcript_score_dispatch SET delivered_revision=revision,available_at='infinity',
    last_error='scoring_attempts_exhausted' WHERE call_id=c.id;
   UPDATE call_records SET metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
    'scoring_status','failed','scoring_error_code','scoring_attempts_exhausted','scoring_failed_at',clock_timestamp()),
    updated_at=clock_timestamp() WHERE id=c.id;
   CONTINUE;
  END IF;
  UPDATE transcript_score_dispatch SET dispatch_attempts=dispatch_attempts+1,
   available_at=clock_timestamp()+interval '60 seconds' WHERE call_id=c.id RETURNING * INTO d;
  RETURN NEXT d;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.guard_call_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP='INSERT' AND NEW.parent_call_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.parent_call_id IS NOT DISTINCT FROM OLD.parent_call_id THEN RETURN NEW; END IF;
  -- Let the FK restore children when their parent is deleted.
  IF pg_trigger_depth()>1 AND NEW.parent_call_id IS NULL THEN RETURN NEW; END IF;
  IF current_user NOT IN ('postgres','service_role') THEN RAISE EXCEPTION 'Use the combine calls service'; END IF;
  IF NEW.parent_call_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id::text,118));
    IF NOT EXISTS (SELECT 1 FROM call_records p WHERE p.id=NEW.parent_call_id
      AND p.tenant_id=NEW.tenant_id AND p.parent_call_id IS NULL AND p.id<>NEW.id)
      OR EXISTS (SELECT 1 FROM call_records child WHERE child.parent_call_id=NEW.id) THEN
      RAISE EXCEPTION 'Invalid call parent';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_client_recap_templates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ch text; t jsonb;
BEGIN
 IF NEW.client_recap_templates IS NOT DISTINCT FROM OLD.client_recap_templates THEN RETURN NEW; END IF;
 IF NOT public.deployment_feature_enabled('CLIENT_RECAP_ENABLED') OR NOT EXISTS(SELECT 1 FROM public.admin_action_permit WHERE transaction_id=txid_current()) THEN RAISE EXCEPTION 'Audited administrator required' USING ERRCODE='42501'; END IF;
 IF NOT public.valid_client_recap_templates(NEW.client_recap_templates) THEN RAISE EXCEPTION 'Invalid recap template' USING ERRCODE='22023'; END IF;
 FOREACH ch IN ARRAY ARRAY['sms','pdf'] LOOP
  t:=NEW.client_recap_templates->ch;
  IF t IS DISTINCT FROM OLD.client_recap_templates->ch THEN
   IF (t->>'version')::integer<>(OLD.client_recap_templates->ch->>'version')::integer THEN RAISE EXCEPTION 'Template changed; reload' USING ERRCODE='40001'; END IF;
   NEW.client_recap_templates:=jsonb_set(NEW.client_recap_templates,ARRAY[ch,'version'],to_jsonb((t->>'version')::integer+1));
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hold_whisper_upload(p_call uuid, p_tenant uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.call_records;k text;
BEGIN
 SELECT * INTO STRICT c FROM public.call_records WHERE id=p_call AND tenant_id=p_tenant FOR UPDATE;
 IF c.metadata->'supervisor_whisper' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Whisper call required'; END IF;
 IF c.metadata->'whisper_upload_hold'->'held'='true'::jsonb THEN RETURN; END IF;
 UPDATE public.call_records SET metadata=coalesce(metadata,'{}')||jsonb_build_object('whisper_upload_hold',jsonb_build_object('held',true,'at',clock_timestamp())) WHERE id=c.id;
 -- Use the existing operational alert state, transition history and delivery queue.
 PERFORM pg_advisory_xact_lock(161,1);
 k:='sha256:'||encode(sha256(convert_to(c.id::text,'UTF8')),'hex');
 IF NOT EXISTS(SELECT 1 FROM public.operational_alert_state WHERE rule='whisper_upload_held' AND condition_key=k AND active) THEN
  INSERT INTO public.operational_alert_history(rule,condition_key,state,count,threshold) VALUES('whisper_upload_held',k,'raised',1,1);
  INSERT INTO public.operational_alert_state VALUES('whisper_upload_held',k,true) ON CONFLICT(rule,condition_key) DO UPDATE SET active=true;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.link_recording_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE r record;
BEGIN
  FOR r IN SELECT id FROM recording_ingestion WHERE
    (TG_TABLE_NAME='telephony_call_attempts' AND attempt_id=NEW.id) OR
    (TG_TABLE_NAME='inbound_calls' AND inbound_call_id=NEW.id AND attempt_id IS NULL)
  LOOP PERFORM resolve_recording_attribution(r.id); END LOOP;
  IF TG_TABLE_NAME='inbound_calls' AND NEW.call_record_id IS NOT NULL THEN
    UPDATE call_records SET recording_url=coalesce(recording_url,NEW.recording_url),
      recording_storage_path=coalesce(recording_storage_path,NEW.recording_storage_path)
    WHERE id=NEW.call_record_id AND tenant_id=NEW.tenant_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.link_telephony_call_record(p_record_id uuid, p_tenant_id uuid, p_sid text, p_user_id text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE attempt telephony_call_attempts; why text;
BEGIN
  PERFORM 1 FROM call_records WHERE id=p_record_id AND tenant_id=p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RETURN 'record_not_found'; END IF;
  SELECT a.* INTO attempt FROM telephony_call_attempts a
    JOIN tenant_agents t ON t.agent_slug=a.agent_id AND t.tenant_id=a.tenant_id
    WHERE a.tenant_id=p_tenant_id AND t.clerk_user_id=p_user_id
      AND (a.parent_call_sid=p_sid OR a.child_call_sid=p_sid)
    ORDER BY a.created_at DESC LIMIT 1 FOR UPDATE OF a;
  IF attempt.inbound_call_id IS NOT NULL THEN
    PERFORM 1 FROM inbound_calls WHERE id=attempt.inbound_call_id FOR UPDATE;
  END IF;
  IF attempt.id IS NULL THEN why:='sid_or_agent_not_found';
  ELSIF EXISTS(SELECT 1 FROM call_records WHERE id=p_record_id AND twilio_call_sid IS NOT NULL AND twilio_call_sid<>attempt.parent_call_sid) THEN why:='record_linked_to_other_call';
  ELSIF attempt.call_record_id IS NOT NULL AND attempt.call_record_id<>p_record_id THEN why:='already_linked';
  ELSIF attempt.inbound_call_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM inbound_calls WHERE id=attempt.inbound_call_id AND call_record_id IS NOT NULL AND call_record_id<>p_record_id
  ) THEN why:='already_linked';
  ELSE
    UPDATE telephony_call_attempts SET call_record_id=p_record_id WHERE id=attempt.id;
    UPDATE inbound_calls SET call_record_id=p_record_id WHERE id=attempt.inbound_call_id AND tenant_id=p_tenant_id;
    UPDATE call_records SET twilio_call_sid=attempt.parent_call_sid WHERE id=p_record_id;
    DELETE FROM integration_link_issues WHERE call_record_id=p_record_id;
    RETURN 'linked';
  END IF;
  INSERT INTO integration_link_issues(call_record_id,twilio_call_sid,reason)
    VALUES(p_record_id,p_sid,why) ON CONFLICT(call_record_id) DO UPDATE SET reason=EXCLUDED.reason,updated_at=now();
  RETURN why;
END;
$function$

CREATE OR REPLACE FUNCTION public.list_practice_sessions(p_actor text, p_org text, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i jsonb; rows jsonb; summaries jsonb;
BEGIN
 i:=public.practice_identity(p_actor,p_org);
 WITH scoped AS (SELECT s.*,r.score FROM public.practice_sessions s LEFT JOIN public.practice_results r USING(id) WHERE s.tenant_id=(i->>'tenant_id')::uuid AND (s.agent_id=(i->>'agent_id')::uuid OR i->>'authority'='admin' OR i->>'authority'='manager' AND i->'team_agent_ids' ? s.agent_id::text))
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO rows FROM (SELECT id,agent_id,scenario_id,difficulty,status,end_reason,started_at,score FROM scoped WHERE p_before IS NULL OR (started_at,id)<(p_before,p_before_id) ORDER BY started_at DESC,id DESC LIMIT 31) x;
 WITH scoped AS (SELECT s.*,r.score,r.scorecard FROM public.practice_sessions s JOIN public.practice_results r USING(id) WHERE s.status='completed' AND s.tenant_id=(i->>'tenant_id')::uuid AND (s.agent_id=(i->>'agent_id')::uuid OR i->>'authority'='admin' OR i->>'authority'='manager' AND i->'team_agent_ids' ? s.agent_id::text)), ranked AS (SELECT *,row_number() OVER(PARTITION BY agent_id ORDER BY started_at DESC,id DESC) n FROM scoped), stats AS (SELECT agent_id,count(*) sessions_completed,round(avg(score),1) average_score,round(avg(score) FILTER(WHERE n<=5)-avg(score) FILTER(WHERE n>5 AND n<=10),1) trend FROM ranked GROUP BY agent_id)
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO summaries FROM (SELECT stats.*,e.name,coalesce((SELECT jsonb_agg(m) FROM (SELECT item->>'intent_code' rule,count(*) missed FROM scoped s CROSS JOIN LATERAL jsonb_array_elements(s.scorecard->'scorecard_items') item WHERE s.agent_id=stats.agent_id AND item->>'result'='fail' GROUP BY item->>'intent_code' ORDER BY count(*) DESC,item->>'intent_code' LIMIT 5)m),'[]') most_missed_rules FROM stats JOIN public.enrolled_agents e ON e.id=stats.agent_id) x;
 RETURN jsonb_build_object('authority',i->>'authority','own_agent_id',i->>'agent_id','sessions',rows,'summaries',summaries);
END $function$

CREATE OR REPLACE FUNCTION public.log_availability_change()
