CREATE OR REPLACE FUNCTION public.log_operator_admin_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE value jsonb:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; tenant uuid; request uuid;
BEGIN
 IF current_setting('role',true) NOT IN ('service_role','none') THEN RAISE EXCEPTION 'Server operator required' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.admin_action_permit WHERE transaction_id=txid_current()) THEN RETURN NULL; END IF;
 tenant:=nullif(value->>'tenant_id','')::uuid;
 IF tenant IS NULL THEN SELECT tenant_id INTO tenant FROM public.deployment_settings WHERE singleton; END IF;
 IF tenant IS NULL THEN RETURN NULL; END IF;
 request:=md5(txid_current()::text||':'||tenant::text)::uuid;
 BEGIN
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,before_summary,after_summary)
 VALUES(request,'service:deployment_operator',tenant,'operator_'||TG_TABLE_NAME,TG_TABLE_NAME,coalesce(value->>'id',(SELECT id::text FROM public.tenant_agents WHERE tenant_id=tenant AND clerk_user_id=value->>'clerk_user_id' ORDER BY id LIMIT 1),tenant::text),'succeeded',public.admin_safe_summary(CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) ELSE '{}' END),public.admin_safe_summary(CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) ELSE '{}' END)) ON CONFLICT(request_id) DO NOTHING;
 EXCEPTION WHEN others THEN RAISE EXCEPTION 'Administrator audit unavailable' USING ERRCODE='P1611'; END;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.log_pii_access(p_contact_id uuid, p_requesting_agent_id uuid, p_action text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_agent RECORD;
BEGIN
  IF current_setting('role',true)<>'service_role' AND NOT public.deployment_can_access_contact(p_contact_id) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501'; END IF;
  IF p_action NOT IN ('view', 'edit', 'export', 'search') THEN
    RAISE EXCEPTION 'invalid pii_access_log action: %', p_action;
  END IF;
  SELECT * INTO v_agent FROM public.deployment_assert_roster(p_requesting_agent_id);
  IF v_agent.id IS NULL THEN
    RAISE EXCEPTION 'requesting agent % not found', p_requesting_agent_id;
  END IF;
  IF auth.role() = 'authenticated'
     AND v_agent.clerk_user_id IS DISTINCT FROM NULLIF(auth.jwt() ->> 'sub', '') THEN
    RAISE EXCEPTION 'access denied: requesting agent is not the signed-in Clerk user';
  END IF;
  INSERT INTO public.pii_access_log (contact_id, agent_id, clerk_user_id, action, ip_address, user_agent)
  VALUES (p_contact_id, p_requesting_agent_id, v_agent.clerk_user_id, p_action, p_ip_address, p_user_agent);
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_compliance_not_applicable(p_call_id uuid, p_tenant_id uuid, p_reason text, p_rules_version text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records; prior compliance_scorecards; selected_template uuid; card_id uuid;
BEGIN
 SELECT * INTO STRICT c FROM call_records WHERE id=p_call_id AND tenant_id=p_tenant_id FOR UPDATE;
 IF p_rules_version<>'cy2027-full-rubric-6' OR p_reason NOT IN ('Excluded call outcome','Talk time below 15 minutes','No connected product conversation reached','No original rubric for this product') THEN RAISE EXCEPTION 'Unrecognized N/A policy'; END IF;
 IF EXISTS(SELECT 1 FROM compliance_llm_passes WHERE call_id=c.id AND status IN ('reserved','running')) THEN RAISE EXCEPTION 'Scoring in progress'; END IF;
 SELECT * INTO prior FROM compliance_scorecards WHERE id=c.compliance_scorecard_id AND tenant_id=c.tenant_id;
 IF prior.scoring_state='na' AND prior.rules_version=p_rules_version THEN RETURN prior.id; END IF;
 selected_template:=prior.template_id;
 IF selected_template IS NULL THEN SELECT id INTO selected_template FROM scoring_templates WHERE product_type=c.product_type AND is_active ORDER BY version DESC LIMIT 1; END IF;
 IF selected_template IS NULL THEN RAISE EXCEPTION 'No product template available for N/A header'; END IF;
 INSERT INTO compliance_scorecards(call_id,tenant_id,template_id,overall_score,overall_grade,total_points_earned,total_points_possible,pass_fail,
 auto_fail_triggered,auto_fail_reasons,category_scores,risk_level,risk_flags,corrective_actions_needed,rules_version,scoring_state,supersedes_id,tokens_used,estimated_cost_usd,request_attempts)
 VALUES(c.id,c.tenant_id,selected_template,NULL,NULL,0,0,'N/A',false,'{}','{}','low',ARRAY[p_reason],false,p_rules_version,'na',prior.id,0,0,0) RETURNING id INTO card_id;
 UPDATE call_records SET compliance_scorecard_id=card_id,metadata=coalesce(metadata,'{}')||jsonb_build_object('scoring_status','na','scoring_error',p_reason),compliance_status='na' WHERE id=c.id;
 RETURN card_id;
END $function$

