CREATE OR REPLACE FUNCTION public.match_contacts_by_phone(p_phones text[], p_requesting_agent_id uuid)
 RETURNS TABLE(phone text, id uuid, first_initial text, last_initial text, email_set boolean, dob_set boolean, zip text, county text, state text, current_carrier text, current_plan text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_agent RECORD;
BEGIN
  SELECT * INTO v_agent FROM public.deployment_assert_roster(p_requesting_agent_id);
  IF v_agent.id IS NULL THEN
    RAISE EXCEPTION 'requesting agent % not found', p_requesting_agent_id;
  END IF;
  IF auth.role() = 'authenticated'
     AND v_agent.clerk_user_id IS DISTINCT FROM NULLIF(auth.jwt() ->> 'sub', '') THEN
    RAISE EXCEPTION 'access denied: requesting agent is not the signed-in Clerk user';
  END IF;

  RETURN QUERY
  SELECT input.phone, c.id, c.first_initial, c.last_initial, c.email_set, c.dob_set,
    c.zip, c.county, c.state, c.current_carrier, c.current_plan
  FROM unnest(p_phones) AS input(phone)
  JOIN public.contacts c ON c.tenant_id = v_agent.tenant_id AND (v_agent.role='admin' OR c.assigned_agent_id=v_agent.agent_slug)
    AND c.phone_hash = public.pii_blind_index(public.normalize_phone_e164(input.phone));
END;
$function$

CREATE OR REPLACE FUNCTION public.merge_contacts_internal(p_keep uuid, p_drop uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a public.contacts; b public.contacts; fk RECORD;
BEGIN
  -- Stable lock order also serializes concurrent reciprocal merges.
  PERFORM id FROM public.contacts WHERE id IN (p_keep, p_drop) ORDER BY id FOR UPDATE;
  SELECT * INTO a FROM public.contacts WHERE id = p_keep;
  SELECT * INTO b FROM public.contacts WHERE id = p_drop;
  IF a.id IS NULL OR b.id IS NULL OR a.id = b.id OR a.tenant_id != b.tenant_id THEN
    RAISE EXCEPTION 'Contacts cannot be merged';
  END IF;
  INSERT INTO public.contact_merge_archive(tenant_id, kept_contact_id, merged_contact_id, encrypted_snapshot)
  VALUES(a.tenant_id, a.id, b.id, public.encrypt_pii_value(to_jsonb(b)::text));
  -- Move every single-column FK, including messages, notes, calls, policies,
  -- lead intelligence and PII audit history. Media stays attached to messages.
  FOR fk IN
    SELECT c.conrelid::regclass AS tbl, att.attname AS col
    FROM pg_constraint c JOIN pg_attribute att
      ON att.attrelid = c.conrelid AND att.attnum = c.conkey[1]
    WHERE c.contype = 'f' AND c.confrelid = 'public.contacts'::regclass
      AND array_length(c.conkey, 1) = 1
  LOOP
    EXECUTE format('UPDATE %s SET %I = $1 WHERE %I = $2', fk.tbl, fk.col, fk.col) USING p_keep, p_drop;
  END LOOP;
  DELETE FROM public.contacts WHERE id = p_drop;
  UPDATE public.contacts SET
    first_name = coalesce(a.first_name, b.first_name), last_name = coalesce(a.last_name, b.last_name),
    phone = coalesce(a.phone, b.phone), email = coalesce(a.email, b.email), dob = coalesce(a.dob, b.dob),
    address = coalesce(a.address, b.address), zip = coalesce(a.zip, b.zip), county = coalesce(a.county, b.county),
    state = coalesce(a.state, b.state), assigned_agent_id = coalesce(a.assigned_agent_id, b.assigned_agent_id),
    current_carrier = coalesce(a.current_carrier, b.current_carrier), current_plan = coalesce(a.current_plan, b.current_plan),
    medicare_parts = coalesce(a.medicare_parts, b.medicare_parts), mbi_last4 = coalesce(a.mbi_last4, b.mbi_last4),
    do_not_call = a.do_not_call OR b.do_not_call
  WHERE id = p_keep;
  -- Existing encryption trigger retains survivor-only custom keys; fill missing ones.
  UPDATE public.contacts SET pii_encrypted = coalesce(b.pii_encrypted, '{}'::jsonb) || coalesce(pii_encrypted, '{}'::jsonb)
  WHERE id = p_keep;
END;
$function$

CREATE OR REPLACE FUNCTION public.merge_contacts_secure(p_keep_id uuid, p_duplicate_id uuid, p_phone text, p_requesting_agent_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a public.tenant_agents; c public.contacts; n TEXT;
BEGIN
  a := public.deployment_assert_roster(p_requesting_agent_id);
  IF a.id IS NULL OR a.clerk_user_id IS DISTINCT FROM nullif(auth.jwt()->>'sub', '') THEN
    RAISE EXCEPTION 'Your agent account is not linked to this session';
  END IF;
  PERFORM id FROM public.contacts WHERE id IN (p_keep_id, p_duplicate_id) ORDER BY id FOR UPDATE;
  FOR c IN SELECT * FROM public.contacts WHERE id IN (p_keep_id, p_duplicate_id) LOOP
    IF c.tenant_id != a.tenant_id OR (a.role != 'admin' AND c.assigned_agent_id IS DISTINCT FROM a.agent_slug) THEN
      RAISE EXCEPTION 'Only the assigned agent or an administrator can merge these contacts';
    END IF;
  END LOOP;
  n := public.normalize_phone_e164(p_phone);
  IF n IS NULL OR NOT EXISTS (SELECT 1 FROM public.contacts WHERE id = p_duplicate_id AND public.normalize_phone_e164(phone) = n) THEN
    RAISE EXCEPTION 'The duplicate changed. Refresh and try again.';
  END IF;
  PERFORM public.merge_contacts_internal(p_keep_id, p_duplicate_id);
  UPDATE public.contacts SET phone = n WHERE id = p_keep_id;
  INSERT INTO public.pii_access_log(contact_id, agent_id, clerk_user_id, action)
  VALUES(p_keep_id, a.id, a.clerk_user_id, 'edit');
END;
$function$

CREATE OR REPLACE FUNCTION public.messages_normalize_phone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
  NEW.from_number := coalesce(public.normalize_phone_e164(NEW.from_number), NEW.from_number);
  NEW.to_number := coalesce(public.normalize_phone_e164(NEW.to_number), NEW.to_number);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.minimize_ghl_delivery_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE payload jsonb; reduced jsonb;
BEGIN
 payload := public.decrypt_pii_value(NEW.payload_encrypted)::jsonb;
 IF payload IS NULL OR jsonb_typeof(payload) <> 'object' THEN
  RAISE EXCEPTION 'Invalid CRM delivery snapshot';
 END IF;
 SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) INTO reduced
 FROM jsonb_each(payload) WHERE key = ANY(ARRAY[
'planType','zip','firstName','lastName','phone','email','state','medicaid',
  'prevCarrier','newCarrier','planName','enrollCode','premium','sunfireCode',
  'effectiveDate','sixtyDayDate','sep','contractId','planId','segmentId',
  'enrollmentId','pcpName','agency','aor','assignedUserId','assignedTo','hra','hraDate','submittedAt'
 ]::text[]);
 NEW.payload_encrypted := public.encrypt_pii_value(reduced::text);
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.mint_supervisor_listen(p_actor text, p_org text, p_session text, p_attempt uuid, p_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target jsonb; gid uuid;
BEGIN
 target:=public.supervisor_listen_authorize(p_actor,p_org,p_attempt);
 IF (SELECT event FROM public.telephony_events WHERE tenant_id=(target->>'tenant')::uuid AND event IN ('session_lock','session_unlock') AND payload->>'clerk_user_id'=p_actor ORDER BY occurred_at DESC,id DESC LIMIT 1)='session_lock' THEN RAISE EXCEPTION 'Session locked' USING ERRCODE='42501'; END IF;
 IF nullif(p_session,'') IS NULL THEN RAISE EXCEPTION 'Session required' USING ERRCODE='42501'; END IF;
 -- Bound unused grants per viewer; old capabilities are invalidated atomically.
 DELETE FROM public.supervisor_listen_grants WHERE actor_id=p_actor OR expires_at<clock_timestamp();
 INSERT INTO public.supervisor_listen_grants(token_hash,tenant_id,actor_id,session_id,agent_id,attempt_id,call_id,expires_at)
 VALUES(p_hash,(target->>'tenant')::uuid,p_actor,p_session,(target->>'agent')::uuid,p_attempt,(target->>'call')::uuid,clock_timestamp()+interval '45 seconds') RETURNING id INTO gid;
 RETURN gid;
END $function$

