 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target jsonb; gid uuid;
BEGIN
 target:=public.supervisor_whisper_authorize(p_actor,p_org,p_attempt);
 IF nullif(p_session,'') IS NULL THEN RAISE EXCEPTION 'Session required' USING ERRCODE='42501'; END IF;
 DELETE FROM public.supervisor_listen_grants WHERE actor_id=p_actor OR expires_at<clock_timestamp();
 INSERT INTO public.supervisor_listen_grants(token_hash,tenant_id,actor_id,session_id,agent_id,attempt_id,call_id,expires_at,mode)
 VALUES(p_hash,(target->>'tenant')::uuid,p_actor,p_session,(target->>'agent')::uuid,p_attempt,(target->>'call')::uuid,clock_timestamp()+interval '45 seconds','whisper') RETURNING id INTO gid;
 RETURN gid;
END $function$

CREATE OR REPLACE FUNCTION public.move_opportunity_stage(p_opportunity_id uuid, p_to_stage_id uuid, p_requesting_agent_id uuid, p_expected_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE o public.opportunities; dest_pipeline uuid;
BEGIN
  SELECT * INTO o FROM public.opportunities WHERE id = p_opportunity_id;
  IF o.id IS NULL THEN RAISE EXCEPTION 'Opportunity not found'; END IF;
  IF current_setting('role',true)<>'service_role' AND public.deployment_row_visible('opportunities',to_jsonb(o)) IS NOT TRUE THEN RAISE EXCEPTION 'Opportunity access denied' USING ERRCODE='42501'; END IF; PERFORM public.opportunities_assert_agent(o.tenant_id,p_requesting_agent_id);
  SELECT pipeline_id INTO dest_pipeline FROM public.pipeline_stages WHERE id = p_to_stage_id AND tenant_id = o.tenant_id;
  -- Stable lock order across moves, edits and stage deletion prevents races.
  PERFORM id FROM public.pipelines WHERE id IN (o.pipeline_id,dest_pipeline) ORDER BY id FOR UPDATE;
  RETURN public.opportunities_move_internal(o.id,p_to_stage_id,p_requesting_agent_id,p_expected_stage_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.next_post_call_request(p_session_id uuid, p_worker_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE request post_call_requests;
BEGIN
 PERFORM 1 FROM post_call_jobs WHERE session_id=p_session_id AND worker_id=p_worker_id FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO request FROM post_call_requests WHERE session_id=p_session_id AND status='queued' ORDER BY sequence FOR UPDATE LIMIT 1;
 IF NOT FOUND THEN
 UPDATE post_call_jobs j SET worker_id=NULL,status=CASE WHEN j.provider_errors<>'{}'::jsonb OR EXISTS(
 SELECT 1 FROM post_call_requests r WHERE r.session_id=j.session_id AND r.status='failed') THEN 'failed' ELSE 'completed' END,
 progress=CASE WHEN j.provider_errors<>'{}'::jsonb THEN 'provider_failed' ELSE 'finished' END,
 completed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE session_id=p_session_id;
 RETURN NULL; END IF;
 UPDATE post_call_requests SET status='running' WHERE session_id=p_session_id AND request_key=request.request_key;
 UPDATE post_call_jobs SET progress=request.action,updated_at=clock_timestamp() WHERE session_id=p_session_id;
 RETURN jsonb_build_object('request_key',request.request_key,'action',request.action,'payload',request.payload);
END; $function$

CREATE OR REPLACE FUNCTION public.operational_paid_budget(p_budgets jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE budget jsonb; used_requests integer; percentage numeric:=0; scoring_percentage numeric;
BEGIN
 IF current_setting('role',true)<>'service_role' OR jsonb_array_length(p_budgets)>12 THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 FOR budget IN SELECT value FROM jsonb_array_elements(p_budgets) LOOP
 IF (budget->>'limit')::integer<1 OR length(budget->>'key')>256 THEN RAISE EXCEPTION 'Invalid budget'; END IF;
 SELECT used INTO used_requests FROM public.admission_counters WHERE key_hash=encode(sha256(convert_to(budget->>'key','UTF8')),'hex') AND window_seconds=86400 AND window_start=floor(extract(epoch FROM clock_timestamp())/86400)::bigint*86400;
 percentage:=greatest(percentage,100.0*coalesce(used_requests,0)/(budget->>'limit')::integer);
 END LOOP;
 SELECT CASE WHEN halted THEN 100 ELSE 100.0*reserved_tokens/token_cap END INTO scoring_percentage FROM public.compliance_daily_budget WHERE day=(clock_timestamp() AT TIME ZONE 'UTC')::date;
 RETURN greatest(percentage,coalesce(scoring_percentage,0));
END $function$

CREATE OR REPLACE FUNCTION public.operational_status(p_window integer DEFAULT 900)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE queues jsonb:='[]'; t text; depth bigint; age numeric; failed bigint; failures bigint:=0; tenant uuid; dry jsonb; result jsonb;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 IF p_window<1 OR p_window>86400 THEN RAISE EXCEPTION 'Invalid operational window'; END IF;
 SELECT tenant_id INTO tenant FROM public.deployment_settings WHERE singleton;
 FOREACH t IN ARRAY ARRAY['integration_deliveries','post_call_jobs','post_call_requests','scoring_jobs','recording_ingestion','conversely_submissions','ix_uploads','ghl_enrollment_deliveries','manual_transcript_gap_fills','paragon_residence_jobs'] LOOP
 EXECUTE format('SELECT count(*) FILTER(WHERE coalesce(j->>''status'',j->>''copy_status'') IN (''pending'',''queued'',''processing'',''running'',''uploading'',''retry'')),coalesce(max(extract(epoch FROM clock_timestamp()-coalesce((j->>''created_at'')::timestamptz,(j->>''started_at'')::timestamptz,(j->>''first_seen_at'')::timestamptz,(j->>''updated_at'')::timestamptz))) FILTER(WHERE coalesce(j->>''status'',j->>''copy_status'') IN (''pending'',''queued'',''processing'',''running'',''uploading'',''retry'')),0),count(*) FILTER(WHERE coalesce(j->>''status'',j->>''copy_status'')=''failed'') FROM (SELECT to_jsonb(t) j FROM public.%I t) q WHERE NOT(j ? ''tenant_id'') OR j->>''tenant_id''=$1',t) INTO depth,age,failed USING tenant::text;
 queues:=queues||jsonb_build_array(jsonb_build_object('queue',t,'depth',depth,'oldest_age_seconds',greatest(0,floor(age))));failures:=failures+failed;
 END LOOP;
 SELECT count(*) FILTER(WHERE coaching_state IN ('queued','processing')),coalesce(max(extract(epoch FROM clock_timestamp()-coaching_queued_at)) FILTER(WHERE coaching_state IN ('queued','processing')),0),count(*) FILTER(WHERE coaching_state='failed') INTO depth,age,failed FROM public.transcript_score_dispatch WHERE tenant_id=tenant;
 queues:=queues||jsonb_build_array(jsonb_build_object('queue','post_call_coaching','depth',depth,'oldest_age_seconds',greatest(0,floor(age))));failures:=failures+failed;
 SELECT jsonb_build_object('finished_at',finished_at,'counts',public.operational_count_summary(r.counts),'deleted',public.operational_count_summary(r.deleted),'skipped_by_hold',public.operational_count_summary(r.skipped_by_hold),'skipped_by_reference',public.operational_count_summary(r.skipped_by_reference),'failures',public.operational_count_summary(r.failures)) INTO dry FROM public.retention_runs r WHERE mode='dry-run' AND status='complete' ORDER BY started_at DESC LIMIT 1;
 SELECT jsonb_build_object('queues',queues,'failed_jobs',failures,'whisper_upload_holds',(SELECT coalesce(jsonb_agg('sha256:'||encode(sha256(convert_to(id::text,'UTF8')),'hex')),'[]') FROM public.call_records WHERE metadata->'supervisor_whisper'='true'::jsonb AND metadata->'whisper_upload_hold'->'held'='true'::jsonb),'active_alerts',(SELECT count(*) FROM public.operational_alert_state WHERE active),
 'last_success',(SELECT jsonb_object_agg(job_name,s.last_success_at) FROM unnest(ARRAY['alert_evaluator','repair_telephony_record_links','enqueue_availability_push','enqueue_disposition_postbacks','enqueue_daily_vendor_reports','compliance_schedule','ix_schedule','presence_sweep','recording_worker','transcript_worker','paragon_billing','paragon_residence','call_status_recovery','conference_recovery','admission_prune','nightly_analytics','weekly_coaching','sync_fema','sync_bulletins','paragon_daily_email','retention']) job_name LEFT JOIN public.scheduled_job_status s ON s.job=job_name), 'last_purge_dry_run',dry,
 'lease_conflicts',count(*) FILTER(WHERE event LIKE '%lease%denied%' OR event LIKE '%lease%conflict%'),
 'audit_failures',count(*) FILTER(WHERE event IN ('audit_write_failed','admin_log_write_failed')),
 'rate_rejections',count(*) FILTER(WHERE event='admission_rejected'),
 'provider_requests',count(*) FILTER(WHERE event='provider_result'),
 'provider_errors',count(*) FILTER(WHERE event='provider_result' AND status>=400),
 'routing_anomalies',count(*) FILTER(WHERE event IN ('presence_sweep_failed','false_overflow','routing_anomaly'))+coalesce(public.operational_routing_anomalies(p_window),0),
 'purge_failures',(SELECT count(*) FROM public.retention_runs pr WHERE (pr.status='failed' OR pr.failures<>'{}'::jsonb) AND pr.started_at>clock_timestamp()-make_interval(secs=>p_window))+(SELECT count(*) FROM public.recording_ingestion WHERE deletion_pending_at<clock_timestamp()-interval '1 hour'),
 'paid_usd',(SELECT coalesce(sum(estimated_cost_usd),0) FROM public.compliance_llm_requests WHERE created_at>=date_trunc('day',clock_timestamp())),
 'subject_denials',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') FROM (SELECT subject,count(*) count FROM public.operational_events WHERE occurred_at>clock_timestamp()-make_interval(secs=>p_window) AND event IN ('authorization_denied','verification_failed') AND subject IS NOT NULL GROUP BY subject) s)) INTO result
 FROM public.operational_events WHERE occurred_at>clock_timestamp()-make_interval(secs=>p_window);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.opportunities_assert_agent(p_tenant_id uuid, p_agent_id uuid, p_admin boolean DEFAULT false)
 RETURNS tenant_agents
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a public.tenant_agents;
BEGIN
 a:=public.deployment_assert_roster(p_agent_id);
 IF a.tenant_id IS DISTINCT FROM p_tenant_id OR (p_admin AND a.role<>'admin' AND current_setting('role',true)<>'service_role') THEN
  RAISE EXCEPTION 'Workspace authority required' USING ERRCODE='42501';
 END IF;
 RETURN a;
END $function$

CREATE OR REPLACE FUNCTION public.opportunities_move_internal(p_id uuid, p_stage_id uuid, p_agent_id uuid, p_expected_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE o public.opportunities; dest public.pipeline_stages; old_name text; old_color text; h uuid; ts timestamptz;
BEGIN
  SELECT * INTO o FROM public.opportunities WHERE id = p_id FOR UPDATE;
  IF o.id IS NULL OR o.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Opportunity not found or deleted'; END IF;
  IF o.stage_id IS DISTINCT FROM p_expected_stage_id THEN
    RAISE EXCEPTION 'This opportunity changed in another session. Refresh and try again.' USING ERRCODE = '40001';
  END IF;
  SELECT * INTO dest FROM public.pipeline_stages WHERE id = p_stage_id AND tenant_id = o.tenant_id;
  IF dest.id IS NULL THEN RAISE EXCEPTION 'Stage does not belong to this workspace'; END IF;
  IF o.stage_id = dest.id THEN RETURN to_jsonb(o) - 'pii_encrypted' - 'title' - 'notes'; END IF;
  SELECT name,color INTO old_name,old_color FROM public.pipeline_stages WHERE id = o.stage_id;
  ts := clock_timestamp();
  UPDATE public.opportunities SET stage_id = dest.id, pipeline_id = dest.pipeline_id,
    status = CASE WHEN dest.is_won THEN 'won' WHEN dest.is_lost THEN 'lost' ELSE 'open' END,
    stage_entered_at = ts, updated_at = ts WHERE id = o.id RETURNING * INTO o;
  INSERT INTO public.opportunity_stage_history(tenant_id,opportunity_id,from_stage_id,to_stage_id,from_stage_name,to_stage_name,from_stage_color,to_stage_color,changed_by,changed_at)
    VALUES(o.tenant_id,o.id,p_expected_stage_id,dest.id,old_name,dest.name,old_color,dest.color,p_agent_id,ts) RETURNING id INTO h;
  INSERT INTO public.opportunity_events(tenant_id,opportunity_id,history_id,event_type,payload,created_at)
    VALUES(o.tenant_id,o.id,h,'opportunity.stage_changed',jsonb_build_object(
      'opportunity_id',o.id,'from_stage_id',p_expected_stage_id,'to_stage_id',dest.id,'changed_by',p_agent_id,'changed_at',ts),ts);
  RETURN to_jsonb(o) - 'pii_encrypted' - 'title' - 'notes';
END;
$function$

CREATE OR REPLACE FUNCTION public.outbound_dnc_status(p_phone text, p_requesting_agent_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE tenant UUID; normalized TEXT;
BEGIN
  IF auth.role() = 'service_role' THEN
    tenant := p_tenant_id;
  ELSE
    SELECT a.tenant_id INTO tenant FROM public.tenant_agents a
    WHERE a.id = p_requesting_agent_id AND a.is_active = true
      AND a.clerk_user_id = nullif(auth.jwt()->>'sub', '');
  END IF;
  IF tenant IS NULL THEN RAISE EXCEPTION 'Active tenant agent required'; END IF;
  normalized := public.normalize_phone_e164(p_phone);
  IF normalized IS NULL THEN RAISE EXCEPTION 'Enter a valid phone number'; END IF;
  RETURN EXISTS (SELECT 1 FROM public.contacts c WHERE c.tenant_id = tenant
    AND c.do_not_call = true
    AND (c.phone_hash = public.pii_blind_index(normalized)
      OR public.normalize_phone_e164(c.phone) = normalized));
END;
$function$

CREATE OR REPLACE FUNCTION public.paragon_hours_open(p_hours jsonb, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE local_at timestamp; day_config jsonb; opens time; closes time;
BEGIN
 IF p_hours IS NULL OR p_at IS NULL OR p_hours->>'timezone' IS DISTINCT FROM public.deployment_timezone() THEN RETURN false; END IF;
 local_at:=p_at AT TIME ZONE public.deployment_timezone();
 day_config:=p_hours->'days'->((ARRAY['sun','mon','tue','wed','thu','fri','sat'])[extract(dow FROM local_at)::integer+1]);
 IF day_config->>'enabled' IS DISTINCT FROM 'true' THEN RETURN false; END IF;
 IF coalesce(day_config->>'start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
 OR coalesce(day_config->>'end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RETURN false; END IF;
 opens:=(day_config->>'start')::time; closes:=(day_config->>'end')::time;
 RETURN opens<closes AND local_at::time>=opens AND local_at::time<closes;
EXCEPTION WHEN OTHERS THEN RETURN false;
END; $function$

CREATE OR REPLACE FUNCTION public.paragon_new_ping_gate(p_tenant uuid, p_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c vendor_controls; n integer;
BEGIN
 SELECT * INTO c FROM vendor_controls WHERE tenant_id=p_tenant;
 IF c.tenant_id IS NULL THEN RETURN 'controls_missing'; END IF;
 IF c.vendor_pause THEN RETURN 'vendor_paused'; END IF;
 IF NOT paragon_hours_open(c.staffed_hours,p_at) THEN RETURN 'outside_staffed_hours'; END IF;
 n:=(paragon_daily_status(p_tenant,p_at)->>'billable_count')::integer;
 IF c.paragon_cap_mode='hard' AND c.paragon_daily_cap IS NOT NULL AND n>=c.paragon_daily_cap THEN RETURN 'daily_cap_reached'; END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.paragon_ping(p_key_hash text, p_state text, p_phone text DEFAULT NULL::text, p_call_id text DEFAULT NULL::text, p_routing_enabled boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE src lead_sources; cfg vendor_routing_config; ctl vendor_controls;
  local_now timestamp; day_cfg jsonb; staffed boolean:=true;
  state_code text:=upper(trim(coalesce(p_state,''))); key text;
  existing paragon_agent_reservations; selected record; eligible_count integer;
  decision text; accepted boolean:=false; gate text; committed paragon_ping_decisions; gate_at timestamptz;
BEGIN
  SELECT NULL::text AS agent_id,NULL::text AS tier INTO selected;
  SELECT * INTO src FROM lead_sources WHERE name=public.bootstrap_vendor_source_name() AND type='publisher' AND active
    AND (ping_key_hash=p_key_hash OR EXISTS(SELECT 1 FROM availability_consumers
      WHERE name=public.bootstrap_vendor_source_name() AND active AND key_hash=p_key_hash)) LIMIT 1;
  IF src.id IS NULL THEN RETURN jsonb_build_object('authorized',false); END IF;
  DELETE FROM paragon_agent_reservations WHERE expires_at<clock_timestamp()-interval '1 day';
  SELECT * INTO cfg FROM vendor_routing_config WHERE source_id=src.id;
  SELECT * INTO ctl FROM vendor_controls WHERE tenant_id=src.tenant_id;
  key:=CASE WHEN nullif(trim(p_call_id),'') IS NOT NULL THEN 'id:'||left(trim(p_call_id),128)
    WHEN nullif(trim(p_phone),'') IS NOT NULL THEN 'phone:'||left(trim(p_phone),32) ELSE NULL END;
  -- Serialize a source's ping decisions; no in-flight budget in soft or hard mode.
  PERFORM pg_advisory_xact_lock(hashtextextended('paragon-ping:'||src.id::text,0));
  gate_at:=clock_timestamp();
  SELECT * INTO committed FROM paragon_ping_decisions d WHERE d.source_id=src.id AND d.available
    AND d.matched_call_sid IS NULL AND d.accepted_until>=gate_at AND d.caller_state=state_code
    AND ((nullif(p_call_id,'') IS NOT NULL AND d.vendor_call_id=p_call_id)
      OR (nullif(p_call_id,'') IS NULL AND nullif(p_phone,'') IS NOT NULL AND d.caller_phone=p_phone))
    ORDER BY received_at DESC LIMIT 1;
  IF p_routing_enabled AND committed.id IS NOT NULL AND NOT coalesce(ctl.vendor_pause,false) THEN
    RETURN jsonb_build_object('authorized',true,'available',true,'reason',committed.reason,'agent_id',committed.agent_id);
  END IF;
  gate:=paragon_new_ping_gate(src.tenant_id,gate_at);
  IF NOT p_routing_enabled THEN decision:='routing_disabled';
  ELSIF gate IS NOT NULL THEN decision:=gate;
  ELSIF cfg.source_id IS NULL THEN decision:='routing_unconfigured';
  ELSIF state_code='' OR NOT state_code=ANY(cfg.allowed_states) THEN decision:='state_not_allowed';
  ELSIF key IS NULL THEN decision:='missing_call_identity';
  ELSE
    PERFORM pg_advisory_xact_lock(hashtextextended(src.id::text||key,0));
    SELECT * INTO existing FROM paragon_agent_reservations
      WHERE source_id=src.id AND reservation_key=key FOR UPDATE;
    IF existing.id IS NOT NULL AND existing.expires_at>clock_timestamp()
      AND existing.consumed_call_sid IS NULL AND existing.caller_state=state_code
      AND EXISTS(SELECT 1 FROM agent_availability a WHERE a.agent_id=existing.agent_id
        AND public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)) THEN
      SELECT existing.agent_id AS agent_id,
        public.paragon_agent_tier(existing.agent_id,state_code,src.id) AS tier INTO selected;
      IF selected.tier NOT IN ('full','partial') THEN selected:=NULL; END IF;
    END IF;
    IF selected.agent_id IS NULL THEN
      DELETE FROM paragon_agent_reservations WHERE source_id=src.id AND reservation_key=key;
      SELECT count(*) INTO eligible_count FROM agent_availability a
        WHERE public.paragon_agent_tier(a.agent_id,state_code,src.id) IN ('full','partial');
      SELECT a.agent_id,public.paragon_agent_tier(a.agent_id,state_code,src.id) AS tier
        INTO selected FROM agent_availability a
        WHERE public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)
          AND public.paragon_agent_tier(a.agent_id,state_code,src.id) IN ('full','partial')
          AND NOT EXISTS(SELECT 1 FROM paragon_agent_reservations r
            WHERE r.agent_id=a.agent_id AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL)
        ORDER BY CASE public.paragon_agent_tier(a.agent_id,state_code,src.id)
          WHEN 'full' THEN 0 ELSE 1 END,a.last_assigned_at ASC NULLS FIRST,a.agent_id
        FOR UPDATE OF a SKIP LOCKED LIMIT 1;
      IF selected.agent_id IS NOT NULL THEN
        INSERT INTO paragon_agent_reservations(source_id,reservation_key,caller_state,agent_id,expires_at)
          VALUES(src.id,key,state_code,selected.agent_id,
            clock_timestamp()+make_interval(secs=>cfg.reservation_ttl_seconds));
      END IF;
    END IF;
    IF selected.agent_id IS NOT NULL THEN
      accepted:=true;
      decision:=CASE selected.tier WHEN 'full' THEN 'accepted_full' ELSE 'accepted_partial' END;
    ELSE
      decision:=CASE WHEN eligible_count>0 THEN 'all_eligible_busy' ELSE 'no_eligible_agent' END;
    END IF;
  END IF;
  INSERT INTO paragon_ping_decisions(source_id,caller_state,caller_phone,vendor_call_id,available,reason,agent_id)
    VALUES(src.id,nullif(state_code,''),nullif(p_phone,''),nullif(p_call_id,''),accepted,decision,selected.agent_id)
    RETURNING id,received_at INTO committed.id,committed.received_at;
  IF accepted THEN UPDATE paragon_ping_decisions SET accepted_until=committed.received_at+interval '30 seconds',
    rate_per_call=ctl.paragon_rate WHERE id=committed.id; END IF;
  RETURN jsonb_build_object('authorized',true,'available',accepted,'reason',decision,
    'agent_id',selected.agent_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.persist_access_review(p_actor text, p_org text, p_report jsonb DEFAULT NULL::jsonb, p_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tenant uuid; r public.access_review_reports;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 SELECT tenant_id INTO tenant FROM public.resolve_deployment_subject(p_actor,p_org) WHERE authority='admin';
 IF tenant IS NULL THEN RAISE EXCEPTION 'Protected admin required' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL THEN
 INSERT INTO public.access_review_reports(tenant_id,generated_by,report,exception_count)
 VALUES(tenant,p_actor,p_report,jsonb_array_length(p_report->'exceptions')) RETURNING * INTO r;
 PERFORM public.record_recovery_action('access_review_generate',p_actor,p_org,r.id,r.exception_count,true);
 ELSE
 SELECT * INTO r FROM public.access_review_reports WHERE id=p_id AND tenant_id=tenant FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Review unavailable' USING ERRCODE='42501'; END IF;
 IF r.reviewed_at IS NULL THEN
 UPDATE public.access_review_reports SET reviewed_at=clock_timestamp(),reviewed_by=p_actor WHERE id=p_id RETURNING * INTO r;
 PERFORM public.record_recovery_action('access_review_signoff',p_actor,p_org,r.id,r.exception_count,true);
 END IF;
 END IF;
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION public.persist_conference_transcript(p_participant_id uuid, p_segment_id uuid, p_speaker text, p_text text, p_captured_at timestamp with time zone, p_start_ms integer, p_end_ms integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE p call_participants; room call_conferences; c call_records; tid uuid; aid uuid; agency_name text; body text; entries jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM public.call_participants WHERE id=p_participant_id AND role='supervisor') THEN RAISE EXCEPTION 'Coach is isolated' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT p FROM call_participants WHERE id=p_participant_id;
 SELECT * INTO STRICT room FROM call_conferences WHERE call_id=p.call_id;
 IF p_speaker<>p.speaker THEN RAISE EXCEPTION 'Participant speaker mismatch'; END IF;
 -- Late flushed finals are retained after participant/call closure.
 SELECT * INTO STRICT c FROM call_records WHERE id=p.call_id AND tenant_id=room.tenant_id FOR UPDATE;
 INSERT INTO telephony_transcript_segments(id,attempt_id,speaker,text,captured_at,start_ms,end_ms,participant_id)
 VALUES(p_segment_id,room.attempt_id,p_speaker,p_text,p_captured_at,greatest(0,p_start_ms),greatest(0,p_end_ms),p.id)
 ON CONFLICT(id) DO NOTHING;
 IF NOT FOUND THEN RETURN c.id; END IF;
 SELECT string_agg(upper(s.speaker)||': '||s.text,E'\n' ORDER BY s.start_ms,s.end_ms,s.id),
  jsonb_agg(jsonb_build_object('id',s.id,'speaker',s.speaker,'participant_id',s.participant_id,'text',s.text,
   'start_ms',s.start_ms,'end_ms',s.end_ms) ORDER BY s.start_ms,s.end_ms,s.id)
 INTO body,entries FROM telephony_transcript_segments s JOIN telephony_call_attempts a ON a.id=s.attempt_id
 WHERE a.call_record_id=c.id;
 body:=concat_ws(E'\n',nullif(c.metadata->>'conference_prior_transcript',''),body);
 entries:=coalesce(c.metadata->'conference_prior_diarized','[]')||coalesce(entries,'[]');
 tid:=c.transcript_id;
 IF tid IS NULL THEN
  SELECT coalesce(agency_display_name,name) INTO agency_name FROM tenants WHERE id=c.tenant_id;
  SELECT id INTO aid FROM agents WHERE name=c.agent_name AND agency=agency_name LIMIT 1;
  IF aid IS NULL THEN INSERT INTO agents(name,agency,is_active) VALUES(c.agent_name,agency_name,true) RETURNING id INTO aid; END IF;
  INSERT INTO call_transcripts(tenant_id,agent_id,owner_agent_id,call_record_id,session_id,call_date,direction,
   product_line,transcript_text,source_system,source_id,phi_scrubbed,last_checkpoint_at)
  VALUES(c.tenant_id,aid,c.agent_id,c.id,c.session_id,c.call_start,c.call_direction,c.product_type,body,
   'deepgram_server',c.id::text,true,clock_timestamp()) RETURNING id INTO tid;
 ELSE UPDATE call_transcripts SET transcript_text=body,last_checkpoint_at=clock_timestamp(),updated_at=clock_timestamp()
  WHERE id=tid AND tenant_id=c.tenant_id;
 END IF;
 UPDATE call_records SET transcript_id=tid,transcript_raw=body,transcript_diarized=entries,updated_at=clock_timestamp()
 WHERE id=c.id;
 RETURN c.id;
END $function$

CREATE OR REPLACE FUNCTION public.persist_manual_gap_result(p_job_id uuid, p_expected_transcript jsonb, p_lines jsonb, p_range_index integer, p_provider_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE j manual_transcript_gap_fills;c call_records;merged jsonb;body text;
BEGIN
 SELECT cr.* INTO STRICT c FROM call_records cr JOIN manual_transcript_gap_fills g ON g.call_id=cr.id WHERE g.id=p_job_id FOR UPDATE OF cr;
 SELECT * INTO STRICT j FROM manual_transcript_gap_fills WHERE id=p_job_id FOR UPDATE;
 IF j.status<>'processing' OR c.tenant_id<>j.tenant_id THEN RAISE EXCEPTION 'Gap job unavailable'; END IF;
 IF c.transcript_diarized IS DISTINCT FROM p_expected_transcript THEN RAISE EXCEPTION 'Transcript changed during repair'; END IF;
 IF NOT EXISTS(SELECT 1 FROM manual_transcript_gap_requests WHERE job_id=j.id AND range_index=p_range_index AND completed_at IS NULL) THEN RAISE EXCEPTION 'Gap request already consumed'; END IF;
 SELECT jsonb_agg(x ORDER BY (x->>'start_ms')::numeric,(x->>'end_ms')::numeric,x->>'id'),
 string_agg((x->>'speaker')||': '||(x->>'text'),E'\n' ORDER BY (x->>'start_ms')::numeric)
 INTO merged,body FROM jsonb_array_elements(coalesce(c.transcript_diarized,'[]')||p_lines)x;
 -- Set the manual flag in the same update so refresh triggers cannot grant a
 -- second paid pass. Original scorecard versions remain untouched.
 UPDATE call_records SET transcript_diarized=merged,transcript_raw=body,
 metadata=coalesce(metadata,'{}')||jsonb_build_object('manual_gap_fill',j.mode='manual','last_manual_gap_job',j.id) WHERE id=c.id;
 -- Persist repairs in the canonical segment store too, so reconciliation cannot erase them.
 INSERT INTO telephony_transcript_segments(id,attempt_id,speaker,text,captured_at,start_ms,end_ms)
 SELECT (line->>'id')::uuid,r.attempt_id,line->>'speaker',line->>'text',
 r.provider_created_at+((line->>'start_ms')::numeric/1000)*interval '1 second',
 (line->>'start_ms')::integer,(line->>'end_ms')::integer
 FROM recording_ingestion r CROSS JOIN jsonb_array_elements(p_lines)line
 WHERE r.id=j.recording_id AND r.attempt_id IS NOT NULL AND line->>'id' IS NOT NULL
 ON CONFLICT(id) DO NOTHING;
 -- A successful range replaces only the corresponding known capture gap.
 UPDATE call_records SET metadata=jsonb_set(metadata,'{transcription_gaps}',
 coalesce((SELECT jsonb_agg(g) FROM jsonb_array_elements(coalesce(metadata->'transcription_gaps','[]'))g
 WHERE NOT ((g->>'start_ms')::numeric >= (j.ranges->p_range_index->>'start_ms')::numeric
 AND (g->>'end_ms')::numeric <= (j.ranges->p_range_index->>'end_ms')::numeric)),'[]')) WHERE id=c.id;
 UPDATE manual_transcript_gap_requests SET completed_at=clock_timestamp(),provider_request_id=p_provider_id
 WHERE job_id=j.id AND range_index=p_range_index;
 RETURN merged;
END $function$

CREATE OR REPLACE FUNCTION public.persist_scoring_result(p_job_id uuid, p_attempt_token uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE saved jsonb; card_id uuid; v jsonb; item_ids uuid[]; prior uuid; c call_records; endpoint numeric;
BEGIN
 SELECT cr.* INTO STRICT c FROM call_records cr JOIN scoring_jobs j ON j.call_id=cr.id WHERE j.id=p_job_id FOR UPDATE OF cr;
 SELECT max(coalesce((x->>'end_ms')::numeric,(x->>'start_ms')::numeric,0)) INTO endpoint
 FROM jsonb_array_elements(coalesce(c.transcript_diarized,'[]')) x;
 IF compliance_call_excluded(c) THEN RAISE EXCEPTION 'Call is not applicable for scoring'; END IF;
 IF coalesce(c.call_duration_seconds,0)<=0 OR coalesce(endpoint,0)<c.call_duration_seconds*950 THEN
  RAISE EXCEPTION 'SCORING INCOMPLETE: transcript coverage below 95 percent';
 END IF;
 IF nullif(p_result->>'rulesVersion','') IS NULL OR jsonb_array_length(coalesce(p_result->'items','[]'))=0 THEN
  RAISE EXCEPTION 'SCORING INCOMPLETE: version or line items missing';
 END IF;
 prior:=c.compliance_scorecard_id;
 saved:=persist_scoring_result_legacy_134(p_job_id,p_attempt_token,p_result);
 card_id:=(saved->'scorecard'->>'id')::uuid;
 IF card_id IS NULL OR coalesce((saved->>'reused')::boolean,false) THEN RETURN saved; END IF;
 FOR v IN SELECT * FROM jsonb_array_elements(p_result->'items') LOOP
  IF coalesce((v->>'auto_fail_triggered')::boolean,false) AND
   (v->>'decided_by' IS DISTINCT FROM 'Code' OR nullif(trim(v->>'evidence_text'),'') IS NULL OR v->>'evidence_timestamp_ms' IS NULL) THEN
   RAISE EXCEPTION 'Auto-fail requires deterministic timestamped evidence';
  END IF;
  UPDATE scorecard_items SET rule_id=v->>'rule_id',decided_by=v->>'decided_by',
   evidence_end_ms=(v->>'evidence_end_ms')::integer,segment_id=v->>'segment_id',missing_reason=v->>'missing_reason'
  WHERE scorecard_id=card_id AND template_item_id=(v->>'template_item_id')::uuid;
 END LOOP;
 SELECT coalesce(array_agg(id),'{}') INTO item_ids FROM scorecard_items WHERE scorecard_id=card_id AND auto_fail_triggered;
 IF (SELECT auto_fail_triggered FROM compliance_scorecards WHERE id=card_id) IS DISTINCT FROM (cardinality(item_ids)>0) THEN RAISE EXCEPTION 'Auto-fail header must match evidence line items'; END IF;
 UPDATE compliance_scorecards SET rules_version=p_result->>'rulesVersion',scoring_state='complete',
  supersedes_id=prior,auto_fail_item_ids=item_ids,llm_pass_id=(p_result->>'passId')::uuid,request_attempts=(SELECT count(*) FROM compliance_llm_requests WHERE pass_id=(p_result->>'passId')::uuid),scoring_duration_ms=(p_result->>'scoringDurationMs')::integer,
  tokens_used=(SELECT sum(coalesce(input_tokens,0)+coalesce(output_tokens,0)) FROM compliance_llm_requests WHERE pass_id=(p_result->>'passId')::uuid),
  estimated_cost_usd=(SELECT sum(estimated_cost_usd) FROM compliance_llm_requests WHERE pass_id=(p_result->>'passId')::uuid) WHERE id=card_id;
 IF p_result->>'passId' IS NOT NULL THEN
  UPDATE compliance_llm_passes SET status='complete' WHERE id=(p_result->>'passId')::uuid AND call_id=c.id AND tenant_id=c.tenant_id;
 END IF;
 IF jsonb_typeof(p_result->'agentAssessment')='object' AND jsonb_typeof(p_result->'beneficiaryRisk')='object' THEN
  UPDATE call_records SET agent_assessment=p_result->'agentAssessment',beneficiary_risk=p_result->'beneficiaryRisk' WHERE id=c.id AND tenant_id=c.tenant_id;
 END IF;
 RETURN scoring_job_result(p_job_id);
END $function$

CREATE OR REPLACE FUNCTION public.persist_scoring_result_legacy_134(p_job_id uuid, p_attempt_token uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE j public.scoring_jobs; c public.call_records; card public.compliance_scorecards;
  d public.intent_detections; item public.scorecard_items; action public.corrective_actions; redaction public.phi_redactions;
  value jsonb; expected integer; short_call boolean; duration numeric;
BEGIN
  -- Same lock order as begin: serialize revisions of a call, then fence workers.
  SELECT cr.* INTO STRICT c FROM call_records cr JOIN scoring_jobs sj ON sj.call_id=cr.id WHERE sj.id=p_job_id FOR UPDATE OF cr;
  SELECT * INTO STRICT j FROM scoring_jobs WHERE id=p_job_id FOR UPDATE;
  IF j.status='complete' THEN RETURN scoring_job_result(j.id)||jsonb_build_object('reused',true); END IF;
  IF j.status!='pending' OR j.attempt_token!=p_attempt_token THEN RAISE EXCEPTION 'Scoring worker lease superseded'; END IF;
  IF NOT public.is_compliance_sale(c.call_outcome) OR c.compliance_requested_at IS NULL THEN
    UPDATE scoring_jobs SET status='failed',error='disposition_changed',updated_at=now() WHERE id=j.id;
    RETURN jsonb_build_object('skipped',true,'reason','disposition_changed');
  END IF;
  IF md5(scoring_transcript_snapshot(c)::text)!=j.transcript_revision THEN RAISE EXCEPTION 'Transcript changed during scoring'; END IF;
  IF jsonb_typeof(p_result->'detections') IS DISTINCT FROM 'array' OR jsonb_typeof(p_result->'items') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_result->'actions') IS DISTINCT FROM 'array' OR jsonb_typeof(p_result->'redactions') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Incomplete scoring result';
  END IF;
  short_call:=coalesce((p_result->>'isShortCall')::boolean,false);
  duration:=coalesce(nullif(c.call_duration_seconds,0),(SELECT max((v->>'end_ms')::numeric)/1000 FROM jsonb_array_elements(coalesce(c.transcript_diarized,'[]')) v),0);
  SELECT count(*) INTO expected FROM scoring_template_items WHERE template_id=j.template_id;
  IF short_call THEN
    IF duration<=0 OR duration>=120 OR jsonb_array_length(p_result->'items')!=0 OR jsonb_array_length(p_result->'detections')!=0
      OR jsonb_array_length(p_result->'actions')!=0 THEN RAISE EXCEPTION 'Invalid short-call result'; END IF;
  ELSE
    IF expected=0 OR jsonb_array_length(p_result->'items')!=expected OR jsonb_array_length(p_result->'detections')=0
      OR (SELECT count(DISTINCT v->>'template_item_id') FROM jsonb_array_elements(p_result->'items') v)!=expected THEN
      RAISE EXCEPTION 'Incomplete scoring evidence or template coverage';
    END IF;
  END IF;
  card:=jsonb_populate_record(NULL::compliance_scorecards,p_result->'scorecard');
  INSERT INTO compliance_scorecards(tenant_id,call_id,template_id,transcript_revision,thread_id,is_thread_composite,
    overall_score,overall_grade,total_points_earned,total_points_possible,pass_fail,auto_fail_triggered,auto_fail_reasons,
    category_scores,risk_level,risk_flags,sequence_violations,sentiment_summary,coaching_notes,corrective_actions_needed)
  VALUES(j.tenant_id,j.call_id,j.template_id,j.transcript_revision,c.thread_id,false,card.overall_score,card.overall_grade,
    card.total_points_earned,card.total_points_possible,card.pass_fail,card.auto_fail_triggered,card.auto_fail_reasons,
    card.category_scores,card.risk_level,card.risk_flags,card.sequence_violations,card.sentiment_summary,card.coaching_notes,card.corrective_actions_needed)
  RETURNING * INTO card;
  IF card.id IS NULL THEN RAISE EXCEPTION 'Scorecard insert produced no row'; END IF;
  FOR value IN SELECT * FROM jsonb_array_elements(p_result->'detections') LOOP
    d:=jsonb_populate_record(NULL::intent_detections,value);
    INSERT INTO intent_detections(id,call_id,scoring_job_id,intent_code,detected,confidence,detection_method,speaker,transcript_segment,
      segment_start_ms,segment_end_ms,sequence_position_actual,sequence_violation,sequence_violation_detail,anti_pattern_match,anti_pattern_detail,llm_reasoning)
    VALUES(d.id,j.call_id,j.id,d.intent_code,d.detected,d.confidence,d.detection_method,d.speaker,d.transcript_segment,
      d.segment_start_ms,d.segment_end_ms,d.sequence_position_actual,d.sequence_violation,d.sequence_violation_detail,d.anti_pattern_match,d.anti_pattern_detail,d.llm_reasoning);
    IF NOT FOUND THEN RAISE EXCEPTION 'Detection insert produced no row'; END IF;
  END LOOP;
  FOR value IN SELECT * FROM jsonb_array_elements(p_result->'items') LOOP
    item:=jsonb_populate_record(NULL::scorecard_items,value);
    PERFORM 1 FROM scoring_template_items WHERE id=item.template_item_id AND template_id=j.template_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Item belongs to another template'; END IF;
    IF item.detection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM intent_detections WHERE id=item.detection_id AND scoring_job_id=j.id) THEN
      RAISE EXCEPTION 'Item evidence belongs to another scoring job';
    END IF;
    INSERT INTO scorecard_items(scorecard_id,template_item_id,intent_id,detection_id,question_text,category,result,points_earned,
      points_possible,confidence,is_auto_fail,auto_fail_triggered,notes,evidence_text,evidence_timestamp_ms,display_order)
    VALUES(card.id,item.template_item_id,item.intent_id,item.detection_id,item.question_text,item.category,item.result,item.points_earned,
      item.points_possible,item.confidence,item.is_auto_fail,item.auto_fail_triggered,item.notes,item.evidence_text,item.evidence_timestamp_ms,item.display_order);
    IF NOT FOUND THEN RAISE EXCEPTION 'Scorecard item insert produced no row'; END IF;
  END LOOP;
  IF card.corrective_actions_needed AND jsonb_array_length(p_result->'actions')=0 THEN RAISE EXCEPTION 'Corrective action missing'; END IF;
  FOR value IN SELECT * FROM jsonb_array_elements(p_result->'actions') LOOP
    action:=jsonb_populate_record(NULL::corrective_actions,value);
    INSERT INTO corrective_actions(scorecard_id,call_id,agent_id,agent_name,severity,category,bucket,title,description,intent_codes,evidence,status)
    VALUES(card.id,j.call_id,c.agent_id,c.agent_name,action.severity,action.category,action.bucket,action.title,action.description,action.intent_codes,action.evidence,'open');
    IF NOT FOUND THEN RAISE EXCEPTION 'Corrective action insert produced no row'; END IF;
  END LOOP;
  FOR value IN SELECT * FROM jsonb_array_elements(p_result->'redactions') LOOP
    redaction:=jsonb_populate_record(NULL::phi_redactions,value);
    INSERT INTO phi_redactions(call_id,redaction_type,original_position_start,original_position_end,replacement_token)
      VALUES(j.call_id,redaction.redaction_type,redaction.original_position_start,redaction.original_position_end,redaction.replacement_token);
    IF NOT FOUND THEN RAISE EXCEPTION 'Redaction insert produced no row'; END IF;
  END LOOP;
  UPDATE scoring_jobs SET status='complete',scorecard_id=card.id,is_short_call=short_call,error=NULL,updated_at=now() WHERE id=j.id;
  UPDATE call_records SET compliance_run_at=clock_timestamp(),compliance_transcript_hash=public.compliance_content_hash(c),
    call_direction=coalesce(nullif(p_result->>'detectedDirection',''),call_direction),compliance_scorecard_id=card.id,metadata=(coalesce(metadata,'{}'::jsonb)-'scoring_error'-'scoring_failed_at')||
    jsonb_build_object('scoring_status','complete','scoring_completed_at',now(),'scoring_job_id',j.id,'scoring_revision',j.transcript_revision)||CASE WHEN nullif(p_result->>'detectedDirection','') IS NOT NULL
      THEN jsonb_build_object('direction_detected_from','transcript_analysis') ELSE '{}'::jsonb END,updated_at=now() WHERE id=j.call_id;
  RETURN scoring_job_result(j.id)||jsonb_build_object('reused',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.persist_telephony_transcript(p_attempt_id uuid, p_segment_id uuid, p_speaker text, p_text text, p_captured_at timestamp with time zone, p_start_ms integer, p_end_ms integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE rid uuid; c call_records; tid uuid; aid uuid; v_agency text; body text; entries jsonb;
BEGIN
 rid:=ensure_inbound_transcript_record(p_attempt_id);
 INSERT INTO telephony_transcript_segments VALUES(p_segment_id,p_attempt_id,p_speaker,p_text,p_captured_at,
  greatest(0,p_start_ms),greatest(0,p_end_ms)) ON CONFLICT(id) DO NOTHING;
 IF NOT FOUND THEN RETURN rid; END IF;
 SELECT * INTO STRICT c FROM call_records WHERE id=rid FOR UPDATE;
 SELECT string_agg(upper(speaker)||': '||text,E'\n' ORDER BY start_ms,end_ms,s.id),
  jsonb_agg(jsonb_build_object('id',s.id,'speaker',speaker,'text',text,'start_ms',start_ms,'end_ms',end_ms) ORDER BY start_ms,end_ms,s.id)
 INTO body,entries FROM telephony_transcript_segments s JOIN telephony_call_attempts a ON a.id=s.attempt_id
 WHERE a.call_record_id=rid;
 tid:=c.transcript_id;
 IF tid IS NULL THEN
  SELECT coalesce(agency_display_name,name) INTO v_agency FROM tenants WHERE id=c.tenant_id;
  SELECT id INTO aid FROM agents WHERE name=c.agent_name AND agents.agency=v_agency LIMIT 1;
  IF aid IS NULL THEN INSERT INTO agents(name,agency,is_active) VALUES(c.agent_name,v_agency,true) RETURNING id INTO aid; END IF;
  INSERT INTO call_transcripts(tenant_id,agent_id,owner_agent_id,call_record_id,session_id,call_date,
   direction,product_line,transcript_text,source_system,source_id,phi_scrubbed,last_checkpoint_at)
  VALUES(c.tenant_id,aid,c.agent_id,rid,c.session_id,c.call_start,'inbound',c.product_type,body,
   'deepgram_server',rid::text,true,now()) RETURNING id INTO tid;
 ELSE
  UPDATE call_transcripts SET transcript_text=body,last_checkpoint_at=now(),updated_at=now() WHERE id=tid AND tenant_id=c.tenant_id;
 END IF;
 UPDATE call_records SET transcript_id=tid,transcript_raw=body,transcript_diarized=entries,
  metadata=coalesce(metadata,'{}')||jsonb_build_object('transcript_source','deepgram_server'),updated_at=now() WHERE id=rid;
 RETURN rid;
END $function$

CREATE OR REPLACE FUNCTION public.persist_tpmo_timing_repair(p_call_id uuid, p_original_scorecard_id uuid, p_template_id uuid, p_transcript jsonb, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records; original compliance_scorecards; j scoring_jobs;
 timing jsonb; saved jsonb; revision text;
BEGIN
 SELECT * INTO STRICT c FROM call_records WHERE id=p_call_id FOR UPDATE;
 SELECT * INTO STRICT original FROM compliance_scorecards
  WHERE id=p_original_scorecard_id AND call_id=c.id AND tenant_id=c.tenant_id FOR UPDATE;
 revision:=md5(p_transcript::text);
 IF c.compliance_scorecard_id IS DISTINCT FROM original.id THEN
  SELECT * INTO j FROM scoring_jobs WHERE call_id=c.id AND template_id=p_template_id
   AND repair_original_scorecard_id=original.id AND transcript_revision=revision
   AND status='complete' AND scorecard_id=c.compliance_scorecard_id;
  IF FOUND THEN RETURN scoring_job_result(j.id)||jsonb_build_object('reused',true); END IF;
  RAISE EXCEPTION 'Current scorecard changed after preview';
 END IF;
 IF NOT coalesce(c.call_outcome IN ('enrolled','enrolled_pending_verification'),false) OR c.call_end IS NULL THEN
  RAISE EXCEPTION 'Repair requires a completed scored sale';
 END IF;
 IF scoring_transcript_snapshot(c) IS DISTINCT FROM p_transcript OR original.transcript_revision IS DISTINCT FROM revision THEN
  RAISE EXCEPTION 'Transcript changed after original score';
 END IF;
 -- Lock the source evidence so human review cannot race this correction.
 PERFORM d.id FROM intent_detections d JOIN scorecard_items i ON i.detection_id=d.id
  WHERE i.scorecard_id=original.id FOR UPDATE OF d;
 IF original.reviewed OR EXISTS(SELECT 1 FROM intent_detections d JOIN scorecard_items i ON i.detection_id=d.id
  WHERE i.scorecard_id=original.id AND d.manually_overridden) THEN
  RAISE EXCEPTION 'Human-reviewed evidence must be retained';
 END IF;
 IF NOT original.auto_fail_triggered OR NOT EXISTS(SELECT 1 FROM scorecard_items i
  JOIN compliance_intents ci ON ci.id=i.intent_id WHERE i.scorecard_id=original.id
  AND ci.intent_code='CALL_OPEN_009_TPMO_TIMING_2027' AND i.auto_fail_triggered) THEN
  RAISE EXCEPTION 'Original scorecard has no TPMO timing auto-fail';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM scoring_templates source JOIN scoring_templates target ON target.id=p_template_id
  WHERE source.id=original.template_id AND source.policy_version='ma-cy2027-2026-10-01'
  AND target.policy_version=source.policy_version AND NOT target.is_active AND target.id<>source.id) THEN
  RAISE EXCEPTION 'Repair requires a separate inactive CY2027 template';
 END IF;
 SELECT item INTO timing FROM jsonb_array_elements(p_result->'items') item
  JOIN scoring_template_items ti ON ti.id=(item->>'template_item_id')::uuid
  JOIN compliance_intents ci ON ci.id=ti.intent_id
  WHERE ti.template_id=p_template_id AND ci.intent_code='CALL_OPEN_009_TPMO_TIMING_2027';
 IF timing IS NULL OR timing->>'result' IS DISTINCT FROM 'na' OR (timing->>'points_possible')::integer IS DISTINCT FROM 0
  OR coalesce((timing->>'auto_fail_triggered')::boolean,true)
  OR coalesce(timing->>'notes','') NOT ILIKE 'Manual review required:%'
  OR nullif(timing->>'evidence_text','') IS NULL OR timing->>'evidence_timestamp_ms' IS NULL
  OR NOT coalesce((p_result->'scorecard'->>'corrective_actions_needed')::boolean,false)
  OR jsonb_array_length(p_result->'actions')=0 THEN
  RAISE EXCEPTION 'Uncertain TPMO evidence must remain an explicit review finding';
 END IF;
 IF p_result ? 'detectedDirection' THEN RAISE EXCEPTION 'TPMO repair cannot change call direction'; END IF;
 IF EXISTS(SELECT 1 FROM scoring_jobs WHERE call_id=c.id AND status='pending' AND lease_until>clock_timestamp()) THEN
  RAISE EXCEPTION 'Another scoring job is active';
 END IF;
 INSERT INTO scoring_jobs(tenant_id,call_id,template_id,transcript_revision,status,lease_until,
  attempt_count,estimated_input_tokens,repair_original_scorecard_id,repair_reason)
 VALUES(c.tenant_id,c.id,p_template_id,revision,'pending',clock_timestamp()+interval '15 minutes',1,0,
  original.id,'tpmo_timing_evidence_2026_10_27') RETURNING * INTO j;
 -- Existing persistence performs all coverage, identity and evidence-link checks.
 -- Both transactions share the held call lock; an error rolls this entire RPC back.
 saved:=persist_scoring_result(j.id,j.attempt_token,p_result);
 IF saved->'scorecard'->>'id' IS NULL THEN RAISE EXCEPTION 'Repair did not produce a scorecard'; END IF;
 UPDATE corrective_actions SET status='superseded',updated_at=clock_timestamp(),
  resolution_notes='Replaced by TPMO evidence repair '||(saved->'scorecard'->>'id')||'; original evidence retained.'
 WHERE scorecard_id=original.id AND status='open' AND assigned_to IS NULL;
 RETURN saved;
END;
$function$

CREATE OR REPLACE FUNCTION public.ping_claim_arrival(p_call_sid text, p_phone text, p_call_id text, p_to_number text, p_exclude text[], p_preferred_agent_id text, p_arrived_at timestamp with time zone)
 RETURNS TABLE(agent_id text, agent_name text, caller_state text, claim_path text, vendor_call_id text, decision_id uuid, campaign_id uuid, tenant_id uuid, source_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE d ping_decisions; camp ping_campaigns; ctl vendor_controls; reserved ping_reservations;
  key text; selected_id text; selected_tier text; preferred_tier text; path text; exchange_on boolean;
  claimed_id text; claimed_name text; excluded text[]:=coalesce(p_exclude,'{}'); pause_source uuid; bill_rate numeric;
BEGIN
 IF NOT public.deployment_feature_enabled('PING_PLATFORM_ENABLED') THEN RETURN; END IF;
 IF nullif(p_call_sid,'') IS NULL OR nullif(p_to_number,'') IS NULL OR p_arrived_at IS NULL
 OR p_arrived_at>clock_timestamp()+interval '5 seconds'
 OR (nullif(p_phone,'') IS NULL AND nullif(p_call_id,'') IS NULL) THEN RETURN; END IF;
 exchange_on:=public.deployment_feature_enabled('PING_EXCHANGE_ENABLED');
 PERFORM pg_advisory_xact_lock(hashtextextended('ping-arrival:'||p_call_sid,0));

 -- A retried webhook for an already claimed call returns that claim.
 RETURN QUERY SELECT a.agent_id,a.agent_name,x.caller_state,'existing'::text,x.vendor_call_id,x.id,x.campaign_id,x.tenant_id,x.source_id
  FROM ping_decisions x JOIN agent_availability a ON a.active_call_sid=p_call_sid
  WHERE x.matched_call_sid=p_call_sid AND (x.engine='generic' OR (x.engine='exchange' AND exchange_on)) LIMIT 1;
 IF FOUND THEN RETURN; END IF;

 SELECT x.* INTO d FROM ping_decisions x
  JOIN ping_campaigns c ON c.id=x.campaign_id AND c.tenant_id=x.tenant_id
  JOIN lead_sources s ON s.id=x.source_id
  WHERE x.available AND c.engine_mode='generic' AND s.active
    AND ((x.engine='generic' AND c.source_id=x.source_id AND s.tenant_id=x.tenant_id AND s.twilio_number=p_to_number)
      OR (x.engine='exchange' AND exchange_on AND c.transfer_number=p_to_number))
    AND x.received_at>=p_arrived_at-interval '5 minutes' AND x.received_at<=p_arrived_at
    AND (x.matched_call_sid IS NULL OR x.matched_call_sid=p_call_sid)
    AND ((nullif(p_call_id,'') IS NOT NULL AND x.vendor_call_id=p_call_id)
      OR (nullif(p_phone,'') IS NOT NULL AND x.caller_phone=p_phone
        AND (nullif(p_call_id,'') IS NULL OR x.vendor_call_id IS NULL)))
  ORDER BY CASE WHEN nullif(p_call_id,'') IS NOT NULL AND x.vendor_call_id=p_call_id THEN 0 ELSE 1 END,x.received_at DESC,x.id
  FOR UPDATE OF x SKIP LOCKED LIMIT 1;
 IF d.id IS NULL OR d.caller_state IS NULL THEN RETURN; END IF;

 SELECT * INTO camp FROM ping_campaigns WHERE id=d.campaign_id;
 SELECT * INTO ctl FROM vendor_controls WHERE tenant_id=d.tenant_id;
 pause_source:=CASE WHEN d.engine='exchange' THEN camp.source_id ELSE d.source_id END;
 -- The pause and campaign gates of ping_decide still hold at arrival.
 IF ctl.tenant_id IS NULL OR ctl.vendor_pause OR NOT camp.active OR camp.engine_mode<>'generic'
 OR NOT d.caller_state=ANY(camp.allowed_states)
 OR EXISTS(SELECT 1 FROM ping_source_controls p WHERE p.tenant_id=d.tenant_id AND p.source_id=pause_source
   AND p.paused AND (p.campaign_id IS NULL OR p.campaign_id=d.campaign_id)) THEN
  RETURN QUERY SELECT NULL::text,NULL::text,d.caller_state,'rejected'::text,d.vendor_call_id,d.id,d.campaign_id,d.tenant_id,d.source_id;
  RETURN;
 END IF;

 key:=CASE WHEN d.vendor_call_id IS NOT NULL THEN 'id:'||d.vendor_call_id ELSE 'phone:'||left(d.caller_phone,32) END;
 SELECT * INTO reserved FROM ping_reservations r WHERE r.campaign_id=d.campaign_id AND r.reservation_key=key
  AND r.expires_at>=p_arrived_at AND r.consumed_call_sid IS NULL FOR UPDATE;
 -- A reserved agent is used only while still routable and eligible, and a
 -- partial reservation yields to a routable full agent, as in claim_paragon_call_at.
 IF reserved.id IS NOT NULL AND reserved.agent_id<>ALL(excluded)
   AND public.ping_agent_tier(reserved.agent_id,d.caller_state,d.campaign_id) IN ('full','partial')
   AND (public.ping_agent_tier(reserved.agent_id,d.caller_state,d.campaign_id)='full'
     OR NOT EXISTS(SELECT 1 FROM agent_availability f
       WHERE public.agent_inbound_routable(f.agent_id,f.status,f.available,f.active_call_sid)
         AND public.ping_agent_tier(f.agent_id,d.caller_state,d.campaign_id)='full'
         AND f.agent_id<>ALL(excluded)))
   AND EXISTS(SELECT 1 FROM agent_availability a WHERE a.agent_id=reserved.agent_id
     AND public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)) THEN
  selected_id:=reserved.agent_id; path:='reserved';
 ELSE
  preferred_tier:=public.ping_agent_tier(p_preferred_agent_id,d.caller_state,d.campaign_id);
  SELECT a.agent_id,public.ping_agent_tier(a.agent_id,d.caller_state,d.campaign_id)
   INTO selected_id,selected_tier FROM agent_availability a
   WHERE public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)
     AND a.agent_id<>ALL(excluded)
     AND public.ping_agent_tier(a.agent_id,d.caller_state,d.campaign_id) IN ('full','partial')
     AND NOT EXISTS(SELECT 1 FROM ping_reservations r WHERE r.agent_id=a.agent_id
       AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL AND r.id IS DISTINCT FROM reserved.id)
     AND NOT EXISTS(SELECT 1 FROM paragon_agent_reservations r WHERE r.agent_id=a.agent_id
       AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL)
   ORDER BY CASE public.ping_agent_tier(a.agent_id,d.caller_state,d.campaign_id) WHEN 'full' THEN 0 ELSE 1 END,
     CASE WHEN a.agent_id=p_preferred_agent_id THEN 0 ELSE 1 END,
     a.last_assigned_at ASC NULLS FIRST,a.agent_id
   FOR UPDATE OF a SKIP LOCKED LIMIT 1;
  path:=CASE WHEN selected_id=p_preferred_agent_id AND preferred_tier=selected_tier THEN 'preferred' ELSE 'round_robin' END;
 END IF;

 IF selected_id IS NOT NULL THEN
  UPDATE agent_availability a SET active_call_sid=p_call_sid,resume_status=a.status,status='busy',available=false,
    last_assigned_at=clock_timestamp(),toggled_at=clock_timestamp()
   WHERE a.agent_id=selected_id AND a.active_call_sid IS NULL
   RETURNING a.agent_id,a.agent_name INTO claimed_id,claimed_name;
 END IF;
 IF claimed_id IS NULL THEN
  RETURN QUERY SELECT NULL::text,NULL::text,d.caller_state,'rejected'::text,d.vendor_call_id,d.id,d.campaign_id,d.tenant_id,d.source_id;
  RETURN;
 END IF;
 UPDATE ping_decisions SET matched_call_sid=p_call_sid WHERE id=d.id;
 UPDATE ping_reservations SET consumed_call_sid=p_call_sid WHERE id=reserved.id;
 -- Price snapshot at claim time; later campaign or route edits never reprice this call.
 bill_rate:=CASE camp.pricing_model WHEN 'free' THEN 0 ELSE coalesce(camp.rate,0) END;
 IF d.engine='exchange' AND camp.pricing_model<>'free' THEN
  SELECT coalesce(er.price_override,bill_rate) INTO bill_rate FROM exchange_routes er
   WHERE er.source_id=d.source_id AND er.campaign_id=d.campaign_id;
  bill_rate:=coalesce(bill_rate,camp.rate,0);
 END IF;
 IF p_call_sid ~ '^CA[0-9a-fA-F]{32}$' THEN
  INSERT INTO ping_call_billing(parent_call_sid,tenant_id,source_id,campaign_id,decision_id,pricing_model,rate,billable_threshold_seconds)
  VALUES(p_call_sid,d.tenant_id,d.source_id,d.campaign_id,d.id,camp.pricing_model,bill_rate,camp.billable_seconds)
  ON CONFLICT DO NOTHING;
 END IF;
 IF d.engine='exchange' THEN
  PERFORM public.platform_record_usage(d.tenant_id,'routed_call',d.source_id,d.campaign_id,left(p_call_sid,128));
 END IF;
 RETURN QUERY SELECT claimed_id,claimed_name,d.caller_state,path,d.vendor_call_id,d.id,d.campaign_id,d.tenant_id,d.source_id;
END; $function$

CREATE OR REPLACE FUNCTION public.ping_decide(p_key_hash text, p_campaign text, p_payload jsonb, p_engine text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE src lead_sources; camp_id uuid; campaign_ref text:=nullif(trim(p_campaign),''); result jsonb; phone text;
BEGIN
  IF NOT public.deployment_feature_enabled('PING_PLATFORM_ENABLED') THEN RETURN jsonb_build_object('status','disabled'); END IF;
  IF p_engine IS NULL OR p_engine NOT IN ('generic','shadow') THEN RAISE EXCEPTION 'Invalid ping engine'; END IF;
  SELECT s.* INTO src FROM lead_sources s WHERE s.active AND s.type IN ('publisher','aggregator')
    AND (s.ping_key_hash=p_key_hash OR EXISTS(SELECT 1 FROM availability_consumers c
      WHERE c.name=s.name AND c.active AND c.key_hash=p_key_hash))
    ORDER BY (s.ping_key_hash=p_key_hash) DESC NULLS LAST LIMIT 1;
  IF src.id IS NULL THEN RETURN jsonb_build_object('authorized',false); END IF;
  -- Campaign: explicit id or name, else the source's single active campaign.
  IF campaign_ref IS NOT NULL THEN
    SELECT id INTO camp_id FROM ping_campaigns WHERE source_id=src.id AND tenant_id=src.tenant_id
      AND (id::text=campaign_ref OR name=campaign_ref) ORDER BY (id::text=campaign_ref) DESC LIMIT 1;
  ELSIF (SELECT count(*) FROM ping_campaigns WHERE source_id=src.id AND tenant_id=src.tenant_id AND active)=1 THEN
    SELECT id INTO camp_id FROM ping_campaigns WHERE source_id=src.id AND tenant_id=src.tenant_id AND active;
  END IF;
  result:=public.ping_decide_campaign(camp_id,src.id,p_payload,p_engine);
  IF p_engine='generic' AND jsonb_typeof(p_payload)='object' THEN
    phone:=nullif(trim(p_payload->>'phone'),'');
    IF phone ~ '^\+[1-9][0-9]{7,14}$' THEN
      BEGIN PERFORM public.shopper_history_record(phone,src.tenant_id,src.id);
      EXCEPTION WHEN OTHERS THEN RAISE WARNING 'shopper_history_record_failed';
      END;
    END IF;
  END IF;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.ping_decide_campaign(p_campaign_id uuid, p_source_id uuid, p_payload jsonb, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE started timestamptz:=clock_timestamp(); src lead_sources; camp ping_campaigns; ctl vendor_controls;
  payload jsonb:=coalesce(p_payload,'{}'::jsonb); shadow boolean:=p_mode IN ('shadow','exchange_eval');
  exchange boolean:=p_mode IN ('exchange_eval','exchange');
  match_mode text:=CASE WHEN p_mode IN ('exchange_eval','exchange') THEN 'generic' ELSE p_mode END;
  owner_tenant uuid; pause_source uuid;
  phone text; state_code text:=''; call_id text; zip text; sub_id text; consent text; t65 boolean;
  routing boolean; valid boolean:=true; key text;
  existing ping_reservations; selected record; eligible_count integer:=0; committed ping_decisions;
  decision text; accepted boolean:=false; trace jsonb:='[]'::jsonb; gate_at timestamptz;
  price numeric; decision_id uuid; phone_hash text;
  retention_hit boolean:=false; client_contact uuid; owner_agent text;
BEGIN
  IF NOT public.deployment_feature_enabled('PING_PLATFORM_ENABLED') THEN RETURN jsonb_build_object('status','disabled'); END IF;
  IF p_mode IS NULL OR p_mode NOT IN ('generic','shadow','exchange_eval','exchange') THEN RAISE EXCEPTION 'Invalid ping engine'; END IF;
  SELECT s.* INTO src FROM lead_sources s WHERE s.id=p_source_id AND s.active AND s.type IN ('publisher','aggregator');
  IF src.id IS NULL THEN RAISE EXCEPTION 'Unknown ping source'; END IF;
  SELECT NULL::text AS agent_id,NULL::text AS tier INTO selected;

  BEGIN
    IF jsonb_typeof(payload)='object' THEN
      phone:=nullif(trim(payload->>'phone'),'');
      state_code:=upper(trim(coalesce(payload->>'state','')));
      call_id:=left(nullif(trim(payload->>'call_id'),''),128);
      zip:=nullif(trim(payload->>'zip'),'');
      sub_id:=left(nullif(trim(payload->>'sub_id'),''),128);
      consent:=left(nullif(trim(payload->>'consent_cert_id'),''),128);
      valid:=(phone IS NULL OR phone ~ '^\+[1-9][0-9]{7,14}$')
        AND (zip IS NULL OR zip ~ '^[0-9]{5}$')
        AND (payload->'t65' IS NULL OR jsonb_typeof(payload->'t65') IN ('boolean','null'));
      IF jsonb_typeof(payload->'t65')='boolean' THEN t65:=(payload->>'t65')::boolean; END IF;
    ELSE valid:=false; END IF;
    routing:=coalesce(payload->'routing_enabled'='true'::jsonb,false);
    key:=CASE WHEN call_id IS NOT NULL THEN 'id:'||call_id
      WHEN phone IS NOT NULL THEN 'phone:'||left(phone,32) ELSE NULL END;

    -- Direct pings reach only the source's own campaigns in its own tenant.
    -- The exchange reaches a buyer campaign only through an active route.
    IF p_campaign_id IS NOT NULL THEN
      IF exchange THEN
        SELECT c.* INTO camp FROM ping_campaigns c WHERE c.id=p_campaign_id
          AND EXISTS(SELECT 1 FROM exchange_routes r WHERE r.source_id=src.id AND r.campaign_id=c.id AND r.active);
      ELSE
        SELECT c.* INTO camp FROM ping_campaigns c WHERE c.id=p_campaign_id AND c.source_id=src.id AND c.tenant_id=src.tenant_id;
      END IF;
    END IF;
    owner_tenant:=coalesce(camp.tenant_id,src.tenant_id);
    pause_source:=coalesce(camp.source_id,src.id);
    routing:=routing AND (camp.id IS NULL OR camp.engine_mode=match_mode);
    SELECT * INTO ctl FROM vendor_controls WHERE tenant_id=owner_tenant;

    -- Serialize a source's decisions, as paragon_ping does.
    PERFORM pg_advisory_xact_lock(hashtextextended('ping-decide:'||src.id::text,0));
    gate_at:=clock_timestamp();
    IF NOT shadow THEN DELETE FROM ping_reservations WHERE expires_at<clock_timestamp()-interval '1 day'; END IF;

    IF NOT routing THEN decision:='routing_disabled';
    ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','routing_disabled','result','pass'));
      IF NOT valid THEN decision:='invalid_payload';
      ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','invalid_payload','result','pass'));
        -- Tenant-wide pause, or a source-level or campaign-level row (173), of
        -- the campaign's own tenant and source.
        IF ctl.tenant_id IS NULL OR ctl.vendor_pause OR EXISTS(SELECT 1 FROM ping_source_controls p
          WHERE p.tenant_id=owner_tenant AND p.source_id=pause_source AND p.paused
            AND (p.campaign_id IS NULL OR p.campaign_id=camp.id)) THEN decision:='source_paused';
        ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','source_paused','result','pass')); END IF;
      END IF;
    END IF;

    -- The 30 second accepted commitment: a re-ping for the same identity and
    -- state replays the committed decision without re-checking hours. An
    -- exchange evaluation never replays; it reports the current state.
    IF decision IS NULL AND camp.id IS NOT NULL AND p_mode<>'exchange_eval' THEN
      SELECT * INTO committed FROM ping_decisions d WHERE d.source_id=src.id AND d.campaign_id=camp.id
        AND d.engine=p_mode AND d.available AND d.matched_call_sid IS NULL
        AND d.received_at+interval '30 seconds'>=gate_at AND d.caller_state=state_code
        AND ((call_id IS NOT NULL AND d.vendor_call_id=call_id)
          OR (call_id IS NULL AND phone IS NOT NULL AND d.caller_phone=phone))
        AND NOT d.rule_trace @> '[{"rule":"commitment_replay"}]'::jsonb
        ORDER BY d.received_at DESC LIMIT 1;
      IF committed.id IS NOT NULL THEN
        decision:=committed.reason; accepted:=true;
        SELECT committed.agent_id AS agent_id,NULL::text AS tier INTO selected;
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','commitment_replay','result','hit','decision_id',committed.id));
      END IF;
    END IF;

    IF decision IS NULL THEN
      IF NOT ping_hours_open(coalesce(camp.staffed_hours_override,ctl.staffed_hours),gate_at) THEN decision:='outside_staffed_hours';
      ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','outside_staffed_hours','result','pass'));
        IF camp.id IS NULL OR NOT camp.active THEN decision:='campaign_inactive';
        ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','campaign_inactive','result','pass'));
          IF state_code='' OR NOT state_code=ANY(camp.allowed_states) THEN decision:='state_not_allowed';
          ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','state_not_allowed','result','pass'));
            IF key IS NULL THEN decision:='missing_call_identity';
            ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','missing_call_identity','result','pass')); END IF;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Rule 8, existing_client_retention: the campaign tenant's own contacts only.
    IF decision IS NULL THEN
      IF NOT camp.retention_enabled OR phone IS NULL THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','existing_client_retention','result','skipped'));
      ELSE
        SELECT x.contact_id,x.owner_agent_id INTO client_contact,owner_agent
          FROM public.ping_existing_client(owner_tenant,phone) x;
        IF client_contact IS NULL THEN
          trace:=trace||jsonb_build_array(jsonb_build_object('rule','existing_client_retention','result','pass'));
        ELSE
          retention_hit:=true;
          trace:=trace||jsonb_build_array(jsonb_build_object('rule','existing_client_retention','result','hit','mode',camp.retention_mode));
          IF camp.retention_mode='reject_and_alert' THEN decision:='existing_client_retention'; END IF;
        END IF;
      END IF;
    END IF;

    -- Rule 9, cooldown_same_source. Existing clients are exempt.
    IF decision IS NULL THEN
      IF retention_hit OR coalesce(camp.cooldown_same_source_days,0)=0 OR phone IS NULL THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','cooldown_same_source','result','skipped'));
      ELSIF public.ping_recent_publisher_call(owner_tenant,phone,src.id,
          gate_at-make_interval(days=>camp.cooldown_same_source_days),gate_at) THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','cooldown_same_source','result','hit'));
        decision:='cooldown_same_source';
      ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','cooldown_same_source','result','pass')); END IF;
    END IF;

    -- Rule 10, cooldown_any_source. Existing clients are exempt.
    IF decision IS NULL THEN
      IF retention_hit OR coalesce(camp.cooldown_any_source_days,0)=0 OR phone IS NULL THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','cooldown_any_source','result','skipped'));
      ELSIF public.ping_recent_publisher_call(owner_tenant,phone,NULL,
          gate_at-make_interval(days=>camp.cooldown_any_source_days),gate_at) THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','cooldown_any_source','result','hit'));
        decision:='cooldown_any_source';
      ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','cooldown_any_source','result','pass')); END IF;
    END IF;

    -- Rule 11, repeat_shopper: pooled count only, while the exchange flag and
    -- the operator opt-in are on. Existing clients are exempt.
    IF decision IS NULL THEN
      IF retention_hit OR coalesce(camp.repeat_shopper_threshold,0)=0 OR coalesce(camp.repeat_shopper_window_days,0)=0
      OR phone IS NULL OR NOT public.ping_pooled_shopper_on() THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','repeat_shopper','result','skipped'));
      ELSIF public.shopper_history_count(public.ping_phone_hash(left(phone,32)),camp.repeat_shopper_window_days)
          >=camp.repeat_shopper_threshold THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','repeat_shopper','result','hit'));
        decision:='repeat_shopper';
      ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','repeat_shopper','result','pass')); END IF;
    END IF;

    -- Rule 12, daily_budget_reached, in the campaign tenant's own day.
    IF decision IS NULL THEN
      IF coalesce(camp.daily_budget_calls,0)=0 THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','daily_budget_reached','result','skipped'));
      ELSIF public.ping_campaign_accepted_today(camp.id,coalesce(camp.staffed_hours_override,ctl.staffed_hours),gate_at)
          >=camp.daily_budget_calls THEN
        trace:=trace||jsonb_build_array(jsonb_build_object('rule','daily_budget_reached','result','hit'));
        decision:='daily_budget_reached';
      ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','daily_budget_reached','result','pass')); END IF;
    END IF;

    IF decision IS NULL THEN
      PERFORM pg_advisory_xact_lock(hashtextextended('ping-decide:'||camp.id::text||key,0));
      IF shadow THEN SELECT * INTO existing FROM ping_reservations WHERE campaign_id=camp.id AND reservation_key=key;
      ELSE SELECT * INTO existing FROM ping_reservations WHERE campaign_id=camp.id AND reservation_key=key FOR UPDATE; END IF;
      IF existing.id IS NOT NULL AND existing.expires_at>clock_timestamp()
        AND existing.consumed_call_sid IS NULL AND existing.caller_state=state_code
        AND EXISTS(SELECT 1 FROM agent_availability a WHERE a.agent_id=existing.agent_id
          AND public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)) THEN
        SELECT existing.agent_id AS agent_id,public.ping_agent_tier(existing.agent_id,state_code,camp.id) AS tier INTO selected;
        IF selected.tier NOT IN ('full','partial') THEN SELECT NULL::text AS agent_id,NULL::text AS tier INTO selected;
        ELSE trace:=trace||jsonb_build_array(jsonb_build_object('rule','reservation_reuse','result','hit')); END IF;
      END IF;
      IF selected.agent_id IS NULL THEN
        IF NOT shadow THEN DELETE FROM ping_reservations WHERE campaign_id=camp.id AND reservation_key=key; END IF;
        SELECT count(*) INTO eligible_count FROM agent_availability a
          WHERE public.ping_agent_tier(a.agent_id,state_code,camp.id) IN ('full','partial');
        -- Rule 8 route_owner: the owner first, while routable, eligible and not
        -- held by another reservation; otherwise the pool below.
        IF retention_hit AND owner_agent IS NOT NULL THEN
          IF shadow THEN
            SELECT a.agent_id,public.ping_agent_tier(a.agent_id,state_code,camp.id) AS tier
              INTO selected FROM agent_availability a
              WHERE a.agent_id=owner_agent
                AND public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)
                AND public.ping_agent_tier(a.agent_id,state_code,camp.id) IN ('full','partial')
                AND NOT EXISTS(SELECT 1 FROM ping_reservations r WHERE r.agent_id=a.agent_id
                  AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL AND r.reservation_key IS DISTINCT FROM key)
                AND NOT EXISTS(SELECT 1 FROM paragon_agent_reservations r WHERE r.agent_id=a.agent_id
                  AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL);
          ELSE
            SELECT a.agent_id,public.ping_agent_tier(a.agent_id,state_code,camp.id) AS tier
              INTO selected FROM agent_availability a
              WHERE a.agent_id=owner_agent
                AND public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)
                AND public.ping_agent_tier(a.agent_id,state_code,camp.id) IN ('full','partial')
                AND NOT EXISTS(SELECT 1 FROM ping_reservations r WHERE r.agent_id=a.agent_id
                  AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL)
                AND NOT EXISTS(SELECT 1 FROM paragon_agent_reservations r WHERE r.agent_id=a.agent_id
                  AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL)
              FOR UPDATE OF a SKIP LOCKED;
          END IF;
          trace:=trace||jsonb_build_array(jsonb_build_object('rule','retention_owner',
            'result',CASE WHEN selected.agent_id IS NOT NULL THEN 'hit' ELSE 'pass' END));
        END IF;
        -- Agents are shared across engines: a live legacy reservation also holds the agent.
        IF selected.agent_id IS NULL AND shadow THEN
          SELECT a.agent_id,public.ping_agent_tier(a.agent_id,state_code,camp.id) AS tier
            INTO selected FROM agent_availability a
            WHERE public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)
              AND public.ping_agent_tier(a.agent_id,state_code,camp.id) IN ('full','partial')
              AND NOT EXISTS(SELECT 1 FROM ping_reservations r WHERE r.agent_id=a.agent_id
                AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL AND r.reservation_key IS DISTINCT FROM key)
              AND NOT EXISTS(SELECT 1 FROM paragon_agent_reservations r WHERE r.agent_id=a.agent_id
                AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL)
            ORDER BY CASE public.ping_agent_tier(a.agent_id,state_code,camp.id) WHEN 'full' THEN 0 ELSE 1 END,
              a.last_assigned_at ASC NULLS FIRST,a.agent_id
            LIMIT 1;
        ELSIF selected.agent_id IS NULL THEN
          SELECT a.agent_id,public.ping_agent_tier(a.agent_id,state_code,camp.id) AS tier
            INTO selected FROM agent_availability a
            WHERE public.agent_inbound_routable(a.agent_id,a.status,a.available,a.active_call_sid)
              AND public.ping_agent_tier(a.agent_id,state_code,camp.id) IN ('full','partial')
              AND NOT EXISTS(SELECT 1 FROM ping_reservations r WHERE r.agent_id=a.agent_id
                AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL)
              AND NOT EXISTS(SELECT 1 FROM paragon_agent_reservations r WHERE r.agent_id=a.agent_id
                AND r.expires_at>clock_timestamp() AND r.consumed_call_sid IS NULL)
            ORDER BY CASE public.ping_agent_tier(a.agent_id,state_code,camp.id) WHEN 'full' THEN 0 ELSE 1 END,
              a.last_assigned_at ASC NULLS FIRST,a.agent_id
            FOR UPDATE OF a SKIP LOCKED LIMIT 1;
        END IF;
        IF NOT shadow AND selected.agent_id IS NOT NULL THEN
          INSERT INTO ping_reservations(tenant_id,campaign_id,reservation_key,caller_state,agent_id,expires_at)
            VALUES(owner_tenant,camp.id,key,state_code,selected.agent_id,
              clock_timestamp()+make_interval(secs=>camp.reservation_ttl_seconds));
        END IF;
      END IF;
      IF selected.agent_id IS NOT NULL THEN
        accepted:=true;
        decision:=CASE WHEN retention_hit THEN 'accepted_retention_owner'
          WHEN selected.tier='full' THEN 'accepted_full' ELSE 'accepted_partial' END;
      ELSE
        decision:=CASE WHEN eligible_count>0 THEN 'all_eligible_busy' ELSE 'no_eligible_agent' END;
      END IF;
    END IF;
    IF accepted THEN price:=CASE camp.pricing_model WHEN 'free' THEN 0 ELSE camp.rate END; END IF;
    trace:=trace||jsonb_build_array(jsonb_build_object('rule',decision,'result',CASE WHEN accepted THEN 'accept' ELSE 'reject' END));
  EXCEPTION WHEN OTHERS THEN
    -- Publisher pings fail closed. The subtransaction rolled back any reservation.
    decision:='error_rejected'; accepted:=false; price:=NULL; retention_hit:=false;
    SELECT NULL::text AS agent_id,NULL::text AS tier INTO selected;
    trace:=trace||jsonb_build_array(jsonb_build_object('rule','error_rejected','result','reject','sqlstate',SQLSTATE));
  END;

  -- An exchange evaluation never stores the caller's phone or ZIP; only the
  -- winning tenant's 'exchange' decision does.
  IF p_mode='exchange_eval' THEN
    phone_hash:=public.ping_phone_hash(left(phone,32));
    IF phone_hash IS NOT NULL THEN
      trace:=trace||jsonb_build_array(jsonb_build_object('rule','phone_hash','result','recorded','sha256',phone_hash));
    END IF;
  END IF;
  INSERT INTO ping_decisions(tenant_id,source_id,campaign_id,latency_ms,caller_phone,caller_state,caller_zip,
    vendor_call_id,publisher_sub_id,consent_cert_id,t65_flag,available,reason,agent_id,price,rule_trace,engine)
  VALUES(owner_tenant,src.id,camp.id,greatest(0,floor(extract(epoch FROM clock_timestamp()-started)*1000))::integer,
    CASE WHEN p_mode<>'exchange_eval' THEN left(phone,32) END,nullif(left(state_code,8),''),
    CASE WHEN p_mode<>'exchange_eval' AND zip ~ '^[0-9]{5}$' THEN zip END,
    call_id,sub_id,consent,t65,accepted,decision,selected.agent_id,price,trace,p_mode)
  RETURNING id INTO decision_id;

  -- Rule 8 alert in the campaign's own tenant. Never blocks the decision.
  IF retention_hit AND client_contact IS NOT NULL
  AND (p_mode IN ('generic','exchange') OR (p_mode='exchange_eval' AND decision='existing_client_retention'))
  AND public.deployment_feature_enabled('PING_RETENTION_ALERTS_ENABLED') THEN
    BEGIN
      INSERT INTO ping_retention_alerts(tenant_id,contact_id,owner_agent_id,source_id,campaign_id,decision_id)
      VALUES(owner_tenant,client_contact,owner_agent,src.id,camp.id,decision_id);
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'ping_retention_alert_failed';
    END;
  END IF;
  RETURN jsonb_build_object('authorized',true,'decision_id',decision_id,'available',accepted,'reason',decision,
    'agent_id',selected.agent_id,'price',price,
    'ttl_seconds',CASE WHEN accepted THEN camp.reservation_ttl_seconds END);
END;
$function$

CREATE OR REPLACE FUNCTION public.ping_flag_returns(p_sid text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE b ping_call_billing; wrong boolean; inserted integer;
BEGIN
 SELECT * INTO b FROM ping_call_billing WHERE parent_call_sid=p_sid;
 IF b.parent_call_sid IS NULL OR b.pricing_model='free' THEN RETURN 0; END IF;
 SELECT coalesce(i.wrong_state,false) INTO wrong FROM inbound_calls i
  WHERE i.id=b.inbound_call_id AND i.tenant_id=b.tenant_id AND i.twilio_call_sid=b.parent_call_sid;
 INSERT INTO ping_returns(tenant_id,billing_parent_call_sid,campaign_id,reason,auto_flagged)
 SELECT b.tenant_id,b.parent_call_sid,b.campaign_id,r.reason,true FROM (VALUES
   ('short_duration',b.finalized_at IS NOT NULL AND b.billable_seconds<b.billable_threshold_seconds),
   ('wrong_state',coalesce(wrong,false)),
   ('duplicate',coalesce(b.duplicate_flag,false))) r(reason,hit)
 WHERE r.hit
 ON CONFLICT (billing_parent_call_sid,reason) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 RETURN inserted;
END; $function$

CREATE OR REPLACE FUNCTION public.ping_hours_open(p_hours jsonb, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE zone text; local_at timestamp; day_config jsonb; opens time; closes time;
BEGIN
 zone:=p_hours->>'timezone';
 IF p_hours IS NULL OR p_at IS NULL OR zone IS NULL
 OR zone !~ '^[A-Z][A-Za-z_]+(/[A-Za-z0-9_+-]+){1,2}$' THEN RETURN false; END IF;
 -- An unknown zone raises here and the handler below closes.
 local_at:=p_at AT TIME ZONE zone;
 day_config:=p_hours->'days'->((ARRAY['sun','mon','tue','wed','thu','fri','sat'])[extract(dow FROM local_at)::integer+1]);
 IF day_config->>'enabled' IS DISTINCT FROM 'true' THEN RETURN false; END IF;
 IF coalesce(day_config->>'start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
 OR coalesce(day_config->>'end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RETURN false; END IF;
 opens:=(day_config->>'start')::time; closes:=(day_config->>'end')::time;
 RETURN opens<closes AND local_at::time>=opens AND local_at::time<closes;
EXCEPTION WHEN OTHERS THEN RETURN false;
END; $function$

CREATE OR REPLACE FUNCTION public.ping_phone_hash(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE pepper text;
BEGIN
 IF p_phone IS NULL THEN RETURN NULL; END IF;
 pepper:=public.ping_phone_pepper();
 IF pepper IS NULL THEN RAISE EXCEPTION 'Ping phone pepper is not provisioned'; END IF;
 RETURN encode(sha256(convert_to(pepper||p_phone,'UTF8')),'hex');
END $function$

CREATE OR REPLACE FUNCTION public.ping_tenant_zone(p_tenant uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE zone text;
BEGIN
 SELECT v.staffed_hours->>'timezone' INTO zone FROM vendor_controls v WHERE v.tenant_id=p_tenant;
 IF zone IS NULL OR zone !~ '^[A-Z][A-Za-z_]+(/[A-Za-z0-9_+-]+){1,2}$' THEN RETURN 'UTC'; END IF;
 -- An unknown zone raises here and the handler falls back to UTC.
 PERFORM clock_timestamp() AT TIME ZONE zone;
 RETURN zone;
EXCEPTION WHEN OTHERS THEN RETURN 'UTC';
END $function$

CREATE OR REPLACE FUNCTION public.platform_record_usage(p_tenant uuid, p_kind text, p_source uuid, p_campaign uuid, p_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE plan platform_price_plans; used numeric; unit numeric:=0; event_id uuid;
BEGIN
 -- Serialize one tenant's allowance count; other tenants are not blocked.
 PERFORM pg_advisory_xact_lock(hashtextextended('platform-usage:'||p_tenant::text,0));
 SELECT * INTO plan FROM platform_price_plans WHERE tenant_id=p_tenant AND effective_at<=clock_timestamp();
 IF plan.tenant_id IS NOT NULL THEN
  IF p_kind='ping' THEN
   SELECT coalesce(sum(quantity),0) INTO used FROM platform_usage_events
    WHERE tenant_id=p_tenant AND kind='ping'
      AND occurred_at>=date_trunc('month',clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
   unit:=CASE WHEN used+1<=plan.included_pings THEN 0 ELSE plan.overage_per_ping END;
  ELSIF p_kind='routed_call' THEN unit:=plan.per_routed_call;
  ELSIF p_kind='screener_minute' THEN unit:=plan.per_screener_minute;
  END IF;
 END IF;
 INSERT INTO platform_usage_events(tenant_id,kind,quantity,unit_price,source_id,campaign_id,ref_id)
 VALUES(p_tenant,p_kind,1,unit,p_source,p_campaign,p_ref)
 ON CONFLICT DO NOTHING RETURNING id INTO event_id;
 RETURN event_id;
END $function$

CREATE OR REPLACE FUNCTION public.practice_target(p_actor text, p_org text, p_id uuid, p_write boolean DEFAULT false)
 RETURNS practice_sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i jsonb; s public.practice_sessions;
BEGIN
 i:=public.practice_identity(p_actor,p_org); SELECT * INTO s FROM public.practice_sessions WHERE id=p_id AND tenant_id=(i->>'tenant_id')::uuid;
 IF s.id IS NULL OR (s.agent_id<>(i->>'agent_id')::uuid AND (p_write OR NOT (i->>'authority'='admin' OR i->>'authority'='manager' AND i->'team_agent_ids' ? s.agent_id::text))) THEN RAISE EXCEPTION 'Practice scope denied' USING ERRCODE='42501'; END IF;
 RETURN s;
END $function$

CREATE OR REPLACE FUNCTION public.prepare_call_conference(p_attempt_id uuid, p_customer_phone text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a telephony_call_attempts; c call_records; inserted boolean;
BEGIN
 SELECT * INTO STRICT a FROM telephony_call_attempts WHERE id=p_attempt_id FOR UPDATE;
 IF a.ended_at IS NOT NULL OR a.answered_at IS NULL OR a.child_call_sid IS NULL THEN
  RAISE EXCEPTION 'Call is not connected'; END IF;
 SELECT * INTO STRICT c FROM call_records WHERE id=a.call_record_id AND tenant_id=a.tenant_id;
 INSERT INTO call_conferences(call_id,tenant_id,attempt_id,parent_call_sid,original_agent_id,owner_agent_id,name,started_at)
 VALUES(c.id,a.tenant_id,a.id,a.parent_call_sid,a.agent_id,a.agent_id,'enrollgen-'||c.id,c.call_start)
 ON CONFLICT(call_id) DO NOTHING;
 inserted:=FOUND;
 IF inserted THEN
  INSERT INTO call_participants(call_id,role,speaker,phone,twilio_call_sid,added_by_agent_id,agent_id,status,joined_at)
  VALUES(c.id,'agent','agent',NULL,CASE WHEN a.direction='inbound' THEN a.child_call_sid ELSE a.parent_call_sid END,a.agent_id,a.agent_id,'connected',clock_timestamp()),
   (c.id,'customer','customer',p_customer_phone,CASE WHEN a.direction='inbound' THEN a.parent_call_sid ELSE a.child_call_sid END,a.agent_id,NULL,'connected',clock_timestamp());
  PERFORM conference_event(c.id,'upgrade_requested');
 END IF;
 RETURN c.id;
END $function$

CREATE OR REPLACE FUNCTION public.protect_agent_call_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status IN ('available','callbacks_only') AND NOT public.agent_phone_routable(NEW.agent_id) THEN
    NEW.status:='offline'; NEW.available:=false;
  END IF;
  IF NEW.status='callbacks_only' THEN NEW.available:=false; END IF;
  IF OLD.active_call_sid IS NOT NULL AND NEW.active_call_sid IS NOT DISTINCT FROM OLD.active_call_sid THEN
    NEW.resume_status:=NEW.status;
    NEW.status:='busy'; NEW.available:=false;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_compliance_tracking()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 IF current_user IN ('anon','authenticated') THEN
  IF TG_OP='INSERT' THEN
   NEW.compliance_requested_at:=NULL; NEW.compliance_run_at:=NULL;
   NEW.compliance_transcript_hash:=NULL; NEW.compliance_dispo_changed_at:=NULL;
   NEW.compliance_status:='not_requested'; NEW.compliance_eligible:=true;
  ELSE
   NEW.compliance_requested_at:=OLD.compliance_requested_at; NEW.compliance_run_at:=OLD.compliance_run_at;
   NEW.compliance_transcript_hash:=OLD.compliance_transcript_hash;
   NEW.compliance_dispo_changed_at:=OLD.compliance_dispo_changed_at; NEW.compliance_status:=OLD.compliance_status;
   NEW.compliance_eligible:=OLD.compliance_eligible;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.provision_deployment_roster(p_profile jsonb, p_agents jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE tenant uuid:=(p_profile->>'tenantId')::uuid; item jsonb; agent_uuid uuid; former_slugs text[]; zone text:=p_profile->>'timezone';
BEGIN
 IF jsonb_typeof(p_agents)<>'array' OR jsonb_array_length(p_agents)=0 OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone) THEN RAISE EXCEPTION 'Invalid deployment provisioning input'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_agents) a WHERE nullif(a->>'clerk_user_id','') IS NULL OR nullif(a->>'agent_slug','') IS NULL OR nullif(a->>'npn','') IS NULL OR nullif(a->>'name','') IS NULL) THEN RAISE EXCEPTION 'Stable roster binding required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('deployment-roster',0));
 IF EXISTS(SELECT 1 FROM deployment_settings WHERE tenant_id<>tenant) THEN RAISE EXCEPTION 'Deployment tenant cannot be replaced'; END IF;
 INSERT INTO tenants(id,name,clerk_org_id,agency_display_name) VALUES(tenant,p_profile->>'agencyName',p_profile->>'organizationId',p_profile->>'agencyName')
 ON CONFLICT(id) DO UPDATE SET name=excluded.name,clerk_org_id=excluded.clerk_org_id,agency_display_name=excluded.agency_display_name;
 INSERT INTO deployment_settings(singleton,tenant_id,public_profile) VALUES(true,tenant,p_profile) ON CONFLICT(singleton) DO UPDATE SET public_profile=excluded.public_profile;
 SELECT array_agg(agent_slug) INTO former_slugs FROM tenant_agents WHERE tenant_id=tenant;
 -- A full reviewed roster is applied atomically, including revocation in protected mappings.
 UPDATE tenant_agents SET is_active=false WHERE tenant_id=tenant;
 UPDATE enrolled_agents SET is_active=false WHERE tenant_id=tenant;
 UPDATE availability_agent_subjects SET is_active=false WHERE tenant_id=tenant;
 DELETE FROM recording_agent_subjects WHERE tenant_id=tenant;
 FOR item IN SELECT * FROM jsonb_array_elements(p_agents) LOOP
  IF (item->>'is_active')::boolean IS NOT TRUE THEN CONTINUE; END IF;
  agent_uuid:=(item->>'id')::uuid;
  IF EXISTS(SELECT 1 FROM tenant_agents WHERE id=agent_uuid AND tenant_id<>tenant) THEN RAISE EXCEPTION 'Foreign roster ID'; END IF;
  INSERT INTO tenant_agents(id,tenant_id,name,npn,clerk_user_id,agent_slug,ghl_user_id,is_active,identity_aliases,licensed_states,team,sunfire_agent_id,ams_producer_id)
  VALUES(agent_uuid,tenant,item->>'name',item->>'npn',item->>'clerk_user_id',item->>'agent_slug',item->>'ghl_user_id',true,item->'identity_aliases',item->'licensed_states',item->>'team',item->>'sunfire_agent_id',item->>'ams_producer_id')
  ON CONFLICT(id) DO UPDATE SET name=excluded.name,npn=excluded.npn,clerk_user_id=excluded.clerk_user_id,agent_slug=excluded.agent_slug,ghl_user_id=excluded.ghl_user_id,is_active=true,identity_aliases=excluded.identity_aliases,licensed_states=excluded.licensed_states,team=excluded.team,sunfire_agent_id=excluded.sunfire_agent_id,ams_producer_id=excluded.ams_producer_id;
  -- Roles deliberately are NOT copied from the roster payload.
  INSERT INTO enrolled_agents(tenant_id,clerk_user_id,name,npn,role,is_active) VALUES(tenant,item->>'clerk_user_id',item->>'name',item->>'npn','agent',true)
  ON CONFLICT(clerk_user_id) DO UPDATE SET name=excluded.name,npn=excluded.npn,is_active=true WHERE enrolled_agents.tenant_id=tenant;
  INSERT INTO agent_availability(agent_id,agent_name,available,status,toggled_at) VALUES(item->>'agent_slug',item->>'name',false,'offline',now())
  ON CONFLICT(agent_id) DO UPDATE SET agent_name=excluded.agent_name;
  INSERT INTO availability_agent_subjects(agent_slug,tenant_id,clerk_org_id,clerk_user_id,is_active) VALUES(item->>'agent_slug',tenant,p_profile->>'organizationId',item->>'clerk_user_id',true)
  ON CONFLICT(agent_slug) DO UPDATE SET clerk_org_id=excluded.clerk_org_id,clerk_user_id=excluded.clerk_user_id,is_active=true WHERE availability_agent_subjects.tenant_id=tenant;
  INSERT INTO recording_agent_subjects(tenant_id,agent_slug,clerk_user_id) VALUES(tenant,item->>'agent_slug',item->>'clerk_user_id');
 END LOOP;
 UPDATE agent_availability SET available=false,status='offline',toggled_at=now() WHERE agent_id=ANY(former_slugs) AND NOT EXISTS(SELECT 1 FROM tenant_agents t WHERE t.tenant_id=tenant AND t.is_active AND t.agent_slug=agent_availability.agent_id);
 RETURN (SELECT count(*)::integer FROM tenant_agents WHERE tenant_id=tenant AND is_active);
END $function$

CREATE OR REPLACE FUNCTION public.read_access_review(p_actor text, p_org text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tenant uuid; answer jsonb;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 SELECT tenant_id INTO tenant FROM public.resolve_deployment_subject(p_actor,p_org) WHERE authority='admin';
 IF tenant IS NULL THEN RAISE EXCEPTION 'Protected admin required' USING ERRCODE='42501'; END IF;
 SELECT to_jsonb(r) INTO answer FROM public.access_review_reports r WHERE id=p_id AND tenant_id=tenant;
 IF answer IS NULL THEN RAISE EXCEPTION 'Review unavailable' USING ERRCODE='42501'; END IF;
 PERFORM public.record_recovery_action('access_review_generate',p_actor,p_org,p_id,(answer->>'exception_count')::integer,true);
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.read_consumer_lifecycle(p_actor text, p_org text, p_contact uuid, p_after_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_key text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_as_of timestamp with time zone DEFAULT NULL::timestamp with time zone, p_export boolean DEFAULT false, p_evidence_table text DEFAULT NULL::text, p_evidence_id uuid DEFAULT NULL::uuid, p_access_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_access_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i record; allowed boolean; answer jsonb; cutoff timestamptz:=coalesce(p_as_of,clock_timestamp());
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('CONSUMER_LIFECYCLE_ENABLED') THEN RAISE EXCEPTION 'Lifecycle unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO i FROM public.resolve_deployment_subject(p_actor,p_org);
 IF i.tenant_id IS NULL OR (p_export AND i.authority<>'admin') THEN RAISE EXCEPTION 'Lifecycle unavailable' USING ERRCODE='42501'; END IF;
 SELECT EXISTS(SELECT 1 FROM public.contacts c WHERE c.id=p_contact AND c.tenant_id=i.tenant_id AND
 (c.assigned_agent_id=i.agent_slug OR i.authority='admin' OR (i.authority='manager' AND EXISTS(
 SELECT 1 FROM public.tenant_agents r JOIN public.enrolled_agents e ON e.tenant_id=r.tenant_id AND e.clerk_user_id=r.clerk_user_id
 WHERE r.tenant_id=c.tenant_id AND r.agent_slug=c.assigned_agent_id AND e.id=ANY(i.team_agent_ids))))) INTO allowed;
 IF NOT allowed THEN RAISE EXCEPTION 'Lifecycle unavailable' USING ERRCODE='42501'; END IF;
 IF p_limit NOT BETWEEN 1 AND 200 OR (p_after_time IS NULL)<>(p_after_key IS NULL) OR (p_access_time IS NULL)<>(p_access_id IS NULL) OR cutoff>clock_timestamp()+interval '1 minute' THEN RAISE EXCEPTION 'Invalid lifecycle page' USING ERRCODE='22023'; END IF;
 WITH rows AS MATERIALIZED (SELECT * FROM public.consumer_lifecycle_rows(p_contact,i.tenant_id) WHERE "time" IS NOT NULL AND "time"<=cutoff),
 page AS (SELECT * FROM rows WHERE (p_type IS NULL OR type=p_type) AND (p_evidence_id IS NULL OR evidence @> jsonb_build_array(jsonb_build_object('table',p_evidence_table,'id',p_evidence_id))) AND (p_after_time IS NULL OR ("time",key)>(p_after_time,p_after_key COLLATE "C")) ORDER BY "time",key COLLATE "C" LIMIT p_limit+1)
 SELECT jsonb_build_object('consumerId',p_contact,'asOf',cutoff,'admin',i.authority='admin',
 'events',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY "time",key COLLATE "C") FROM (SELECT * FROM page ORDER BY "time",key COLLATE "C" LIMIT p_limit) p),'[]'),
 'hasMore',(SELECT count(*)>p_limit FROM page),
 'checkInputs',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY "time",key COLLATE "C") FROM rows r WHERE type IN ('consent','soa','call','recording','transcript','disclosure','review','enrollment','retention')),'[]'),
 'accesses',CASE WHEN i.authority='admin' THEN coalesce((SELECT jsonb_agg(to_jsonb(a)) FROM (SELECT id,actor_id,occurred_at,action,result FROM public.evidence_access_log WHERE tenant_id=i.tenant_id AND resource_type='consumer_lifecycle' AND resource_id=p_contact::text AND (p_access_time IS NULL OR (occurred_at,id)<(p_access_time,p_access_id)) ORDER BY occurred_at DESC,id DESC LIMIT 100) a),'[]') ELSE '[]'::jsonb END) INTO answer;
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.read_contact_details(p_contact_ids uuid[], p_requesting_agent_id uuid)
 RETURNS TABLE(contact_id uuid, fields jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a public.tenant_agents; c RECORD; details JSONB;
BEGIN
  a := public.deployment_assert_roster(p_requesting_agent_id);
  IF a.id IS NULL OR (auth.role() = 'authenticated'
    AND a.clerk_user_id IS DISTINCT FROM nullif(auth.jwt()->>'sub', '')) THEN
    RAISE EXCEPTION 'Your agent account is not linked to this session';
  END IF;
  IF coalesce(cardinality(p_contact_ids), 0) > 200 THEN
    RAISE EXCEPTION 'Request at most 200 contacts at a time';
  END IF;
  FOR c IN SELECT id FROM public.contacts WHERE id = ANY(p_contact_ids) AND tenant_id = a.tenant_id AND (a.role='admin' OR assigned_agent_id=a.agent_slug) LOOP
    details := public.decrypt_pii(c.id, a.id, 'view');
    -- Only send fields needed by the CRM, never SSNs or encryption metadata.
    RETURN QUERY SELECT c.id, jsonb_build_object(
      'first_name', details->'first_name', 'last_name', details->'last_name',
      'phone', details->'phone', 'email', details->'email',
      'dob', details->'dob', 'address', details->'address', 'mbi_full', details->'mbi_full');
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.read_contact_tags(p_tenant_id uuid, p_requesting_agent_id uuid, p_contact_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE cid uuid; result jsonb;
BEGIN
  PERFORM public.opportunities_assert_agent(p_tenant_id,p_requesting_agent_id);
  IF coalesce(cardinality(p_contact_ids),0) > 200 THEN RAISE EXCEPTION 'Request up to 200 contacts at a time'; END IF;
  -- Same audited, encrypted read pattern as contacts and opportunities.
  FOR cid IN SELECT DISTINCT contact_id FROM public.contact_tags
    WHERE tenant_id = p_tenant_id AND contact_id = ANY(p_contact_ids) AND (current_setting('role',true)='service_role' OR public.deployment_can_access_contact(contact_id)) LOOP
    INSERT INTO public.pii_access_log(contact_id,agent_id,clerk_user_id,action)
      VALUES(cid,p_requesting_agent_id,auth.jwt()->>'sub','view');
  END LOOP;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'contact_id',contact_id,
    'name',public.decrypt_pii_value(name_encrypted)) ORDER BY created_at,id),'[]') INTO result
    FROM public.contact_tags WHERE tenant_id = p_tenant_id AND contact_id = ANY(p_contact_ids) AND (current_setting('role',true)='service_role' OR public.deployment_can_access_contact(contact_id));
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.read_evidence_agent_coaching(p_resource uuid DEFAULT NULL::uuid, p_action text DEFAULT 'list'::text)
 RETURNS SETOF agent_coaching
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE allowed boolean;
BEGIN
 IF p_action NOT IN ('list','read','export') THEN p_action:='read'; END IF;
 SELECT EXISTS(SELECT 1 FROM public.current_deployment_identity()) AND
 (p_resource IS NULL OR EXISTS(SELECT 1 FROM public.agent_coaching r WHERE r.id=p_resource AND public.deployment_row_visible('agent_coaching',to_jsonb(r)))) INTO allowed;
 PERFORM public.audit_browser_evidence('agent_coaching',p_resource,p_action,allowed);
 IF allowed THEN RETURN QUERY SELECT r.* FROM public.agent_coaching r
 WHERE (p_resource IS NULL OR r.id=p_resource) AND public.deployment_row_visible('agent_coaching',to_jsonb(r)); END IF;
END $function$

CREATE OR REPLACE FUNCTION public.read_evidence_call_insights(p_resource uuid DEFAULT NULL::uuid, p_action text DEFAULT 'list'::text)
 RETURNS SETOF call_insights
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE allowed boolean;
BEGIN
