CREATE OR REPLACE FUNCTION public.record_recovery_action(p_action text, p_actor text, p_org text, p_target uuid, p_count integer DEFAULT 0, p_success boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tenant uuid; event_id uuid;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 IF p_action IN ('access_review_generate','access_review_signoff') THEN
 SELECT tenant_id INTO tenant FROM public.resolve_deployment_subject(p_actor,p_org) WHERE authority='admin';
 ELSIF p_action IN ('recovery_drill','recovery_backup','recovery_restore','recording_purge_pending','recording_purge_complete','recording_purge_cancelled','recording_purge_held_missing') AND p_actor='service:recovery' THEN
 SELECT tenant_id INTO tenant FROM public.deployment_settings WHERE singleton;
 ELSE RAISE EXCEPTION 'Unknown recovery action' USING ERRCODE='42501'; END IF;
 IF tenant IS NULL OR p_count<0 THEN RAISE EXCEPTION 'Protected admin required' USING ERRCODE='42501'; END IF;
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,after_summary)
 VALUES(gen_random_uuid(),p_actor,tenant,p_action,CASE WHEN p_action LIKE 'access_review%' THEN 'staff_access_review' ELSE 'recovery' END,coalesce(p_target::text,'collection'),CASE WHEN p_success THEN 'succeeded' ELSE 'denied' END,jsonb_build_object('count',p_count,'success',p_success)) RETURNING id INTO event_id;
 RETURN event_id;
END $function$

CREATE OR REPLACE FUNCTION public.record_telephony_evidence(p_attempt_id uuid, p_parent_sid text, p_agent_id text, p_child_sid text, p_source text, p_status text, p_answered_at timestamp with time zone, p_ended_at timestamp with time zone, p_talk_seconds integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a telephony_call_attempts; is_answer BOOLEAN; is_terminal BOOLEAN; qualifies BOOLEAN;
BEGIN
  SELECT * INTO a FROM telephony_call_attempts WHERE id = p_attempt_id FOR UPDATE;
  IF a.id IS NULL OR a.parent_call_sid IS DISTINCT FROM p_parent_sid OR
     a.agent_id IS DISTINCT FROM p_agent_id OR nullif(p_child_sid, '') IS NULL OR
     (a.child_call_sid IS NOT NULL AND a.child_call_sid != p_child_sid) THEN
    RAISE EXCEPTION 'Call attempt identity mismatch';
  END IF;
  IF p_source NOT IN ('child', 'dial') THEN RAISE EXCEPTION 'Invalid evidence source'; END IF;
  is_terminal := p_status IN ('completed', 'canceled', 'no-answer', 'busy', 'failed');
  is_answer := (p_source = 'child' AND p_status IN ('answered', 'in-progress')) OR
    (p_status = 'completed' AND p_talk_seconds > 0 AND (p_source = 'dial' OR a.direction = 'outbound'));
  IF is_answer AND p_answered_at IS NULL THEN RAISE EXCEPTION 'Answer timestamp required'; END IF;

  -- First authoritative answer fixes this attempt's timestamp. Later callbacks
  -- cannot turn retries into newer conversations, or reopen a terminated leg.
  UPDATE telephony_call_attempts SET child_call_sid = p_child_sid,
    answered_at = coalesce(answered_at, CASE WHEN is_answer THEN p_answered_at END),
    ended_at = coalesce(ended_at, CASE WHEN is_terminal THEN p_ended_at END),
    talk_seconds = greatest(talk_seconds, CASE WHEN p_status = 'completed' THEN coalesce(p_talk_seconds, 0) ELSE 0 END),
    status = CASE WHEN is_terminal THEN p_status WHEN ended_at IS NULL AND is_answer THEN 'accepted' ELSE status END
  WHERE id = a.id RETURNING * INTO a;

  qualifies := a.answered_at IS NOT NULL AND
    (a.direction = 'inbound' OR (a.status = 'completed' AND a.talk_seconds >= a.min_connected_seconds));
  IF qualifies THEN
    UPDATE telephony_call_attempts SET qualified_at = coalesce(qualified_at, a.answered_at) WHERE id = a.id;
    PERFORM advance_contact_connection(a.contact_id, a.tenant_id, a.agent_id, a.answered_at, a.direction);
  END IF;
  IF a.direction = 'inbound' AND a.answered_at IS NOT NULL THEN
    UPDATE inbound_calls SET
      answered_at = coalesce(answered_at, a.answered_at),
      answered_agent_id = coalesce(answered_agent_id, a.agent_id),
      status = CASE WHEN ended_at IS NOT NULL OR a.ended_at IS NOT NULL THEN 'completed' ELSE 'accepted' END,
      ended_at = coalesce(ended_at, a.ended_at)
    WHERE id = a.inbound_call_id AND tenant_id = a.tenant_id AND twilio_call_sid = a.parent_call_sid
      AND (answered_agent_id IS NULL OR answered_agent_id = a.agent_id);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_transcription_incident(p_attempt_id uuid, p_participant_id uuid, p_reason text, p_at_ms integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE rid uuid;tid uuid;
BEGIN
 IF p_participant_id IS NOT NULL THEN SELECT p.call_id,c.tenant_id INTO rid,tid FROM call_participants p JOIN call_conferences c ON c.call_id=p.call_id WHERE p.id=p_participant_id;
 ELSE SELECT call_record_id,tenant_id INTO rid,tid FROM telephony_call_attempts WHERE id=p_attempt_id; END IF;
 IF rid IS NULL THEN RETURN; END IF;
 INSERT INTO transcription_incidents(call_id,tenant_id,reason,at_ms) VALUES(rid,tid,left(p_reason,100),greatest(0,p_at_ms));
END $function$

CREATE OR REPLACE FUNCTION public.refresh_sale_compliance_request(p_call_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records;
BEGIN
 IF NOT public.deployment_feature_enabled('SCORING_ENABLED') THEN RETURN; END IF;
 SELECT * INTO STRICT c FROM call_records WHERE id=p_call_id FOR UPDATE;
 IF c.metadata->>'scoring_status' IN ('incomplete','na') AND NOT EXISTS(SELECT 1 FROM compliance_scorecards s WHERE s.id=c.compliance_scorecard_id AND s.scoring_state='complete') THEN
  UPDATE call_records SET compliance_status=c.metadata->>'scoring_status' WHERE id=c.id;
  UPDATE transcript_score_dispatch SET delivered_revision=revision,available_at='infinity' WHERE call_id=c.id;
  RETURN;
 END IF;
 PERFORM refresh_sale_compliance_request_legacy_139(p_call_id);
END $function$

CREATE OR REPLACE FUNCTION public.refresh_sale_compliance_request_legacy_139(p_call_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records; d transcript_score_dispatch; content_hash text; ready boolean; next_status text;
BEGIN
 SELECT * INTO STRICT c FROM call_records WHERE id=p_call_id FOR UPDATE;
 content_hash:=public.compliance_content_hash(c);
 IF NOT public.is_compliance_sale(c.call_outcome) OR c.compliance_requested_at IS NULL THEN
  next_status:=CASE WHEN c.compliance_dispo_changed_at IS NOT NULL AND c.compliance_scorecard_id IS NOT NULL
   THEN 'dispo_changed' ELSE 'not_requested' END;
  UPDATE transcript_score_dispatch SET delivered_revision=revision,available_at='infinity' WHERE call_id=c.id;
 ELSIF c.compliance_run_at IS NOT NULL AND c.compliance_scorecard_id IS NOT NULL AND c.compliance_transcript_hash=content_hash THEN
  next_status:='complete';
  UPDATE transcript_score_dispatch SET delivered_revision=revision,available_at='infinity',last_error=NULL WHERE call_id=c.id;
 ELSE
  ready:=public.sale_compliance_transcript_ready(c);
  SELECT * INTO d FROM transcript_score_dispatch WHERE call_id=c.id FOR UPDATE;
  IF d.call_id IS NOT NULL AND d.snapshot_revision=content_hash
   AND d.last_error IN ('scoring_attempts_exhausted','call_token_budget_exceeded') THEN
   next_status:='failed';
  ELSE
   next_status:=CASE WHEN NOT ready THEN 'transcript_pending'
    WHEN c.metadata->>'scoring_status'='pending' AND c.metadata->>'scoring_revision'=md5(scoring_transcript_snapshot(c)::text) THEN 'scoring'
    WHEN c.metadata->>'scoring_status'='failed' AND c.metadata->>'scoring_revision'=md5(scoring_transcript_snapshot(c)::text) THEN 'failed'
    ELSE 'queued' END;
   IF d.call_id IS NULL THEN
    INSERT INTO transcript_score_dispatch(call_id,tenant_id,available_at,snapshot_revision)
     VALUES(c.id,c.tenant_id,CASE WHEN ready THEN clock_timestamp()+interval '5 seconds' ELSE 'infinity'::timestamptz END,content_hash);
   ELSIF d.snapshot_revision IS DISTINCT FROM content_hash THEN
    UPDATE transcript_score_dispatch SET revision=revision+1,snapshot_revision=content_hash,last_error=NULL,
     available_at=CASE WHEN ready THEN clock_timestamp()+interval '5 seconds' ELSE 'infinity'::timestamptz END WHERE call_id=c.id;
   ELSIF NOT ready THEN
    UPDATE transcript_score_dispatch SET available_at='infinity' WHERE call_id=c.id;
   ELSIF d.available_at='infinity'::timestamptz THEN
    -- A pending transcript just became ready, or a canceled request became a sale again.
    UPDATE transcript_score_dispatch SET delivered_revision=least(delivered_revision,revision-1),
     available_at=clock_timestamp()+interval '5 seconds' WHERE call_id=c.id;
   END IF;
  END IF;
 END IF;
 UPDATE call_records SET compliance_status=next_status WHERE id=c.id AND compliance_status IS DISTINCT FROM next_status;
END $function$

CREATE OR REPLACE FUNCTION public.regenerate_post_call_coaching(p_actor text, p_org text, p_call uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE identity record; c public.call_records; allowance jsonb;
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('POST_CALL_COACHING_ENABLED') THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO identity FROM public.resolve_deployment_subject(p_actor,p_org) WHERE authority='admin';
 IF NOT EXISTS(SELECT 1 FROM public.admin_action_permit WHERE transaction_id=txid_current()) THEN RAISE EXCEPTION 'Administrator audit boundary required' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.call_records WHERE id=p_call AND tenant_id=identity.tenant_id FOR UPDATE;
 IF c.id IS NULL OR NOT public.coaching_call_eligible(c) THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.transcript_score_dispatch WHERE call_id=c.id AND coaching_lease_until>clock_timestamp()) THEN RAISE EXCEPTION 'Coaching busy' USING ERRCODE='55000'; END IF;
 SELECT public.consume_admission(jsonb_build_array(jsonb_build_object('key',identity.tenant_id::text||':coaching-regenerate-db:'||p_actor,'seconds',60,'limit',3))) INTO allowance;
 IF allowance->>'allowed' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Regenerate rate limited' USING ERRCODE='P1649'; END IF;
 UPDATE public.transcript_score_dispatch SET coaching_generation=coaching_generation+1,coaching_state='queued',coaching_attempts=0,coaching_reserved_day=NULL,coaching_token=NULL,coaching_lease_until=NULL,coaching_available_at=clock_timestamp(),coaching_queued_at=clock_timestamp() WHERE call_id=c.id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Coaching unavailable'; END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.register_lead_ping(p_key_hash text, p_phone text, p_publisher text, p_call_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE source lead_sources;
BEGIN
  SELECT * INTO source FROM lead_sources WHERE ping_key_hash=p_key_hash AND active AND type='aggregator';
  IF source.id IS NULL THEN RETURN false; END IF;
  IF p_phone !~ '^\+[1-9][0-9]{7,14}$' THEN RAISE EXCEPTION 'invalid phone'; END IF;
  INSERT INTO lead_source_pings(source_id,caller_phone,publisher,aggregator_call_id)
    VALUES(source.id,p_phone,left(p_publisher,128),left(p_call_id,128));
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_stt_stream(p_tenant_id uuid, p_call_sid text, p_channel text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE budget stt_call_reconnects; prior integer;
BEGIN
 IF length(p_channel)>100 OR NOT (EXISTS(SELECT 1 FROM telephony_call_attempts WHERE tenant_id=p_tenant_id AND parent_call_sid=p_call_sid AND ended_at IS NULL AND answered_at IS NOT NULL) OR EXISTS(SELECT 1 FROM call_conferences WHERE tenant_id=p_tenant_id AND parent_call_sid=p_call_sid AND ended_at IS NULL)) THEN RETURN false; END IF;
 INSERT INTO stt_call_reconnects(tenant_id,call_sid) VALUES(p_tenant_id,p_call_sid) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT budget FROM stt_call_reconnects WHERE tenant_id=p_tenant_id AND call_sid=p_call_sid FOR UPDATE;
 prior:=coalesce((budget.channels->>p_channel)::integer,0);
 IF prior>0 AND budget.reconnects>=20 THEN RETURN false; END IF;
 UPDATE stt_call_reconnects SET channels=jsonb_set(channels,ARRAY[p_channel],to_jsonb(prior+1)),reconnects=reconnects+CASE WHEN prior>0 THEN 1 ELSE 0 END,updated_at=clock_timestamp() WHERE tenant_id=p_tenant_id AND call_sid=p_call_sid;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.release_whisper_upload(p_actor text, p_org text, p_call uuid, p_recording uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i record;c public.call_records;
BEGIN
 SELECT * INTO i FROM public.resolve_deployment_subject(p_actor,p_org);
 IF i.authority IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Protected admin required' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT c FROM public.call_records WHERE id=p_call AND tenant_id=i.tenant_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.whisper_customer_recordings(c.id,c.tenant_id) WHERE id=p_recording) THEN RAISE EXCEPTION 'Choose a usable customer recording' USING ERRCODE='42501'; END IF;
 INSERT INTO public.admin_action_log(request_id,actor_id,tenant_id,action,target_type,target_id,result,after_summary) VALUES(gen_random_uuid(),p_actor,c.tenant_id,'whisper_upload_release','call_records',c.id::text,'authorized',jsonb_build_object('recording_id',p_recording));
 INSERT INTO public.evidence_access_log(actor_id,tenant_id,resource_type,resource_id,action,result,grant_id) VALUES(p_actor,c.tenant_id,'recording',p_recording::text,'export','allowed',gen_random_uuid());
 UPDATE public.call_records SET metadata=metadata||jsonb_build_object('whisper_upload_hold',jsonb_build_object('held',false,'recording_id',p_recording)) WHERE id=c.id;
 UPDATE public.ix_uploads SET status='pending',retryable=true,next_attempt_at=clock_timestamp(),last_error=NULL,attempts=0,lease_token=NULL,lease_until=NULL WHERE call_id=c.id AND last_error='whisper_customer_recording_required' AND finalized_at IS NULL;
 UPDATE public.conversely_submissions SET status='pending',next_attempt_at=clock_timestamp(),last_error=NULL,attempts=0,lease_token=NULL,lease_until=NULL WHERE call_id=c.id AND last_error='whisper_customer_recording_required' AND uploaded_at IS NULL;
END $function$

CREATE OR REPLACE FUNCTION public.remove_contact_tag(p_tag_id uuid, p_requesting_agent_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE tag public.contact_tags;
BEGIN
  SELECT * INTO tag FROM public.contact_tags WHERE id = p_tag_id;
  IF tag.id IS NULL THEN RAISE EXCEPTION 'Tag not found'; END IF;
  IF current_setting('role',true)<>'service_role' AND NOT public.deployment_can_access_contact(tag.contact_id) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501'; END IF; PERFORM public.opportunities_assert_agent(tag.tenant_id,p_requesting_agent_id);
  DELETE FROM public.contact_tags WHERE id = tag.id;
  INSERT INTO public.pii_access_log(contact_id,agent_id,clerk_user_id,action)
    VALUES(tag.contact_id,p_requesting_agent_id,auth.jwt()->>'sub','edit');
END;
$function$

CREATE OR REPLACE FUNCTION public.renew_supervisor_listen(p_id uuid, p_actor text, p_org text, p_session text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.supervisor_listen_sessions;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.supervisor_listen_sessions WHERE mode='listen' AND id=p_id AND actor_id=p_actor AND session_id=p_session AND ended_at IS NULL AND lease_until>clock_timestamp() AND expires_at>clock_timestamp();
 IF s.id IS NULL THEN RETURN false; END IF;
 PERFORM public.supervisor_listen_authorize(p_actor,p_org,s.attempt_id);
 IF EXISTS(SELECT 1 FROM public.telephony_events WHERE tenant_id=s.tenant_id AND event='session_lock' AND payload->>'clerk_user_id'=p_actor AND occurred_at>=s.started_at) THEN RETURN false; END IF;
 UPDATE public.supervisor_listen_sessions SET lease_until=clock_timestamp()+interval '8 seconds' WHERE id=p_id AND ended_at IS NULL;
 RETURN FOUND;
END $function$

CREATE OR REPLACE FUNCTION public.renew_supervisor_whisper(p_id uuid, p_actor text, p_org text, p_session text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.supervisor_listen_sessions;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.supervisor_listen_sessions WHERE id=p_id AND actor_id=p_actor AND session_id=p_session AND mode='whisper' AND ended_at IS NULL AND lease_until>clock_timestamp() AND expires_at>clock_timestamp();
 IF s.id IS NULL THEN RETURN false; END IF;
 -- Runs outside the operation lease, independently of browser-supplied state.
 PERFORM public.supervisor_whisper_authorize(p_actor,p_org,s.attempt_id,false);
 IF EXISTS(SELECT 1 FROM public.telephony_events WHERE tenant_id=s.tenant_id AND event='session_lock' AND payload->>'clerk_user_id'=p_actor AND occurred_at>=s.started_at)
 OR s.participant_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.call_participants WHERE call_id=s.call_id AND role='agent' AND twilio_call_sid=s.agent_leg_sid AND status='connected') THEN RETURN false; END IF;
 UPDATE public.supervisor_listen_sessions SET lease_until=clock_timestamp()+interval '8 seconds' WHERE id=s.id AND ended_at IS NULL;
 RETURN FOUND;
END $function$

CREATE OR REPLACE FUNCTION public.request_conversely_run(p_tenant uuid, p_actor text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE week date; run uuid;
BEGIN
 IF NOT public.deployment_feature_enabled('CONVERSELY_UPLOAD_ENABLED') THEN RETURN NULL; END IF;
 week:=date_trunc('week',now() AT TIME ZONE public.deployment_timezone())::date;
 IF NOT EXISTS(SELECT 1 FROM conversely_worker_status WHERE singleton AND enabled AND heartbeat_at>now()-interval '5 minutes') THEN
  RAISE EXCEPTION 'Conversely worker is disabled or unavailable'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant::text||':conversely-request:'||week::text,0));
 SELECT id INTO run FROM conversely_runs WHERE tenant_id=p_tenant AND week_start=week AND trigger='manual'
 AND status IN ('pending','selecting','delivering') LIMIT 1;
 IF run IS NOT NULL THEN RETURN run; END IF;
 INSERT INTO conversely_runs(tenant_id,week_start,trigger,requested_by) VALUES(p_tenant,week,'manual',p_actor) RETURNING id INTO run;
 RETURN run;
END; $function$

CREATE OR REPLACE FUNCTION public.require_uhc_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 IF NEW.call_outcome IN ('enrolled','enrolled_pending_verification') THEN
  IF upper(coalesce(NEW.product_type,''))='MA' AND EXISTS(SELECT 1 FROM enrollment_intakes WHERE call_id=NEW.id AND tenant_id=NEW.tenant_id AND completed_at IS NOT NULL) THEN
   IF EXISTS(SELECT 1 FROM enrollment_intakes WHERE call_id=NEW.id AND tenant_id=NEW.tenant_id AND completed_at IS NOT NULL
    AND carrier_key='UnitedHealthcare' AND nullif(btrim(data->>'sunfireCode'),'') IS NULL) THEN
    RAISE EXCEPTION 'SunFire Confirmation Code is required for UHC enrollment'; END IF;
  ELSIF public.is_uhc_carrier(NEW.carrier_name) AND NOT EXISTS(SELECT 1 FROM public.sunfire_codes(NEW.sunfire_code)) THEN
   IF TG_OP='INSERT' THEN RAISE EXCEPTION 'SunFire Confirmation Code is required for UHC enrollment';
   ELSIF NEW.call_outcome IS DISTINCT FROM OLD.call_outcome OR NEW.carrier_name IS DISTINCT FROM OLD.carrier_name OR NEW.sunfire_code IS DISTINCT FROM OLD.sunfire_code THEN
    RAISE EXCEPTION 'SunFire Confirmation Code is required for UHC enrollment'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.reserve_compliance_request(p_pass_id uuid, p_request_id uuid, p_model text, p_tokens integer, p_daily_cap bigint, p_fallback boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE p compliance_llm_passes; b compliance_daily_budget; n integer; result uuid; alert_now boolean:=false; budget_day date:=(clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM compliance_runtime_control WHERE id AND enabled) THEN RAISE EXCEPTION 'scoring_disabled'; END IF;
 SELECT * INTO STRICT p FROM compliance_llm_passes WHERE id=p_pass_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM call_records cr WHERE cr.id=p.call_id AND compliance_call_excluded(cr)) THEN RAISE EXCEPTION 'Call is not applicable for scoring'; END IF;
 IF p.status NOT IN ('reserved','running') OR p_tokens<1 THEN RAISE EXCEPTION 'Pass unavailable'; END IF;
 SELECT id INTO result FROM compliance_llm_requests WHERE request_id=p_request_id AND pass_id=p.id;
 IF FOUND THEN RAISE EXCEPTION 'Provider request already reserved; never replay'; END IF;
 SELECT count(*) INTO n FROM compliance_llm_requests WHERE pass_id=p.id;
 -- One request per pass. No retry or Terra fallback can silently add a pass.
 IF n>=1 OR p_fallback THEN RAISE EXCEPTION 'Paid request limit reached'; END IF;
 IF p_daily_cap IS NULL OR p_daily_cap<1 THEN RAISE EXCEPTION 'Daily scoring cap not configured'; END IF;
 INSERT INTO compliance_daily_budget(day,token_cap) VALUES(budget_day,least(p_daily_cap,2000000)) ON CONFLICT DO NOTHING;
 SELECT * INTO b FROM compliance_daily_budget WHERE day=budget_day FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Daily budget unavailable'; END IF;
 IF b.halted OR b.reserved_tokens+p_tokens>least(b.token_cap,p_daily_cap,2000000) THEN
  alert_now:=NOT b.alert_claimed;
  UPDATE compliance_daily_budget SET halted=true,alert_claimed=true WHERE day=b.day;
  -- Return instead of raising: the halt and once-per-day claim must commit.
  RETURN jsonb_build_object('status','daily_cap','alert_claimed',alert_now,'day',b.day);
 END IF;
 alert_now:=b.reserved_tokens+p_tokens=least(b.token_cap,p_daily_cap,2000000) AND NOT b.alert_claimed;
 UPDATE compliance_daily_budget SET reserved_tokens=reserved_tokens+p_tokens,
 halted=reserved_tokens+p_tokens>=least(token_cap,p_daily_cap,2000000),alert_claimed=alert_claimed OR alert_now WHERE day=b.day;
 UPDATE compliance_llm_passes SET status='running' WHERE id=p.id;
 INSERT INTO compliance_llm_requests(pass_id,request_id,model,attempt,reserved_tokens,fallback)
 VALUES(p.id,p_request_id,p_model,n+1,p_tokens,p_fallback) RETURNING id INTO result;
 RETURN jsonb_build_object('status','reserved','id',result,'alert_claimed',alert_now,'day',b.day);
END $function$

CREATE OR REPLACE FUNCTION public.reserve_conference_agent(p_call_sid text, p_agent_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE room call_conferences;
BEGIN
 SELECT * INTO STRICT room FROM call_conferences WHERE parent_call_sid=p_call_sid AND ended_at IS NULL;
 IF NOT EXISTS(SELECT 1 FROM availability_agent_subjects r JOIN enrolled_agents e
  ON e.tenant_id=r.tenant_id AND e.clerk_user_id=r.clerk_user_id
  WHERE r.agent_slug=p_agent_id AND r.tenant_id=room.tenant_id AND r.is_active AND e.is_active)
 OR NOT EXISTS(SELECT 1 FROM agent_phone_sessions WHERE agent_id=p_agent_id AND expires_at>clock_timestamp())
 THEN RETURN false; END IF;
 PERFORM 1 FROM agent_availability WHERE agent_id=p_agent_id AND active_call_sid=p_call_sid;
 IF FOUND THEN RETURN true; END IF;
 UPDATE agent_availability SET active_call_sid=p_call_sid,resume_status=status,status='busy',available=false,
  last_assigned_at=clock_timestamp(),toggled_at=clock_timestamp()
 WHERE agent_id=p_agent_id AND active_call_sid IS NULL AND status IN ('available','callbacks_only');
 RETURN FOUND;
END $function$

CREATE OR REPLACE FUNCTION public.reserve_conversely_run(p_id uuid, p_token uuid, p_decisions jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE r conversely_runs;a record;d jsonb;slot conversely_week_slots;job uuid;job_status text;skip_reason text;
BEGIN
 IF NOT public.deployment_feature_enabled('CONVERSELY_UPLOAD_ENABLED') THEN RETURN; END IF;
 SELECT * INTO r FROM conversely_runs WHERE id=p_id FOR UPDATE;
 IF r.id IS NULL OR r.status<>'selecting' OR r.lease_token IS DISTINCT FROM p_token THEN RETURN; END IF;
 -- Match the scheduler's lock order before touching the shared week row.
 PERFORM pg_advisory_xact_lock(hashtextextended('conversely-week:'||r.week_start::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(r.tenant_id::text||':conversely-slots:'||r.week_start::text,0));
 INSERT INTO conversely_weekly_runs(week_start,samples_per_agent) VALUES(r.week_start,1) ON CONFLICT DO NOTHING;
 FOR a IN SELECT * FROM enrolled_agents WHERE tenant_id=r.tenant_id AND is_active ORDER BY id LOOP
  SELECT * INTO slot FROM conversely_week_slots WHERE tenant_id=r.tenant_id AND week_start=r.week_start AND agent_id=a.id;
  IF slot.submission_id IS NOT NULL THEN
   SELECT status INTO job_status FROM conversely_submissions WHERE id=slot.submission_id;
   INSERT INTO conversely_run_agents VALUES(r.id,r.tenant_id,a.id,CASE WHEN job_status='uploaded' THEN 'skipped' ELSE 'selected' END,
    CASE WHEN job_status='uploaded' THEN 'already_submitted' ELSE 'already_queued' END,slot.submission_id) ON CONFLICT DO NOTHING;
   CONTINUE;
  END IF;
  d:=NULL;
  SELECT value INTO d FROM jsonb_array_elements(p_decisions) WHERE value->>'tenant_id'=r.tenant_id::text
   AND value->>'agent_id'=a.id::text AND (value->>'selected')::boolean ORDER BY (value->>'sample_rank')::integer LIMIT 1;
  IF d IS NULL THEN
   SELECT value->>'reason' INTO skip_reason FROM jsonb_array_elements(p_decisions) WHERE value->>'agent_id'=a.id::text
    AND value->>'tenant_id'=r.tenant_id::text AND value->>'reason'<>'no_eligible_calls' LIMIT 1;
   INSERT INTO conversely_run_agents VALUES(r.id,r.tenant_id,a.id,'skipped',coalesce(skip_reason,'no_eligible_calls'),NULL) ON CONFLICT DO NOTHING;
   CONTINUE;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM call_records WHERE id=(d->>'call_id')::uuid AND tenant_id=r.tenant_id AND agent_id=a.id
   AND call_outcome IN ('enrolled','enrolled_pending_verification')
   AND call_start<=CASE WHEN r.trigger='manual' THEN r.requested_at ELSE now() END AND call_start >= (r.week_start::timestamp AT TIME ZONE public.deployment_timezone())
   AND call_start < ((r.week_start+7)::timestamp AT TIME ZONE public.deployment_timezone())) THEN RAISE EXCEPTION 'Invalid selected call'; END IF;
  job:=NULL;
  INSERT INTO conversely_submissions(tenant_id,call_id,twilio_recording_sid,enrollment_key)
   VALUES(r.tenant_id,(d->>'call_id')::uuid,d->>'recording_sid',d->>'enrollment_key') ON CONFLICT DO NOTHING RETURNING id INTO job;
  IF job IS NULL THEN SELECT id INTO job FROM conversely_submissions WHERE tenant_id=r.tenant_id AND twilio_recording_sid=d->>'recording_sid' AND enrollment_key=d->>'enrollment_key'; END IF;
  INSERT INTO conversely_week_slots VALUES(r.tenant_id,r.week_start,a.id,d->>'agent_slug',job);
  INSERT INTO conversely_weekly_audit(week_start,tenant_id,agent_id,agent_slug,call_id,recording_sid,enrollment_key,score,eligible,selected,reason,sample_rank,submission_id)
   VALUES(r.week_start,r.tenant_id,a.id,d->>'agent_slug',(d->>'call_id')::uuid,d->>'recording_sid',d->>'enrollment_key',(d->>'score')::numeric,true,true,'selected',1,job)
   ON CONFLICT(week_start,tenant_id,agent_id,sample_rank) DO NOTHING;
  INSERT INTO conversely_run_agents VALUES(r.id,r.tenant_id,a.id,'selected','selected',job) ON CONFLICT DO NOTHING;
 END LOOP;
 UPDATE conversely_runs SET status='delivering',lease_token=NULL,lease_until=NULL WHERE id=r.id;
END; $function$

CREATE OR REPLACE FUNCTION public.reserve_conversely_week(p_week date, p_samples integer, p_decisions jsonb)
 RETURNS SETOF conversely_weekly_audit
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE t record;r uuid;token uuid;d jsonb;
BEGIN
 IF NOT public.deployment_feature_enabled('CONVERSELY_UPLOAD_ENABLED') THEN RETURN; END IF;
 IF p_samples<>1 OR extract(isodow FROM p_week)<>1 OR p_week+7>(now() AT TIME ZONE public.deployment_timezone())::date THEN RAISE EXCEPTION 'Invalid weekly run'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('conversely-week:'||p_week::text,0));
 IF EXISTS(SELECT 1 FROM conversely_weekly_runs WHERE week_start=p_week AND scheduled_at IS NOT NULL) THEN RETURN; END IF;
 INSERT INTO conversely_weekly_runs(week_start,samples_per_agent,scheduled_at) VALUES(p_week,1,now())
 ON CONFLICT(week_start) DO UPDATE SET scheduled_at=excluded.scheduled_at;
 FOR t IN SELECT DISTINCT (value->>'tenant_id')::uuid tenant FROM jsonb_array_elements(p_decisions) LOOP
  token:=gen_random_uuid();
  INSERT INTO conversely_runs(tenant_id,week_start,trigger,status,started_at,lease_token)
   VALUES(t.tenant,p_week,'scheduled','selecting',now(),token) RETURNING id INTO r;
  PERFORM reserve_conversely_run(r,token,p_decisions);
 END LOOP;
 FOR d IN SELECT value FROM jsonb_array_elements(p_decisions) WHERE NOT (value->>'selected')::boolean LOOP
  INSERT INTO conversely_weekly_audit(week_start,tenant_id,agent_id,agent_slug,call_id,recording_sid,enrollment_key,score,eligible,selected,reason)
   VALUES(p_week,(d->>'tenant_id')::uuid,(d->>'agent_id')::uuid,d->>'agent_slug',(d->>'call_id')::uuid,d->>'recording_sid',d->>'enrollment_key',(d->>'score')::numeric,(d->>'eligible')::boolean,false,d->>'reason');
 END LOOP;
 RETURN QUERY SELECT * FROM conversely_weekly_audit WHERE week_start=p_week ORDER BY agent_id,call_id;
END; $function$

CREATE OR REPLACE FUNCTION public.reserve_practice_tokens(p_id uuid, p_token uuid, p_tokens integer, p_task text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.practice_sessions; maximum integer;
BEGIN
 PERFORM public.practice_server(); SELECT * INTO s FROM public.practice_sessions WHERE id=p_id FOR UPDATE;
 maximum:=CASE p_task WHEN 'practice_consumer' THEN 24000 WHEN 'practice_scoring' THEN 180000 WHEN 'practice_coaching' THEN 180000 ELSE 0 END;
 IF p_token IS NULL OR s.work_token IS DISTINCT FROM p_token OR s.lease_until<=clock_timestamp() OR s.status NOT IN ('active','ending') OR p_tokens IS NULL OR p_tokens<1 OR p_tokens>maximum OR s.reserved_tokens+p_tokens>1200000 THEN RETURN false; END IF;
 UPDATE public.practice_sessions SET reserved_tokens=reserved_tokens+p_tokens WHERE id=p_id; RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.reserve_scoring_input_tokens(p_job_id uuid, p_attempt_token uuid, p_tokens integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE j public.scoring_jobs;
BEGIN
  UPDATE scoring_jobs SET estimated_input_tokens=estimated_input_tokens+greatest(p_tokens,0),updated_at=now()
    WHERE id=p_job_id AND attempt_token=p_attempt_token AND status='pending'
    RETURNING * INTO j;
  IF j.id IS NULL THEN RETURN jsonb_build_object('status','superseded'); END IF;
  IF j.estimated_input_tokens>500000 THEN
    UPDATE scoring_jobs SET status='failed',error='call_token_budget_exceeded',updated_at=now() WHERE id=j.id RETURNING * INTO j;
    UPDATE call_records SET metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('scoring_status','failed',
      'scoring_error_code','call_token_budget_exceeded','scoring_failed_at',now()),updated_at=now() WHERE id=j.call_id;
    RETURN jsonb_build_object('status','exceeded','estimatedInputTokens',j.estimated_input_tokens);
  END IF;
  RETURN jsonb_build_object('status','reserved','estimatedInputTokens',j.estimated_input_tokens);
END;
$function$

CREATE OR REPLACE FUNCTION public.reshop_evaluate(c jsonb, transitions jsonb, successors jsonb, loaded boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE codes text[]:='{}'; t jsonb; s jsonb; confirmed boolean:=false; renewal boolean:=false; increase numeric:=0; premium numeric;
BEGIN
 IF c->>'coverage' NOT IN ('MA','PDP') THEN RETURN jsonb_build_object('group','not_covered','reasons','[]'::jsonb,'premium_increase',0,'county_confirmed',false); END IF;
 IF c->>'year' IS NULL THEN RETURN jsonb_build_object('group','effective_date_missing','reasons','[]'::jsonb,'premium_increase',0,'county_confirmed',false); END IF;
 IF NOT coalesce(loaded,false) THEN RETURN jsonb_build_object('group','next_year_not_loaded','reasons','[]'::jsonb,'premium_increase',0,'county_confirmed',false); END IF;
 IF c->>'premium' ~ '^\d+(\.\d{1,2})?$' THEN premium:=(c->>'premium')::numeric; END IF;
 FOR t IN SELECT value FROM jsonb_array_elements(transitions) LOOP
  IF t->>'county_fips'=c->>'county_fips' AND t->>'county_mapping_status' IN ('affected_service_area','current_service_area') THEN confirmed:=true; END IF;
  IF t->>'termination_type'='terminated' THEN codes:=array_append(codes,'terminated'); END IF;
  IF t->>'termination_type'='service_area_reduction' AND t->>'county_mapping_status'='affected_service_area' AND t->>'county_fips'=c->>'county_fips' THEN codes:=array_append(codes,'county_dropped'); END IF;
  IF t->>'termination_type'='consolidated_renewal' OR (t->>'new_contract_id' IS NOT NULL AND t->>'new_plan_id' IS NOT NULL AND (t->>'new_contract_id'<>c->>'contract_id' OR lpad(t->>'new_plan_id',3,'0')<>c->>'plan_id')) THEN codes:=array_append(codes,'crosswalked'); END IF;
  IF t->>'termination_type' IN ('renewal','consolidated_renewal','service_area_reduction') THEN renewal:=true; END IF;
 END LOOP;
 FOR s IN SELECT value FROM jsonb_array_elements(successors) LOOP
  IF s->>'low_performing'='true' THEN codes:=array_append(codes,'low_performing'); END IF;
  IF (s->>'overall_star_rating')::numeric<3 THEN codes:=array_append(codes,'stars_below_3'); END IF;
  IF premium IS NOT NULL AND (s->>'monthly_premium')::numeric>premium THEN
   codes:=array_append(codes,'premium_increase'); increase:=greatest(increase,(s->>'monthly_premium')::numeric-premium);
  END IF;
  IF nullif(c->>'plan_type','') IS NOT NULL AND nullif(s->>'plan_type','') IS NOT NULL AND c->>'plan_type'<>s->>'plan_type' THEN codes:=array_append(codes,'type_changed'); END IF;
 END LOOP;
 SELECT coalesce(array_agg(code ORDER BY ord),'{}') INTO codes FROM unnest(ARRAY['terminated','county_dropped','crosswalked','low_performing','stars_below_3','premium_increase','type_changed']) WITH ORDINALITY a(code,ord) WHERE code=ANY(codes);
 IF cardinality(codes)=0 AND renewal AND jsonb_array_length(successors)>0 AND confirmed THEN codes:=ARRAY['renewing']; END IF;
 RETURN jsonb_build_object('group',CASE WHEN codes=ARRAY['renewing'] THEN 'renewing' WHEN cardinality(codes)>0 THEN 'needs_review' ELSE 'cms_not_confirmed' END,'reasons',to_jsonb(codes),'premium_increase',increase,'county_confirmed',confirmed);
END $function$

CREATE OR REPLACE FUNCTION public.reshop_landscape_loaded(p_year integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE relation regclass; answer boolean;
BEGIN
 IF p_year IS NULL OR p_year<1900 OR p_year>3000 THEN RETURN false; END IF;
 relation:=to_regclass(format('public.cms_plans_py%s',p_year));
 IF relation IS NULL THEN RETURN false; END IF;
 EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s WHERE plan_year=$1)',relation) INTO answer USING p_year;
 RETURN answer;
