 IF p_years IS NULL OR p_years<1 OR p_years>100 OR (p_years<10 AND
  (coalesce(p_override->>'approved','')<>'true' OR length(btrim(coalesce(p_override->>'reason','')))<10)) THEN RAISE EXCEPTION 'Invalid audit period'; END IF;
