CREATE OR REPLACE FUNCTION public.retry_failed_scoring(p_call_id uuid, p_tenant_id uuid, p_request_id uuid, p_reason text, p_requested_by text, p_execute boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records; d transcript_score_dispatch; prior scoring_manual_retries;
 revision_hash text; jobs jsonb; result jsonb;
BEGIN
 -- Match the worker's call -> dispatch/job lock order and fence old attempt tokens.
 SELECT * INTO c FROM call_records WHERE id=p_call_id AND tenant_id=p_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Call unavailable for this tenant'; END IF;
 SELECT * INTO prior FROM scoring_manual_retries WHERE request_id=p_request_id;
 IF FOUND THEN
  IF prior.call_id<>c.id OR prior.tenant_id<>c.tenant_id THEN RAISE EXCEPTION 'Retry request ID belongs to another call'; END IF;
  RETURN jsonb_build_object('status','already_requested','call_id',c.id,'request_id',p_request_id);
 END IF;
 IF NOT c.compliance_eligible OR NOT public.is_compliance_sale(c.call_outcome)
  OR c.compliance_requested_at IS NULL THEN RAISE EXCEPTION 'Call is not eligible for sale compliance'; END IF;
 IF c.compliance_run_at IS NOT NULL AND c.compliance_transcript_hash=public.compliance_content_hash(c) THEN
  RETURN jsonb_build_object('status','already_complete','call_id',c.id);
 END IF;
 SELECT * INTO d FROM transcript_score_dispatch WHERE call_id=c.id AND tenant_id=c.tenant_id FOR UPDATE;
 IF NOT FOUND OR d.snapshot_revision IS DISTINCT FROM public.compliance_content_hash(c) THEN
  RAISE EXCEPTION 'No current dispatch snapshot; reconcile the call first';
 END IF;
 IF NOT public.sale_compliance_transcript_ready(c) THEN RAISE EXCEPTION 'Full finalized transcript is not ready'; END IF;
 IF EXISTS(SELECT 1 FROM scoring_jobs WHERE call_id=c.id AND status='pending' AND lease_until>clock_timestamp()) THEN
  RAISE EXCEPTION 'Scoring worker is still active; wait for its lease to expire';
 END IF;
 revision_hash:=md5(scoring_transcript_snapshot(c)::text);
 IF EXISTS(SELECT 1 FROM scoring_jobs WHERE call_id=c.id AND transcript_revision=revision_hash AND status='complete') THEN
  RAISE EXCEPTION 'Current transcript already has a completed job; reconcile its result instead';
 END IF;
 IF c.compliance_status<>'failed' AND coalesce(c.metadata->>'scoring_status','')<>'failed'
  AND coalesce(d.last_error,'') NOT IN ('scoring_attempts_exhausted','call_token_budget_exceeded')
  AND NOT EXISTS(SELECT 1 FROM scoring_jobs WHERE call_id=c.id AND transcript_revision=revision_hash AND status='failed') THEN
  RAISE EXCEPTION 'Call is not failed; no manual retry is needed';
 END IF;
 -- Retain the cumulative token budget. Manual retries cannot bypass this safety cap.
 IF EXISTS(SELECT 1 FROM scoring_jobs WHERE call_id=c.id AND transcript_revision=revision_hash
  AND (estimated_input_tokens>500000 OR error='call_token_budget_exceeded')) THEN
  RAISE EXCEPTION 'Call token budget exhausted; investigate before resetting its budget';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'status',status,'attempt_count',attempt_count,
  'estimated_input_tokens',estimated_input_tokens,'error',error,'lease_until',lease_until)),'[]'::jsonb)
 INTO jobs FROM scoring_jobs WHERE call_id=c.id AND transcript_revision=revision_hash;
 result:=jsonb_build_object('status','ready','call_id',c.id,'tenant_id',c.tenant_id,
  'dispatch_attempts',d.dispatch_attempts,'matching_jobs',jsonb_array_length(jobs),'new_dispatch_limit',3);
 IF NOT coalesce(p_execute,false) THEN RETURN result; END IF;
 IF p_request_id IS NULL OR nullif(trim(p_reason),'') IS NULL OR length(p_reason)>500
  OR nullif(trim(p_requested_by),'') IS NULL OR length(p_requested_by)>200 THEN
  RAISE EXCEPTION 'Execution requires a request ID, operator and reason (maximum 200/500 characters)';
 END IF;
 INSERT INTO scoring_manual_retries(request_id,call_id,tenant_id,requested_by,reason,previous_dispatch,previous_jobs)
 VALUES(p_request_id,c.id,c.tenant_id,trim(p_requested_by),trim(p_reason),to_jsonb(d),jobs);
 UPDATE scoring_jobs SET status='failed',attempt_count=0,error=NULL,attempt_token=gen_random_uuid(),
  lease_until=clock_timestamp(),updated_at=clock_timestamp()
 WHERE call_id=c.id AND transcript_revision=revision_hash AND status<>'complete';
 -- A new dispatch revision fences delayed acknowledgements from the previous batch.
 UPDATE transcript_score_dispatch SET revision=revision+1,dispatch_attempts=0,last_error=NULL,
  available_at=clock_timestamp()+interval '5 seconds',transcript_ready_at=clock_timestamp()+interval '5 seconds'
 WHERE call_id=c.id;
 UPDATE call_records SET metadata=(coalesce(metadata,'{}'::jsonb)-'scoring_error'-'scoring_error_code'
  -'scoring_failed_at'-'scoring_completed_at'-'scoring_revision'-'scoring_job_id')||jsonb_build_object('scoring_status','queued'),
  updated_at=clock_timestamp() WHERE id=c.id;
 RETURN result||jsonb_build_object('status','queued','request_id',p_request_id);
END $function$

CREATE OR REPLACE FUNCTION public.retry_ix_upload(p_id uuid, p_tenant uuid, p_actor text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 IF nullif(p_actor,'') IS NULL THEN RAISE EXCEPTION 'Retry actor required'; END IF;
 UPDATE ix_uploads SET status='pending',attempts=0,retryable=true,next_attempt_at=now(),last_error=NULL,
 provider_message=NULL,lease_token=NULL,lease_until=NULL,ix_state='{}',ix_receipt_id=NULL,updated_at=now()
 WHERE id=p_id AND tenant_id=p_tenant AND status IN ('failed','needs_attention')
 AND finalized_at IS NULL AND finalize_receipt IS NULL AND uploaded_at IS NULL;
 IF NOT FOUND THEN RETURN false; END IF;
 INSERT INTO ix_upload_retries(upload_id,tenant_id,actor) VALUES(p_id,p_tenant,p_actor);
 RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.retry_post_call_recovery(p_session_id uuid, p_request_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE job post_call_jobs;
BEGIN
 SELECT * INTO STRICT job FROM post_call_jobs WHERE session_id=p_session_id FOR UPDATE;
 IF job.worker_id IS NOT NULL THEN RAISE EXCEPTION 'Recovery is still running'; END IF;
 IF NOT EXISTS(SELECT 1 FROM sessions WHERE id=p_session_id AND ended_at IS NOT NULL) THEN RAISE EXCEPTION 'Session is open'; END IF;
 UPDATE post_call_requests SET retry_history=retry_history||jsonb_build_array(jsonb_build_object(
   'error_code',error_code,'result',result,'completed_at',completed_at,'retried_at',clock_timestamp())),
 status='queued',error_code=NULL,result='{}',completed_at=NULL
 WHERE session_id=p_session_id AND request_key=p_request_key AND action='recover' AND status='failed';
 IF NOT FOUND THEN RETURN false; END IF;
 UPDATE post_call_jobs SET status='queued',progress='queued',error_code=NULL,provider_errors='{}',updated_at=clock_timestamp()
 WHERE session_id=p_session_id;
 RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.retry_post_call_transcript(p_session_id uuid, p_request_key text, p_payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 PERFORM 1 FROM post_call_jobs WHERE session_id=p_session_id AND worker_id IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Processing is already running'; END IF;
 INSERT INTO post_call_requests(session_id,request_key,action,payload) VALUES(p_session_id,p_request_key,'finalize',p_payload)
 ON CONFLICT(session_id,request_key) DO UPDATE SET status=CASE WHEN post_call_requests.status='failed' THEN 'queued' ELSE post_call_requests.status END,error_code=NULL;
 UPDATE post_call_requests SET retry_request_key=p_request_key WHERE session_id=p_session_id AND action='finalize'
 AND status='failed' AND request_key<>p_request_key AND payload->>'call_record_id'=p_payload->>'call_record_id';
 UPDATE post_call_jobs SET status='queued',progress='queued',error_code=NULL WHERE session_id=p_session_id;
 RETURN p_request_key;
END; $function$

CREATE OR REPLACE FUNCTION public.review_post_call_coaching(p_actor text, p_org text, p_call uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE identity record;
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('POST_CALL_COACHING_ENABLED') THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO identity FROM public.resolve_deployment_subject(p_actor,p_org);
 IF identity.tenant_id IS NULL THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 UPDATE public.post_call_coaching SET reviewed_at=clock_timestamp(),reviewed_by=p_actor WHERE call_id=p_call AND tenant_id=identity.tenant_id AND agent_id=identity.agent_id AND status IN ('generated','nothing_to_coach');
 IF NOT FOUND THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.save_agent_call_disposition(p_tenant_id uuid, p_agent_id uuid, p_agent_slug text, p_call_sid text, p_outcome text, p_product text, p_automatic boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a telephony_call_attempts; s sessions; c call_records; reservation text; seconds integer; at timestamptz:=clock_timestamp();
BEGIN
 IF NOT EXISTS(SELECT 1 FROM enrolled_agents e JOIN availability_agent_subjects r
  ON r.tenant_id=e.tenant_id AND r.clerk_user_id=e.clerk_user_id
  WHERE e.id=p_agent_id AND e.tenant_id=p_tenant_id AND e.is_active AND r.is_active AND r.agent_slug=p_agent_slug)
 THEN RAISE EXCEPTION 'Disposition identity mismatch'; END IF;
 -- Serialize with claim_call_agent: a concurrent new reservation either wins
 -- first (save refuses), or waits until this completed session has been saved.
 SELECT active_call_sid INTO STRICT reservation FROM agent_availability WHERE agent_id=p_agent_slug FOR UPDATE;
 IF reservation IS NOT NULL OR EXISTS(SELECT 1 FROM telephony_call_attempts
  WHERE tenant_id=p_tenant_id AND agent_id=p_agent_slug AND answered_at IS NOT NULL AND ended_at IS NULL)
 THEN RAISE EXCEPTION 'Agent has an in-progress call'; END IF;
 SELECT * INTO STRICT a FROM telephony_call_attempts WHERE tenant_id=p_tenant_id
  AND agent_id=p_agent_slug AND parent_call_sid=p_call_sid FOR UPDATE;
 IF a.status<>'completed' OR a.ended_at IS NULL OR a.answered_at IS NULL OR
  (a.direction='inbound' AND coalesce(a.child_call_sid,'') !~ '^CA[0-9a-fA-F]{32}$') OR
  (a.direction='outbound' AND NOT EXISTS(SELECT 1 FROM telephony_events WHERE tenant_id=p_tenant_id
   AND twilio_call_sid=p_call_sid AND event='call_completed' AND payload->>'CallSid'=p_call_sid AND payload->>'CallStatus'='completed'))
 THEN RAISE EXCEPTION 'Agent leg has not ended'; END IF;
 SELECT * INTO STRICT s FROM sessions WHERE tenant_id=p_tenant_id AND agent_id=p_agent_id AND twilio_call_sid=p_call_sid FOR UPDATE;
 SELECT * INTO STRICT c FROM call_records WHERE tenant_id=p_tenant_id AND agent_id=p_agent_id
  AND twilio_call_sid=p_call_sid AND session_id=s.id AND id=s.call_record_id FOR UPDATE;
 IF c.metadata->>'wrap_up_saved_at' IS NOT NULL THEN
  RETURN jsonb_build_object('saved',true,'session_id',s.id,'call_record_id',c.id,'call_outcome',c.call_outcome);
 END IF;
 IF c.call_outcome IS NOT NULL AND c.call_outcome NOT IN ('incomplete','pending') THEN
  RAISE EXCEPTION 'Call already has a disposition'; END IF;
 IF p_outcome IS NULL OR p_outcome IN ('','incomplete','pending') THEN RAISE EXCEPTION 'Disposition required'; END IF;
 seconds:=CASE WHEN a.talk_seconds>0 THEN a.talk_seconds ELSE greatest(0,floor(extract(epoch FROM a.ended_at-a.answered_at))::integer) END;
 IF p_automatic AND (p_outcome<>'short_call_hangup' OR seconds>=15) THEN RAISE EXCEPTION 'Manual disposition required'; END IF;
 UPDATE call_records SET call_outcome=p_outcome,
  ancillary_product_type=CASE WHEN p_outcome='sale_ancillary' THEN p_product END,
  enrollment_completed=p_outcome='enrolled',call_end=a.ended_at,call_duration_seconds=seconds,
  metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('wrap_up_saved_at',at,'disposition_source','dialer')||
   CASE WHEN p_automatic THEN jsonb_build_object('auto_disposition',p_outcome) ELSE '{}'::jsonb END WHERE id=c.id;
 UPDATE sessions SET ended_at=a.ended_at,completed=p_outcome='enrolled',duration_seconds=seconds WHERE id=s.id;
 UPDATE call_transcripts SET disposition=p_outcome WHERE id=c.transcript_id AND session_id=s.id AND tenant_id=p_tenant_id;
 RETURN jsonb_build_object('saved',true,'session_id',s.id,'call_record_id',c.id,'call_outcome',p_outcome);
END $function$

CREATE OR REPLACE FUNCTION public.save_call_wrap_up()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE w call_wrap_ups;
BEGIN
 SELECT * INTO w FROM call_wrap_ups WHERE call_sid=NEW.twilio_call_sid AND tenant_id=NEW.tenant_id AND agent_id=NEW.agent_id;
 IF w.attempt_id IS NULL THEN RETURN NEW; END IF;
 IF NEW.metadata->>'wrap_up_saved_at' IS NOT NULL AND NEW.call_outcome IS NOT NULL AND NEW.call_outcome<>'incomplete' THEN
  UPDATE call_wrap_ups SET status='saved',outcome=NEW.call_outcome,session_id=NEW.session_id,
   saved_at=(NEW.metadata->>'wrap_up_saved_at')::timestamptz,updated_at=clock_timestamp() WHERE attempt_id=w.attempt_id;
  UPDATE sessions SET ended_at=coalesce(ended_at,(NEW.metadata->>'wrap_up_saved_at')::timestamptz),
   completed=NEW.call_outcome='enrolled',duration_seconds=coalesce(w.connected_seconds,NEW.call_duration_seconds)
  WHERE id=NEW.session_id AND tenant_id=NEW.tenant_id AND agent_id=NEW.agent_id;
  UPDATE call_transcripts SET disposition=NEW.call_outcome WHERE call_record_id=NEW.id AND tenant_id=NEW.tenant_id;
  PERFORM refresh_agent_wrap_up(w.agent_slug);
 ELSIF NEW.session_id IS DISTINCT FROM w.session_id THEN
  UPDATE call_wrap_ups SET session_id=NEW.session_id WHERE attempt_id=w.attempt_id;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.save_compliance_version(p_call_id uuid, p_tenant_id uuid, p_source_id uuid, p_request_id uuid, p_requested_by text, p_payload jsonb, p_decision jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c call_records; original compliance_scorecards; card compliance_scorecards;
 item scorecard_items; v jsonb; prior compliance_version_requests; expected integer;
BEGIN
 SELECT * INTO STRICT c FROM call_records WHERE id=p_call_id AND tenant_id=p_tenant_id FOR UPDATE;
 SELECT * INTO prior FROM compliance_version_requests WHERE request_id=p_request_id;
 IF FOUND THEN
  IF prior.call_id<>c.id OR prior.tenant_id<>c.tenant_id THEN RAISE EXCEPTION 'Request identity mismatch'; END IF;
  RETURN prior.scorecard_id;
 END IF;
 IF nullif(p_requested_by,'') IS NULL THEN RAISE EXCEPTION 'Verified administrator required'; END IF;
 IF c.compliance_scorecard_id IS DISTINCT FROM p_source_id THEN RAISE EXCEPTION 'Scorecard changed; reload before reviewing'; END IF;
 IF p_source_id IS NOT NULL THEN
  SELECT * INTO STRICT original FROM compliance_scorecards WHERE id=p_source_id AND call_id=c.id AND tenant_id=c.tenant_id;
 END IF;
 card:=jsonb_populate_record(NULL::compliance_scorecards,p_payload->'scorecard');
 IF NOT EXISTS(SELECT 1 FROM scoring_templates t WHERE t.id=card.template_id AND t.product_type=c.product_type AND t.is_active) THEN RAISE EXCEPTION 'Target must be the active product rubric'; END IF;
 SELECT count(*) INTO expected FROM scoring_template_items WHERE template_id=card.template_id;
 IF expected=0 OR jsonb_array_length(p_payload->'items')<>expected THEN RAISE EXCEPTION 'SCORING INCOMPLETE: item coverage mismatch'; END IF;
 IF (SELECT count(DISTINCT x->>'template_item_id') FROM jsonb_array_elements(p_payload->'items')x)<>expected THEN RAISE EXCEPTION 'Duplicate items'; END IF;
 card:=jsonb_populate_record(NULL::compliance_scorecards,p_payload->'scorecard');
 IF card.call_id IS DISTINCT FROM c.id OR card.tenant_id IS DISTINCT FROM c.tenant_id OR card.template_id IS NULL
  OR card.supersedes_id IS DISTINCT FROM p_source_id OR nullif(card.rules_version,'') IS NULL THEN RAISE EXCEPTION 'Version identity mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM compliance_llm_passes p WHERE p.call_id=c.id AND p.status IN ('reserved','running') AND (card.llm_pass_id IS NULL OR p.id<>card.llm_pass_id)) THEN RAISE EXCEPTION 'Scoring in progress'; END IF;
 card.id:=gen_random_uuid();card.created_at:=clock_timestamp();card.updated_at:=card.created_at;
 IF card.scoring_state='na' AND (card.overall_score IS NOT NULL OR card.overall_grade IS NOT NULL OR card.auto_fail_triggered OR card.pass_fail IS DISTINCT FROM 'N/A' OR coalesce(card.total_points_earned,0)<>0 OR coalesce(card.total_points_possible,0)<>0
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'items') i WHERE i->>'result'<>'na' OR coalesce((i->>'points_possible')::numeric,0)<>0 OR coalesce((i->>'points_earned')::numeric,0)<>0)) THEN RAISE EXCEPTION 'N/A version cannot grade line items'; END IF;
 IF card.scoring_state='incomplete' AND (card.overall_score IS NOT NULL OR card.auto_fail_triggered OR card.overall_grade IS NOT NULL) THEN RAISE EXCEPTION 'Incomplete version cannot have grade or auto-fail'; END IF;
 INSERT INTO compliance_scorecards SELECT card.*;
 FOR v IN SELECT * FROM jsonb_array_elements(p_payload->'items') LOOP
  item:=jsonb_populate_record(NULL::scorecard_items,v);item.scorecard_id:=card.id;
  IF NOT EXISTS(SELECT 1 FROM scoring_template_items t WHERE t.id=item.template_item_id AND t.template_id=card.template_id) THEN RAISE EXCEPTION 'Item belongs to another template'; END IF;
  IF item.detection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM intent_detections d WHERE d.id=item.detection_id AND d.call_id=c.id) THEN RAISE EXCEPTION 'Evidence belongs to another call'; END IF;
  INSERT INTO scorecard_items SELECT item.*;
 END LOOP;
 IF EXISTS(SELECT 1 FROM unnest(card.auto_fail_item_ids) id WHERE NOT EXISTS(SELECT 1 FROM scorecard_items i WHERE i.id=id AND i.scorecard_id=card.id AND i.auto_fail_triggered)) THEN RAISE EXCEPTION 'Auto-fail link invalid'; END IF;
 IF coalesce(card.auto_fail_triggered,false) IS DISTINCT FROM (coalesce(cardinality(card.auto_fail_item_ids),0)>0) OR EXISTS(SELECT 1 FROM scorecard_items i WHERE i.scorecard_id=card.id AND i.auto_fail_triggered AND NOT(i.id=ANY(card.auto_fail_item_ids))) THEN RAISE EXCEPTION 'Auto-fail header and evidence disagree'; END IF;
 IF p_decision IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM scorecard_items i WHERE i.id=(p_decision->>'item_id')::uuid AND i.scorecard_id=original.id AND i.result='review') THEN RAISE EXCEPTION 'Review item unavailable'; END IF;
  INSERT INTO compliance_review_decisions(scorecard_item_id,tenant_id,request_id,decision,decided_by,note,replacement_scorecard_id)
  VALUES((p_decision->>'item_id')::uuid,c.tenant_id,p_request_id,p_decision->>'decision',p_requested_by,p_decision->>'note',card.id);
 END IF;
 IF card.llm_pass_id IS NOT NULL THEN UPDATE compliance_llm_passes SET status=CASE WHEN card.scoring_state='complete' THEN 'complete' ELSE 'failed' END WHERE id=card.llm_pass_id AND call_id=c.id AND tenant_id=c.tenant_id AND mode='manual'; END IF;
 INSERT INTO compliance_version_requests VALUES(p_request_id,c.id,c.tenant_id,card.id,p_requested_by,clock_timestamp());
 -- A free version never creates or resets a scoring dispatch or model job.
 UPDATE call_records SET compliance_scorecard_id=card.id,metadata=coalesce(metadata,'{}')||jsonb_build_object('scoring_status',CASE WHEN card.scoring_state='complete' THEN 'complete' WHEN card.scoring_state='na' THEN 'na' ELSE 'incomplete' END) WHERE id=c.id;
 UPDATE call_records SET compliance_status=CASE WHEN card.scoring_state='complete' THEN 'complete' WHEN card.scoring_state='na' THEN 'na' ELSE 'incomplete' END WHERE id=c.id;
 IF jsonb_typeof(p_payload->'agentAssessment')='object' AND jsonb_typeof(p_payload->'beneficiaryRisk')='object' THEN
  UPDATE call_records SET agent_assessment=p_payload->'agentAssessment',beneficiary_risk=p_payload->'beneficiaryRisk' WHERE id=c.id AND tenant_id=c.tenant_id;
 END IF;
 RETURN card.id;
END $function$

CREATE OR REPLACE FUNCTION public.save_enrollment_intake(p_id uuid, p_tenant uuid, p_call uuid, p_contact uuid, p_data jsonb, p_carrier text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE result uuid; task uuid; owner_slug text; previous public.enrollment_intakes; codes text;
BEGIN
 -- Lock the call to serialize intake/disposition changes and household code updates.
 PERFORM 1 FROM call_records WHERE id=p_call AND tenant_id=p_tenant FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM contacts WHERE id=p_contact AND tenant_id=p_tenant) THEN
  RAISE EXCEPTION 'Invalid intake relationship'; END IF;
 IF p_id IS NOT NULL THEN
  SELECT * INTO previous FROM enrollment_intakes WHERE id=p_id AND call_id=p_call AND tenant_id=p_tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Intake unavailable'; END IF;
 END IF;
 IF nullif(p_data->>'sixtyDayDate','') IS NULL OR nullif(p_data->>'aor','') IS NULL THEN RAISE EXCEPTION 'Incomplete intake'; END IF;
 SELECT agent_slug INTO STRICT owner_slug FROM tenant_agents WHERE id=(p_data->>'writingAgentId')::uuid AND tenant_id=p_tenant AND is_active AND name=p_data->>'aor';
 task:=previous.follow_up_id;
 IF task IS NULL THEN
  INSERT INTO follow_ups(tenant_id,contact_id,agent_id,due_at,reason)
  VALUES(p_tenant,p_contact,owner_slug,((p_data->>'sixtyDayDate')::date+time '09:00') AT TIME ZONE public.deployment_timezone(),'Medicare enrollment — 60 day follow-up') RETURNING id INTO task;
 ELSE
  UPDATE follow_ups SET contact_id=p_contact,agent_id=owner_slug,
   due_at=((p_data->>'sixtyDayDate')::date+time '09:00') AT TIME ZONE public.deployment_timezone(),updated_at=now() WHERE id=task AND tenant_id=p_tenant;
 END IF;
 INSERT INTO enrollment_intakes(id,tenant_id,call_id,contact_id,data,pii_encrypted,carrier_key,follow_up_id,submitted_at,is_test_enrollment)
 VALUES(coalesce(p_id,gen_random_uuid()),p_tenant,p_call,p_contact,p_data-ARRAY['dob','mbi','medicaidNum'],
 jsonb_build_object('dob',encrypt_pii_value(p_data->>'dob'),'mbi',encrypt_pii_value(p_data->>'mbi'),'medicaidNum',encrypt_pii_value(p_data->>'medicaidNum')),p_carrier,task,(p_payload->>'submittedAt')::timestamptz,coalesce((p_data->>'testEnrollment')::boolean,false))
 ON CONFLICT(id) DO UPDATE SET contact_id=excluded.contact_id,data=excluded.data,pii_encrypted=excluded.pii_encrypted,
 completed_at=now(),carrier_key=excluded.carrier_key,is_test_enrollment=excluded.is_test_enrollment,updated_at=now() RETURNING id INTO result;
 IF NOT coalesce((p_data->>'testEnrollment')::boolean,false) THEN
 INSERT INTO ghl_enrollment_deliveries(tenant_id,call_id,twilio_recording_sid,enrollment_key,intake_id,payload_encrypted)
 VALUES(p_tenant,p_call,'ghl',gen_random_uuid()::text,result,encrypt_pii_value(p_payload::text));
 END IF;
 SELECT string_agg(data->>'sunfireCode',E'\n' ORDER BY submitted_at,id) INTO codes FROM enrollment_intakes WHERE call_id=p_call AND tenant_id=p_tenant AND nullif(data->>'sunfireCode','') IS NOT NULL;
 UPDATE call_records SET sunfire_code=coalesce(codes,'') WHERE id=p_call AND tenant_id=p_tenant;
 PERFORM enqueue_compliance_uploads(p_call);
 RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.save_follow_up(p_tenant_id uuid, p_requesting_agent_id uuid, p_contact_id uuid, p_due_at timestamp with time zone, p_reason text DEFAULT NULL::text, p_agent_slug text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE a public.tenant_agents; c public.contacts; task_id uuid; owner_slug text;
BEGIN
 IF current_setting('role',true)<>'service_role' AND NOT public.deployment_can_access_contact(p_contact_id) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501'; END IF;
  a := public.opportunities_assert_agent(p_tenant_id,p_requesting_agent_id);
  IF auth.role() IS DISTINCT FROM 'authenticated' OR a.id IS NULL
    OR a.clerk_user_id IS DISTINCT FROM nullif(auth.jwt()->>'sub','') THEN
    RAISE EXCEPTION 'Follow-up access denied' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO c FROM public.contacts WHERE id = p_contact_id AND tenant_id = p_tenant_id;
  IF c.id IS NULL THEN
    RAISE EXCEPTION 'Contact access denied' USING ERRCODE = '42501';
  END IF;
  owner_slug := coalesce(nullif(p_agent_slug,''), a.agent_slug);
  IF NOT public.follow_up_access(p_tenant_id, owner_slug) OR NOT EXISTS (
    SELECT 1 FROM public.tenant_agents WHERE tenant_id = p_tenant_id AND agent_slug = owner_slug AND is_active = true
  ) THEN RAISE EXCEPTION 'Follow-up assignee denied' USING ERRCODE = '42501'; END IF;
  IF p_due_at IS NULL OR NOT isfinite(p_due_at) THEN RAISE EXCEPTION 'A valid due date is required'; END IF;
  INSERT INTO public.follow_ups(tenant_id,contact_id,agent_id,due_at,reason)
    VALUES(p_tenant_id,p_contact_id,owner_slug,p_due_at,nullif(trim(p_reason),'')) RETURNING id INTO task_id;
  INSERT INTO public.contact_activities(tenant_id,contact_id,type,summary)
    VALUES(p_tenant_id,p_contact_id,'follow_up','Follow-up scheduled');
  RETURN task_id;
END $function$

CREATE OR REPLACE FUNCTION public.save_opportunity(p_tenant_id uuid, p_requesting_agent_id uuid, p_fields jsonb, p_opportunity_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE o public.opportunities; s public.pipeline_stages; cid uuid; aid uuid; source_id uuid; callid uuid; encrypted jsonb; a public.tenant_agents;
BEGIN
 IF current_setting('role',true)<>'service_role' AND (NOT public.deployment_is_admin(p_tenant_id)) AND ((p_fields->>'assigned_agent_id')::uuid IS DISTINCT FROM p_requesting_agent_id OR (p_opportunity_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.opportunities resource_check WHERE resource_check.id=p_opportunity_id AND resource_check.assigned_agent_id=p_requesting_agent_id AND public.deployment_can_access_contact(resource_check.contact_id)))) THEN RAISE EXCEPTION 'Opportunity access denied' USING ERRCODE='42501'; END IF;
 IF current_setting('role',true)<>'service_role' AND NOT public.deployment_can_access_contact((p_fields->>'contact_id')::uuid) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501'; END IF;
  a := public.opportunities_assert_agent(p_tenant_id,p_requesting_agent_id);
  cid := (p_fields->>'contact_id')::uuid;
  aid := nullif(p_fields->>'assigned_agent_id','')::uuid;
  source_id := nullif(p_fields->>'lead_source_id','')::uuid;
  callid := nullif(p_fields->>'call_id','')::uuid;
  SELECT * INTO s FROM public.pipeline_stages WHERE id = (p_fields->>'stage_id')::uuid
    AND pipeline_id = (p_fields->>'pipeline_id')::uuid AND tenant_id = p_tenant_id;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Select a valid pipeline and stage'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.contacts WHERE id = cid AND tenant_id = p_tenant_id) THEN RAISE EXCEPTION 'Select a contact in this workspace'; END IF;
  IF aid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.tenant_agents WHERE id = aid AND tenant_id = p_tenant_id AND coalesce(is_active,true)) THEN RAISE EXCEPTION 'Agent is outside this workspace'; END IF;
  IF source_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.lead_sources WHERE id = source_id AND tenant_id = p_tenant_id) THEN RAISE EXCEPTION 'Source is outside this workspace'; END IF;
  IF callid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.call_records WHERE id = callid AND tenant_id = p_tenant_id AND contact_id = cid) THEN RAISE EXCEPTION 'Call must belong to the selected contact'; END IF;
  IF nullif(btrim(p_fields->>'title'),'') IS NULL THEN RAISE EXCEPTION 'Enter an opportunity title'; END IF;
  SELECT * INTO o FROM public.opportunities WHERE id = p_opportunity_id AND tenant_id = p_tenant_id;
  PERFORM id FROM public.pipelines WHERE id IN (s.pipeline_id,o.pipeline_id) ORDER BY id FOR UPDATE;
  encrypted := jsonb_strip_nulls(jsonb_build_object('title',public.encrypt_pii_value(btrim(p_fields->>'title')),
    'notes',public.encrypt_pii_value(p_fields->>'notes')));
  IF p_opportunity_id IS NULL THEN
    -- Unspecified call links to the latest related call. No inbound automation.
    IF callid IS NULL THEN
      SELECT id INTO callid FROM public.call_records WHERE contact_id = cid AND tenant_id = p_tenant_id ORDER BY call_start DESC NULLS LAST, id LIMIT 1;
    END IF;
    INSERT INTO public.opportunities(tenant_id,pipeline_id,stage_id,contact_id,assigned_agent_id,pii_encrypted,
      line_of_business,carrier,plan_name,effective_date,est_value,lead_source_id,call_id,status)
    VALUES(p_tenant_id,s.pipeline_id,s.id,cid,aid,encrypted,p_fields->>'line_of_business',nullif(btrim(p_fields->>'carrier'),''),
      nullif(btrim(p_fields->>'plan_name'),''),nullif(p_fields->>'effective_date','')::date,coalesce(nullif(p_fields->>'est_value','')::numeric,0),source_id,callid,
      CASE WHEN s.is_won THEN 'won' WHEN s.is_lost THEN 'lost' ELSE 'open' END) RETURNING * INTO o;
    INSERT INTO public.opportunity_stage_history(tenant_id,opportunity_id,to_stage_id,to_stage_name,to_stage_color,changed_by)
      VALUES(p_tenant_id,o.id,s.id,s.name,s.color,a.id);
  ELSE
    SELECT * INTO o FROM public.opportunities WHERE id = p_opportunity_id AND tenant_id = p_tenant_id FOR UPDATE;
    IF o.id IS NULL OR o.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Opportunity not found or deleted'; END IF;
    IF p_expected_updated_at IS NULL OR o.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'This opportunity changed in another session. Refresh and try again.' USING ERRCODE = '40001';
    END IF;
    PERFORM public.opportunities_move_internal(o.id,s.id,a.id,o.stage_id);
    UPDATE public.opportunities SET contact_id = cid, assigned_agent_id = aid, pii_encrypted = encrypted,
      line_of_business = p_fields->>'line_of_business', carrier = nullif(btrim(p_fields->>'carrier'),''),
      plan_name = nullif(btrim(p_fields->>'plan_name'),''), effective_date = nullif(p_fields->>'effective_date','')::date,
      est_value = coalesce(nullif(p_fields->>'est_value','')::numeric,0), lead_source_id = source_id,call_id = callid,updated_at = clock_timestamp() WHERE id = o.id;
  END IF;
  INSERT INTO public.pii_access_log(contact_id,agent_id,clerk_user_id,action) VALUES(cid,a.id,a.clerk_user_id,'edit');
  RETURN o.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_opportunity_pipeline(p_tenant_id uuid, p_requesting_agent_id uuid, p_pipeline_id uuid, p_name text, p_line_of_business text, p_stages jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE p uuid; item jsonb; sid uuid; pos integer := 0;
BEGIN
  PERFORM public.opportunities_assert_agent(p_tenant_id,p_requesting_agent_id,true);
  IF jsonb_typeof(p_stages) <> 'array' OR jsonb_array_length(p_stages) = 0 THEN RAISE EXCEPTION 'A pipeline needs at least one stage'; END IF;
  IF p_pipeline_id IS NULL THEN
    INSERT INTO public.pipelines(tenant_id,name,line_of_business) VALUES(p_tenant_id,btrim(p_name),nullif(p_line_of_business,'')) RETURNING id INTO p;
  ELSE
    SELECT id INTO p FROM public.pipelines WHERE id = p_pipeline_id AND tenant_id = p_tenant_id FOR UPDATE;
    IF p IS NULL THEN RAISE EXCEPTION 'Pipeline not found'; END IF;
    UPDATE public.pipelines SET name = btrim(p_name),line_of_business = nullif(p_line_of_business,'') WHERE id = p;
  END IF;
  IF EXISTS(SELECT 1 FROM public.pipeline_stages s WHERE s.pipeline_id = p
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_stages) x WHERE nullif(x->>'id','')::uuid = s.id)) THEN
    RAISE EXCEPTION 'Delete stages using the move-to-stage workflow first';
  END IF;
  FOR item IN SELECT * FROM jsonb_array_elements(p_stages) LOOP
    sid := coalesce(nullif(item->>'id','')::uuid,gen_random_uuid());
    IF EXISTS(SELECT 1 FROM public.pipeline_stages WHERE id = sid AND (tenant_id <> p_tenant_id OR pipeline_id <> p)) THEN RAISE EXCEPTION 'Stage belongs to another pipeline'; END IF;
    INSERT INTO public.pipeline_stages(id,tenant_id,pipeline_id,name,position,color,is_won,is_lost)
      VALUES(sid,p_tenant_id,p,btrim(item->>'name'),pos,item->>'color',coalesce((item->>'is_won')::boolean,false),coalesce((item->>'is_lost')::boolean,false))
      ON CONFLICT(id) DO UPDATE SET name = EXCLUDED.name,position = EXCLUDED.position,color = EXCLUDED.color,is_won = EXCLUDED.is_won,is_lost = EXCLUDED.is_lost;
    pos := pos + 1;
  END LOOP;
  UPDATE public.opportunities o SET status = CASE WHEN s.is_won THEN 'won' WHEN s.is_lost THEN 'lost' ELSE 'open' END,updated_at = clock_timestamp()
    FROM public.pipeline_stages s WHERE o.stage_id = s.id AND s.pipeline_id = p
      AND o.status IS DISTINCT FROM CASE WHEN s.is_won THEN 'won' WHEN s.is_lost THEN 'lost' ELSE 'open' END;
  RETURN p;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_paragon_contact_zip(p_contact uuid, p_tenant uuid, p_zip text, p_user text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE c contacts;
BEGIN
 IF p_zip IS NOT NULL AND p_zip !~ '^[0-9]{5}$' THEN RAISE EXCEPTION 'Invalid ZIP'; END IF;
 UPDATE contacts SET zip=p_zip WHERE id=p_contact AND tenant_id=p_tenant RETURNING * INTO c;
 IF NOT FOUND THEN RAISE EXCEPTION 'Contact unavailable'; END IF;
 IF p_zip IS NULL THEN DELETE FROM paragon_contact_zip_origin WHERE contact_id=c.id;
 ELSE
 INSERT INTO paragon_contact_zip_origin(contact_id,tenant_id,zip,contact_version,metadata)
 VALUES(c.id,c.tenant_id,c.zip,c.updated_at,jsonb_build_object('source','agent_entered','clerk_user_id',p_user))
 ON CONFLICT(contact_id) DO UPDATE SET zip=excluded.zip,contact_version=excluded.contact_version,metadata=excluded.metadata,recorded_at=clock_timestamp();
 END IF;
 RETURN jsonb_build_object('saved',true);
END; $function$

CREATE OR REPLACE FUNCTION public.search_contacts_secure(p_query text, p_requesting_agent_id uuid)
 RETURNS TABLE(contact_id uuid, masked_preview text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_agent RECORD;
  v_phone TEXT;
  v_phone_hash TEXT;
  v_name_hash TEXT;
BEGIN
  SELECT * INTO v_agent FROM public.deployment_assert_roster(p_requesting_agent_id);
  IF v_agent.id IS NULL THEN
    RAISE EXCEPTION 'requesting agent % not found', p_requesting_agent_id;
  END IF;
  IF auth.role() = 'authenticated'
     AND v_agent.clerk_user_id IS DISTINCT FROM NULLIF(auth.jwt() ->> 'sub', '') THEN
    RAISE EXCEPTION 'access denied: requesting agent is not the signed-in Clerk user';
  END IF;

  v_phone := public.normalize_phone_e164(p_query);
  IF v_phone IS NOT NULL THEN v_phone_hash := public.pii_blind_index(v_phone); END IF;
  v_name_hash := public.pii_blind_index(p_query);
  INSERT INTO public.pii_access_log (contact_id, agent_id, clerk_user_id, action)
  VALUES (NULL, p_requesting_agent_id, v_agent.clerk_user_id, 'search');

  RETURN QUERY
  SELECT c.id,
    coalesce(c.first_initial, '') || '*** ' || coalesce(c.last_initial, '') || '**, --' || coalesce(c.phone_last4, '????')
  FROM public.contacts c
  WHERE c.tenant_id = v_agent.tenant_id AND (v_agent.role='admin' OR c.assigned_agent_id=v_agent.agent_slug)
    AND ((v_phone_hash IS NOT NULL AND c.phone_hash = v_phone_hash) OR c.name_search = v_name_hash);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_paragon_controls(p_tenant uuid, p_hours jsonb, p_cap integer, p_mode text, p_rate numeric, p_actor text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE day text; cfg jsonb;
BEGIN
 IF p_hours->>'timezone' IS DISTINCT FROM public.deployment_timezone() OR p_mode NOT IN ('soft','hard')
 OR p_mode IS NULL OR p_rate IS NULL OR p_rate<=0 OR p_rate>99999999.99
 OR (p_cap IS NOT NULL AND p_cap<=0) OR nullif(p_actor,'') IS NULL THEN RAISE EXCEPTION 'Invalid Paragon controls'; END IF;
 FOREACH day IN ARRAY ARRAY['mon','tue','wed','thu','fri','sat','sun'] LOOP
 cfg:=p_hours->'days'->day;
 IF cfg IS NULL OR jsonb_typeof(cfg->'enabled') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid staffed day'; END IF;
 IF cfg->>'enabled'='true' AND (coalesce(cfg->>'start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
  OR coalesce(cfg->>'end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') THEN RAISE EXCEPTION 'Invalid staffed time'; END IF;
 IF cfg->>'enabled'='true' AND (cfg->>'start')::time>=(cfg->>'end')::time THEN RAISE EXCEPTION 'Invalid staffed window'; END IF;
 END LOOP;
 UPDATE vendor_controls SET staffed_hours=p_hours,paragon_daily_cap=p_cap,paragon_cap_mode=p_mode,
 paragon_rate=p_rate,updated_by=p_actor,updated_at=clock_timestamp() WHERE tenant_id=p_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'Controls missing'; END IF;
 INSERT INTO paragon_control_changes(tenant_id,settings,changed_by)
 VALUES(p_tenant,jsonb_build_object('staffed_hours',p_hours,'daily_cap',p_cap,'cap_mode',p_mode,'rate',p_rate),p_actor);
END; $function$

CREATE OR REPLACE FUNCTION public.set_ping_source_control(p_tenant uuid, p_source uuid, p_campaign uuid, p_paused boolean, p_actor text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE control_id uuid;
BEGIN
 IF NOT public.deployment_feature_enabled('PING_PLATFORM_ENABLED') THEN RAISE EXCEPTION 'Ping platform disabled'; END IF;
 IF p_tenant IS NULL OR p_source IS NULL OR p_paused IS NULL OR nullif(trim(p_actor),'') IS NULL
 THEN RAISE EXCEPTION 'Invalid ping source control'; END IF;
 UPDATE ping_source_controls SET paused=p_paused,changed_by=left(trim(p_actor),128)
  WHERE tenant_id=p_tenant AND source_id=p_source AND campaign_id IS NOT DISTINCT FROM p_campaign
  RETURNING id INTO control_id;
 IF control_id IS NULL THEN
  INSERT INTO ping_source_controls(tenant_id,source_id,campaign_id,paused,changed_by)
  VALUES(p_tenant,p_source,p_campaign,p_paused,left(trim(p_actor),128)) RETURNING id INTO control_id;
 END IF;
 RETURN control_id;
END $function$

CREATE OR REPLACE FUNCTION public.set_post_call_provider_status(p_session_id uuid, p_stage text, p_error_code text, p_started_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE job post_call_jobs; errors jsonb; failure text;
BEGIN
 IF p_stage NOT IN ('embeddings','scoring') THEN RAISE EXCEPTION 'Invalid provider stage'; END IF;
 INSERT INTO post_call_jobs(session_id,tenant_id,agent_id,clerk_user_id,clerk_org_id)
 SELECT s.id,s.tenant_id,s.agent_id,e.clerk_user_id,t.clerk_org_id FROM sessions s
 JOIN enrolled_agents e ON e.id=s.agent_id AND e.tenant_id=s.tenant_id
 JOIN tenants t ON t.id=s.tenant_id WHERE s.id=p_session_id AND e.is_active
 ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT job FROM post_call_jobs WHERE session_id=p_session_id FOR UPDATE;
 errors:=job.provider_errors;
 IF p_error_code IS NOT NULL THEN
   errors:=errors||jsonb_build_object(p_stage,jsonb_build_object('code',left(p_error_code,100),'at',clock_timestamp()));
 ELSIF (errors->p_stage->>'at')::timestamptz IS NULL OR (errors->p_stage->>'at')::timestamptz<=p_started_at THEN
   errors:=errors-p_stage;
 END IF;
 SELECT value->>'code' INTO failure FROM jsonb_each(errors) ORDER BY value->>'at' DESC LIMIT 1;
 IF failure IS NULL THEN
   SELECT error_code INTO failure FROM post_call_requests WHERE session_id=p_session_id AND status='failed' ORDER BY sequence DESC LIMIT 1;
 END IF;
 UPDATE post_call_jobs SET provider_errors=errors,error_code=failure,
 status=CASE WHEN failure IS NOT NULL THEN 'failed' WHEN worker_id IS NOT NULL THEN 'running'
   WHEN EXISTS(SELECT 1 FROM post_call_requests r WHERE r.session_id=p_session_id AND r.status='failed') THEN 'failed'
   WHEN EXISTS(SELECT 1 FROM post_call_requests r WHERE r.session_id=p_session_id AND r.status IN ('queued','running')) THEN 'queued'
   ELSE 'completed' END,
 progress=CASE WHEN failure IS NOT NULL THEN p_stage||'_failed' ELSE p_stage||'_complete' END,
 updated_at=clock_timestamp() WHERE session_id=p_session_id;
 IF p_stage='scoring' AND (p_error_code IS NOT NULL OR NOT (errors ? p_stage)) THEN
   UPDATE call_records SET metadata=CASE WHEN p_error_code IS NULL THEN coalesce(metadata,'{}')-'scoring_error_code'
   ELSE coalesce(metadata,'{}')||jsonb_build_object('scoring_error_code',left(p_error_code,100)) END
   WHERE session_id=p_session_id AND tenant_id=job.tenant_id;
 END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.set_scoring_dispatch_readiness()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  NEW.transcript_ready_at:=NEW.available_at;
 ELSIF NEW.snapshot_revision IS DISTINCT FROM OLD.snapshot_revision THEN
  NEW.transcript_ready_at:=NEW.available_at;
  NEW.dispatch_attempts:=0;
 ELSIF OLD.available_at='infinity'::timestamptz AND NEW.available_at<>'infinity'::timestamptz THEN
  NEW.transcript_ready_at:=NEW.available_at;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.shopper_history_count(p_phone_hash text, p_window_days integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
 IF p_phone_hash IS NULL OR coalesce(p_window_days,0)<=0 OR NOT public.ping_pooled_shopper_on() THEN RETURN 0; END IF;
 SELECT count(*)::integer INTO n FROM shopper_history
  WHERE phone_hash=p_phone_hash AND seen_on>(clock_timestamp() AT TIME ZONE 'UTC')::date-p_window_days;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.snapshot_ping_billing_duplicate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE prior uuid;
BEGIN
 IF NEW.inbound_call_id IS NULL THEN RETURN NEW; END IF;
 SELECT coalesce(CASE WHEN i.duplicate_flag THEN i.duplicate_prior_call_id END,
   find_duplicate_prior_call(i.tenant_id,i.lead_source_id,i.from_number,i.created_at,i.twilio_call_sid))
 INTO prior FROM inbound_calls i WHERE i.id=NEW.inbound_call_id AND i.tenant_id=NEW.tenant_id
   AND i.twilio_call_sid=NEW.parent_call_sid;
 NEW.duplicate_prior_call_id:=prior; NEW.duplicate_flag:=prior IS NOT NULL;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.start_practice_session(p_actor text, p_org text, p_scenario text, p_product text, p_difficulty text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i jsonb; cfg jsonb; allowance jsonb; s public.practice_sessions;
BEGIN
 i:=public.practice_identity(p_actor,p_org);
 SELECT practice_settings INTO cfg FROM public.tenants WHERE id=(i->>'tenant_id')::uuid;
 -- The existing atomic counter routine locks/checks/increments both caps together.
 allowance:=public.consume_admission(jsonb_build_array(jsonb_build_object('key',i->>'tenant_id'||':practice:agent:'||(i->>'agent_id'),'seconds',86400,'limit',(cfg->>'agent_daily')::integer),jsonb_build_object('key',i->>'tenant_id'||':practice:agency','seconds',86400,'limit',(cfg->>'agency_daily')::integer)));
 IF allowance->>'allowed' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Practice daily cap' USING ERRCODE='54000'; END IF;
 INSERT INTO public.practice_sessions(tenant_id,agent_id,scenario_id,product_type,difficulty,turn_limit,expires_at) VALUES((i->>'tenant_id')::uuid,(i->>'agent_id')::uuid,p_scenario,p_product,p_difficulty,(cfg->>'turns')::integer,clock_timestamp()+make_interval(mins=>(cfg->>'minutes')::integer)) RETURNING * INTO s;
 RETURN to_jsonb(s)-ARRAY['work_token','lease_until','work_kind'];
END $function$

CREATE OR REPLACE FUNCTION public.start_telephony_session(p_tenant_id uuid, p_agent_id uuid, p_call_sid text, p_flow text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE owner enrolled_agents; a telephony_call_attempts; s sessions; c call_records; rid uuid;
BEGIN
 IF p_call_sid !~ '^CA[0-9a-fA-F]{32}$' OR p_flow NOT IN ('ma','medsup','aca','u65','ancillary') THEN
  RAISE EXCEPTION 'Invalid call identity'; END IF;
 SELECT * INTO STRICT owner FROM enrolled_agents WHERE id=p_agent_id AND tenant_id=p_tenant_id AND is_active;
 SELECT attempt.* INTO STRICT a FROM telephony_call_attempts attempt
 JOIN availability_agent_subjects roster ON roster.agent_slug=attempt.agent_id
  AND roster.tenant_id=attempt.tenant_id AND roster.clerk_user_id=owner.clerk_user_id AND roster.is_active
 WHERE attempt.parent_call_sid=p_call_sid AND attempt.tenant_id=p_tenant_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('session:'||p_call_sid,0));
 SELECT * INTO c FROM call_records WHERE tenant_id=p_tenant_id AND agent_id=p_agent_id
  AND twilio_call_sid=p_call_sid ORDER BY created_at LIMIT 1;
 SELECT * INTO s FROM sessions WHERE tenant_id=p_tenant_id AND agent_id=p_agent_id
  AND (twilio_call_sid=p_call_sid OR id=c.session_id) ORDER BY created_at LIMIT 1;
 IF s.id IS NULL THEN
  INSERT INTO sessions(tenant_id,agent_id,flow,product_line,twilio_call_sid)
  VALUES(p_tenant_id,p_agent_id,p_flow,CASE p_flow WHEN 'ma' THEN 'MA' WHEN 'medsup' THEN 'MedSup'
   WHEN 'aca' THEN 'ACA' WHEN 'u65' THEN 'U65' ELSE 'Ancillary' END,p_call_sid) RETURNING * INTO s;
 ELSE
  UPDATE sessions SET twilio_call_sid=p_call_sid WHERE id=s.id;
 END IF;
 IF a.direction='inbound' THEN
  rid:=ensure_inbound_transcript_record(a.id,s.id);
  SELECT * INTO c FROM call_records WHERE id=rid;
 ELSE
  IF c.id IS NULL THEN
   INSERT INTO call_records(tenant_id,agent_id,agent_name,session_id,twilio_call_sid,call_direction,call_type,product_type,
    call_start,contact_id,metadata)
   VALUES(p_tenant_id,p_agent_id,owner.name,s.id,p_call_sid,'outbound','enrollment',s.product_line,a.created_at,a.contact_id,
    jsonb_build_object('telephony_call',true,'transcript_source','enrollgen_live')) RETURNING * INTO c;
   UPDATE telephony_call_attempts SET call_record_id=c.id WHERE id=a.id;
  END IF;
  IF c.session_id IS NOT NULL AND c.session_id<>s.id THEN RAISE EXCEPTION 'Call session ownership mismatch'; END IF;
  UPDATE call_records SET session_id=s.id WHERE id=c.id;
  UPDATE call_transcripts SET session_id=s.id WHERE call_record_id=c.id AND tenant_id=p_tenant_id;
  UPDATE sessions SET call_record_id=c.id WHERE id=s.id;
 END IF;
 RETURN jsonb_build_object('session_id',s.id,'agent_id',owner.id,'agent_name',owner.name,
  'call_record_id',c.id,'transcript_id',c.transcript_id,'call_direction',a.direction);
END $function$

CREATE OR REPLACE FUNCTION public.supervisor_listen_authorize(p_actor text, p_org text, p_attempt uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i record; f record;
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('SUPERVISOR_FLOOR_ENABLED') OR NOT public.deployment_feature_enabled('SUPERVISOR_LISTEN_ENABLED') THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO i FROM public.resolve_deployment_subject(p_actor,p_org);
 IF i.tenant_id IS NULL OR i.authority NOT IN ('admin','manager') THEN RAISE EXCEPTION 'Supervisor required' USING ERRCODE='42501'; END IF;
 SELECT * INTO f FROM public.supervisor_floor_rows(i.tenant_id,CASE WHEN i.authority='manager' THEN i.team_agent_ids END) WHERE attempt_id=p_attempt AND status='on_call' AND listen_available;
 IF f.agent_id IS NULL THEN RAISE EXCEPTION 'Call unavailable' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('tenant',i.tenant_id,'agent',f.agent_id,'call',f.call_id);
END $function$

CREATE OR REPLACE FUNCTION public.supervisor_listen_history(p_actor text, p_org text, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i record; answer jsonb;
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('SUPERVISOR_FLOOR_ENABLED') OR NOT (public.deployment_feature_enabled('SUPERVISOR_LISTEN_ENABLED') OR public.deployment_feature_enabled('SUPERVISOR_WHISPER_ENABLED') AND public.deployment_feature_enabled('CONFERENCE_CALLING_ENABLED')) THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO i FROM public.resolve_deployment_subject(p_actor,p_org);
 IF i.tenant_id IS NULL OR i.authority<>'admin' THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 IF (p_before IS NULL)<>(p_before_id IS NULL) THEN RAISE EXCEPTION 'Invalid page' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO answer FROM (SELECT s.id,s.actor_id supervisor,e.name agent,coalesce(s.call_id,a.call_record_id) call_id,s.started_at,s.ended_at,s.duration_seconds,s.mode,s.talk_seconds FROM public.supervisor_listen_sessions s LEFT JOIN public.telephony_call_attempts a ON a.id=s.attempt_id AND a.tenant_id=s.tenant_id LEFT JOIN public.enrolled_agents e ON e.id=s.agent_id AND e.tenant_id=s.tenant_id WHERE s.tenant_id=i.tenant_id AND (p_before IS NULL OR (s.started_at,s.id)<(p_before,p_before_id)) ORDER BY s.started_at DESC,s.id DESC LIMIT 100) x;
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.supervisor_whisper_authorize(p_actor text, p_org text, p_attempt uuid, p_check_lock boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE i record; f record; a public.telephony_call_attempts; c public.call_conferences;
BEGIN
 IF current_setting('role',true)<>'service_role' OR NOT public.deployment_feature_enabled('SUPERVISOR_FLOOR_ENABLED') OR NOT public.deployment_feature_enabled('CONFERENCE_CALLING_ENABLED') OR NOT public.deployment_feature_enabled('SUPERVISOR_WHISPER_ENABLED') THEN RAISE EXCEPTION 'Unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO i FROM public.resolve_deployment_subject(p_actor,p_org);
 IF i.tenant_id IS NULL OR i.authority NOT IN ('admin','manager') THEN RAISE EXCEPTION 'Supervisor required' USING ERRCODE='42501'; END IF;
 SELECT * INTO f FROM public.supervisor_floor_rows(i.tenant_id,CASE WHEN i.authority='manager' THEN i.team_agent_ids END) WHERE attempt_id=p_attempt AND status IN ('on_call','on_hold');
 SELECT * INTO a FROM public.telephony_call_attempts WHERE id=p_attempt AND tenant_id=i.tenant_id;
 SELECT * INTO c FROM public.call_conferences WHERE attempt_id=p_attempt AND tenant_id=i.tenant_id;
 IF f.agent_id IS NULL OR a.child_call_sid IS NULL OR a.answered_at IS NULL OR a.ended_at IS NOT NULL OR a.status IN ('completed','failed','canceled','no-answer','busy')
 OR EXISTS(SELECT 1 FROM public.call_wrap_ups WHERE attempt_id=p_attempt AND status='pending')
 OR c.call_id IS NOT NULL AND (c.ended_at IS NOT NULL OR c.phase NOT IN ('active','warm_completed') OR p_check_lock AND c.operation_until>clock_timestamp()
 OR NOT EXISTS(SELECT 1 FROM public.call_participants WHERE call_id=c.call_id AND role='agent' AND agent_id=c.owner_agent_id AND status='connected')) THEN RAISE EXCEPTION 'Call unavailable' USING ERRCODE='42501'; END IF;
 IF (SELECT event FROM public.telephony_events WHERE tenant_id=i.tenant_id AND event IN ('session_lock','session_unlock') AND payload->>'clerk_user_id'=p_actor ORDER BY occurred_at DESC,id DESC LIMIT 1)='session_lock' THEN RAISE EXCEPTION 'Session locked' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('tenant',i.tenant_id,'agent',f.agent_id,'call',f.call_id);
END $function$

CREATE OR REPLACE FUNCTION public.sweep_practice_sessions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.practice_sessions; result jsonb:='[]';
BEGIN
 PERFORM public.practice_server();
 FOR s IN SELECT * FROM public.practice_sessions WHERE status IN ('active','ending') AND (expires_at<=clock_timestamp() OR last_activity_at<clock_timestamp()-interval '5 minutes' OR lease_until<clock_timestamp() OR status='ending' AND work_token IS NULL) ORDER BY started_at LIMIT 20 FOR UPDATE SKIP LOCKED LOOP
  IF s.work_token IS NOT NULL AND s.lease_until>clock_timestamp() THEN CONTINUE; END IF;
  IF s.work_token IS NOT NULL OR s.last_activity_at<clock_timestamp()-interval '5 minutes' AND s.expires_at>clock_timestamp() THEN
   UPDATE public.practice_sessions SET status='incomplete',end_reason='abandoned',ended_at=clock_timestamp(),work_token=NULL,work_kind=NULL,lease_until=NULL WHERE id=s.id;
  ELSE
   UPDATE public.practice_sessions SET status='ending',end_reason=coalesce(end_reason,'time_limit'),work_token=gen_random_uuid(),work_kind='result',lease_until=clock_timestamp()+interval '3 minutes' WHERE id=s.id RETURNING * INTO s;
   result:=result||jsonb_build_array(to_jsonb(s));
  END IF;
 END LOOP;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.sweep_supervisor_listens()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s record;
BEGIN
 IF current_setting('role',true)<>'service_role' THEN RAISE EXCEPTION 'Server required' USING ERRCODE='42501'; END IF;
 FOR s IN SELECT id FROM public.supervisor_listen_sessions WHERE mode='listen' AND ended_at IS NULL AND (lease_until<=clock_timestamp() OR expires_at<=clock_timestamp()) LOOP PERFORM public.finish_supervisor_listen(s.id); END LOOP;
 DELETE FROM public.supervisor_listen_grants WHERE expires_at<clock_timestamp();
END $function$

CREATE OR REPLACE FUNCTION public.sync_ma_disposition_opportunity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  actor uuid; owner_id uuid; pipeline uuid; dest public.pipeline_stages;
  opp public.opportunities; old_outcome text; action text; reason text;
  before_stage uuid; changed_history_id uuid;
BEGIN
  IF upper(btrim(coalesce(NEW.product_type,''))) <> 'MA' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' THEN old_outcome := OLD.call_outcome; END IF;
  IF coalesce(NEW.call_outcome,'') NOT IN ('enrolled','enrolled_pending_verification')
    AND old_outcome IS DISTINCT FROM 'enrolled' THEN RETURN NEW; END IF;

  SELECT ta.id INTO owner_id FROM public.enrolled_agents e
    JOIN public.tenant_agents ta ON ta.tenant_id=e.tenant_id AND ta.clerk_user_id=e.clerk_user_id
    WHERE e.id=NEW.agent_id AND e.tenant_id=NEW.tenant_id AND e.is_active
      AND coalesce(ta.is_active,true) ORDER BY ta.id LIMIT 1;
  IF auth.role() = 'authenticated' THEN
    SELECT id INTO actor FROM public.tenant_agents WHERE tenant_id=NEW.tenant_id
      AND clerk_user_id=nullif(auth.jwt()->>'sub','') AND coalesce(is_active,true) ORDER BY id LIMIT 1;
    IF actor IS NULL THEN RAISE EXCEPTION 'Agent is outside this workspace' USING ERRCODE='42501'; END IF;
  ELSIF auth.role() = 'service_role' THEN actor := owner_id;
  ELSE RETURN NEW;
  END IF;

  -- Serialize automation for one contact, including retries from different calls.
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id::text || ':' || coalesce(NEW.contact_id::text,NEW.id::text) || ':ma-disposition',0));
  SELECT * INTO opp FROM public.opportunities WHERE tenant_id=NEW.tenant_id
    AND call_id=NEW.id AND line_of_business='MA'
    ORDER BY (deleted_at IS NULL) DESC,created_at DESC,id LIMIT 1;
  -- Reuse an open MA opportunity, never another business or an unrelated won sale.
  IF opp.id IS NULL AND NEW.contact_id IS NOT NULL THEN
    SELECT o.* INTO opp FROM public.opportunities o JOIN public.pipelines p ON p.id=o.pipeline_id
      WHERE o.tenant_id=NEW.tenant_id AND o.contact_id=NEW.contact_id AND o.line_of_business='MA'
        AND o.status='open' AND o.deleted_at IS NULL AND (p.line_of_business IS NULL OR p.line_of_business='MA')
      ORDER BY o.updated_at DESC,o.id LIMIT 1;
  END IF;

  IF opp.id IS NOT NULL THEN
    -- Match the board RPC lock order, then re-read after a concurrent manual move.
    PERFORM 1 FROM public.pipelines WHERE id=opp.pipeline_id FOR UPDATE;
    SELECT * INTO opp FROM public.opportunities WHERE id=opp.id FOR UPDATE;
    before_stage := opp.stage_id;
  END IF;
  IF old_outcome = 'enrolled' AND NEW.call_outcome IS DISTINCT FROM 'enrolled' THEN
    action := 'enrollment_changed'; reason := 'Disposition changed away from Enrolled; stage retained';
  ELSIF opp.deleted_at IS NOT NULL THEN
    action := 'skipped'; reason := 'Deleted opportunity retained';
  ELSIF NEW.contact_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.contacts WHERE id=NEW.contact_id AND tenant_id=NEW.tenant_id
  ) THEN
    action := 'skipped'; reason := 'No linked contact in this workspace';
  ELSIF opp.id IS NOT NULL AND opp.contact_id IS DISTINCT FROM NEW.contact_id THEN
    action := 'skipped'; reason := 'Call contact differs from the linked opportunity';
  ELSIF actor IS NULL THEN
    action := 'skipped'; reason := 'No active call agent linked to this workspace';
  ELSE
    IF NEW.call_outcome='enrolled_pending_verification' AND opp.id IS NOT NULL
      AND (opp.stage_change_source <> 'call_disposition' OR opp.status <> 'open') THEN
      action := 'stage_preserved'; reason := CASE WHEN opp.stage_change_source <> 'call_disposition'
        THEN 'Pending verification cannot replace a manually set stage'
        ELSE 'Pending verification cannot reopen a closed opportunity' END;
    ELSE
      pipeline := opp.pipeline_id;
      IF pipeline IS NULL THEN
        SELECT id INTO pipeline FROM public.pipelines WHERE tenant_id=NEW.tenant_id
          AND (line_of_business IS NULL OR line_of_business='MA')
          ORDER BY (line_of_business='MA') DESC NULLS LAST,is_default DESC,created_at,id LIMIT 1;
        IF pipeline IS NULL THEN
          INSERT INTO public.pipelines(tenant_id,name,line_of_business)
            VALUES(NEW.tenant_id,'Medicare Advantage','MA') RETURNING id INTO pipeline;
        END IF;
        PERFORM 1 FROM public.pipelines WHERE id=pipeline FOR UPDATE;
      END IF;
      SELECT * INTO dest FROM public.pipeline_stages WHERE tenant_id=NEW.tenant_id AND pipeline_id=pipeline
        AND CASE WHEN NEW.call_outcome='enrolled' THEN is_won
          ELSE lower(btrim(name))='pending' AND NOT is_won AND NOT is_lost END
        ORDER BY (lower(btrim(name))='enrolled') DESC,position,id LIMIT 1;
      IF dest.id IS NULL THEN
        INSERT INTO public.pipeline_stages(tenant_id,pipeline_id,name,position,color,is_won)
          SELECT NEW.tenant_id,pipeline,CASE WHEN NEW.call_outcome='enrolled' THEN 'Enrolled' ELSE 'Pending' END,
            coalesce(max(position),-1)+1,CASE WHEN NEW.call_outcome='enrolled' THEN '#4ade80' ELSE '#fb923c' END,
            NEW.call_outcome='enrolled' FROM public.pipeline_stages WHERE pipeline_id=pipeline RETURNING * INTO dest;
      END IF;
      IF opp.id IS NULL THEN
        SELECT public.save_opportunity(NEW.tenant_id,actor,jsonb_build_object(
          'contact_id',NEW.contact_id,'pipeline_id',pipeline,'stage_id',dest.id,
          'assigned_agent_id',coalesce(owner_id,actor),'line_of_business','MA','title','MA Enrollment',
          'call_id',NEW.id,'carrier',NEW.carrier_name,'plan_name',NEW.plan_name,'effective_date',NEW.effective_date
        )) INTO opp.id;
        action := 'created';
      ELSE
        IF opp.stage_id IS DISTINCT FROM dest.id THEN
          PERFORM public.opportunities_move_internal(opp.id,dest.id,actor,opp.stage_id);
          action := 'moved';
        ELSE action := 'stage_preserved'; reason := 'Already in the disposition stage';
        END IF;
        UPDATE public.opportunities SET call_id=NEW.id,updated_at=clock_timestamp()
          WHERE id=opp.id AND call_id IS DISTINCT FROM NEW.id;
      END IF;
      IF action IN ('created','moved') THEN
        UPDATE public.opportunities SET stage_change_source='call_disposition' WHERE id=opp.id;
        SELECT id INTO changed_history_id FROM public.opportunity_stage_history WHERE opportunity_id=opp.id AND to_stage_id=dest.id
          ORDER BY changed_at DESC,id DESC LIMIT 1;
        UPDATE public.opportunity_events SET payload=payload || jsonb_build_object(
          'source','call_disposition','call_id',NEW.id,'call_outcome',NEW.call_outcome) WHERE history_id=changed_history_id;
      END IF;
    END IF;
  END IF;
  INSERT INTO public.call_disposition_opportunity_log(tenant_id,call_id,opportunity_id,actor_id,
    old_outcome,new_outcome,action,reason,stage_id_before,stage_id_after)
    VALUES(NEW.tenant_id,NEW.id,opp.id,actor,old_outcome,NEW.call_outcome,action,reason,before_stage,
      coalesce((SELECT stage_id FROM public.opportunities WHERE id=opp.id),before_stage));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_post_call_scoring_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.post_call_status='failed' AND NEW.metadata IS NOT DISTINCT FROM OLD.metadata THEN RETURN NEW; END IF;
 IF NEW.metadata->>'scoring_status'='failed' THEN NEW.post_call_status:='failed';NEW.post_call_last_error:=NEW.metadata->>'scoring_error_code';
 ELSIF NEW.metadata->>'scoring_status' IN ('pending','queued') THEN NEW.post_call_status:='processing';
 ELSIF NEW.metadata->>'scoring_status'='complete' THEN NEW.post_call_status:='completed';NEW.post_call_last_error:=NULL;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.sync_user_preference_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.clerk_user_id IS DISTINCT FROM OLD.clerk_user_id THEN
      NEW.user_id := NEW.clerk_user_id;
    ELSIF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
      NEW.clerk_user_id := NEW.user_id;
    END IF;
    IF NEW.theme_preference IS DISTINCT FROM OLD.theme_preference THEN
      NEW.theme := NEW.theme_preference;
    ELSIF NEW.theme IS DISTINCT FROM OLD.theme THEN
      NEW.theme_preference := CASE WHEN NEW.theme = 'dark' THEN 'dark' ELSE 'light' END;
    END IF;
  ELSE
    IF NEW.theme_preference IS NOT NULL THEN NEW.theme := NEW.theme_preference; END IF;
  END IF;
  NEW.clerk_user_id := coalesce(NEW.clerk_user_id, NEW.user_id);
  NEW.user_id := coalesce(NEW.user_id, NEW.clerk_user_id);
  IF NEW.clerk_user_id IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'Preference user identifiers must match';
  END IF;
  NEW.theme_preference := coalesce(NEW.theme_preference,
    CASE WHEN NEW.theme = 'dark' THEN 'dark' ELSE 'light' END);
  NEW.theme := coalesce(NEW.theme, NEW.theme_preference);
  NEW.preferences := coalesce(NEW.preferences, '{}'::jsonb);
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tag_inbound_lead_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE source lead_sources; pub lead_sources; ping lead_source_pings; pubkey text; extid text;
BEGIN
  SELECT * INTO source FROM lead_sources WHERE tenant_id=NEW.tenant_id AND active AND twilio_number=NEW.to_number LIMIT 1;
  IF source.id IS NULL AND NEW.caller_classification='new' AND NEW.source_kind='publisher' THEN
    SELECT * INTO source FROM lead_sources WHERE tenant_id=NEW.tenant_id AND active AND type='publisher' AND name=public.bootstrap_vendor_source_name() LIMIT 1;
  END IF;
  IF source.id IS NULL THEN RETURN NEW; END IF;
  NEW.lead_source_id:=source.id; NEW.source_kind:=source.type;
  IF source.type <> 'aggregator' THEN RETURN NEW; END IF;
  NEW.aggregator_source_id:=source.id;
  pubkey:=nullif(NEW.vendor_metadata->>'publisher',''); extid:=nullif(NEW.vendor_metadata->>'aggregator_call_id','');
  SELECT * INTO ping FROM lead_source_pings WHERE source_id=source.id AND caller_phone=NEW.from_number AND matched_call_sid IS NULL
    AND received_at>=clock_timestamp()-interval '5 minutes' AND received_at<=clock_timestamp() ORDER BY received_at DESC FOR UPDATE SKIP LOCKED LIMIT 1;
  IF ping.id IS NOT NULL THEN pubkey:=coalesce(pubkey,ping.publisher); extid:=coalesce(extid,ping.aggregator_call_id); UPDATE lead_source_pings SET matched_call_sid=NEW.twilio_call_sid WHERE id=ping.id; END IF;
  NEW.aggregator_call_id:=CASE WHEN extid ~ '^[A-Za-z0-9_.:@+ -]{1,128}$' THEN extid ELSE NULL END;
  SELECT * INTO pub FROM lead_sources WHERE tenant_id=NEW.tenant_id AND active AND type='publisher' AND parent_source_id=source.id AND (external_id=pubkey OR name=pubkey) ORDER BY (external_id=pubkey) DESC NULLS LAST LIMIT 1;
  IF pub.id IS NOT NULL THEN NEW.lead_source_id:=pub.id; NEW.source_kind:='publisher'; NEW.publisher:=coalesce(pub.external_id,pub.name); END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'integration_source_tag_failed'; NEW.lead_source_id:=NULL; NEW.aggregator_source_id:=NULL; NEW.publisher:=NULL; NEW.aggregator_call_id:=NULL; NEW.source_kind:='direct'; RETURN NEW;
END; $function$

