CREATE OR REPLACE FUNCTION public.update_pii_field(p_contact_id uuid, p_requesting_agent_id uuid, p_field text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_contact RECORD;
  v_agent RECORD;
  v_encrypted JSONB;
BEGIN
  IF current_setting('role',true)<>'service_role' AND NOT public.deployment_can_access_contact(p_contact_id) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501'; END IF;
  IF p_field NOT IN ('mbi_full', 'ssn') THEN
    RAISE EXCEPTION 'field % is not a supported write-only PII field', p_field;
  END IF;
  SELECT id, tenant_id, assigned_agent_id, pii_encrypted INTO v_contact
  FROM public.contacts WHERE id = p_contact_id;
  IF v_contact.id IS NULL THEN RAISE EXCEPTION 'contact % not found', p_contact_id; END IF;
  SELECT * INTO v_agent FROM public.deployment_assert_roster(p_requesting_agent_id);
  IF v_agent.id IS NULL THEN RAISE EXCEPTION 'requesting agent % not found', p_requesting_agent_id; END IF;
  IF auth.role() = 'authenticated'
     AND v_agent.clerk_user_id IS DISTINCT FROM NULLIF(auth.jwt() ->> 'sub', '') THEN
    RAISE EXCEPTION 'access denied: requesting agent is not the signed-in Clerk user';
  END IF;
  IF v_agent.tenant_id != v_contact.tenant_id THEN
    RAISE EXCEPTION 'access denied: agent and contact belong to different tenants';
  END IF;

  IF p_value IS NULL OR btrim(p_value) = '' THEN
    v_encrypted := coalesce(v_contact.pii_encrypted, '{}'::jsonb) - p_field;
  ELSE
    v_encrypted := coalesce(v_contact.pii_encrypted, '{}'::jsonb)
      || jsonb_build_object(p_field, public.encrypt_pii_value(p_value));
  END IF;
  UPDATE public.contacts SET mbi_last4 = CASE WHEN p_field != 'mbi_full' THEN mbi_last4
      WHEN p_value IS NOT NULL AND length(regexp_replace(p_value, '[^a-zA-Z0-9]', '', 'g')) >= 4
      THEN right(regexp_replace(p_value, '[^a-zA-Z0-9]', '', 'g'), 4) ELSE NULL END
  WHERE id = p_contact_id;
  -- The last-four update fires the encryption trigger. Write custom encrypted
  -- fields afterwards so that trigger cannot replace the newly saved MBI.
  UPDATE public.contacts SET pii_encrypted = v_encrypted WHERE id = p_contact_id;
  INSERT INTO public.pii_access_log (contact_id, agent_id, clerk_user_id, action)
  VALUES (p_contact_id, p_requesting_agent_id, v_agent.clerk_user_id, 'edit');
  RETURN v_encrypted;
END;
$function$

CREATE OR REPLACE FUNCTION public.valid_client_recap_templates(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ch text; t jsonb; token text[]; remainder text;
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'object' OR NOT v ?& ARRAY['sms','pdf'] OR v-ARRAY['sms','pdf']<>'{}'::jsonb THEN RETURN false; END IF;
 FOREACH ch IN ARRAY ARRAY['sms','pdf'] LOOP
  t:=v->ch;
  IF jsonb_typeof(t)<>'object' OR NOT t ?& ARRAY['body','next','disclaimer','version'] OR t-ARRAY['body','next','disclaimer','version']<>'{}'::jsonb
   OR jsonb_typeof(t->'body')<>'string' OR length(btrim(t->>'body'))=0 OR length(t->>'body')>1800
   OR t->>'next' IS DISTINCT FROM 'The carrier will send plan materials and a member card.'
   OR t->>'disclaimer' IS DISTINCT FROM 'Submission is not confirmation of coverage. The carrier determines enrollment status.'
   OR jsonb_typeof(t->'version')<>'number' OR (t->>'version') !~ '^[1-9][0-9]{0,8}$' THEN RETURN false; END IF;
  FOR token IN SELECT regexp_matches(t->>'body','\{\{([A-Za-z]+)\}\}','g') LOOP
   IF token[1]<>ALL(ARRAY['firstName','planName','carrier','planType','effectiveDate','confirmationNumber','agentName','agencyName','callbackNumber']) OR ch='sms' AND token[1]='confirmationNumber' THEN RETURN false; END IF;
  END LOOP;
  IF (t->>'body') ~ '\m[0-9]{3}[- ]?[0-9]{2}[- ]?[0-9]{4}\M' OR (t->>'body') ~* '\m[1-9][A-HJ-NP-Z][A-HJ-NP-Z0-9][0-9][- ]?[A-HJ-NP-Z][A-HJ-NP-Z0-9][0-9][- ]?[A-HJ-NP-Z]{2}[0-9]{2}\M' THEN RETURN false; END IF;
  remainder:=regexp_replace(t->>'body','\{\{([A-Za-z]+)\}\}','','g');
  IF remainder ~ '[{}]' OR (t->>'body') ~ '[\x00-\x08\x0B-\x1F\x7F]' THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN others THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.valid_practice_settings(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE k text; hi integer;
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT v ?& ARRAY['agent_daily','agency_daily','turns','minutes'] OR v-ARRAY['agent_daily','agency_daily','turns','minutes']<>'{}' THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY['agent_daily','agency_daily','turns','minutes'] LOOP
  hi:=CASE k WHEN 'agent_daily' THEN 50 WHEN 'agency_daily' THEN 500 WHEN 'turns' THEN 120 ELSE 60 END;
  IF jsonb_typeof(v->k) IS DISTINCT FROM 'number' OR (v->>k)::numeric<1 OR (v->>k)::numeric>hi OR (v->>k)::numeric<>trunc((v->>k)::numeric) THEN RETURN false; END IF;
 END LOOP; RETURN true;
END $function$
